 [70]={["source"]="QuestieDB Forever",["text"]="Retrieve Stalvan's Undelivered Letter from the chest and deliver it to the Canal District in Stormwind."},
 [71]={["source"]="QuestieDB Forever",["text"]="Deliver Rolf and Malakai's Medallions to Guard Thomas at the eastern Elwynn bridge."},
 [72]={["source"]="QuestieDB Forever",["text"]="Search through the packed up possessions for a clue."},
 [74]={["source"]="QuestieDB Forever",["text"]="The Torn Journal page you discovered provides your next clue."},
 [75]={["source"]="QuestieDB Forever",["text"]="Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page."},
 [76]={["source"]="QuestieDB Forever",["text"]="Explore the Jasperlode Mine, then report back to Marshal Dughan in Goldshire."},
 [77]={["source"]="QuestieDB Forever",["text"]="Recover 10 bottles of Hinterlands Honey Ripple from the crates located around the abandoned Horde base in Skulk Rock."},
 [78]={["source"]="QuestieDB Forever",["text"]="Take the Faded Journal Page to Tavernkeep Smitts."},
 [79]={["source"]="QuestieDB Forever",["text"]="Take the muddy page to Commander Ebonlocke."},
 [80]={["source"]="QuestieDB Forever",["text"]="Show Clerk Daltry the Bloodstained Journal Page."},
 [81]={["source"]="QuestieDB Forever",["text"]="Deliver the barrel to Dran Droffers in Orgrimmar."},
 [82]={["source"]="QuestieDB Forever",["text"]="Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan."},
 [83]={["source"]="QuestieDB Forever",["text"]="Bring 6 Red Linen Bandanas to Sara Timberlain at the Eastvale Logging Camp."},
 [84]={["source"]="QuestieDB Forever",["text"]="Bring the Pork Belly Pie to Billy Maclure at the Maclure Vineyards."},
 [85]={["source"]="QuestieDB Forever",["text"]="Speak with Billy Maclure."},
 [86]={["source"]="QuestieDB Forever",["text"]="Bring 4 Chunks of Boar Meat to Auntie Bernice Stonefield at the Stonefield's Farm."},
 [87]={["source"]="QuestieDB Forever",["text"]="Bring Bernice's Necklace to \"Auntie\" Bernice Stonefield at the Stonefield Farm."},
 [88]={["source"]="QuestieDB Forever",["text"]="Kill Princess, grab her collar, then bring it back to Ma Stonefield at the Stonefield Farm."},
 [89]={["source"]="QuestieDB Forever",["text"]="Bring 5 Iron Pikes and 5 Iron Rivets to Foreman Oslow in Lakeshire."},
 [90]={["source"]="QuestieDB Forever",["text"]="Gather 10 Lean Wolf Flanks and Stormwind Seasoning Herbs and return to Chef Grual in Darkshire."},
 [91]={["source"]="QuestieDB Forever",["text"]="Bring 10 Shadowhide Pendants to Bailiff Conacher in the Lakeshire Town Hall."},
 [92]={["source"]="QuestieDB Forever",["text"]="Chef Breanna of Lakeshire wants five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat."},
 [93]={["source"]="QuestieDB Forever",["text"]="Gather 6 Gooey Spider Legs and bring them to Chef Grual in Darkshire."},
 [94]={["source"]="QuestieDB Forever",["text"]="Take the Glyph of Azora to the Lion Statue near the Tower of Ilgalar in Redridge."},
 [95]={["source"]="QuestieDB Forever",["text"]="Go to Sven's Farm and find what was buried behind the old stump."},
 [96]={["source"]="QuestieDB Forever",["text"]="Bring the Shard of Water to Islen Waterseer in the Barrens."},
 [97]={["source"]="QuestieDB Forever",["text"]="Report the news to Commander Ebonlocke."},
 [98]={["source"]="QuestieDB Forever",["text"]="Kill Stalvan Mistmantle and show Madame Eva his family ring."},
 [99]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring 6 Pyrewood Shackles to Dalar Dawnweaver at the Sepulcher."},
 [100]={["source"]="QuestieDB Forever",["text"]="Speak to the Minor Manifestation of Water in Silverpine Forest."},
 [101]={["source"]="QuestieDB Forever",["text"]="Bring 10 Ghoul Fangs, 10 Skeleton Fingers and 5 Vials of Spider Venom to Madame Eva in Darkshire."},
 [102]={["source"]="QuestieDB Forever",["text"]="Bring 8 Gnoll Paws to Captain Danuvin on Sentinel Hill."},
 [103]={["source"]="QuestieDB Forever",["text"]="Bring 5 Flasks of Oil to Captain Grayson at the Westfall Lighthouse."},
 [104]={["source"]="QuestieDB Forever",["text"]="Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse."},
 [105]={["source"]="QuestieDB Forever",["text"]="Bring Araj's Phylactery Shard to High Executor Derrington at the Bulwark, Western Plaguelands."},
 [106]={["source"]="QuestieDB Forever",["text"]="Give Maybell's Love Letter to Tommy Joe Stonefield."},
 [107]={["source"]="QuestieDB Forever",["text"]="Take Gramma Stonefield's Note to William Pestle."},
 [109]={["source"]="QuestieDB Forever",["text"]="Talk to Gryan Stoutmantle. He usually can be found in the stone tower on Sentinel Hill, just off the road, in the middle of Westfall."},
 [110]={["source"]="QuestieDB Forever",["text"]="Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts."},
 [111]={["source"]="QuestieDB Forever",["text"]="Speak with Gramma Stonefield."},
 [112]={["source"]="QuestieDB Forever",["text"]="Bring 4 Crystal Kelp Fronds to William Pestle in Goldshire."},
 [113]={["source"]="QuestieDB Forever",["text"]="Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan. Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested."},
 [114]={["source"]="QuestieDB Forever",["text"]="Take the Invisibility Liquor to Maybell Maclure."},
 [115]={["source"]="QuestieDB Forever",["text"]="Bring 3 Midnight Orbs to Marshal Marris in Lakeshire."},
 [116]={["source"]="QuestieDB Forever",["text"]="Barkeep Daniels of Lakeshire needs a keg of Thunderbrew Lager, a cask of Merlot, a bottle of Moonshine and a skin of Sweet Rum."},
 [117]={["source"]="QuestieDB Forever",["text"]="Bring Grimbooze Thunderbrew 5 hops to complete his special brew."},
 [118]={["source"]="QuestieDB Forever",["text"]="Take Verner's Note to Smith Argus in Goldshire."},
 [119]={["source"]="QuestieDB Forever",["text"]="Return to Verner Osgood in Redridge. Give him the Crate of Horseshoes."},
 [120]={["source"]="QuestieDB Forever",["text"]="Magistrate Solomon has given you a report which must be delivered to General Marcus Jonathan in Stormwind. The judge wants you to return to him as soon as the delivery has been made."},
 [121]={["source"]="QuestieDB Forever",["text"]="Take General Marcus Jonathan's letter of response to Magistrate Solomon in Lakeshire."},
 [122]={["source"]="QuestieDB Forever",["text"]="Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge."},
 [123]={["source"]="QuestieDB Forever",["text"]="Go to Marshal Dughan in Goldshire and give him The Collector's Schedule."},
 [124]={["source"]="QuestieDB Forever",["text"]="Kill 10 Redridge Brutes and 8 Redridge Mystics, then return to Verner Osgood."},
 [125]={["source"]="QuestieDB Forever",["text"]="Foreman Oslow of Lakeshire wants you to retrieve his toolbox from the bottom of Lake Everstill."},
 [126]={["source"]="QuestieDB Forever",["text"]="Bring Yowler's Paw to Verner Osgood in Lakeshire."},
 [127]={["source"]="QuestieDB Forever",["text"]="Bring 10 Spotted Sunfish to Dockmaster Baren in Lakeshire."},
 [128]={["source"]="QuestieDB Forever",["text"]="Kill 15 Blackrock Champions and Guard Howe in Lakeshire will reward you."},
 [129]={["source"]="QuestieDB Forever",["text"]="Bring Parker's lunch to Guard Parker. He patrols the road leading to Darkshire."},
 [130]={["source"]="QuestieDB Forever",["text"]="Speak with the Redridge Herbalist, Martie Jainrose."},
 [131]={["source"]="QuestieDB Forever",["text"]="Give Darcy the Daffodil Bouquet."},
 [132]={["source"]="QuestieDB Forever",["text"]="Take Wiley's Note to Gryan Stoutmantle in Westfall."},
 [133]={["source"]="QuestieDB Forever",["text"]="Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack."},
 [134]={["source"]="QuestieDB Forever",["text"]="Return Abercrombie's Crate to Abercrombie."},
 [135]={["source"]="QuestieDB Forever",["text"]="Take Wiley's Note to Mathias Shaw in Stormwind."},
 [136]={["source"]="QuestieDB Forever",["text"]="Find Captain Sanders' footlocker and search it for the next clue."},
 [138]={["source"]="QuestieDB Forever",["text"]="Find the old barrel near the ruined chimney and search it for your next clue."},
 [139]={["source"]="QuestieDB Forever",["text"]="Search the empty jug next to the windmill for the next clue."},
 [140]={["source"]="QuestieDB Forever",["text"]="Locate Captain Sanders' chest and open it for your reward."},
 [141]={["source"]="QuestieDB Forever",["text"]="Take Shaw's report to Gryan Stoutmantle in Westfall."},
 [142]={["source"]="QuestieDB Forever",["text"]="Track down the Defias Messenger in Westfall and bring his message to Stoutmantle."},
 [143]={["source"]="QuestieDB Forever",["text"]="Magistrate Solomon wants you to take his written plea to Gryan Stoutmantle in Westfall."},
 [144]={["source"]="QuestieDB Forever",["text"]="Return to Magistrate Solomon with Gryan Stoutmantle's response."},
 [145]={["source"]="QuestieDB Forever",["text"]="Magistrate Solomon wants you to take a letter to Lord Ebonlocke in Darkshire."},
 [146]={["source"]="QuestieDB Forever",["text"]="Return to Magistrate Solomon with Lord Ebonlocke's letter of response."},
 [147]={["source"]="QuestieDB Forever",["text"]="Find and kill \"the Collector\" then return to Marshal Dughan with The Collector's Ring."},
 [148]={["source"]="QuestieDB Forever",["text"]="Speak with Madame Eva."},
 [149]={["source"]="QuestieDB Forever",["text"]="Bring the Spectral Comb to Blind Mary."},
 [150]={["source"]="QuestieDB Forever",["text"]="Bring 8 Murloc Fins to Dockmaster Baren in Lakeshire."},
 [151]={["source"]="QuestieDB Forever",["text"]="Verna Furlbrow in Westfall wants you to bring her 8 Handfuls of Oats."},
 [152]={["source"]="QuestieDB Forever",["text"]="Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and return to Captain Grayson at the Westfall Lighthouse."},
 [153]={["source"]="QuestieDB Forever",["text"]="Bring 15 Red Leather Bandanas to Scout Galiaan at Sentinel Hill."},
 [154]={["source"]="QuestieDB Forever",["text"]="Return the Ghost Hair Comb to Madame Eva in Darkshire."},
 [155]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort the Defias Traitor to the secret hideout of the Defias Brotherhood. Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information."},
 [156]={["source"]="QuestieDB Forever",["text"]="Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire."},
 [157]={["source"]="QuestieDB Forever",["text"]="Bring the Ghost Hair Thread to Abercrombie, in his shack north of the Raven Hill Cemetery."},
 [158]={["source"]="QuestieDB Forever",["text"]="Speak with Tavernkeep Smitts."},
 [159]={["source"]="QuestieDB Forever",["text"]="Bring the Zombie Juice to Abercrombie at his shack."},
 [160]={["source"]="QuestieDB Forever",["text"]="Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire."},
 [161]={["source"]="QuestieDB Forever",["text"]="Chief Engineer Hinderweir wants you to take the strange smelling powder to Ashlan Stonesmirk, the explosives expert in Dun Modr."},
 [162]={["source"]="QuestieDB Forever",["text"]="Take the Insect Analysis Report to Gracina Spiritmight in Darnassus."},
 [163]={["source"]="QuestieDB Forever",["text"]="Find out what is haunting Raven Hill."},
 [164]={["source"]="QuestieDB Forever",["text"]="Deliver the supplies to Sven."},
 [165]={["source"]="QuestieDB Forever",["text"]="Check on the old man in the shack near Raven Hill cemetery."},
 [166]={["source"]="QuestieDB Forever",["text"]="Kill Edwin VanCleef and bring his head to Gryan Stoutmantle."},
 [167]={["source"]="QuestieDB Forever",["text"]="Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind."},
 [168]={["source"]="QuestieDB Forever",["text"]="Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind."},
 [169]={["source"]="QuestieDB Forever",["text"]="Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward."},
 [170]={["source"]="QuestieDB Forever",["text"]="Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs."},
 [171]={["source"]="QuestieDB Forever",["text"]="Return your ward to the Stormwind orphanage by handing in the Human Orphan Whistle to Orphan Matron Nightingale in the Cathedral District."},
 [172]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Orcish Orphan Whistle to talk with the child you will be looking after during Children's Week."},
 [173]={["source"]="QuestieDB Forever",["text"]="Kill 6 Nightbane Shadow Weaver worgen for Calor in Darkshire."},
 [174]={["source"]="QuestieDB Forever",["text"]="Viktori Prism'Antras of Darkshire wants you to bring him a bronze tube."},
 [175]={["source"]="QuestieDB Forever",["text"]="Locate Mary and persuade her to give up a reflective surface for Viktori's project."},
 [176]={["source"]="QuestieDB Forever",["text"]="Slay the gnoll Hogger and bring his Huge Gnoll Claw to Marshal Dughan."},
 [177]={["source"]="QuestieDB Forever",["text"]="Retrieve Blind Mary's Looking Glass from the Insane Ghoul and give it to Viktori in Darkshire."},
 [178]={["source"]="QuestieDB Forever",["text"]="Bring the Faded Shadowhide Pendant to Theocritus the Mage."},
 [179]={["source"]="QuestieDB Forever",["text"]="Sten Stoutarm would like 8 pieces of Tough Wolf Meat."},
 [180]={["source"]="QuestieDB Forever",["text"]="Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw."},
 [181]={["source"]="QuestieDB Forever",["text"]="Locate Zzarc'Vul in the southern ogre mound in Duskwood and return his monocle to Viktori in Darkshire."},
 [182]={["source"]="QuestieDB Forever",["text"]="Grelin Whitebeard would like you to kill 14 Frostmane Troll Whelps."},
 [183]={["source"]="QuestieDB Forever",["text"]="Talin Keeneye would like you to kill 12 Small Crag Boars."},
 [184]={["source"]="QuestieDB Forever",["text"]="Bring Furlbrow's Deed to Farmer Furlbrow."},
 [185]={["source"]="QuestieDB Forever",["text"]="Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers."},
 [186]={["source"]="QuestieDB Forever",["text"]="Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers."},
 [187]={["source"]="QuestieDB Forever",["text"]="Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers."},
 [188]={["source"]="QuestieDB Forever",["text"]="Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw."},
 [189]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay."},
 [190]={["source"]="QuestieDB Forever",["text"]="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers."},
 [191]={["source"]="QuestieDB Forever",["text"]="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers."},
 [192]={["source"]="QuestieDB Forever",["text"]="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers."},
 [193]={["source"]="QuestieDB Forever",["text"]="Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera."},
 [194]={["source"]="QuestieDB Forever",["text"]="Hemet Nesingwary wants you to kill 10 Stranglethorn Raptors."},
 [195]={["source"]="QuestieDB Forever",["text"]="Hemet Nesingwary wants you to kill 10 Lashtail Raptors."},
 [196]={["source"]="QuestieDB Forever",["text"]="Hemet Nesingwary wants you to kill 10 Jungle Stalkers."},
 [197]={["source"]="QuestieDB Forever",["text"]="Hemet Nesingwary wants you to kill Tethis, an elusive, dangerous raptor in Stranglethorn."},
 [198]={["source"]="QuestieDB Forever",["text"]="Deliver the Miscellaneous Goblin Supplies to Private Thorsen."},
 [199]={["source"]="QuestieDB Forever",["text"]="Return to Chief Engineer Hinderweir and show him the clue that you discovered."},
 [200]={["source"]="QuestieDB Forever",["text"]="Find Bookie Herod's Records."},
 [201]={["source"]="QuestieDB Forever",["text"]="Find the hunters' camp and report its location to Krazek in Booty Bay."},
 [202]={["source"]="QuestieDB Forever",["text"]="Kill 6 Kurzen Elite, 4 Kurzen Subchiefs, and bring Kurzen's Head to Lieutenant Doren at the Rebel Camp."},
 [203]={["source"]="QuestieDB Forever",["text"]="Kill 15 Kurzen Jungle Fighters.\010Return to Sergeant Yohwa at the Rebel Camp."},
 [204]={["source"]="QuestieDB Forever",["text"]="Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp."},
 [205]={["source"]="QuestieDB Forever",["text"]="Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp."},
 [206]={["source"]="QuestieDB Forever",["text"]="Bring the Mind's Eye to Brother Nimetz at the Rebel Camp."},
 [207]={["source"]="QuestieDB Forever",["text"]="Find the 4 tablets and bring their legends back to Brother Nimetz."},
 [208]={["source"]="QuestieDB Forever",["text"]="Hemet Nesingwary wants you to bring him the head of King Bangalash, the great white tiger."},
 [209]={["source"]="QuestieDB Forever",["text"]="Acquire 18 Skullsplitter Tusks and return them to Kebok."},
 [210]={["source"]="QuestieDB Forever",["text"]="Bring Krazek's Crock Pot to Krazek the goblin."},
 [211]={["source"]="QuestieDB Forever",["text"]="Bring Araj's Phylactery Shard to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands."},
 [212]={["source"]="QuestieDB Forever",["text"]="Kill a Cold Eye Basilisk, get a Chilled Basilisk Haunch, and return it to Angus Stern in the Blue Recluse."},
 [213]={["source"]="QuestieDB Forever",["text"]="Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay."},
 [214]={["source"]="QuestieDB Forever",["text"]="Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas."},
 [215]={["source"]="QuestieDB Forever",["text"]="Speak with Lieutenant Doren at the Rebel Camp."},
 [216]={["source"]="QuestieDB Forever",["text"]="Take down 8 Thistlefur Avengers and 8 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village. Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale."},
 [217]={["source"]="QuestieDB Forever",["text"]="Kill the Trogg leader, Grawmug, and his two guards, Gnasher and Brawler then report back to Captain Rugelfuss in the southern guard tower."},
 [218]={["source"]="QuestieDB Forever",["text"]="Grelin Whitebeard wants you to kill Grik'nir the Cold, and retrieve his journal."},
 [219]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Protect Corporal Keeshan on the journey back to Redridge."},
 [220]={["source"]="QuestieDB Forever",["text"]="Bring the Vial of Purest Water to Islen Waterseer in the Barrens."},
 [221]={["source"]="QuestieDB Forever",["text"]="Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire."},
 [222]={["source"]="QuestieDB Forever",["text"]="Kill 8 Nightbane Vile Fang and 8 Nightbane Tainted One worgen for Calor in Darkshire."},
 [223]={["source"]="QuestieDB Forever",["text"]="Bring Calor's note to Jonathan Carevin."},
 [224]={["source"]="QuestieDB Forever",["text"]="Mountaineer Cobbleflint of the southern guard tower wants you to kill 10 Stonesplinter Troggs and 10 Stonesplinter Scouts."},
 [225]={["source"]="QuestieDB Forever",["text"]="Speak with Sirra Von'Indi in Darkshire."},
 [226]={["source"]="QuestieDB Forever",["text"]="Kill 12 Starving Dire Wolves and 8 Rabid Dire Wolves, then return to Lars at Sven's Camp on the western border of Duskwood."},
 [227]={["source"]="QuestieDB Forever",["text"]="Speak with Commander Althea Ebonlocke in Darkshire."},
 [228]={["source"]="QuestieDB Forever",["text"]="Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire."},
 [229]={["source"]="QuestieDB Forever",["text"]="Speak with Watcher Sarah Ladimore in Darkshire."},
 [230]={["source"]="QuestieDB Forever",["text"]="Bring the Book from Sven's Farm to Sven."},
 [231]={["source"]="QuestieDB Forever",["text"]="Take Sarah Ladimore's ring to Morgan Ladimore's grave."},
 [232]={["source"]="QuestieDB Forever",["text"]="Take the purchase order to Alessandro Luca in the Undercity."},
 [233]={["source"]="QuestieDB Forever",["text"]="Deliver the stack of letters to Talin Keeneye."},
 [234]={["source"]="QuestieDB Forever",["text"]="Deliver the letter to Grelin Whitebeard."},
 [235]={["source"]="QuestieDB Forever",["text"]="Speak with Senani Thunderheart at Splintertree Post, Ashenvale."},
 [237]={["source"]="QuestieDB Forever",["text"]="Mountaineer Gravelgaw in the southern guard tower wants you to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers and report back to him."},
 [238]={["source"]="QuestieDB Forever",["text"]="Bring the Field Sampling Kit to Apothecary Zinge in the Undercity."},
 [239]={["source"]="QuestieDB Forever",["text"]="Go to the Westbrook Garrison and speak with Deputy Rainer."},
 [240]={["source"]="QuestieDB Forever",["text"]="Return to Jitters with the Dusky Crab Cakes."},
 [243]={["source"]="QuestieDB Forever",["text"]="Speak to Chief Engineer Bilgewhizzle in Gadgetzan about getting a power source for the testing kit."},
 [244]={["source"]="QuestieDB Forever",["text"]="Report to Deputy Feldon."},
 [245]={["source"]="QuestieDB Forever",["text"]="Kill 15 Pygmy Venom Web Spiders, and then report back to Watcher Dodds in Duskwood."},
 [246]={["source"]="QuestieDB Forever",["text"]="Kill 10 Redridge Mongrels and 6 Redridge Poachers, then report back to Deputy Feldon in Lakeshire."},
 [248]={["source"]="QuestieDB Forever",["text"]="Climb the intact watch tower beside Stonewatch Keep.\010Find a suitable container to place the Glyph of Azora."},
 [249]={["source"]="QuestieDB Forever",["text"]="Defeat Morganth.\010Bring his Pendant of Shadow to Theocritus at the Tower of Azora in Elwynn Forest."},
 [250]={["source"]="QuestieDB Forever",["text"]="Investigate the area near the eastern ramp of the Dam and bring Chief Engineer Hinderweir a clue that might reveal what the Dark Iron Dwarves are up to."},
 [251]={["source"]="QuestieDB Forever",["text"]="Bring the Letter to Ello to Sirra Von'Indi."},
 [252]={["source"]="QuestieDB Forever",["text"]="Bring the Translated Letter to Lord Ello Ebonlocke"},
 [253]={["source"]="QuestieDB Forever",["text"]="Find Eliza's grave. Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke."},
 [255]={["source"]="QuestieDB Forever",["text"]="Magistrate Bluntnose of Thelsamar has hired you to kill 4 Mo'grosh Ogres, 4 Mo'grosh Brutes and 4 Mo'grosh Enforcers."},
 [256]={["source"]="QuestieDB Forever",["text"]="Kill Chok'sul and bring his head to Magistrate Bluntnose of Thelsamar."},
 [257]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Kill 6 Mountain Buzzards and return to Daryl the Youngling in the Farstrider Lodge within 15 minutes."},
 [258]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Kill 5 Elder Mountain Boars and return to Daryl the Youngling in the Farstrider Lodge within 12 minutes."},
 [261]={["source"]="QuestieDB Forever",["text"]="Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point."},
 [262]={["source"]="QuestieDB Forever",["text"]="Take the book you found at Sven's farm and show it to townsfolk in Darkshire."},
 [263]={["source"]="QuestieDB Forever",["text"]="Mountaineer Wallbang in the southern guard tower wants you to kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers."},
 [264]={["source"]="QuestieDB Forever",["text"]="Place Clarice's Pendant on Yuriv's Tomb in Silverpine."},
 [265]={["source"]="QuestieDB Forever",["text"]="See if other townsfolk have clues about the shadowy figure."},
 [266]={["source"]="QuestieDB Forever",["text"]="Search the inn for clues about the shadowy figure."},
 [267]={["source"]="QuestieDB Forever",["text"]="Bring 8 Trogg Stone Teeth to Captain Rugelfuss in the southern guard tower."},
 [268]={["source"]="QuestieDB Forever",["text"]="Return to Sven with Jitters' completed journal."},
 [269]={["source"]="QuestieDB Forever",["text"]="Give Jitters' Completed Journal to Bishop Farthing in Stormwind."},
 [270]={["source"]="QuestieDB Forever",["text"]="Go to Menethil Harbor in the Wetlands, and speak with Glorin Steelbrow."},
 [271]={["source"]="QuestieDB Forever",["text"]="Kill Ol' Sooty then show your handiwork to Daryl the Youngling at the Farstrider Lodge."},
 [272]={["source"]="QuestieDB Forever",["text"]="Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance. Speak with the residents of Moonglade to learn clues as to where these items may be located.\010Form the Pendant of the Sea Lion from the two pendant halves. You need to be in proximity of the Shrine of Remulos to do this.\010Bring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade."},
 [273]={["source"]="QuestieDB Forever",["text"]="Speak with Huldar."},
 [274]={["source"]="QuestieDB Forever",["text"]="Ashlan Stonesmirk wants you to return to Chief Engineer Hinderweir and inform him of the new discovery."},
 [275]={["source"]="QuestieDB Forever",["text"]="Kill 12 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands."},
 [276]={["source"]="QuestieDB Forever",["text"]="Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands."},
 [277]={["source"]="QuestieDB Forever",["text"]="Bring Rethiel the Greenwarden 9 Crude Flints."},
 [278]={["source"]="QuestieDB Forever",["text"]="Chief Engineer Hinderweir wants you to gather Lurker Venom, a Mo'grosh Crystal, and a Crocolisk Tear."},
 [279]={["source"]="QuestieDB Forever",["text"]="Kill 12 Bluegill Murlocs.\010Slay Gobbler and take his head.\010Bring Gobbler's Head to Karl Boran in Menethil Harbor."},
 [280]={["source"]="QuestieDB Forever",["text"]="Chief Engineer Hinderweir wants you to swim down to the base of the dam, locate the powder keg and stir in the Disarming Mixture to prevent an explosion."},
 [281]={["source"]="QuestieDB Forever",["text"]="Search the crates and barrels at the coastal Murloc camps."},
 [282]={["source"]="QuestieDB Forever",["text"]="Speak with Mountaineer Thalos."},
 [283]={["source"]="QuestieDB Forever",["text"]="The Disarming Mixture seemed to take effect. Return to Chief Engineer Hinderweir to report the good news."},
 [284]={["source"]="QuestieDB Forever",["text"]="Search for the Menethil Statuette."},
 [285]={["source"]="QuestieDB Forever",["text"]="Continue searching the Murloc hovels for the Menethil Statuette."},
 [286]={["source"]="QuestieDB Forever",["text"]="Bring Karl Boran the Menethil Statuette."},
 [287]={["source"]="QuestieDB Forever",["text"]="Explore Frostmane Hold, and kill 5 Frostmane Headhunters for Senir Whitebeard in Kharanos."},
 [288]={["source"]="QuestieDB Forever",["text"]="Buy First Mate Fitzsimmons a Flagon of Mead."},
 [289]={["source"]="QuestieDB Forever",["text"]="Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig. Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor."},
 [290]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Get the Intrepid Strongbox Key from Captain Halyndor.\010Use the key to open the Intrepid's Locked Strongbox."},
 [291]={["source"]="QuestieDB Forever",["text"]="Deliver Senir's report to Senator Barin Redstone in Ironforge."},
 [292]={["source"]="QuestieDB Forever",["text"]="Bring the Cursed Eye of Paleth to Glorin Steelbrow."},
 [293]={["source"]="QuestieDB Forever",["text"]="Bring Archbishop Benedictus the Cursed Eye of Paleth. Benedictus is in the Cathedral of Light, in the city of Stormwind."},
 [294]={["source"]="QuestieDB Forever",["text"]="Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors."},
 [295]={["source"]="QuestieDB Forever",["text"]="Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site."},
 [296]={["source"]="QuestieDB Forever",["text"]="Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled."},
 [297]={["source"]="QuestieDB Forever",["text"]="Bring Magmar Fellhew 8 Carved Stone Idols."},
 [298]={["source"]="QuestieDB Forever",["text"]="Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar."},
 [299]={["source"]="QuestieDB Forever",["text"]="Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru."},
 [301]={["source"]="QuestieDB Forever",["text"]="Take Ironband's Progress Report to Prospector Stormpike."},
 [302]={["source"]="QuestieDB Forever",["text"]="Speak with Jern Hornhelm in Thelsamar."},
 [303]={["source"]="QuestieDB Forever",["text"]="Motley Garmason at Dun Modr wants you to kill 10 Dark Iron Dwarves, 5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists."},
 [304]={["source"]="QuestieDB Forever",["text"]="Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr."},
 [305]={["source"]="QuestieDB Forever",["text"]="Tarrel Rockweaver wants you to travel to the Excavation Site and contact Merrin Rockweaver."},
 [306]={["source"]="QuestieDB Forever",["text"]="Return to Tarrel Rockweaver with Merrin's note."},
 [307]={["source"]="QuestieDB Forever",["text"]="Go to the Silver Stream Mine and collect 4 loads of Miners' Gear.\010Return to Mountaineer Stormpike."},
 [309]={["source"]="QuestieDB Forever",["text"]="Ensure Miran and the shipment arrive at the excavation site, then inform Prospector Ironband."},
 [310]={["source"]="QuestieDB Forever",["text"]="In the basement of the Thunderbrew Distillery in Kharanos, replace a barrel of Thunder Ale with a Barrel of Barleybrew Scalder."},
 [311]={["source"]="QuestieDB Forever",["text"]="Bring the barrel of Thunder Ale to Marleth Barleybrew at the Brewnall Village."},
 [312]={["source"]="QuestieDB Forever",["text"]="Retrieve Tundra MacGrann's dried meats from the stolen meat locker in Old Icebeard's cave."},
 [313]={["source"]="QuestieDB Forever",["text"]="Gather 8 Wendigo Manes and bring them to Pilot Stonegear."},
 [314]={["source"]="QuestieDB Forever",["text"]="Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch."},
 [315]={["source"]="QuestieDB Forever",["text"]="Bring 6 Shimmerweeds to Rejold Barleybrew in the Brewnall Village."},
 [317]={["source"]="QuestieDB Forever",["text"]="Gather 4 Chunks of Boar Meat and 2 Thick Bear Furs, and deliver them to Pilot Bellowfiz at Steelgrill's Depot."},
 [318]={["source"]="QuestieDB Forever",["text"]="Get a cask of Evershine from Rejold Barleybrew in Brewnall Village."},
 [319]={["source"]="QuestieDB Forever",["text"]="Kill 6 Ice Claw Bears, 8 Elder Crag Boars, and 8 Snow Leopards, and then return to Rejold Barleybrew in Brewnall Village."},
 [320]={["source"]="QuestieDB Forever",["text"]="Give the cask of Evershine to Pilot Bellowfiz at Steelgrill's Depot."},
 [321]={["source"]="QuestieDB Forever",["text"]="Search the wreckage of The Flying Osprey in the Wetlands."},
 [322]={["source"]="QuestieDB Forever",["text"]="Take the Crate of Lightforge Ingots to Grimand Elmore in Stormwind."},
 [323]={["source"]="QuestieDB Forever",["text"]="Kill 15 Skeletal Raiders, 3 Skeletal Healers and 3 Skeletal Warders, and then return to Sven."},
 [324]={["source"]="QuestieDB Forever",["text"]="Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands."},
 [325]={["source"]="QuestieDB Forever",["text"]="Bring Morbent's Bane to Sven in Duskwood."},
 [328]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Small Brass Key to open Bookie Herod's Strongbox."},
 [329]={["source"]="QuestieDB Forever",["text"]="Take the Muddy Note to Lieutenant Doren at the Rebel Camp."},
 [330]={["source"]="QuestieDB Forever",["text"]="Speak with Corporal Sethman."},
 [331]={["source"]="QuestieDB Forever",["text"]="Speak with Lieutenant Doren."},
 [332]={["source"]="QuestieDB Forever",["text"]="Go to the Gallina Winery, and bring Suzetta Gallina the Wine Ticket for a free bottle of wine."},
 [333]={["source"]="QuestieDB Forever",["text"]="Go to the Canal Tailor Shop and bring Rema Schneider the Cloth Request from Harlan Bagley."},
 [334]={["source"]="QuestieDB Forever",["text"]="Go to the Larson Clothiers in the Stormwind Mage Quarter, and give Thurman Schneider his Sewing Kit."},
 [335]={["source"]="QuestieDB Forever",["text"]="Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands."},
 [336]={["source"]="QuestieDB Forever",["text"]="Take the Black Claw Stout to Lord Wishock in the Hall of Petitioners."},
 [337]={["source"]="QuestieDB Forever",["text"]="Return the book: The History of Stormwind, to the Stormwind Library."},
 [338]={["source"]="QuestieDB Forever",["text"]="Collect the missing pages from The Green Hills of Stranglethorn manuscript. Once all four chapters are complete, return them to Barnil."},
 [339]={["source"]="QuestieDB Forever",["text"]="Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I."},
 [340]={["source"]="QuestieDB Forever",["text"]="Bring pages 10, 11, 14 and 16 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter II."},
 [341]={["source"]="QuestieDB Forever",["text"]="Bring pages 18, 20, 21and 24 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter III."},
 [342]={["source"]="QuestieDB Forever",["text"]="Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV."},
 [343]={["source"]="QuestieDB Forever",["text"]="Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf. He can find for you the book on metallurgy that Brother Kristoff needs for his speech."},
 [344]={["source"]="QuestieDB Forever",["text"]="Speak with Brother Paxton in the Northshire Abbey."},
 [345]={["source"]="QuestieDB Forever",["text"]="Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore."},
 [346]={["source"]="QuestieDB Forever",["text"]="Return to Brother Kristoff in the Cathedral Square. Give him the book The Stresses of Iron."},
 [347]={["source"]="QuestieDB Forever",["text"]="Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library."},
 [348]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket."},
 [350]={["source"]="QuestieDB Forever",["text"]="Speak to Elling Trias in Stormwind."},
 [351]={["source"]="QuestieDB Forever",["text"]="Bring the distress beacon to Oglethorpe's homing robot."},
 [353]={["source"]="QuestieDB Forever",["text"]="Deliver the Package for Stormpike to Mountaineer Stormpike in Loch Modan."},
 [354]={["source"]="QuestieDB Forever",["text"]="Bring Gregor's Remains, Nissa's Remains and Thurman's Remains to Coleman Farthing in Brill."},
 [355]={["source"]="QuestieDB Forever",["text"]="Speak with Magistrate Sevren in Brill."},
 [356]={["source"]="QuestieDB Forever",["text"]="Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp."},
 [357]={["source"]="QuestieDB Forever",["text"]="Bring the Lich's Spellbook to Bethor Iceshard in the Undercity."},
 [358]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kill Rot Hide Graverobbers and Rot Hide Mongrels.\010\010Bring 8 Embalming Ichors to Magistrate Sevren in Brill."},
 [359]={["source"]="QuestieDB Forever",["text"]="Speak with Deathguard Linnea."},
 [360]={["source"]="QuestieDB Forever",["text"]="Return to Magistrate Sevren in Brill."},
 [361]={["source"]="QuestieDB Forever",["text"]="Find Yvette Farthing, and deliver to her the letter from Thurman Agamand."},
 [362]={["source"]="QuestieDB Forever",["text"]="Slay Devlin Agamand, and bring Devlin's Remains to Coleman Farthing in Brill."},
 [363]={["source"]="QuestieDB Forever",["text"]="Speak with Shadow Priest Sarvis."},
 [364]={["source"]="QuestieDB Forever",["text"]="Shadow Priest Sarvis wants you to kill 8 Mindless Zombies and 8 Wretched Zombies."},
 [365]={["source"]="ForeverDungeonJournal learned client text",["text"]="Steal 10 pumpkins from the farm to the west, just north of Deathknell and take them to Apothecary Johaan in Brill."},
 [366]={["source"]="QuestieDB Forever",["text"]="Return Gunther's Spellbook to him, on the island of Gunther's Retreat."},
 [367]={["source"]="ForeverDungeonJournal learned client text",["text"]="Apothecary Johaan in the town of Brill wants you to collect 5 Vials of Darkhound Blood."},
 [368]={["source"]="QuestieDB Forever",["text"]="Apothecary Johaan of the town of Brill needs 5 Vile Fin Scales from Murlocs in Tirisfal Glades."},
 [369]={["source"]="QuestieDB Forever",["text"]="Apothecary Johaan in the town of Brill wants you to bring him 4 samples of venom from a Vicious Night Web Spider."},
 [370]={["source"]="QuestieDB Forever",["text"]="Executor Zygand in Brill wants you to kill Captain Perrine, 3 Scarlet Zealots and 3 Scarlet Missionaries."},
 [371]={["source"]="QuestieDB Forever",["text"]="Executor Zygand in Brill has commissioned you to slay Captain Vachon and 5 Scarlet Friars."},
 [372]={["source"]="ForeverDungeonJournal learned client text",["text"]="Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards."},
 [373]={["source"]="QuestieDB Forever",["text"]="Deliver the Letter to the City Architect to Baros Alexston in Stormwind."},
 [374]={["source"]="QuestieDB Forever",["text"]="Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill."},
 [375]={["source"]="QuestieDB Forever",["text"]="Bring five Duskbat Pelts and some Coarse Thread to Gretchen Dedmar in Brill."},
 [376]={["source"]="QuestieDB Forever",["text"]="Novice Elreth requires 6 Scavenger Paws and 6 Duskbat Wings."},
 [377]={["source"]="QuestieDB Forever",["text"]="Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward."},
 [378]={["source"]="QuestieDB Forever",["text"]="Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr."},
 [379]={["source"]="QuestieDB Forever",["text"]="Bring 5 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan."},
 [380]={["source"]="QuestieDB Forever",["text"]="Executor Arren wants you to kill 10 Young Night Web Spiders and 8 Night Web Spiders."},
 [381]={["source"]="QuestieDB Forever",["text"]="Bring Executor Arren 12 Scarlet Armbands from Scarlet Converts and Scarlet Initiates."},
 [382]={["source"]="QuestieDB Forever",["text"]="Kill Meven Korgal, the messenger, at the Crusader camp, then return any information you find to Executor Arren."},
 [383]={["source"]="QuestieDB Forever",["text"]="Deliver the Scarlet Crusade Documents to Executor Zygand in Brill."},
 [384]={["source"]="QuestieDB Forever",["text"]="Ragnar Thunderbrew in Kharanos wants 6 Crag Boar Ribs and a mug of Rhapsody Malt."},
 [385]={["source"]="QuestieDB Forever",["text"]="Get 5 pieces of Crocolisk Meat and 6 Crocolisk Skins for Marek Ironheart at the Farstrider Lodge."},
 [386]={["source"]="QuestieDB Forever",["text"]="Bring the head of Targorr the Dread to Guard Berton in Lakeshire."},
 [387]={["source"]="QuestieDB Forever",["text"]="Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade."},
 [388]={["source"]="QuestieDB Forever",["text"]="Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas."},
 [389]={["source"]="QuestieDB Forever",["text"]="Speak with Warden Thelwater in the Stockade."},
 [391]={["source"]="QuestieDB Forever",["text"]="Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade."},
 [392]={["source"]="QuestieDB Forever",["text"]="Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind."},
 [393]={["source"]="QuestieDB Forever",["text"]="Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind."},
 [394]={["source"]="QuestieDB Forever",["text"]="Speak to Mathias Shaw in Stormwind."},
 [395]={["source"]="QuestieDB Forever",["text"]="Speak with Baros Alexston in Stormwind."},
 [396]={["source"]="QuestieDB Forever",["text"]="Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep."},
 [397]={["source"]="QuestieDB Forever",["text"]="Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward."},
 [398]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kill Maggot Eye and return to Executor Zygand in Brill with his paw for a reward."},
 [399]={["source"]="QuestieDB Forever",["text"]="Go to Baros Alexston's house in Westfall and search for his compass, then return it to him in Cathedral Square of Stormwind."},
 [400]={["source"]="QuestieDB Forever",["text"]="Deliver Steelgrill's Tools to Beldin Steelgrill."},
 [401]={["source"]="QuestieDB Forever",["text"]="Wait a moment, then speak with Sirra Von'Indi again."},
 [404]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring 7 Putrid Claws to Deathguard Dillinger in Brill."},
 [405]={["source"]="QuestieDB Forever",["text"]="Present Sevren's Orders to Bethor Iceshard in the Undercity."},
 [407]={["source"]="ForeverDungeonJournal learned client text",["text"]="Take the Laced Pumpkin to the Captured Scarlet Zealot who is being held in the cellar of the Gallow's End Tavern."},
 [408]={["source"]="QuestieDB Forever",["text"]="Kill 8 Wailing Ancestors and 8 Rotting Ancestors.\010Kill Captain Dargol, and bring his skull to Magistrate Sevren in Brill."},
 [409]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Obtain a Candle of Beckoning.\010Summon Lillith Nefara and kill her.\010Return to Gunther on his island."},
 [411]={["source"]="QuestieDB Forever",["text"]="Bring the Nether Gem to Bethor Iceshard in the Undercity."},
 [412]={["source"]="QuestieDB Forever",["text"]="Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears."},
 [413]={["source"]="QuestieDB Forever",["text"]="Take the Barrel of Shimmer Stout to Mountaineer Barleybrew."},
 [414]={["source"]="QuestieDB Forever",["text"]="Take the Cask of Shimmer Stout to Mountaineer Kadrell."},
 [415]={["source"]="QuestieDB Forever",["text"]="Speak with Rejold Barleybrew."},
 [416]={["source"]="QuestieDB Forever",["text"]="Bring 12 Tunnel Rat Ears to Mountaineer Kadrell in Thelsamar."},
 [417]={["source"]="QuestieDB Forever",["text"]="Kill Mangeclaw.\010Bring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot."},
 [418]={["source"]="QuestieDB Forever",["text"]="Bring 3 pieces of Bear Meat, 3 Boar Intestines, and 3 Spider Ichor to Vidra Hearthstove in Thelsamar."},
 [419]={["source"]="QuestieDB Forever",["text"]="Find Pilot Hildelve."},
 [420]={["source"]="QuestieDB Forever",["text"]="Deliver Grelin's report to Senir Whitebeard in Kharanos."},
 [421]={["source"]="ForeverDungeonJournal learned client text",["text"]="Dalar Dawnweaver at the Sepulcher wants you to kill 5 Moonrage Whitescalps."},
 [422]={["source"]="ForeverDungeonJournal learned client text",["text"]="Retrieve the Remedy of Arugal for Dalar Dawnweaver at the Sepulcher."},
 [423]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring 6 Glutton Shackles and 3 Darksoul Shackles to Dalar Dawnweaver at the Sepulcher."},
 [424]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kill Grimson the Pale and bring his head to Dalar Dawnweaver at the Sepulcher."},
 [425]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kill Ivar the Foul, and bring Ivar's Head to Rane Yorick at the Ivar Patch."},
 [426]={["source"]="ForeverDungeonJournal learned client text",["text"]="Gather 5 Notched Ribs and 3 Blackened Skulls, then return to Deathguard Dillinger in Brill."},
 [427]={["source"]="ForeverDungeonJournal learned client text",["text"]="Executor Zygand of Brill wants you to kill 10 Scarlet Warriors."},
 [428]={["source"]="ForeverDungeonJournal learned client text",["text"]="Find the Deathstalkers Quinn and Rane Yorick."},
 [429]={["source"]="ForeverDungeonJournal learned client text",["text"]="Gather 3 discolored worg hearts and bring them to Apothecary Renferrel at the Sepulcher."},
 [430]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher."},
 [432]={["source"]="QuestieDB Forever",["text"]="Kill 6 Rockjaw Skullthumpers for Foreman Stonebrow at the Gol'Bolar quarry."},
 [433]={["source"]="QuestieDB Forever",["text"]="Kill 10 Rockjaw Bonesnappers for Senator Mehr Stonehallow at the Gol'Bolar quarry."},
 [434]={["source"]="QuestieDB Forever",["text"]="Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind."},
 [435]={["complex"]=true,["source"]="ForeverDungeonJournal learned client text",["text"]="Escort Erland through the wolves, to Rane Yorick."},
 [436]={["source"]="QuestieDB Forever",["text"]="Speak with Explorer Fellhew."},
 [437]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kill rot hide gnolls at the Dead Fields.\010\010When Nightlash appears, kill her.\010\010Bring the Essence of Nightlash to High Executor Hadrec at the Sepulcher."},
 [438]={["source"]="ForeverDungeonJournal learned client text",["text"]="Go to the Decrepit Ferry.\010\010Search for the reason the Scourge are there."},
 [439]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Deliah's Ring to High Executor Hadrec at the Sepulcher."},
 [440]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Deliah's Ring to Magistrate Sevren in Brill."},
 [441]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Deliah's Ring to Raleigh."},
 [442]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Thule's Head to High Executor Hadrec at the Sepulcher."},
 [443]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring 8 bottles of rot hide ichor to Apothecary Renferrel at the Sepulcher."},
 [444]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring the Sample Ichor to Bethor Iceshard in the Undercity."},
 [445]={["source"]="ForeverDungeonJournal learned client text",["text"]="Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest."},
 [446]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Bethor's Scroll to Apothecary Renferrel at the Silverpine Sepulcher."},
 [447]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity."},
 [448]={["source"]="QuestieDB Forever",["text"]="Report to High Executor Hadrec at the Sepulcher."},
 [449]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring the Deathstalker Report to High Executor Hadrec at the Sepulcher."},
 [450]={["source"]="ForeverDungeonJournal learned client text",["text"]="Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher."},
 [451]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity."},
 [452]={["source"]="ForeverDungeonJournal learned client text",["text"]="Help Deathstalker Faerleia kill the Pyrewood Council."},
 [453]={["source"]="QuestieDB Forever",["text"]="Find the Shadowy Figure. Your clues:\010He is not native to Darkshire.\010He is a nervous, jittery person.\010He left Darkshire and headed west."},
 [454]={["source"]="QuestieDB Forever",["text"]="Speak with Miran."},
 [455]={["source"]="QuestieDB Forever",["text"]="Traverse Dun Algaz.\010Kill 8 Dragonmaw Scouts and 6 Dragonmaw Grunts.\010Report to Valstag Ironjaw in Menethil Harbor."},
 [456]={["source"]="QuestieDB Forever",["text"]="Kill 7 Young Nightsabers and 4 Young Thistle Boars and return to Conservator Ilthalaine."},
 [457]={["source"]="QuestieDB Forever",["text"]="Conservator Ilthalaine needs you to kill 7 Mangy Nightsabers and 7 Thistle Boars."},
 [458]={["source"]="QuestieDB Forever",["text"]="Seek out the dryad known as Tarindrella."},
 [459]={["source"]="QuestieDB Forever",["text"]="Collect 8 Fel Moss and bring them to Tarindrella."},
 [460]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Alaric's Head to his grave."},
 [461]={["source"]="ForeverDungeonJournal learned client text",["text"]="Take Alaric to the hidden alcove."},
 [463]={["source"]="QuestieDB Forever",["text"]="Find the Greenwarden."},
 [464]={["source"]="QuestieDB Forever",["text"]="Bring 8 Dragonmaw War Banners to Captain Stoutfist."},
 [465]={["source"]="QuestieDB Forever",["text"]="Destroy the Dragonmaw catapults."},
 [466]={["source"]="QuestieDB Forever",["text"]="Bring 6 loads of Incendicite Ore to Pilot Stonegear in Dun Morogh."},
 [467]={["source"]="QuestieDB Forever",["text"]="Speak with Pilot Stonegear."},
 [468]={["source"]="QuestieDB Forever",["text"]="Speak with Mountaineer Rockgar."},
 [469]={["source"]="QuestieDB Forever",["text"]="Deliver the Bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor."},
 [470]={["source"]="QuestieDB Forever",["text"]="One of the oozes at Ironbeard's Tomb has Sida's bag, retrieve it and bring it back to her in Menethil Harbor."},
 [471]={["source"]="QuestieDB Forever",["text"]="Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor."},
 [472]={["source"]="QuestieDB Forever",["text"]="Search for Longbraid near the town of Dun Modr."},
 [473]={["source"]="QuestieDB Forever",["text"]="Speak with Captain Stoutfist."},
 [474]={["source"]="QuestieDB Forever",["text"]="Kill Chieftain Nek'rosh\010Bring Nek'rosh's Head to Captain Stoutfist."},
 [475]={["source"]="QuestieDB Forever",["text"]="Seek out Gaerolas Talvethren in Starbreeze Village."},
 [476]={["source"]="QuestieDB Forever",["text"]="Return to Athridas Bearmantle in Dolanaar."},
 [477]={["source"]="ForeverDungeonJournal learned client text",["text"]="Retrieve the contents of one of the Dalaran wizards' crates. You will find Pyrewood Village to the south."},
 [478]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring the strange pendant to Shadow Priest Allister at the Sepulcher."},
 [479]={["source"]="ForeverDungeonJournal learned client text",["text"]="Obtain 8 Dalaran Pendants for Shadow Priest Allister at the Sepulcher."},
 [480]={["source"]="QuestieDB Forever",["text"]="Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher."},
 [481]={["source"]="ForeverDungeonJournal learned client text",["text"]="Take the rune-inscribed pendant to Dalar Dawnweaver at the Sepulcher."},
 [482]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Shadow Priest Allister at the Sepulcher."},
 [483]={["source"]="QuestieDB Forever",["text"]="Retrieve the Relics of Wakening and bring them to Athridas Bearmantle in Dolanaar."},
 [484]={["source"]="QuestieDB Forever",["text"]="Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor."},
 [485]={["source"]="QuestieDB Forever",["text"]="Take the distress beacon to Oglethorpe's homing robot at the head of the river in the Hinterlands, near Skulk Rock."},
 [486]={["source"]="QuestieDB Forever",["text"]="Kill Ursal the Mauler and return to Athridas Bearmantle in Dolanaar."},
 [487]={["source"]="QuestieDB Forever",["text"]="Slay 6 Gnarlpine Ambushers and return to Sentinel Amara Nightwalker outside of Dolanaar."},
 [488]={["source"]="QuestieDB Forever",["text"]="Bring Zenn Foulhoof outside of Dolanaar 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk."},
 [489]={["source"]="QuestieDB Forever",["text"]="Collect 3 Fel Cones and give them to Zenn Foulhoof outside of Dolanaar."},
 [490]={["source"]="QuestieDB Forever",["text"]="Shayla Nightbreeze on the road outside of Darnassus wants you to bring her 15 Gnarlpine Fangs."},
 [491]={["source"]="ForeverDungeonJournal learned client text",["text"]="Take the Woven Wand to Bethor Iceshard in the Magic Quarter of the Undercity."},
 [492]={["source"]="QuestieDB Forever",["text"]="Bring Johaan's Special Drink to the Captured Mountaineer."},
 [493]={["source"]="ForeverDungeonJournal learned client text",["text"]="Deliver Apothecary Renferrel's findings to Apothecary Lydon in the town of Tarren Mill in the Hillsbrad Foothills."},
 [494]={["source"]="ForeverDungeonJournal learned client text",["text"]="Travel to Tarren Mill to deliver Deathstalker Lesh's message to High Executor Darthalia."},
 [495]={["source"]="QuestieDB Forever",["text"]="Report to Melisara at Tarren Mill in the Hillsbrad Foothills."},
 [496]={["source"]="QuestieDB Forever",["text"]="Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor."},
 [498]={["source"]="QuestieDB Forever",["text"]="Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep."},
 [499]={["source"]="QuestieDB Forever",["text"]="Give Umpi the Elixir of Suffering."},
 [500]={["source"]="QuestieDB Forever",["text"]="Gather 9 Dirty Knucklebones from Crushridge ogres in the Alterac Mountains. Bring them to Marshal Redpath in Southshore."},
 [501]={["source"]="QuestieDB Forever",["text"]="Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill."},
 [502]={["source"]="QuestieDB Forever",["text"]="Feed the Elixir of Pain to Stanley."},
 [503]={["source"]="QuestieDB Forever",["text"]="Free Gol'dir then return to Krusk in Tarren Mill."},
 [504]={["source"]="QuestieDB Forever",["text"]="Slay 15 Crushridge Warmongers, then return to Marshal Redpath in Southshore."},
 [505]={["source"]="QuestieDB Forever",["text"]="Kill 12 Syndicate Footpads and 8 Syndicate Thieves, then return to Magistrate Henry Maleb in Southshore."},
 [506]={["source"]="QuestieDB Forever",["text"]="Return the information gathered by Gol'dir to Krusk in Tarren Mill."},
 [507]={["source"]="QuestieDB Forever",["text"]="Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant."},
 [508]={["source"]="QuestieDB Forever",["text"]="Return Taretha's pendant to Krusk in Tarren Mill."},
 [509]={["source"]="QuestieDB Forever",["text"]="Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill."},
 [510]={["source"]="QuestieDB Forever",["text"]="Bring the Foreboding Plans to Magistrate Maleb in Southshore."},
 [511]={["source"]="QuestieDB Forever",["text"]="Bring the Encrypted Letter to Loremaster Dibbs in Southshore."},
 [512]={["source"]="QuestieDB Forever",["text"]="Bring 7 Alterac Signet Rings to Magistrate Maleb in Southshore."},
 [513]={["source"]="QuestieDB Forever",["text"]="Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity."},
 [514]={["source"]="QuestieDB Forever",["text"]="Take the Cleverly Encrypted Letter to Prospector Stormpike in Ironforge."},
 [515]={["source"]="QuestieDB Forever",["text"]="Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill."},
 [516]={["source"]="ForeverDungeonJournal learned client text",["text"]="Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher."},
 [517]={["source"]="QuestieDB Forever",["text"]="Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill."},
 [518]={["source"]="QuestieDB Forever",["text"]="Kill 10 Crushridge Maulers for Melisara in Tarren Mill."},
 [519]={["source"]="QuestieDB Forever",["text"]="Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill."},
 [520]={["source"]="QuestieDB Forever",["text"]="Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill."},
 [521]={["source"]="QuestieDB Forever",["text"]="Deliver the Crown of Will to Sharlindra in the Undercity."},
 [522]={["source"]="QuestieDB Forever",["text"]="Bring the Assassin's Contract to Magistrate Maleb in Southshore."},
 [523]={["source"]="QuestieDB Forever",["text"]="Bring the Head of Baron Vardus to Magistrate Maleb in Southshore."},
 [524]={["source"]="QuestieDB Forever",["text"]="Place the Tainted Keg on the rug for the captured farmers."},
 [525]={["source"]="QuestieDB Forever",["text"]="Bring the Decrypted Letter to Magistrate Maleb in Southshore."},
 [526]={["source"]="QuestieDB Forever",["text"]="Gather 5 lightforge ingots, then return to Glorin Steelbrow in the Wetlands."},
 [527]={["source"]="QuestieDB Forever",["text"]="Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill."},
 [528]={["source"]="QuestieDB Forever",["text"]="Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill."},
 [529]={["source"]="QuestieDB Forever",["text"]="Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths.\010Retrieve a shipment of iron and report back to Darthalia in Tarren Mill."},
 [530]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kill Valdred Moray.\010\010Bring his hands to Raleigh Andrean in the Undercity."},
 [531]={["source"]="QuestieDB Forever",["text"]="Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge."},
 [532]={["source"]="QuestieDB Forever",["text"]="Kill Magistrate Burnside and 5 Hillsbrad Councilmen. Destroy the Hillsbrad Proclamation. Steal the Hillsbrad Town Registry. Report back to Darthalia in Tarren Mill afterwards."},
 [533]={["source"]="QuestieDB Forever",["text"]="Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill."},
 [535]={["source"]="QuestieDB Forever",["text"]="Bring a mug of Southshore Stout to Valik in the Syndicate camp."},
 [536]={["source"]="QuestieDB Forever",["text"]="Kill 10 Torn Fin Tidehunters and 10 Torn Fin Oracles for Lieutenant Farren Orinelle in Southshore."},
 [537]={["source"]="QuestieDB Forever",["text"]="Kill 4 Argus Shadow Mages.\010Bring the Head of Nagaz to Magistrate Maleb in Southshore."},
 [538]={["source"]="QuestieDB Forever",["text"]="Speak with Loremaster Dibbs in Southshore."},
 [539]={["source"]="QuestieDB Forever",["text"]="Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill."},
 [540]={["source"]="QuestieDB Forever",["text"]="Bring 5 Recovered Tomes and the Worn Leather Book containing The Arm of Gri'lek to Loremaster Dibbs in Southshore."},
 [541]={["source"]="QuestieDB Forever",["text"]="Travel to Dun Garok and kill 8 Mountaineers, 4 Riflemen, 2 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill."},
 [542]={["source"]="QuestieDB Forever",["text"]="Bring the Tomes of Alterac to Milton Sheaf in Stormwind."},
 [543]={["source"]="QuestieDB Forever",["text"]="Bring the Perenolde Tiara to Remington Ridgewell in Stormwind."},
 [544]={["source"]="QuestieDB Forever",["text"]="Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill."},
 [545]={["source"]="QuestieDB Forever",["text"]="Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill."},
 [546]={["source"]="QuestieDB Forever",["text"]="Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls."},
 [547]={["source"]="QuestieDB Forever",["text"]="Retrieve Deathguard Humbert's sword from Dun Garok and return it to him in Tarren Mill."},
 [549]={["source"]="QuestieDB Forever",["text"]="Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward."},
 [550]={["source"]="QuestieDB Forever",["text"]="Take Darthalia's Sealed Commendation to Varimathras in the Undercity."},
 [551]={["source"]="QuestieDB Forever",["text"]="Take the Ensorcelled Parchment to Loremaster Dibbs in Southshore."},
 [552]={["source"]="QuestieDB Forever",["text"]="Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill."},
 [553]={["source"]="QuestieDB Forever",["text"]="Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel.\010Drive the charged rod into Helcular's grave in Southshore."},
 [554]={["source"]="QuestieDB Forever",["text"]="Take the Ensorcelled Parchment to Prospector Stormpike in Ironforge."},
 [555]={["source"]="QuestieDB Forever",["text"]="Bring 10 pieces of Turtle Meat and some Soothing Spices to Chef Jessen in Southshore."},
 [556]={["source"]="QuestieDB Forever",["text"]="Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill."},
 [557]={["source"]="QuestieDB Forever",["text"]="Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill."},
 [558]={["source"]="QuestieDB Forever",["text"]="Travel to Theramore to see about getting Lady Jaina Proudmoore's autograph for your ward."},
 [559]={["source"]="QuestieDB Forever",["text"]="Collect 10 Murloc Heads from the murlocs on the Western Strand for Lieutenant Farren Orinelle in Southshore."},
 [560]={["source"]="QuestieDB Forever",["text"]="Deliver the sack of murloc heads to Marshall Redpath in Southshore."},
 [561]={["source"]="QuestieDB Forever",["text"]="Speak with Lieutenant Farren Orinelle in Southshore."},
 [562]={["source"]="QuestieDB Forever",["text"]="Kill 10 Daggerspine Shorehunters and 10 Daggerspine Sirens for Lieutenant Farren Orinelle in Southshore."},
 [563]={["source"]="QuestieDB Forever",["text"]="Deliver Farren's report to Major Samuelson in Stormwind Keep."},
 [564]={["source"]="QuestieDB Forever",["text"]="Darren Malvew of Southshore wants you to kill 8 Mountain Lions and 10 Hulking Mountain Lions."},
 [565]={["source"]="QuestieDB Forever",["text"]="Bring Bartolo Ginsetti of Southshore a Bolt of Wool, a Hillman's Cloak, Fine Thread and 10 clumps of Yeti Fur."},
 [566]={["source"]="QuestieDB Forever",["text"]="Kill Baron Vardus and deliver his head to High Executor Darthalia in Tarren Mill."},
 [567]={["source"]="QuestieDB Forever",["text"]="High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba."},
 [568]={["source"]="QuestieDB Forever",["text"]="Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors."},
 [569]={["source"]="QuestieDB Forever",["text"]="Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors."},
 [570]={["source"]="QuestieDB Forever",["text"]="Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang."},
 [571]={["source"]="QuestieDB Forever",["text"]="Bring an Aged Gorilla Sinew to Far Seer Mok'thardin in Grom'gol."},
 [572]={["source"]="QuestieDB Forever",["text"]="Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp."},
 [573]={["source"]="QuestieDB Forever",["text"]="Far Seer Mok'thardin of Grom'gol needs Holy Spring Water. He also wants you to kill 10 Naga Explorers."},
 [574]={["source"]="QuestieDB Forever",["text"]="Kill 10 Kurzen Commandoes and 6 Kurzen Headshrinkers.\010Report to Lieutenant Doren at the Rebel Camp."},
 [575]={["source"]="QuestieDB Forever",["text"]="Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay."},
 [576]={["source"]="QuestieDB Forever",["text"]="Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers."},
 [577]={["source"]="QuestieDB Forever",["text"]="Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay."},
 [578]={["source"]="QuestieDB Forever",["text"]="Find the haunted island for Baron Revilgaz in Booty Bay."},
 [580]={["source"]="QuestieDB Forever",["text"]="Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost."},
 [581]={["source"]="QuestieDB Forever",["text"]="Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp."},
 [582]={["source"]="QuestieDB Forever",["text"]="Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp."},
 [583]={["source"]="QuestieDB Forever",["text"]="Speak with Hemet Nesingwary"},
 [584]={["source"]="QuestieDB Forever",["text"]="Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp."},
 [585]={["source"]="QuestieDB Forever",["text"]="Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp."},
 [586]={["source"]="QuestieDB Forever",["text"]="Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers.\010Bring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp."},
 [587]={["source"]="QuestieDB Forever",["text"]="Deeg in Booty Bay wants you to bring him 15 shares of Snuff."},
 [588]={["source"]="QuestieDB Forever",["text"]="Speak with Kin'weelay."},
 [589]={["source"]="QuestieDB Forever",["text"]="Bring 3 Pulsing Blue Shards to Kin'weelay at the Grom'gol Base Camp."},
 [590]={["source"]="QuestieDB Forever",["text"]="Defeat Calvin Montague in Deathknell."},
 [591]={["source"]="QuestieDB Forever",["text"]="Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp."},
 [592]={["source"]="QuestieDB Forever",["text"]="Bring the Filled Soul Gem to Nimboya."},
 [594]={["source"]="QuestieDB Forever",["text"]="Find the author of the message in a bottle."},
 [595]={["source"]="QuestieDB Forever",["text"]="First Mate Crazz wants you to check the cove north of Booty Bay."},
 [596]={["source"]="QuestieDB Forever",["text"]="Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp."},
 [597]={["source"]="QuestieDB Forever",["text"]="Report your findings to First Mate Crazz in Booty Bay."},
 [598]={["source"]="QuestieDB Forever",["text"]="Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp."},
 [599]={["source"]="QuestieDB Forever",["text"]="Report the planned Bloodsail attack to Fleet Master Seahorn."},
 [600]={["source"]="QuestieDB Forever",["text"]="Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay."},
 [601]={["source"]="QuestieDB Forever",["text"]="Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay."},
 [602]={["source"]="QuestieDB Forever",["text"]="Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran."},
 [603]={["source"]="QuestieDB Forever",["text"]="Talk to Catelyn in Booty Bay."},
 [604]={["source"]="QuestieDB Forever",["text"]="Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders."},
 [605]={["source"]="QuestieDB Forever",["text"]="Bring 10 Singing Crystal Shards to Crank Fizzlebub."},
 [606]={["source"]="QuestieDB Forever",["text"]="Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay."},
 [607]={["source"]="QuestieDB Forever",["text"]="Bring Shaky's Payment to \"Sea Wolf\" MacKinley."},
 [608]={["source"]="QuestieDB Forever",["text"]="Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon."},
 [609]={["source"]="QuestieDB Forever",["text"]="Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay."},
 [610]={["source"]="QuestieDB Forever",["text"]="Get Catelyn's dagger from \"Pretty Boy\" Duncan."},
 [611]={["source"]="QuestieDB Forever",["text"]="Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz."},
 [613]={["source"]="QuestieDB Forever",["text"]="Bring Maury's Key to \"Sea Wolf\" Mackinley in Booty Bay."},
 [614]={["source"]="QuestieDB Forever",["text"]="Bring Smotts' Chest to Hecklebury Smotts in Booty Bay."},
 [615]={["source"]="QuestieDB Forever",["text"]="Speak with Sprogger."},
 [616]={["source"]="QuestieDB Forever",["text"]="Speak with Baron Revilgaz in Booty Bay."},
 [617]={["source"]="QuestieDB Forever",["text"]="Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay."},
 [618]={["source"]="QuestieDB Forever",["text"]="Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.\010Kill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn."},
 [621]={["source"]="QuestieDB Forever",["text"]="Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay."},
 [622]={["source"]="QuestieDB Forever",["text"]="Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp."},
 [623]={["source"]="QuestieDB Forever",["text"]="Bring a Bundle of Akiris Reeds to Privateer Groy in Theramore."},
 [624]={["source"]="QuestieDB Forever",["text"]="Solve the riddle!"},
 [625]={["source"]="QuestieDB Forever",["text"]="Solve the riddle!"},
 [626]={["source"]="QuestieDB Forever",["text"]="Solve the riddle!"},
 [627]={["source"]="QuestieDB Forever",["text"]="Bring 4 loads of Lesser Bloodstone Ore to Krazek in Booty Bay."},
 [628]={["source"]="QuestieDB Forever",["text"]="Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay."},
 [629]={["source"]="QuestieDB Forever",["text"]="Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp."},
 [630]={["source"]="QuestieDB Forever",["text"]="Slay King Mukla and return to Princess Poobah with the Key to free her."},
 [631]={["source"]="QuestieDB Forever",["text"]="Rhag Garmason wants you to locate Ol' Rustlocke."},
 [632]={["source"]="QuestieDB Forever",["text"]="Report back to Rhag Garmason and show him the parchment you found on Rustlocke's corpse."},
 [633]={["source"]="QuestieDB Forever",["text"]="Destroy the cache of explosives."},
 [634]={["source"]="QuestieDB Forever",["text"]="Seek out Captain Nials at Refuge Pointe."},
 [635]={["source"]="QuestieDB Forever",["text"]="Find the crystal from your vision."},
 [636]={["source"]="QuestieDB Forever",["text"]="Find the Shards of Myzrael."},
 [637]={["source"]="QuestieDB Forever",["text"]="Deliver Sully Balloo's Letter to Sara Balloo."},
 [638]={["source"]="QuestieDB Forever",["text"]="Travel to Hammerfall in the Arathi Highlands and speak with Zengu."},
 [639]={["source"]="QuestieDB Forever",["text"]="Get the Sigil of Strom for Zengu in Hammerfall."},
 [640]={["source"]="QuestieDB Forever",["text"]="Retrieve the 11 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall."},
 [641]={["source"]="QuestieDB Forever",["text"]="Bring the restored Sigil of Thoradin to Zengu in Hammerfall."},
 [642]={["source"]="QuestieDB Forever",["text"]="Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge."},
 [643]={["source"]="QuestieDB Forever",["text"]="Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall."},
 [644]={["source"]="QuestieDB Forever",["text"]="Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall."},
 [645]={["source"]="QuestieDB Forever",["text"]="Retrieve Trol'kalar from Trollbane's tomb in Stromgarde."},
 [646]={["source"]="QuestieDB Forever",["text"]="Deliver Trol'kalar to Zengu in Hammerfall."},
 [647]={["source"]="QuestieDB Forever",["text"]="Take MacKreel's Moonshine to Brewmeister Bilger in Southshore."},
 [648]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort OOX-17/TN to Steamwheedle Port, then report to Oglethorpe Obnoticus in Booty Bay."},
 [649]={["source"]="QuestieDB Forever",["text"]="Talk to Malton Droffers in Orgrimmar."},
 [650]={["source"]="QuestieDB Forever",["text"]="Talk to Gilveradin Sunchaser; his camp is located in the Hinterlands."},
 [651]={["source"]="QuestieDB Forever",["text"]="Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.\010Bring them to the Stone of Inner Binding."},
 [652]={["source"]="QuestieDB Forever",["text"]="Find and kill Fozruk. Bring the Rod of Order to the Keystone in the Arathi Highlands."},
 [653]={["source"]="QuestieDB Forever",["text"]="Speak with Gerrig Bonegrip in the Forlorn Cavern of Ironforge."},
 [654]={["source"]="QuestieDB Forever",["text"]="Acquire acceptable samples for 8 basilisks, 8 hyenas, and 8 scorpions. Bring the testing kit back to Chief Engineer Bilgewhizzle in Gadgetzan before the power source runs out."},
 [655]={["source"]="QuestieDB Forever",["text"]="Speak with Tor'gan in Hammerfall."},
 [656]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Go to the Shards of Myzrael, summon her and defeat her.\010Gather her Eldritch Shackles and bind them to the Shards of Myzrael."},
 [657]={["source"]="QuestieDB Forever",["text"]="Speak to Kinelory."},
 [658]={["source"]="QuestieDB Forever",["text"]="Find the Forsaken Courier and bring back her Sealed Folder to Quae near the Go'Shek Farm."},
 [659]={["source"]="QuestieDB Forever",["text"]="Find Quae and Kinelory near the Go'Shek Farm in the Arathi Highlands."},
 [660]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Protect Kinelory until she returns to Quae."},
 [661]={["source"]="QuestieDB Forever",["text"]="Find Phin Odelic in Southshore."},
 [662]={["source"]="QuestieDB Forever",["text"]="First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine."},
 [663]={["source"]="QuestieDB Forever",["text"]="Talk to Captain O'Breen in Faldir's Cove."},
 [664]={["source"]="QuestieDB Forever",["text"]="Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses."},
 [665]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Professor Phizzlethorpe to the cave and back."},
 [666]={["source"]="QuestieDB Forever",["text"]="Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done."},
 [667]={["complex"]=true,["extra"]={"Use the cannon"},["source"]="QuestieDB Forever",["text"]="Protect Shakes O'Breen during the attack.\010Use the cannon"},
 [668]={["source"]="QuestieDB Forever",["text"]="Take the Elven Gems to Captain O'Breen."},
 [669]={["source"]="QuestieDB Forever",["text"]="Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay."},
 [670]={["source"]="QuestieDB Forever",["text"]="Deliver Seahorn's Letter to Shakes O'Breen in Arathi Highlands."},
 [671]={["source"]="QuestieDB Forever",["text"]="Get 10 Bloodstone Amulets for Tor'gan in Hammerfall."},
 [672]={["source"]="QuestieDB Forever",["text"]="Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall."},
 [673]={["source"]="QuestieDB Forever",["text"]="Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall."},
 [674]={["source"]="QuestieDB Forever",["text"]="Give the Raptor Talon Amulet to Gor'mul."},
 [675]={["source"]="QuestieDB Forever",["text"]="Speak with Tor'gan."},
 [676]={["source"]="QuestieDB Forever",["text"]="Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands."},
 [677]={["source"]="QuestieDB Forever",["text"]="Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost."},
 [678]={["source"]="QuestieDB Forever",["text"]="Kill 10 Boulderfist Brutes and 4 Boulderfist Magi, and return to Drum Fel in the Hammerfall outpost."},
 [679]={["source"]="QuestieDB Forever",["text"]="Kill 7 Boulderfist Shaman and 3 Boulderfist Lords and return to Drum Fel in the Hammerfall outpost."},
 [680]={["source"]="QuestieDB Forever",["text"]="Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost."},
 [681]={["source"]="QuestieDB Forever",["text"]="Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries.\010Return to Captain Nials at Refuge Pointe."},
 [682]={["source"]="QuestieDB Forever",["text"]="Bring 7 Stromgarde Badges to Captain Nials at Refuge Pointe."},
 [683]={["source"]="QuestieDB Forever",["text"]="Take Sara Balloo's note to King Magni Bronzebeard of Ironforge."},
 [684]={["source"]="QuestieDB Forever",["text"]="Bring Marez's head to Captain Nials at Refuge Pointe."},
 [685]={["source"]="QuestieDB Forever",["text"]="Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe."},
 [686]={["source"]="QuestieDB Forever",["text"]="King Magni Bronzebeard wants you to speak with Grand Mason Marblesten."},
 [687]={["source"]="QuestieDB Forever",["text"]="Find Theldurin the Lost."},
 [688]={["source"]="QuestieDB Forever",["text"]="Speak with Zaruk in Hammerfall."},
 [689]={["source"]="QuestieDB Forever",["text"]="Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite."},
 [690]={["source"]="QuestieDB Forever",["text"]="Find Skuerto at Refuge Pointe in the Arathi Highlands."},
 [691]={["source"]="QuestieDB Forever",["text"]="Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe."},
 [692]={["source"]="QuestieDB Forever",["text"]="Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost."},
 [693]={["source"]="QuestieDB Forever",["text"]="Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe."},
 [694]={["source"]="QuestieDB Forever",["text"]="Find an Azure Agate and bring it to Apprentice Kryten at Refuge Pointe."},
 [695]={["source"]="QuestieDB Forever",["text"]="Speak to Skuerto."},
 [696]={["complex"]=true,["extra"]={"Use it"},["source"]="QuestieDB Forever",["text"]="Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.\010Use it"},
 [697]={["source"]="QuestieDB Forever",["text"]="Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind."},
 [698]={["source"]="QuestieDB Forever",["text"]="Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows."},
 [699]={["source"]="QuestieDB Forever",["text"]="Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows."},
 [700]={["source"]="QuestieDB Forever",["text"]="Report to King Magni Bronzebeard."},
 [701]={["source"]="QuestieDB Forever",["text"]="Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan."},
 [702]={["source"]="QuestieDB Forever",["text"]="Give Tor'gan's Orb to Gor'mul."},
 [703]={["source"]="QuestieDB Forever",["text"]="Bring 4 Buzzard Wings to Rigglefuzz."},
 [704]={["source"]="QuestieDB Forever",["text"]="Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan."},
 [705]={["source"]="QuestieDB Forever",["text"]="Bring 9 Blue Pearls to Rigglefuzz in the Badlands."},
 [706]={["source"]="QuestieDB Forever",["text"]="Acquire a Black Drake's Heart for Sigrun Ironhew."},
 [707]={["source"]="QuestieDB Forever",["text"]="Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan."},
 [708]={["source"]="QuestieDB Forever",["text"]="Take the Corroded Black Box to the Hall of Arms in Ironforge."},
 [709]={["source"]="QuestieDB Forever",["text"]="Bring the Tablet of Ryun'eh to Theldurin the Lost."},
 [710]={["source"]="QuestieDB Forever",["text"]="Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands."},
 [711]={["source"]="QuestieDB Forever",["text"]="Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands."},
 [712]={["source"]="QuestieDB Forever",["text"]="Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands."},
 [713]={["source"]="QuestieDB Forever",["text"]="Find Frost Oil and bring it to Lotwil Veriatus in Badlands."},
 [714]={["source"]="QuestieDB Forever",["text"]="Bring a Gyrochronatom to Lotwil Veriatus in the Badlands."},
 [715]={["source"]="QuestieDB Forever",["text"]="Bring a Healing Potion and a Lesser Invisibility Potion to Lucien Tosselwrench in the Badlands."},
 [716]={["source"]="QuestieDB Forever",["text"]="Bring some Patterned Bronze Bracers to Lucien Tosselwrench in the Badlands."},
 [717]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.\010Place the runestones in the Seal of the Earth to free Blacklash and Hematus.\010Slay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek."},
 [718]={["source"]="QuestieDB Forever",["text"]="Retrieve the Supply Crate for Sigrun Ironhew."},
 [719]={["source"]="QuestieDB Forever",["text"]="Find Ryedol's Lucky Pick and return it to Prospector Ryedol south of Hammertoe's Dig Site."},
 [720]={["source"]="QuestieDB Forever",["text"]="Find Prospector Ryedol and let him know Hammertoe Grez is alive."},
 [721]={["source"]="QuestieDB Forever",["text"]="Find Hammertoe Grez in Uldaman."},
 [722]={["source"]="QuestieDB Forever",["text"]="Find Hammertoe's Amulet and return it to him in Uldaman."},
 [723]={["source"]="QuestieDB Forever",["text"]="Take Hammertoe's Amulet to Prospector Ryedol in the Badlands."},
 [724]={["source"]="QuestieDB Forever",["text"]="Take Hammertoe's Amulet to Historian Karnik in Ironforge."},
 [725]={["source"]="QuestieDB Forever",["text"]="Find Advisor Belgrum and give him his note."},
 [726]={["source"]="QuestieDB Forever",["text"]="Speak to Historian Karnik."},
 [727]={["source"]="QuestieDB Forever",["text"]="Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge."},
 [728]={["source"]="QuestieDB Forever",["text"]="Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity."},
 [729]={["source"]="QuestieDB Forever",["text"]="Travel south and check on Prospector Remtravel."},
 [730]={["source"]="QuestieDB Forever",["text"]="Travel to Auberdine and look for signs of the dwarven excavation team."},
 [731]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine."},
 [732]={["source"]="QuestieDB Forever",["text"]="Retrieve the Sign of the Earth for Garek."},
 [733]={["source"]="QuestieDB Forever",["text"]="Get 7 pieces of Scrap Metal for Sigrun."},
 [734]={["source"]="QuestieDB Forever",["text"]="Speak to Lucien Tosselwrench in the Badlands."},
 [735]={["complex"]=true,["extra"]={"Summon Dagun the Ravenous using an Enchanted Sea Kelp"},["source"]="QuestieDB Forever",["text"]="Return the items on the Bonegrip's Note to Gerrig Bonegrip in Ironforge.\010Summon Dagun the Ravenous using an Enchanted Sea Kelp"},
 [736]={["complex"]=true,["extra"]={"Summon Dagun the Ravenous using an Enchanted Sea Kelp"},["source"]="QuestieDB Forever",["text"]="Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity.\010Summon Dagun the Ravenous using an Enchanted Sea Kelp"},
 [737]={["source"]="QuestieDB Forever",["text"]="Bring Yagyin's Digest to Theldurin."},
 [738]={["source"]="QuestieDB Forever",["text"]="Find Agmond."},
 [739]={["source"]="QuestieDB Forever",["text"]="Slay Agmond's killer, Murdaloc.\010Slay 12 Stonevault Bonesnappers.\010Report to Prospector Ironband in Loch Modan."},
 [741]={["source"]="QuestieDB Forever",["text"]="Take the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus."},
 [742]={["source"]="QuestieDB Forever",["text"]="Speak with Senani Thunderheart at Splintertree Post, Ashenvale."},
 [743]={["source"]="QuestieDB Forever",["text"]="Bring 8 Windfury Talons to Ruul Eagletalon in Bloodhoof Village."},
 [744]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 6 Azure Feathers and 6 Bronze Feathers, and bring them to Eyahn Eagletalon in Thunder Bluff."},
 [745]={["source"]="QuestieDB Forever",["text"]="Kill 10 Palemane Tanners, 8 Palemane Skinners, and 5 Palemane Poachers, then return to Baine Bloodhoof in Bloodhoof Village."},
 [746]={["source"]="QuestieDB Forever",["text"]="Collect 5 Prospector's Picks.\010At a forge, smash the Prospector's Picks to create Broken Tools.\010Bring 5 Broken Tools to Baine Bloodhoof in Bloodhoof Village."},
 [747]={["source"]="QuestieDB Forever",["text"]="Grull Hawkwind in Camp Narache wants you to bring him 7 Plainstrider Feathers and 7 pieces of Plainstrider Meat."},
 [748]={["source"]="QuestieDB Forever",["text"]="Bring 6 Prairie Wolf Paws and 4 Plainstrider Talons to Mull Thunderhorn in Bloodhoof."},
 [749]={["source"]="QuestieDB Forever",["text"]="Morin Cloudstalker wants you to examine the contents of a supply crate at the Ravaged Caravan."},
 [750]={["source"]="QuestieDB Forever",["text"]="Grull Hawkwind in Camp Narache wants you to bring him 10 Mountain Cougar Pelts."},
 [751]={["source"]="QuestieDB Forever",["text"]="Return the Venture Co. Documents to Morin Cloudstalker near Bloodhoof Village."},
 [752]={["source"]="QuestieDB Forever",["text"]="Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache."},
 [753]={["source"]="QuestieDB Forever",["text"]="Take a Water Pitcher from the water well.\010Return the pitcher to Chief Hawkwind in Camp Narache which is northwest from the water well."},
 [754]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Winterhoof Cleansing Totem at the Winterhoof Water Well, then return to Mull Thunderhorn."},
 [755]={["source"]="QuestieDB Forever",["text"]="Travel to Seer Graytongue who lives in the hills directly south of Camp Narache."},
 [756]={["source"]="QuestieDB Forever",["text"]="Bring 6 Stalker Claws and 6 Cougar Claws to Mull Thunderhorn."},
 [757]={["source"]="QuestieDB Forever",["text"]="Kill Bristlebacks in Brambleblade Ravine and bring 12 Bristleback Belts to Chief Hawkwind in Camp Narache."},
 [758]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well, then return to Mull."},
 [759]={["source"]="QuestieDB Forever",["text"]="Bring 8 Prairie Alpha Teeth to Mull Thunderhorn in Bloodhoof Village."},
 [760]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn."},
 [761]={["source"]="QuestieDB Forever",["text"]="Bring 8 Trophy Swoop Quills to Harken Windtotem in Bloodhoof Village."},
 [762]={["source"]="QuestieDB Forever",["text"]="Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge."},
 [763]={["source"]="QuestieDB Forever",["text"]="Take the Totem of Hawkwind to Baine Bloodhoof in Bloodhoof Village. Follow the road out of Camp Narache."},
 [764]={["source"]="QuestieDB Forever",["text"]="Kill 14 Venture Co. Workers and 6 Venture Co. Supervisors for Morin Cloudstalker at Bloodhoof Village."},
 [765]={["source"]="QuestieDB Forever",["text"]="Kill Supervisor Fizsprocket and return his clipboard to Morin Cloudstalker at Bloodhoof Village."},
 [766]={["source"]="QuestieDB Forever",["text"]="Bring a Prairie Wolf Heart, Flatland Cougar Femur, Plainstrider Scale and Swoop Gizzard to Maur Raincaller at Bloodhoof Village."},
 [767]={["source"]="QuestieDB Forever",["text"]="Speak with Zarlman Two-Moons in Bloodhoof Village."},
 [768]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff."},
 [769]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring 4 Light Leather and 4 Coarse Thread to Veren Tallstrider in Thunder Bluff."},
 [770]={["source"]="QuestieDB Forever",["text"]="Find someone who knows of Ghost Howl."},
 [771]={["source"]="QuestieDB Forever",["text"]="Collect 2 Well Stones and 2 Ambercorn and bring them back to Zarlman Two-Moons in Bloodhoof Village."},
 [772]={["source"]="QuestieDB Forever",["text"]="Consume the Water of the Seers in front of the tribal fire in Bloodhoof Village and follow the vision once it appears."},
 [773]={["source"]="QuestieDB Forever",["text"]="Travel to Red Rocks east of Thunder Bluff and speak with the Ancestral Spirit."},
 [775]={["source"]="QuestieDB Forever",["text"]="Speak with Cairne Bloodhoof in Thunder Bluff."},
 [776]={["source"]="QuestieDB Forever",["text"]="Cairne Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea."},
 [777]={["source"]="QuestieDB Forever",["text"]="Bring Cog #5 to Lotwil Veriatus."},
 [778]={["source"]="QuestieDB Forever",["text"]="Defeat the Fam'retor Guardian and bring Lotwil's Shackles of Elemental Binding back to Lotwil Veriatus."},
 [780]={["source"]="QuestieDB Forever",["text"]="Grull Hawkwind in Camp Narache wants you to kill Battleboars and bring back 8 Battleboar Snouts and 8 Battleboar Flanks."},
 [781]={["source"]="QuestieDB Forever",["text"]="Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache."},
 [782]={["source"]="QuestieDB Forever",["text"]="Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath."},
 [783]={["source"]="QuestieDB Forever",["text"]="Speak with Marshal McBride."},
 [784]={["source"]="QuestieDB Forever",["text"]="Kill 10 Kul Tiras Sailors, 8 Kul Tiras Marines and Lieutenant Benedict and return to Gar'Thok in Razor Hill."},
 [786]={["source"]="QuestieDB Forever",["text"]="Lar Prowltusk outside of Sen'jin Village wants you to destroy the 3 sets of Attack Plans held within Kolkar Crag."},
 [787]={["source"]="QuestieDB Forever",["text"]="Report to Gornek in the Den."},
 [788]={["source"]="QuestieDB Forever",["text"]="Kill 10 Mottled Boars then return to Gornek at the Den."},
 [789]={["source"]="QuestieDB Forever",["text"]="Get 10 Scorpid Worker Tails for Gornek in the Den."},
 [790]={["source"]="QuestieDB Forever",["text"]="Kill Sarkoth and bring his claw back to Hana'zua."},
 [791]={["source"]="QuestieDB Forever",["text"]="Furl Scornbrow in the Razor Hill watchtower wants 8 Canvas Scraps."},
 [792]={["source"]="QuestieDB Forever",["text"]="Kill 12 Vile Familiars.\010Return to Zureetha Fargaze outside the Den."},
 [793]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Sign of the Earth to activate the Pillars of Diamond, Opal, and Amethyst and obtain the Runestones.\010Place the runestones in the Seal of the Earth to free Blacklash and Hematus.\010Slay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Gorn."},
 [794]={["source"]="QuestieDB Forever",["text"]="Bring the Burning Blade Medallion to Zureetha Fargaze, outside The Den."},
 [804]={["source"]="QuestieDB Forever",["text"]="Bring the news of Hana'zua's plight to Gornek at the Den."},
 [805]={["source"]="QuestieDB Forever",["text"]="Speak with Master Gadrin in Sen'jin Village."},
 [806]={["source"]="QuestieDB Forever",["text"]="Bring Fizzle's Claw to Orgnil Soulscar in Razor Hill."},
 [808]={["source"]="QuestieDB Forever",["text"]="Retrieve Minshina's skull from the circle of power on the Echo Isles.\010Bring it to Master Gadrin in Sen'jin Village."},
 [809]={["source"]="QuestieDB Forever",["text"]="Speak with Ak'Zeloth in the Barrens."},
 [812]={["source"]="QuestieDB Forever",["text"]="Find Kor'ghan in Orgrimmar and get the Venomtail Antidote. Then bring the antidote to Rhinag near the northwestern border of Durotar."},
 [813]={["source"]="QuestieDB Forever",["text"]="Bring 4 Venomtail Poison Sacs to Kor'ghan in Orgrimmar."},
 [815]={["source"]="QuestieDB Forever",["text"]="Bring 3 Taillasher Eggs to Cook Torka in Razor Hill."},
 [816]={["source"]="QuestieDB Forever",["text"]="Bring a sign of Kron's fate to Misha Tor'kren at the farmstead northwest of Razor Hill."},
 [817]={["source"]="QuestieDB Forever",["text"]="Bring 4 Durotar Tiger Furs to Vel'rin Fang in Sen'jin Village."},
 [818]={["source"]="QuestieDB Forever",["text"]="Bring 4 Intact Makrura Eyes and 8 vials of Crawler Mucus to Master Vornal in Sen'jin Village."},
 [819]={["source"]="QuestieDB Forever",["text"]="Find someone who knows about Chen's Empty Keg."},
 [821]={["source"]="QuestieDB Forever",["text"]="Bring 5 Savannah Lion Tusks, 5 Plainstrider Kidneys, and 1 Thunder Lizard Horn to Brewmaster Drohn in Ratchet."},
 [822]={["source"]="QuestieDB Forever",["text"]="Bring 5 Lightning Glands, 1 Thunderhawk Saliva Gland and 1 Kodo Liver to Brewmaster Drohn in Ratchet."},
 [823]={["source"]="QuestieDB Forever",["text"]="Speak with Orgnil Soulscar in Razor Hill."},
 [824]={["source"]="QuestieDB Forever",["text"]="Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."},
 [825]={["source"]="QuestieDB Forever",["text"]="Gar'Thok of Razor Hill wants you to retrieve 3 Gnomish Tools from the wreckage off the coast."},
 [826]={["source"]="QuestieDB Forever",["text"]="Defeat Zalazane.\010Kill 8 Voodoo Trolls and 8 Hexed Trolls.\010Bring Zalazane's Head to Gadrin."},
 [827]={["source"]="QuestieDB Forever",["text"]="Gather Searing Collars from the cultists in Skull Rock.\010Bring them to Margoz at his camp."},
 [828]={["source"]="QuestieDB Forever",["text"]="Speak with Margoz."},
 [829]={["source"]="QuestieDB Forever",["text"]="Bring an Example Collar to Neeru Fireblade in Orgrimmar."},
 [830]={["source"]="QuestieDB Forever",["text"]="Take Admiral Proudmoore's Orders to Gar'Thok in Razor Hill."},
 [831]={["source"]="QuestieDB Forever",["text"]="Deliver Admiral Proudmoore's Orders to Nazgrel in Thrall's chamber in Orgrimmar."},
 [832]={["source"]="ForeverDungeonJournal learned client text",["text"]="Take this eye to Neeru Fireblade."},
 [833]={["source"]="QuestieDB Forever",["text"]="Lorekeeper Raintotem wants you to kill 8 Bristleback Interlopers at Red Rocks."},
 [834]={["source"]="QuestieDB Forever",["text"]="Retrieve 5 Sacks of Supplies and return them to Rezlak near Orgrimmar."},
 [835]={["source"]="QuestieDB Forever",["text"]="Kill 12 Dustwind Savages and 8 Dustwind Storm Witches for Rezlak near Drygulch Ravine."},
 [836]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort OOX-09/HL to the shoreline beyond Overlook Cliff, then report to Oglethorpe Obnoticus in Booty Bay."},
 [837]={["source"]="QuestieDB Forever",["text"]="Kill 4 Razormane Quilboars, 4 Razormane Scouts, 4 Razormane Dustrunners and 4 Razormane Battleguards for Gar'Thok at Razor Hill."},
 [838]={["source"]="QuestieDB Forever",["text"]="Speak with Apothecary Dithers at the Bulwark, Western Plaguelands."},
 [840]={["source"]="QuestieDB Forever",["text"]="Follow the western road from Razor Hill to the Barrens over a bridge.\010Stop at the orc outpost across the bridge.\010Give Kargal Battlescar at the Barrens outpost your recruitment letter."},
 [841]={["source"]="QuestieDB Forever",["text"]="Bring 10 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan in exchange for another power source."},
 [842]={["source"]="QuestieDB Forever",["text"]="Follow the western road from Kargal's Far Watch Outpost.\010At the T intersection, turn left and follow the road south.\010Find Sergra Darkthorn at the crossing of roads within the Crossroads."},
 [843]={["source"]="QuestieDB Forever",["text"]="Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.\010Bring Khazgorm's Journal to Gann Stonespire."},
 [844]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 7 Plainstrider Beaks and return them to Sergra Darkthorn in the Crossroads."},
 [845]={["source"]="ForeverDungeonJournal learned client text",["text"]="Slay Zhevra Runners to collect 4 Zhevra Hooves for Sergra Darkthorn in the Crossroads."},
 [846]={["source"]="QuestieDB Forever",["text"]="Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate."},
 [847]={["source"]="QuestieDB Forever",["text"]="Speak with Tor'gan."},
 [848]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring 4 Fungal Spores to Apothecary Helbrim at the Crossroads."},
 [849]={["source"]="QuestieDB Forever",["text"]="Destroy the flying machine at Bael Modan and return to Gann Stonespire."},
 [850]={["source"]="QuestieDB Forever",["text"]="Bring Barak's Head to Regthar Deathgate, west of the Crossroads."},
 [851]={["source"]="QuestieDB Forever",["text"]="Bring Verog's Head to Regthar Deathgate, west of the Crossroads."},
 [852]={["source"]="QuestieDB Forever",["text"]="Bring Hezrul's Head to Regthar Deathgate, west of the Crossroads."},
 [853]={["source"]="QuestieDB Forever",["text"]="Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up."},
 [854]={["source"]="QuestieDB Forever",["text"]="Speak with Thork at the Crossroads in the Barrens."},
 [855]={["source"]="QuestieDB Forever",["text"]="Bring 15 Centaur Bracers to Regthar Deathgate, west of the Crossroads."},
 [857]={["source"]="QuestieDB Forever",["text"]="Feegly the Exiled wants you to retrieve for him the Tear of the Moons."},
 [858]={["source"]="QuestieDB Forever",["text"]="Get the Ignition Key and bring it to Wizzlecrank."},
 [860]={["source"]="QuestieDB Forever",["text"]="Speak with Sergra Darkthorn at the Crossroads."},
 [861]={["source"]="QuestieDB Forever",["text"]="Bring 4 Flatland Prowler Claws to Melor Stonehoof in Thunder Bluff."},
 [862]={["source"]="QuestieDB Forever",["text"]="Bring 8 Dig Rats to Grub east of the Crossroads."},
 [863]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Protect Wizzlecrank and the stolen goblin shredder on the way to Sputtervalve in Ratchet."},
 [864]={["source"]="QuestieDB Forever",["text"]="Bring the Sealed Field Testing Kit to Apothecary Zinge in the Undercity."},
 [865]={["source"]="QuestieDB Forever",["text"]="Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet."},
 [866]={["source"]="QuestieDB Forever",["text"]="Bring 8 Root Samples to Mebok Mizzyrix in Ratchet."},
 [867]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 8 Witchwing talons.\010\010Return them to Darsok Swiftdagger at the Crossroads."},
 [868]={["source"]="QuestieDB Forever",["text"]="Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads."},
 [869]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring 12 Raptor Heads to Gazrog at the Crossroads."},
 [870]={["source"]="ForeverDungeonJournal learned client text",["text"]="Report back to Tonga Runetotem with your findings."},
 [871]={["source"]="ForeverDungeonJournal learned client text",["text"]="Of the Razormane tribe, kill 8 Water Seekers, 8 Thornweavers and 3 Hunters, and then return to Thork in the Crossroads."},
 [872]={["source"]="QuestieDB Forever",["text"]="Kill 8 Razormane Geomancers, 8 Razormane Defenders, and Kreenig Snarlsnout.\010Then bring Kreenig Snarlsnout's Tusk to Thork at the Crossroads."},
 [873]={["source"]="QuestieDB Forever",["text"]="Bring the Heart of Isha Awak to Mahren Skyseer."},
 [874]={["source"]="QuestieDB Forever",["text"]="Speak with Mahren Skyseer."},
 [875]={["source"]="QuestieDB Forever",["text"]="Collect 6 Harpy Lieutenant Rings from Witchwing Slayers and return them to Darsok Swiftdagger at the Crossroads."},
 [876]={["source"]="QuestieDB Forever",["text"]="Slay Serena Bloodfeather and return her head to Darsok Swiftdagger at the Crossroads."},
 [877]={["source"]="QuestieDB Forever",["text"]="Return to Tonga at The Crossroads, after investigating the Stagnant Oasis."},
 [878]={["source"]="QuestieDB Forever",["text"]="Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens."},
 [879]={["source"]="QuestieDB Forever",["text"]="Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens."},
 [880]={["source"]="QuestieDB Forever",["text"]="Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads."},
 [881]={["source"]="QuestieDB Forever",["text"]="Bring Echeyakee's Hide to Sergra Darkthorn at the Crossroads."},
 [882]={["source"]="QuestieDB Forever",["text"]="Bring Ishamuhale's Fang to Jorn at Camp Taurajo."},
 [883]={["source"]="QuestieDB Forever",["text"]="Bring the Hoof of Lakota'mani to Jorn at Camp Taurajo."},
 [884]={["source"]="QuestieDB Forever",["text"]="Bring Owatanka's Tailspike to Jorn at Camp Taurajo."},
 [885]={["source"]="QuestieDB Forever",["text"]="Bring Washte Pawne's Feather to Jorn Skyseer at Camp Taurajo."},
 [886]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Tonga Runetotem at the Crossroads."},
 [887]={["source"]="QuestieDB Forever",["text"]="Kill 12 Southsea Brigands and 6 Southsea Cannoneers for Gazlowe in Ratchet."},
 [888]={["source"]="QuestieDB Forever",["text"]="Retrieve the Shipment of Boots and Telescopic Lens for Gazlowe in Ratchet."},
 [890]={["source"]="QuestieDB Forever",["text"]="Bring Gazlowe's Ledger to Wharfmaster Dizzywig."},
 [891]={["source"]="QuestieDB Forever",["text"]="Captain Thalo'thas Brightsun of Ratchet wants you to collect 10 Theramore Medals and slay Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe."},
 [892]={["source"]="QuestieDB Forever",["text"]="Return Gazlowe's Ledger to Gazlowe in Ratchet."},
 [893]={["source"]="QuestieDB Forever",["text"]="Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens."},
 [894]={["source"]="ForeverDungeonJournal learned client text",["text"]="Access the control console at the Venture Company research site."},
 [895]={["source"]="QuestieDB Forever",["text"]="Bring the head of Baron Longshore to Gazlowe in Ratchet."},
 [896]={["source"]="ForeverDungeonJournal learned client text",["text"]="Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers for Wharfmaster Dizzywig at Ratchet."},
 [897]={["source"]="QuestieDB Forever",["text"]="Bring the Harvester's Head to Jorn Skyseer."},
 [898]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Safely escort Gilthares Firebough back to Captain Brightsun in Ratchet."},
 [899]={["source"]="QuestieDB Forever",["text"]="Bring 60 Bristleback Quilboar Tusks to Mankrik at the Crossroads."},
 [900]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again."},
 [901]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Get the Console Key from Tinkerer Sniggles to use on the control console."},
 [902]={["source"]="QuestieDB Forever",["text"]="Return the Samophlange to Sputtervalve in Ratchet."},
 [903]={["source"]="QuestieDB Forever",["text"]="Collect 7 Prowler Claws from Savannah Prowlers for Sergra Darkthorn in the Crossroads."},
 [905]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Scytheclaw nests. Return to Sergra Darkthorn in the Crossroads."},
 [906]={["source"]="QuestieDB Forever",["text"]="Bring Lok's Skull to Thork at the Crossroads in the Barrens."},
 [907]={["source"]="QuestieDB Forever",["text"]="Bring 3 Thunder Lizard Blood to Jorn Skyseer at Camp Taurajo."},
 [910]={["source"]="QuestieDB Forever",["text"]="Take your ward to the docks of Ratchet in the Barrens."},
 [911]={["source"]="QuestieDB Forever",["text"]="Take your ward to the Mor'shan Rampart in the northern part of the Barrens, just before entering Ashenvale."},
 [913]={["source"]="QuestieDB Forever",["text"]="Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo."},
 [914]={["source"]="QuestieDB Forever",["text"]="Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff."},
 [915]={["source"]="QuestieDB Forever",["text"]="Get some Strawberry Ice Cream for your ward. The lad seems to prefer Tigule's brand ice cream."},
 [916]={["source"]="QuestieDB Forever",["text"]="Bring 10 Webwood Venom Sacs to Gilshalan Windwalker at Aldrassil."},
 [917]={["source"]="QuestieDB Forever",["text"]="Bring a Webwood Egg to Gilshalan in Aldrassil."},
 [918]={["source"]="QuestieDB Forever",["text"]="Bring 8 Timberling Seeds to Denelan at Lake Al'Ameth."},
 [919]={["source"]="QuestieDB Forever",["text"]="Bring 12 Timberling Sprouts to Denalan at Lake Al'Ameth."},
 [920]={["source"]="QuestieDB Forever",["text"]="Speak with Tenaron Stormgrip atop Aldrassil in Shadowglen."},
 [921]={["source"]="QuestieDB Forever",["text"]="Fill the Crystal Phial and bring it back to Tenaron Stormgrip atop Aldrassil."},
 [922]={["source"]="QuestieDB Forever",["text"]="Bring a Timberling Seed to Rellian Greenspyre in Darnassus."},
 [923]={["source"]="QuestieDB Forever",["text"]="Bring 5 Mossy Tumors to Rellian Greenspyre in Darnassus."},
 [924]={["source"]="QuestieDB Forever",["text"]="Grab a Flawed Power Stone. Bring it to the Altar of Fire before the stone expires, then return to Ak'Zeloth."},
 [925]={["source"]="QuestieDB Forever",["text"]="Travel to Thunder Bluff to see about getting Cairne Bloodhoof's hoofprint for your ward."},
 [927]={["source"]="QuestieDB Forever",["text"]="Bring the Moss-twined Heart to Denalan at Lake Al'Ameth."},
 [928]={["source"]="QuestieDB Forever",["text"]="Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar."},
 [929]={["source"]="QuestieDB Forever",["text"]="Fill the Jade Phial and bring it back to Corithras Moonrage in Dolanaar."},
 [930]={["source"]="QuestieDB Forever",["text"]="Bring the glowing fruit to Denalan at Lake Al'Ameth."},
 [931]={["source"]="QuestieDB Forever",["text"]="Bring a Shimmering Frond to Denalan at Lake Al'Ameth"},
 [932]={["source"]="QuestieDB Forever",["text"]="Kill Lord Melenas and bring his head to Tallonkai Swiftroot in Dolanaar."},
 [933]={["source"]="QuestieDB Forever",["text"]="Fill the Tourmaline Phial and bring it back to Corithras Moonrage in Dolanaar."},
 [934]={["source"]="QuestieDB Forever",["text"]="Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar."},
 [935]={["source"]="QuestieDB Forever",["text"]="Bring the Filled Vessel to Arch Druid Fandral Staghelm in Darnassus."},
 [936]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Hamuul Runetotem in Thunder Bluff."},
 [937]={["source"]="QuestieDB Forever",["text"]="Acquire 6 Bloodfeather Belts and bring them to Sentinel Arynia Cloudsbreak in the Oracle Glade."},
 [938]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Mist to Sentinel Arynia Cloudsbreak at the moon well near the Oracle Tree."},
 [939]={["source"]="QuestieDB Forever",["text"]="Bring the Flute of Xavaric and 5 Jadefire Felbind samples to Eridan Bluewind in southern Felwood."},
 [940]={["source"]="QuestieDB Forever",["text"]="Deliver the Oracle Tree's report to Arch Druid Fandral Staghelm in Darnassus."},
 [941]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Plant the Tainted Heart in Denalan's Planter."},
 [942]={["source"]="QuestieDB Forever",["text"]="Take the mysterious fossil to Archaeologist Flagongut in Menethil Harbor."},
 [943]={["source"]="QuestieDB Forever",["text"]="Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil."},
 [944]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Gather information, then use the Phial of Scrying to create a Scrying Bowl. Use the bowl to speak with Onu."},
 [945]={["source"]="QuestieDB Forever",["text"]="Help Therylune escape, then tell Therysil at the Shrine of Aessina that her sister is safe."},
 [947]={["source"]="QuestieDB Forever",["text"]="Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine."},
 [948]={["source"]="QuestieDB Forever",["text"]="Speak with Onu at the Grove of the Ancients."},
 [949]={["source"]="QuestieDB Forever",["text"]="Find a clue in the Twilight's Hammer camp at the Master's Glaive."},
 [950]={["source"]="QuestieDB Forever",["text"]="Bring Onu the recovered Insane Scribbles."},
 [951]={["source"]="QuestieDB Forever",["text"]="Bring 6 Mathystra Relics to Onu at the Grove of the Ancients."},
 [952]={["source"]="QuestieDB Forever",["text"]="Deliver Fandral's message to Onu in the Grove of the Ancients in Darkshore, south of Auberdine."},
 [953]={["source"]="QuestieDB Forever",["text"]="Study the tablets which tell of Ameth'Aran and of its fall, then return to Sentinel Tysha Moonblade in Darkshore."},
 [954]={["source"]="QuestieDB Forever",["text"]="Find the source of the strange blue aura in the ruins of Bashal'Aran."},
 [955]={["source"]="QuestieDB Forever",["text"]="Acquire 8 Grell Earrings for Asterion in Bashal'Aran."},
 [956]={["source"]="QuestieDB Forever",["text"]="Obtain the Ancient Moonstone Seal and bring it to Asterion in Bashal'Aran."},
 [957]={["source"]="QuestieDB Forever",["text"]="Destroy the Ancient Moonstone Seal at the ancient flame in Ameth'Aran, then return to Asterion in Bashal'Aran."},
 [958]={["source"]="QuestieDB Forever",["text"]="Retrieve 7 Highborne Relics for Thundris Windweaver in Auberdine."},
 [959]={["source"]="ForeverDungeonJournal learned client text",["text"]="Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns."},
 [962]={["source"]="QuestieDB Forever",["text"]="Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom."},
 [963]={["source"]="QuestieDB Forever",["text"]="Free the spirit of Anaya Dawnrunner and bring her pendant back to Cerellean Whiteclaw in Auberdine."},
 [964]={["source"]="QuestieDB Forever",["text"]="Bring 15 Skeletal Fragments to Apothecary Dithers at the Bulwark, Western Plaguelands."},
 [965]={["source"]="QuestieDB Forever",["text"]="Find Balthule Shadowstrike near the Tower of Althalaxx in Darkshore."},
 [966]={["source"]="QuestieDB Forever",["text"]="Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx."},
 [967]={["source"]="QuestieDB Forever",["text"]="Deliver Balthule's letter to Delgren the Purifier in Ashenvale Forest."},
 [968]={["source"]="QuestieDB Forever",["text"]="Bring the Book: The Powers Below to Gerrig Bonegrip in the Forlorn Cavern, Ironforge."},
 [969]={["source"]="QuestieDB Forever",["text"]="Collect 4 Frostmaul Shards for Witch Doctor Mau'ari in Everlook."},
 [970]={["source"]="QuestieDB Forever",["text"]="Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post."},
 [971]={["source"]="QuestieDB Forever",["text"]="Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge."},
 [973]={["source"]="QuestieDB Forever",["text"]="Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post."},
 [974]={["source"]="QuestieDB Forever",["text"]="Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.\010Whenever you find a hot spot, right click the thermometer to check the temperature. Keep looking until you find the hottest one."},
 [975]={["source"]="QuestieDB Forever",["text"]="Speak to Witch Doctor Mau'ari again in a moment to receive the lucky charm."},
 [976]={["source"]="QuestieDB Forever",["text"]="Speak with Delgren the Purifier at Maestra's Post after seeing Feero safely through Ashenvale Forest."},
 [977]={["source"]="QuestieDB Forever",["text"]="Collect 2 Pristine Yeti Horns for Umi Rumplesnicker in Everlook."},
 [978]={["source"]="QuestieDB Forever",["text"]="Collect 10 Moontouched Feathers from Winterspring, then return to Erelas Ambersky in Rut'theran Village."},
 [979]={["source"]="QuestieDB Forever",["text"]="Find Ranshalla in eastern Winterspring."},
 [980]={["source"]="QuestieDB Forever",["text"]="Travel to Winterspring and speak with Donova Snowden."},
 [981]={["source"]="QuestieDB Forever",["text"]="Talk to Delgren the Purifier at Maestra's Post."},
 [982]={["source"]="QuestieDB Forever",["text"]="Recover the Silver Dawning's Lockbox and the Mist Veil's Lockbox for Gorbold Steelhand in Auberdine. Both items should be found aboard the wreckage of the ships to the north of the village."},
 [983]={["source"]="QuestieDB Forever",["text"]="Collect 6 Crawler Legs and place them in Buzzbox 827."},
 [984]={["source"]="QuestieDB Forever",["text"]="Find a corrupt furbolg camp in Darkshore and return to Terenthis in Auberdine."},
 [985]={["source"]="QuestieDB Forever",["text"]="Kill 8 Blackwood Pathfinders and 5 Windtalkers and return to Terenthis in Auberdine."},
 [986]={["source"]="QuestieDB Forever",["text"]="Find 5 Fine Moonstalker Pelts and return them to Terenthis in Auberdine."},
 [990]={["source"]="QuestieDB Forever",["text"]="Find Raene Wolfrunner in Ashenvale."},
 [991]={["source"]="QuestieDB Forever",["text"]="Find Teronis in Ashenvale."},
 [992]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the untapped dowsing widget near the pool of water by Sandsorrow Watch. Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan."},
 [993]={["source"]="QuestieDB Forever",["text"]="Find Volcor in Darkshore and give him the Enchanted Moonstalker Cloak."},
 [994]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Protect Volcor until you reach the road, then speak to Terenthis in Auberdine."},
 [995]={["source"]="QuestieDB Forever",["text"]="Escape the Furbolg cave and meet Terenthis in Auberdine."},
 [997]={["source"]="QuestieDB Forever",["text"]="Bring the package of Rare Earth to Denalan at Lake Al'Ameth."},
 [1000]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor."},
 [1001]={["source"]="QuestieDB Forever",["text"]="Collect 3 Thresher Eyes from Darkshore Threshers in the deep sea near Buzzbox 411."},
 [1002]={["source"]="QuestieDB Forever",["text"]="Collect 6 Moonstalker Fangs and place them in Buzzbox 323."},
 [1003]={["source"]="QuestieDB Forever",["text"]="Collect 4 Grizzled Scalps from Grizzled Thistle Bears to the south of Auberdine and place them in Buzzbox 525."},
 [1004]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor."},
 [1007]={["source"]="QuestieDB Forever",["text"]="Bring the Ancient Statuette to Talen, in his camp near the Zoram Strand."},
 [1008]={["source"]="QuestieDB Forever",["text"]="Bring 20 Wrathtail Heads to Shindrell Swiftfire in Astranaar."},
 [1009]={["source"]="QuestieDB Forever",["text"]="Bring the Ring of Zoram to Talen near the Zoram Strand."},
 [1010]={["source"]="QuestieDB Forever",["text"]="Bring 5 Bathran's Hair to Orendil Broadleaf in Ashenvale."},
 [1011]={["source"]="QuestieDB Forever",["text"]="Bring a Bottle of Disease to Kayneth Stillwind in Forest Song."},
 [1012]={["source"]="QuestieDB Forever",["text"]="Kill the druids: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; then return to Kayneth Stillwind in Forest Song."},
 [1013]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity."},
 [1014]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher."},
 [1015]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor."},
 [1016]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Collect 5 Intact Elemental Bracers and use the Divining Scroll on them. Afterwards, bring the Divined Scroll to Sentinel Velene Starstrike at the Silverwind Refuge."},
 [1017]={["source"]="QuestieDB Forever",["text"]="Slay Sarilus Foulborne and bring his head to Sentinel Velene Starstrike in Silverwind Refuge."},
 [1018]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor."},
 [1019]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor."},
 [1020]={["source"]="QuestieDB Forever",["text"]="Bring Orendil's Cure to Pelturas Whitemoon in Astranaar."},
 [1021]={["source"]="QuestieDB Forever",["text"]="Find Anilia in Xavian."},
 [1022]={["source"]="QuestieDB Forever",["text"]="Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at Forest Song."},
 [1023]={["source"]="QuestieDB Forever",["text"]="Find the Glowing Gem and return to Raene Wolfrunner in Astranaar with Teronis' Journal."},
 [1024]={["source"]="QuestieDB Forever",["text"]="Find Shael'dryn at the moonwell to the northeast."},
 [1025]={["source"]="QuestieDB Forever",["text"]="Kill 1 Den Watcher, 2 Ursas, 10 Totemics, and 12 Warriors of the Foulweald tribe, and then return to Raene Wolfrunner in Astranaar."},
 [1026]={["source"]="QuestieDB Forever",["text"]="Find the Wooden Key and a piece of Dartol's Rod before returning to Shael'dryn at the moonwell."},
 [1027]={["complex"]=true,["extra"]={"Slay slimes until they leave behind a Rusty Chest"},["source"]="QuestieDB Forever",["text"]="Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell.\010Slay slimes until they leave behind a Rusty Chest"},
 [1028]={["source"]="QuestieDB Forever",["text"]="Find the hidden shrine and re-enchant Dartol's Rod."},
 [1029]={["source"]="QuestieDB Forever",["text"]="Return to Raene Wolfrunner in Astranaar."},
 [1030]={["source"]="QuestieDB Forever",["text"]="Find an uncorrupted furbolg, and using the power of Dartol's Rod of Transformation, speak to him."},
 [1031]={["source"]="QuestieDB Forever",["text"]="Kill Geltharis and return the Branch of Cenarius to Illiyana at Forest Song."},
 [1032]={["source"]="QuestieDB Forever",["text"]="Bring 16 Satyr Horns to Illiyana in Forest Song."},
 [1033]={["source"]="QuestieDB Forever",["text"]="Bring Elune's Tear to Pelturas in Astranaar."},
 [1034]={["source"]="QuestieDB Forever",["text"]="Bring 5 Handfuls of Stardust to Pelturas in Astranaar."},
 [1035]={["source"]="QuestieDB Forever",["text"]="Retrieve a Fallen Moonstone from the Shadethicket Oracle, then bring it to Pelturas in Astranaar."},
 [1036]={["source"]="QuestieDB Forever",["text"]="Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale."},
 [1037]={["source"]="QuestieDB Forever",["text"]="Speak with Thyn'tel Bladeweaver at the Warrior's Terrace in Darnassus."},
 [1038]={["source"]="QuestieDB Forever",["text"]="Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus."},
 [1039]={["source"]="QuestieDB Forever",["text"]="Speak with Wharfmaster Dizzywig in Ratchet."},
 [1040]={["source"]="QuestieDB Forever",["text"]="Take a boat to Booty Bay and speak with Caravaneer Ruzzgot."},
 [1041]={["source"]="QuestieDB Forever",["text"]="Speak with Clerk Daltry in Darkshire."},
 [1042]={["source"]="QuestieDB Forever",["text"]="Speak with Jonathan Carevin in Darkshire."},
 [1043]={["source"]="QuestieDB Forever",["text"]="Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire."},
 [1044]={["source"]="QuestieDB Forever",["text"]="Return to Thyn'tel Bladeweaver in Darnassus."},
 [1045]={["source"]="QuestieDB Forever",["text"]="Kill Ran Bloodtooth and 4 Bloodtooth Guards and return to Krolg near Lake Mystral."},
 [1046]={["source"]="QuestieDB Forever",["text"]="Bring Ran Bloodtooth's Skull and Dartol's Rod of Transformation to Raene Wolfrunner in Astranaar."},
 [1047]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor."},
 [1048]={["source"]="QuestieDB Forever",["text"]="Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity."},
 [1049]={["source"]="QuestieDB Forever",["text"]="Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff."},
 [1050]={["source"]="QuestieDB Forever",["text"]="Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge."},
 [1051]={["source"]="QuestieDB Forever",["text"]="Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill."},
 [1052]={["source"]="QuestieDB Forever",["text"]="Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore."},
 [1053]={["source"]="QuestieDB Forever",["text"]="Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore."},
 [1054]={["source"]="QuestieDB Forever",["text"]="Bring Dal Bloodclaw's Skull to Raene Wolfrunner in Astranaar."},
 [1055]={["source"]="QuestieDB Forever",["text"]="Return to Shael'dryn at the moonwell."},
 [1056]={["source"]="QuestieDB Forever",["text"]="Travel to Keeper Albagorm on Stonetalon Peak."},
 [1057]={["source"]="QuestieDB Forever",["text"]="Keeper Albagorm on Stonetalon Peak wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers."},
 [1058]={["source"]="QuestieDB Forever",["text"]="Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale."},
 [1059]={["source"]="QuestieDB Forever",["text"]="Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas."},
 [1060]={["source"]="QuestieDB Forever",["text"]="Deliver Darsok's letter to Jin'Zil within his cave in Malaka'Jin, in Stonetalon."},
 [1061]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Seereth Stonebreak in the Stonetalon Mountains."},
 [1062]={["source"]="QuestieDB Forever",["text"]="Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens."},
 [1063]={["source"]="QuestieDB Forever",["text"]="Speak with Magatha in Thunder Bluff."},
 [1064]={["source"]="QuestieDB Forever",["text"]="Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff."},
 [1065]={["source"]="QuestieDB Forever",["text"]="Bring Zamah's Note to Apothecary Lydon in Tarren Mill."},
 [1066]={["source"]="QuestieDB Forever",["text"]="Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill."},
 [1067]={["source"]="QuestieDB Forever",["text"]="Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff."},
 [1068]={["source"]="QuestieDB Forever",["text"]="Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens."},
 [1069]={["source"]="QuestieDB Forever",["text"]="Bring 15 Deepmoss Eggs to Mebok Mizzyrix in Ratchet."},
 [1070]={["source"]="QuestieDB Forever",["text"]="Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains."},
 [1071]={["source"]="QuestieDB Forever",["text"]="Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon."},
 [1072]={["source"]="QuestieDB Forever",["text"]="Speak to Lomac Gearstrip in Ironforge."},
