 [1250]={["source"]="QuestieDB Forever",["text"]="Speak to Mikhail in the Wetlands."},
 [1251]={["source"]="QuestieDB Forever",["text"]="Bring the Blackened Iron Shield to Krog in Brackenwall Village."},
 [1252]={["source"]="QuestieDB Forever",["text"]="Bring Reethe's Badge to Captain Garran Vimes in Theramore."},
 [1253]={["source"]="QuestieDB Forever",["text"]="Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore."},
 [1258]={["source"]="QuestieDB Forever",["text"]="Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore."},
