 [1260]={["source"]="QuestieDB Forever",["text"]="Speak with Morgan Stern in Theramore."},
 [1261]={["source"]="QuestieDB Forever",["text"]="Bring the Jeweled Pendant to Nazeer in Brackenwall Village."},
 [1262]={["source"]="QuestieDB Forever",["text"]="Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar."},
