 [1267]={["source"]="QuestieDB Forever",["text"]="Speak to Jaina Proudmore in Dustwallow Swamp."},
 [1268]={["source"]="QuestieDB Forever",["text"]="Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village."},
 [1269]={["source"]="QuestieDB Forever",["text"]="Bring Reethe's Badge to Krog in Brackenwall Village."},
