 [1276]={["source"]="QuestieDB Forever",["text"]="Show the Blackened Iron Shield to Mosarn in Thunder Bluff."},
 [1282]={["source"]="QuestieDB Forever",["text"]="Speak with Captain Garran Vimes on the top floor of Foothold Citadel."},
