 [1319]={["source"]="QuestieDB Forever",["text"]="Show the Blackened Iron Shield to Caz Twosprocket in Theramore."},
 [1320]={["source"]="QuestieDB Forever",["text"]="Speak with Captain Garran Vimes in Theramore."},
 [1321]={["source"]="QuestieDB Forever",["text"]="Show the Blackened Iron Shield to Do'gol in Brackenwall Village."},
