 [1703]={["source"]="QuestieDB Forever",["text"]="Bring Furen's Notes to Mathiel."},
 [1704]={["source"]="QuestieDB Forever",["text"]="Bring Furen's Notes to Klockmort Spannerspan."},
 [1705]={["source"]="QuestieDB Forever",["text"]="Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind."},
 [1707]={["source"]="QuestieDB Forever",["text"]="Bring 5 Wastewander Water Pouches to Spigot Operator Luglunket in Gadgetzan."},
 [1708]={["source"]="QuestieDB Forever",["text"]="Bring 20 loads of Searing Coral to Klockmort Spannerspan in Ironforge."},
 [1710]={["source"]="QuestieDB Forever",["text"]="Bring 20 Sunscorched Shells to Mathiel in Darnassus."},
 [1712]={["source"]="QuestieDB Forever",["text"]="Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac."},
 [1713]={["source"]="QuestieDB Forever",["text"]="Bring the Whirlwind Heart to Bath'rah Windwatcher."},
 [1715]={["source"]="QuestieDB Forever",["text"]="Report to Gakin the Darkbinder in the Mage Quarter of Stormwind."},
 [1716]={["source"]="QuestieDB Forever",["text"]="Speak with Takar the Seer in the Barrens."},
 [1717]={["source"]="QuestieDB Forever",["text"]="Report to Gakin the Darkbinder in the Mage Quarter of Stormwind."},
 [1718]={["source"]="QuestieDB Forever",["text"]="Speak with Klannoc Macleod."},
 [1719]={["source"]="QuestieDB Forever",["text"]="Kill Big Will, then speak to Klannoc Macleod on Fray Island."},
 [1738]={["source"]="QuestieDB Forever",["text"]="Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind."},
 [1739]={["complex"]=true,["extra"]={"Summon the Succubus"},["source"]="QuestieDB Forever",["text"]="Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb.\010Summon the Succubus"},
 [1740]={["source"]="QuestieDB Forever",["text"]="Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens."},
 [1758]={["source"]="QuestieDB Forever",["text"]="Speak with Krom Stoutarm in Ironforge."},
 [1778]={["source"]="QuestieDB Forever",["text"]="Speak to Tiza Battleforge in Ironforge."},
 [1779]={["source"]="QuestieDB Forever",["text"]="Take the Symbol of Life and speak to Muiredon Battleforge in Ironforge."},
 [1780]={["source"]="QuestieDB Forever",["text"]="Speak to Duthorian Rall in Stormwind."},
 [1781]={["source"]="QuestieDB Forever",["text"]="Take the Symbol of Life to Gazin Tenorm in Stormwind."},
 [1782]={["source"]="ForeverDungeonJournal authored summary",["text"]="Wait for Furen Longbeard to finish your armor."},
 [1783]={["source"]="QuestieDB Forever",["text"]="Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh."},
 [1784]={["source"]="QuestieDB Forever",["text"]="Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge."},
 [1785]={["source"]="QuestieDB Forever",["text"]="Speak to Tiza Battleforge in Ironforge."},
 [1786]={["source"]="QuestieDB Forever",["text"]="Take the Symbol of Life and resurrect Henze Faulk in Elwynn."},
 [1787]={["source"]="QuestieDB Forever",["text"]="Retrieve a Defias Script from the Defias Rogue Wizards in Elwynn, and return to Gazin Tenorm in Stormwind."},
 [1788]={["source"]="QuestieDB Forever",["text"]="Speak to Duthorian Rall in Stormwind."},
 [1791]={["source"]="QuestieDB Forever",["text"]="Speak with Bath'rah the Windwatcher."},
 [1795]={["complex"]=true,["extra"]={"Summon the Felhunter"},["source"]="QuestieDB Forever",["text"]="Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.\010Summon the Felhunter"},
 [1796]={["source"]="QuestieDB Forever",["text"]="Bring Robes of the Arcana to Menara Voidrender in the Barrens."},
 [1798]={["source"]="QuestieDB Forever",["text"]="Speak with Strahad Farsan in the Barrens."},
 [1799]={["source"]="QuestieDB Forever",["text"]="Speak to Menara's acolytes inside the tower above Ratchet and choose one of their paths to follow.\010Afterwards, bring an Infernal Orb to Tabetha in Dustwallow Marsh."},
 [1800]={["source"]="QuestieDB Forever",["text"]="Take your ward to the old Lordaeron Throne Room that lies just before descending into the Undercity."},
 [1801]={["source"]="QuestieDB Forever",["text"]="Speak with Jorah Annison in the Undercity."},
 [1802]={["source"]="QuestieDB Forever",["text"]="Retrieve the Moldy Tome and Tattered Manuscript for Krom Stoutarm in Ironforge."},
 [1803]={["source"]="QuestieDB Forever",["text"]="Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity."},
 [1804]={["source"]="QuestieDB Forever",["text"]="Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet."},
 [1805]={["source"]="QuestieDB Forever",["text"]="Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet."},
 [1806]={["source"]="QuestieDB Forever",["text"]="Wait for Jordan Stilwell to finish forging a weapon for you."},
 [1818]={["source"]="QuestieDB Forever",["text"]="Speak with Deathguard Dillinger in Brill."},
 [1819]={["source"]="QuestieDB Forever",["text"]="Kill Ulag the Cleaver, then speak with Deathguard Dillinger."},
 [1820]={["source"]="QuestieDB Forever",["text"]="Speak with Coleman Farthing."},
 [1821]={["source"]="QuestieDB Forever",["text"]="Bring Coleman Farthing the Agamand Family Axe, the Agamand Family Sword, the Agamand Family Mace and the Agamand Family dagger."},
 [1823]={["source"]="QuestieDB Forever",["text"]="Speak with Ruga Ragetotem."},
 [1824]={["source"]="QuestieDB Forever",["text"]="Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo"},
 [1825]={["source"]="QuestieDB Forever",["text"]="Speak with Thun'grim Firegaze in the Barrens."},
 [1838]={["source"]="QuestieDB Forever",["text"]="Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston."},
 [1839]={["source"]="QuestieDB Forever",["text"]="Speak with Ula'elek in Durotar."},
 [1840]={["source"]="QuestieDB Forever",["text"]="Speak with Orm Stonehoof in Thunder Bluff."},
 [1841]={["source"]="QuestieDB Forever",["text"]="Speak with Velora Nitely in the Undercity."},
 [1842]={["source"]="QuestieDB Forever",["text"]="Bring 7 Uncloven Satyr Hooves to Ula'elek at Sen'jin Village in Durotar."},
 [1844]={["source"]="QuestieDB Forever",["text"]="Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff."},
 [1846]={["source"]="QuestieDB Forever",["text"]="Bring 8 Sturdy Dragonmaw Shinbones to Velora Nitely in the Undercity."},
 [1848]={["source"]="ForeverDungeonJournal authored summary",["text"]="Wait for Thun'grim Firegaze to finish your armor."},
 [1858]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Steal Tazan's key, then use it to open his Satchel and deliver its contents to Therzok in the Cleft of Shadow in Orgrimmar."},
 [1859]={["source"]="QuestieDB Forever",["text"]="Speak with Therzok in the Cleft of Shadow in Orgrimmar."},
 [1860]={["source"]="QuestieDB Forever",["text"]="Speak with Jennea Cannon in Stormwind."},
 [1861]={["source"]="QuestieDB Forever",["text"]="Bring a Mirror Lake sample to Jennea Cannon in Stormwind."},
 [1879]={["source"]="QuestieDB Forever",["text"]="Speak with Bink in Ironforge."},
 [1880]={["source"]="QuestieDB Forever",["text"]="Bring Bink her Mage-tastic Gizmonitor."},
 [1881]={["source"]="QuestieDB Forever",["text"]="Speak with Anastasia Hartwell."},
 [1882]={["source"]="QuestieDB Forever",["text"]="Bring Balnir Snapdragons to Anastasia Hartwell in the Mage Quarter of the Undercity."},
 [1883]={["source"]="QuestieDB Forever",["text"]="Speak with Un'thuwa."},
 [1884]={["source"]="QuestieDB Forever",["text"]="Destroy 4 Ju-Ju Heaps, then return to Un'thuwa in Sen'jin Village."},
 [1885]={["source"]="QuestieDB Forever",["text"]="Speak with Mennet Carkad in the Rogues' Quarter of the Undercity."},
 [1886]={["source"]="QuestieDB Forever",["text"]="Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter."},
 [1898]={["source"]="QuestieDB Forever",["text"]="Speak with Andron Gant in the Undercity."},
 [1899]={["source"]="QuestieDB Forever",["text"]="Bring Andron's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity."},
 [1918]={["source"]="QuestieDB Forever",["text"]="Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale."},
 [1919]={["source"]="QuestieDB Forever",["text"]="Speak with Jennea Cannon in Stormwind."},
 [1920]={["complex"]=true,["extra"]={"Use Cantation of Manifestation to reveal Rift Spawn. Use Chest of Containment Coffers on stunned Rift Spawn"},["source"]="QuestieDB Forever",["text"]="Obtain a Cantation of Manifestation and a Chest of Containment coffers from behind Jennea Cannon. Bring 3 Filled Containment Coffers to Jennea at the Wizard's Sanctum.\010Use Cantation of Manifestation to reveal Rift Spawn. Use Chest of Containment Coffers on stunned Rift Spawn"},
 [1921]={["source"]="QuestieDB Forever",["text"]="Bring 10 Linen Cloth and the 6 Charged Rift Gems to Wynne Larson in Stormwind."},
 [1938]={["source"]="QuestieDB Forever",["text"]="Bring Ur's Treatise on Shadow Magic to High Sorcerer Andromath in Stormwind."},
 [1939]={["source"]="QuestieDB Forever",["text"]="Speak with High Sorcerer Andromath."},
 [1940]={["source"]="QuestieDB Forever",["text"]="Bring 8 Pristine Spider Silk to Wynne Larson in Stormwind."},
 [1943]={["source"]="QuestieDB Forever",["text"]="Speak with Deino."},
 [1944]={["source"]="QuestieDB Forever",["text"]="Bring the Xavian Water Sample to Deino in Orgrimmar."},
 [1945]={["source"]="QuestieDB Forever",["text"]="Bring 12 Laughing Sister's Hairs to Kil'hala at the Crossroads."},
 [1947]={["source"]="QuestieDB Forever",["text"]="Speak with Tabetha."},
 [1948]={["source"]="QuestieDB Forever",["text"]="Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh."},
 [1949]={["source"]="QuestieDB Forever",["text"]="Speak with Magus Tirth in the Shimmering Flats."},
 [1950]={["source"]="QuestieDB Forever",["text"]="Find the phrase to Tirth's strongbox, then return to Tirth."},
 [1951]={["source"]="QuestieDB Forever",["text"]="Bring the book Rituals of Power to Tabetha in Dustwallow Marsh."},
 [1952]={["source"]="QuestieDB Forever",["text"]="Speak with Tabetha after her ritual."},
 [1953]={["source"]="QuestieDB Forever",["text"]="Speak with Tabetha."},
 [1954]={["source"]="QuestieDB Forever",["text"]="Bring an Infernal Orb to Tabetha in Dustwallow Marsh."},
 [1955]={["source"]="QuestieDB Forever",["text"]="Kill the Demon of the Orb, then speak with Tabetha."},
 [1956]={["source"]="QuestieDB Forever",["text"]="Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh."},
 [1957]={["source"]="QuestieDB Forever",["text"]="Kill 12 Mana Surges in the allowed time limit."},
 [1959]={["source"]="QuestieDB Forever",["text"]="Speak with Anastasia Hartwell."},
 [1960]={["complex"]=true,["extra"]={"Use Cantation of Manifestation to reveal Rift Spawn. Use Chest of Containment Coffers on stunned Rift Spawn"},["source"]="QuestieDB Forever",["text"]="Obtain a Cantation of Manifestation and a Chest of Containment Coffers from behind Anastasia Hartwell. Bring 3 Filled Containment Coffers, the Chest of Containment Coffers and the Cantation of Manifestation to Anastasia in the Undercity.\010Use Cantation of Manifestation to reveal Rift Spawn. Use Chest of Containment Coffers on stunned Rift Spawn"},
 [1961]={["source"]="QuestieDB Forever",["text"]="Bring 10 Linen Cloth and 6 Dalaran Mana Gems to Josef Gregorian."},
 [1963]={["source"]="QuestieDB Forever",["text"]="Kill Tazan and bring his Satchel to Therzok in the Cleft of Shadow in Orgrimmar."},
 [1978]={["source"]="QuestieDB Forever",["text"]="Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity."},
 [1998]={["source"]="QuestieDB Forever",["text"]="Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity."},
 [1999]={["complex"]=true,["extra"]={"Talk to Estelle Gendry"},["source"]="QuestieDB Forever",["text"]="Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity.\010Talk to Estelle Gendry"},
 [2038]={["source"]="QuestieDB Forever",["text"]="Find and return Bingles' supplies:\010Bingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper."},
 [2039]={["source"]="QuestieDB Forever",["text"]="Find Bingles Blastenheimer in Loch Modan."},
 [2040]={["source"]="QuestieDB Forever",["text"]="Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind."},
 [2041]={["source"]="QuestieDB Forever",["text"]="Speak with Shoni the Shilent in Stormwind."},
 [2078]={["source"]="QuestieDB Forever",["text"]="Find Gelkak's First Mate, the Threshwackonator 4100, and lead it back to Gelkak."},
 [2098]={["source"]="QuestieDB Forever",["text"]="Find and return the three pieces of Gelkak's Key to Gelkak Gyromast."},
 [2118]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Capture a living Rabid Thistle Bear and bring it back to Tharnariun.\010Should you fail to capture a Rabid Thistle Bear and lose your trap, return to Tharnariun Treetender and request another trap."},
 [2138]={["source"]="QuestieDB Forever",["text"]="Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore."},
 [2139]={["source"]="QuestieDB Forever",["text"]="Find and kill the Den Mother."},
 [2158]={["source"]="QuestieDB Forever",["text"]="Speak with Innkeeper Farley at the Lion's Pride Inn."},
 [2159]={["source"]="QuestieDB Forever",["text"]="Bring the Dolanaar Delivery to Innkeeper Keldamyr."},
 [2160]={["source"]="QuestieDB Forever",["text"]="Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos."},
 [2161]={["source"]="QuestieDB Forever",["text"]="Bring Ukor's Burden to Innkeeper Grosk in Razor Hill."},
 [2178]={["source"]="QuestieDB Forever",["text"]="Bring back 5 Strider Meat to Alanndarian Nightsong in Auberdine."},
 [2198]={["source"]="QuestieDB Forever",["text"]="Search for the original creator of the shattered necklace to learn of its potential value."},
 [2199]={["source"]="QuestieDB Forever",["text"]="Bring five silver bars to Talvash del Kissel in Ironforge."},
 [2200]={["source"]="QuestieDB Forever",["text"]="Search for clues as to the current disposition of Talvash's necklace within Uldaman. The slain paladin he mentioned was the person who had it last."},
 [2201]={["source"]="QuestieDB Forever",["text"]="Find the ruby, sapphire, and topaz that are scattered throughout Uldaman. Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.\010From the journal, you know...\010* The ruby has been stashed in a barricaded Shadowforge area.\010* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\010* The sapphire has been claimed by Grimlok, the trogg leader."},
 [2202]={["source"]="QuestieDB Forever",["text"]="Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath."},
 [2203]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands. Once you have them filled, bring them to Jarkal Mossmeld in Kargath."},
 [2204]={["source"]="QuestieDB Forever",["text"]="Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge."},
 [2205]={["source"]="QuestieDB Forever",["text"]="Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks."},
 [2206]={["source"]="QuestieDB Forever",["text"]="Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw."},
 [2218]={["source"]="QuestieDB Forever",["text"]="Speak with Hulfdan Blackbeard in Ironforge."},
 [2238]={["source"]="QuestieDB Forever",["text"]="Find Onin MacHammar by Gnomeregan."},
 [2239]={["source"]="QuestieDB Forever",["text"]="Take Onin's Report back to Hulfdan in Ironforge."},
 [2240]={["source"]="QuestieDB Forever",["text"]="Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike."},
 [2241]={["source"]="QuestieDB Forever",["text"]="Take Jannok's Rose to Syurna in Darnassus."},
 [2242]={["source"]="QuestieDB Forever",["text"]="Find Sethir the Ancient and bring back any clues that you may discover to Syurna."},
 [2258]={["source"]="QuestieDB Forever",["text"]="Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and 5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands."},
 [2259]={["source"]="QuestieDB Forever",["text"]="Contact Erion Shadewhisper in Darnassus."},
 [2260]={["source"]="QuestieDB Forever",["text"]="Travel to Stormwind City and seek council with Renzik \"The Shiv.\""},
 [2278]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Speak with stone watcher and learn what ancient lore it keeps. Once you have learned what lore it has to offer, activate the Discs of Norgannon."},
 [2279]={["source"]="QuestieDB Forever",["text"]="Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge."},
 [2280]={["source"]="QuestieDB Forever",["text"]="Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff."},
 [2281]={["source"]="QuestieDB Forever",["text"]="Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius."},
 [2282]={["source"]="QuestieDB Forever",["text"]="Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire."},
 [2283]={["source"]="QuestieDB Forever",["text"]="Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged."},
 [2284]={["source"]="QuestieDB Forever",["text"]="Find a clue as to the gems' whereabouts in the depths of Uldaman."},
 [2298]={["source"]="QuestieDB Forever",["text"]="Travel to Stormwind and seek out Renzik \"The Shiv.\""},
 [2299]={["source"]="QuestieDB Forever",["text"]="Travel to Ironforge and speak with Hulfdan Blackbeard."},
 [2300]={["source"]="QuestieDB Forever",["text"]="Travel to Stormwind and seek out Renzik \"The Shiv.\""},
 [2318]={["source"]="QuestieDB Forever",["text"]="Find someone who can translate the paladin's journal. The closest location that might have someone is Kargath, in the Badlands."},
 [2338]={["source"]="QuestieDB Forever",["text"]="Let Jarkal borrow the necklace. In exchange, he will translate the journal for you."},
 [2339]={["source"]="QuestieDB Forever",["text"]="Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.\010From the journal, you know...\010* The ruby has been stashed in a barricaded Shadowforge area.\010* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\010* The sapphire has been claimed by Grimlok, the trogg leader."},
 [2340]={["source"]="QuestieDB Forever",["text"]="Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar."},
 [2341]={["source"]="QuestieDB Forever",["text"]="Visit Jarkal Mossmeld in Kargath to see if he was successful."},
 [2342]={["source"]="QuestieDB Forever",["text"]="Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity."},
 [2358]={["source"]="QuestieDB Forever",["text"]="Return the Horns of Nez'ra to Arantir's Shadow in Lakeshire."},
 [2359]={["source"]="QuestieDB Forever",["text"]="Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower."},
 [2360]={["source"]="QuestieDB Forever",["text"]="Travel to Westfall and find Agent Kearnen for your debriefing."},
 [2361]={["source"]="ForeverDungeonJournal authored summary",["text"]="Let Talvash del Kissel finish restoring the necklace, then take it from him."},
 [2378]={["source"]="QuestieDB Forever",["text"]="Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow."},
 [2379]={["source"]="QuestieDB Forever",["text"]="Speak with Zando'zan at the Cleft of Shadow."},
 [2380]={["source"]="QuestieDB Forever",["text"]="Speak with Shenthul at the Cleft of Shadow in Orgrimmar."},
 [2381]={["complex"]=true,["extra"]={"Open the chest","Use the E.C.A.C. to weaken it"},["source"]="QuestieDB Forever",["text"]="Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.\010Should you be attacked by any unusually hostile parrots, use your E.C.A.C.!\010Open the chest\010Use the E.C.A.C. to weaken it"},
 [2382]={["source"]="QuestieDB Forever",["text"]="Travel to Ratchet and speak with Wrenix the Wretched."},
 [2383]={["source"]="QuestieDB Forever",["text"]="Read the Simple Parchment and speak to Frang in the Valley of Trials."},
 [2398]={["source"]="QuestieDB Forever",["text"]="Find Baelog in Uldaman."},
 [2418]={["source"]="QuestieDB Forever",["text"]="Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands."},
 [2438]={["source"]="QuestieDB Forever",["text"]="Bring the Emerald Dreamcatcher to Tallonkai Swiftroot in Dolanaar."},
 [2439]={["source"]="QuestieDB Forever",["text"]="Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge."},
 [2440]={["source"]="QuestieDB Forever",["text"]="Take the reward voucher to Bena Winterhoof in Thunder Bluff."},
 [2458]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.\010When the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.\010These actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize."},
 [2459]={["source"]="QuestieDB Forever",["text"]="Tallonkai Swiftroot in Dolanaar wants you to kill 7 Gnarlpine Mystics and find the Missing Jewel."},
 [2460]={["source"]="QuestieDB Forever",["text"]="Perform the Shattered Salute on Shenthul."},
 [2478]={["source"]="QuestieDB Forever",["text"]="Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.\010Assassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction."},
 [2479]={["source"]="QuestieDB Forever",["text"]="Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.\010To get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!"},
 [2480]={["source"]="QuestieDB Forever",["text"]="Wait for Serge Hinott to complete the cure."},
 [2498]={["source"]="QuestieDB Forever",["text"]="Rellian Greenspyre wants you to speak with Denalan at Lake Al'Ameth."},
 [2499]={["source"]="QuestieDB Forever",["text"]="Denalan at Lake Al'Ameth wants you to collect the Gargantuan Tumor from Oakenscowl."},
 [2500]={["source"]="QuestieDB Forever",["text"]="Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar."},
 [2501]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands. Once you have them filled, bring them to Ghak Healtouch in Thelsamar."},
 [2518]={["source"]="QuestieDB Forever",["text"]="Priestess A'moora in the Temple of the Moon at Darnassus wants you to bring her Lady Sathrah's Silvery Spinnerets."},
 [2519]={["source"]="QuestieDB Forever",["text"]="Sister Aquinne wants you to speak with Priestess A'moora in the Temple of the Moon."},
 [2520]={["source"]="QuestieDB Forever",["text"]="Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her."},
 [2521]={["source"]="QuestieDB Forever",["text"]="In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.\010Be warned, this gem is one of the most rare crystals in all of Azeroth. Any creature in these lands could be holding a Flawless Draenethyst Sphere.\010You will be rewarded for each Flawless Draenethyst Sphere you have collected."},
