 [3000]={["source"]="QuestieDB Forever",["text"]="Speak to Tiza Battleforge in Ironforge."},
 [3001]={["source"]="QuestieDB Forever",["text"]="Find Strahad Farsan in Ratchet."},
 [3002]={["source"]="QuestieDB Forever",["text"]="Bring the Gordunni Orb to Uthel'nay in the Darkbriar Lodge in Orgrimmar."},
 [3022]={["source"]="QuestieDB Forever",["text"]="Bring the Carefully-packed Crate to Erelas Ambersky in Rut'theran Village."},
 [3042]={["source"]="QuestieDB Forever",["text"]="Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan."},
 [3062]={["source"]="QuestieDB Forever",["text"]="Talo Thornhoof in Camp Mojache wants Edana Hatetalon's Dark Heart."},
 [3063]={["source"]="QuestieDB Forever",["text"]="Talo Thornhoof wants you to kill 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers, and 4 Northspring Slayers."},
 [3065]={["source"]="QuestieDB Forever",["text"]="Read the Simple Tablet and speak to Frang in the Valley of Trials."},
 [3082]={["source"]="QuestieDB Forever",["text"]="Speak to Jen'shan in the Valley of Trials."},
 [3083]={["source"]="QuestieDB Forever",["text"]="Read the Encrypted Tablet and speak to Rwag in the Valley of Trials."},
 [3084]={["source"]="QuestieDB Forever",["text"]="Speak to Shikrik in the Valley of Trials."},
 [3085]={["source"]="QuestieDB Forever",["text"]="Read the Hallowed Tablet and speak to Ken'jai outside the Den in the Valley of Trials."},
 [3086]={["source"]="QuestieDB Forever",["text"]="Read the Glyphic Tablet and speak with Mai'ah near the entrance to the Den in the Valley of Trials."},
 [3087]={["source"]="QuestieDB Forever",["text"]="Read the Etched Parchment and speak to Jen'shan in the Valley of Trials."},
 [3088]={["source"]="QuestieDB Forever",["text"]="Read the Encrypted Parchment and speak to Rwag in the Valley of Trials."},
 [3089]={["source"]="QuestieDB Forever",["text"]="Read the Rune-Inscribed Parchment and speak to Shikrik in the Valley of Trials."},
 [3090]={["source"]="QuestieDB Forever",["text"]="Read the Tainted Parchment and speak to Nartok inside the Den in the Valley of Trials."},
 [3091]={["source"]="QuestieDB Forever",["text"]="Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache."},
 [3092]={["source"]="QuestieDB Forever",["text"]="Read the Etched Note and speak to Lanka Farshot in Red Cloud Mesa."},
 [3093]={["source"]="QuestieDB Forever",["text"]="Read the Rune-Inscribed Note and speak to Meela Dawnstrider in Camp Narache."},
 [3094]={["source"]="QuestieDB Forever",["text"]="Read the Verdant Note and speak to Gart Mistrunner in Camp Narache."},
 [3095]={["source"]="QuestieDB Forever",["text"]="Read the Simple Scroll and speak to Dannal Stern in Deathknell."},
 [3096]={["source"]="QuestieDB Forever",["text"]="Read the Encrypted Scroll and speak to David Trias in Deathknell."},
 [3097]={["source"]="QuestieDB Forever",["text"]="Read the Hallowed Scroll and speak to Dark Cleric Duesten in the church in Deathknell."},
 [3098]={["source"]="QuestieDB Forever",["text"]="Read the Glyphic Scroll and speak to Isabella in the church in Deathknell."},
 [3099]={["source"]="QuestieDB Forever",["text"]="Read the Tainted Scroll and speak to Maximillion in Deathknell."},
 [3100]={["source"]="QuestieDB Forever",["text"]="Read the Simple Letter and speak to Llane Beshere in Northshire Abbey."},
 [3101]={["source"]="QuestieDB Forever",["text"]="Read the Consecrated Letter and speak to Brother Sammuel in Northshire Abbey."},
 [3102]={["source"]="QuestieDB Forever",["text"]="Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey."},
 [3103]={["source"]="QuestieDB Forever",["text"]="Read the Hallowed Letter and speak to Priestess Anetta in Northshire Abbey."},
 [3104]={["source"]="QuestieDB Forever",["text"]="Read the Glyphic Letter and speak to Khelden Bremen inside Northshire Abbey."},
 [3105]={["source"]="QuestieDB Forever",["text"]="Read the Tainted Letter and speak to Drusilla La Salle next to Northshire Abbey."},
 [3106]={["source"]="QuestieDB Forever",["text"]="Read the Simple Rune and speak to Thran Khorman in Coldridge Valley."},
 [3107]={["source"]="QuestieDB Forever",["text"]="Read the Consecrated Rune and speak to Bromos Grummner in Coldridge Valley."},
 [3108]={["source"]="QuestieDB Forever",["text"]="Read the Etched Rune and speak to Thorgas Grimson in Coldridge Valley."},
 [3109]={["source"]="QuestieDB Forever",["text"]="Read the Encrypted Rune and speak to Solm Hargrin in Coldridge Valley."},
 [3110]={["source"]="QuestieDB Forever",["text"]="Read the Hallowed Rune and speak to Branstock Khalder in Anvilmar."},
 [3112]={["source"]="QuestieDB Forever",["text"]="Read the Simple Memorandum and speak to Thran Khorman in Coldridge Valley."},
 [3113]={["source"]="QuestieDB Forever",["text"]="Read the Encrypted Memorandum and speak to Solm Hargrin in Coldridge Valley."},
 [3114]={["source"]="QuestieDB Forever",["text"]="Read the Glyphic Memorandum and speak to Marryk Nurribit inside Anvilmar above Coldridge Valley."},
 [3115]={["source"]="QuestieDB Forever",["text"]="Read the Tainted Memorandum and speak to Alamar Grimm inside Anvilmar above Coldridge Valley."},
 [3116]={["source"]="QuestieDB Forever",["text"]="Read the Simple Sigil and speak to Alyissia in Shadowglen."},
 [3117]={["source"]="QuestieDB Forever",["text"]="Read the Etched Sigil and speak to Ayanna Everstride at the top of Aldrassil in Shadowglen."},
 [3118]={["source"]="QuestieDB Forever",["text"]="Read the Encrypted Sigil and speak to Frahun Shadewhisper in Shadowglen."},
 [3119]={["source"]="QuestieDB Forever",["text"]="Read the Hallowed Sigil and speak to Shanda in Aldrassil."},
 [3120]={["source"]="QuestieDB Forever",["text"]="Read the Verdant Sigil and speak to Mardant Strongoak, in the tree Aldrassil in Shadowglen."},
 [3121]={["source"]="QuestieDB Forever",["text"]="Take the Shrunken Head to Neeru Fireblade in Orgrimmar."},
 [3122]={["source"]="QuestieDB Forever",["text"]="Deliver Neeru's Herb Pouch to Witch Doctor Uzer'i in Feralas."},
 [3123]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Travel to the Hinterlands, and locate the Wildkin. Kill 10, and use the Muisek Vessel to shrink and capture the fallen Wildkin.\010Bring 10 Wildkin Muiseks and the Muisek Vessel to Witch Doctor Uzer'i in Feralas."},
 [3124]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them."},
 [3125]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons."},
 [3126]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants."},
 [3127]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Kill 7 Land Walkers or Cliff Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants."},
 [3128]={["source"]="QuestieDB Forever",["text"]="Bring 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew, and 40 Metallic Fragments to Witch Doctor Uzer'i in Camp Mojache."},
 [3129]={["source"]="QuestieDB Forever",["text"]="Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons."},
 [3130]={["source"]="QuestieDB Forever",["text"]="Report to Latronicus Moonspear in Feathermoon Stronghold."},
 [3141]={["source"]="QuestieDB Forever",["text"]="Listen to Loramus Thalipedes tell his story."},
 [3161]={["source"]="QuestieDB Forever",["text"]="Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments."},
 [3181]={["source"]="QuestieDB Forever",["text"]="Take Margol's Gigantic Horn to Mountaineer Pebblebitty."},
 [3182]={["source"]="QuestieDB Forever",["text"]="Take Margol's Gigantic Horn to Curator Thorius in Ironforge."},
 [3201]={["source"]="QuestieDB Forever",["text"]="Take the Proof of Deed back to Mountaineer Pebblebitty."},
 [3221]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Apothecary Renferrel at the Sepulcher."},
 [3261]={["source"]="QuestieDB Forever",["text"]="Speak with Jorn Skyseer at Camp Taurajo."},
 [3281]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring the Stolen Silver to Gazrog in the Crossroads."},
 [3301]={["source"]="QuestieDB Forever",["text"]="Speak with Mura Runetotem in the Sepulcher."},
 [3321]={["source"]="QuestieDB Forever",["text"]="Wait for Trenton to finish his work."},
 [3341]={["source"]="QuestieDB Forever",["text"]="Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull."},
 [3361]={["source"]="QuestieDB Forever",["text"]="Bring Felix's Box, Felix's Chest and Felix's Bucket of Bolts to Felix Whindlebolt in Anvilmar."},
 [3362]={["source"]="QuestieDB Forever",["text"]="Tran'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers."},
 [3364]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold in five minutes!"},
 [3365]={["source"]="QuestieDB Forever",["text"]="Return Nori's Mug to Nori Pridedrift."},
 [3367]={["source"]="QuestieDB Forever",["text"]="Help Dorius get back to Ironforge."},
 [3368]={["source"]="QuestieDB Forever",["text"]="Take the Singed Letter to Thorius in Ironforge. He is in the Hall of Explorers."},
 [3369]={["source"]="QuestieDB Forever",["text"]="Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise."},
 [3370]={["source"]="QuestieDB Forever",["text"]="Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus."},
 [3371]={["source"]="QuestieDB Forever",["text"]="Return to the Searing Gorge and find Dorius's archaeology unit."},
 [3372]={["source"]="QuestieDB Forever",["text"]="Find the Mysterious Artifact being guarded by the Twilight's Hammer Idolaters in the northwest quadrant of the Searing Gorge and bring it to the Altar of Suntara in the Slag Pit."},
 [3373]={["source"]="QuestieDB Forever",["text"]="Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple."},
 [3374]={["source"]="QuestieDB Forever",["text"]="Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows. It is there that you will make your choice to aid Ysera's Dragonflight or not."},
 [3375]={["source"]="QuestieDB Forever",["text"]="Bring a Mana Potion, Coal, and Sweet Nectar to Talvash del Kissel in Ironforge to get a replacement for Talvash's Phial of Scrying."},
 [3376]={["source"]="QuestieDB Forever",["text"]="Bring the head of Chief Sharptusk Thornmantle to Brave Windfeather in Red Cloud Mesa."},
 [3377]={["source"]="QuestieDB Forever",["text"]="Hear Zamael tell his tale."},
 [3378]={["source"]="QuestieDB Forever",["text"]="Find the Prayer to Elune and take it to Astarii Starseeker in Darnassus."},
 [3379]={["source"]="QuestieDB Forever",["text"]="Kill the group of Shadow Silk Poachers that wander the Searing Gorge. Nilith has reason to believe that there are five of them that need to be exterminated. Return to Nilith in the Searing Gorge when this task is complete."},
 [3380]={["source"]="QuestieDB Forever",["text"]="Find Marvon Rivetseeker in Tanaris."},
 [3382]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Defend Captain Vanessa Beltis, her crew and the Horizon Scout's passengers against the naga attack. Captain Vanessa Beltis must survive."},
 [3385]={["source"]="QuestieDB Forever",["text"]="Slay Trade Master Kovic and his minion Clunk. Retrieve the Trader's Satchel from his corpse and return it to Nilith."},
 [3402]={["source"]="QuestieDB Forever",["text"]="Speak with Vizzklick in Gadgetzan."},
 [3441]={["source"]="QuestieDB Forever",["text"]="Listen as Kalaran Windblade tells his story."},
 [3442]={["source"]="QuestieDB Forever",["text"]="Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade."},
 [3443]={["source"]="QuestieDB Forever",["text"]="Bring 8 Thorium Plated Daggers to Kalaran Windblade."},
 [3444]={["source"]="QuestieDB Forever",["text"]="Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet."},
 [3445]={["source"]="QuestieDB Forever",["text"]="Find Marvon Rivetseeker in Tanaris."},
 [3446]={["source"]="QuestieDB Forever",["text"]="Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows."},
 [3447]={["source"]="QuestieDB Forever",["text"]="Travel into the Sunken Temple and discover the secret hidden in the circle of statues."},
 [3448]={["source"]="QuestieDB Forever",["text"]="Speak to Tymor in Ironforge."},
 [3449]={["source"]="QuestieDB Forever",["text"]="Using the Drawing Kit, make rubbings of the Rune of Beth'Amara, the Rune of Jin'yael, the Rune of Markri, and the Rune of Sael'hai before heading to the small island off of the southern peninsula of Azshara and signaling Pilot Xiggs Fuselighter to pick them up."},
 [3450]={["source"]="QuestieDB Forever",["text"]="Speak to Xiggs Fuselighter in Ironforge."},
 [3451]={["source"]="QuestieDB Forever",["text"]="Speak to Xiggs Fuselighter and get a Standard Issue Flare Gun from him in Ironforge."},
 [3452]={["source"]="QuestieDB Forever",["text"]="Find and return a Symbol of Ragnaros to Kalaran Windblade."},
 [3453]={["source"]="QuestieDB Forever",["text"]="Wait for Kalaran Windblade to complete the Torch of Retribution."},
 [3454]={["source"]="QuestieDB Forever",["text"]="Take the Torch of Retribution."},
 [3461]={["source"]="QuestieDB Forever",["text"]="Return Tymor's Drawing Kit to him in Ironforge."},
 [3462]={["source"]="QuestieDB Forever",["text"]="Speak with Squire Maltrake."},
 [3463]={["source"]="QuestieDB Forever",["text"]="Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings."},
 [3481]={["source"]="QuestieDB Forever",["text"]="Open the chest."},
 [3501]={["source"]="QuestieDB Forever",["text"]="Bring Kum'isha Imperfect Draenethyst Fragments and be rewarded for each one you turn in."},
 [3502]={["source"]="QuestieDB Forever",["text"]="Bring Kum'isha Imperfect Draenethyst Fragments. Any form of monster in the Blasted Lands could be carrying a fragment."},
 [3504]={["source"]="QuestieDB Forever",["text"]="Deliver the Sealed Letter to Ag'tor Bloodfist in Azshara."},
 [3505]={["source"]="QuestieDB Forever",["text"]="Kill 10 Blood Elf Reclaimers, and 10 Blood Elf Surveyors before seeking out Magus Rimtori's camp. Once you've found it, look for something that might be important to her that can be used to draw her into a fight."},
 [3506]={["source"]="QuestieDB Forever",["text"]="Destroy the arcane focusing crystal tied to Magus Rimtori and then slay her. Afterwards, take the Head of Magus Rimtori to Ag'tor Bloodfist in Azshara."},
 [3507]={["source"]="QuestieDB Forever",["text"]="Speak to Belgrom Rockmaul in Orgrimmar."},
 [3508]={["source"]="QuestieDB Forever",["text"]="Wait for Loramus to complete the enlightenment spell."},
 [3509]={["source"]="QuestieDB Forever",["text"]="Speak with Lord Arkkoroc in Azshara. Begin your search at the waters edge to find the Temple of Arkkoran."},
 [3510]={["source"]="QuestieDB Forever",["text"]="Slay Hetaera and bring back Hetaera's Bloodied Head, Hetaera's Beaten Head, and Hetaera's Bruised Head to Lord Arkkoroc."},
 [3511]={["source"]="QuestieDB Forever",["text"]="Take the temper back to Loramus Thalipedes."},
 [3512]={["source"]="QuestieDB Forever",["text"]="Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker."},
 [3513]={["source"]="QuestieDB Forever",["text"]="Take the Runed Scroll to the northern guard tower in the Barrens."},
 [3514]={["source"]="QuestieDB Forever",["text"]="Kill the leader of the Talon Den, Rynthariel the Keymaster."},
 [3517]={["source"]="QuestieDB Forever",["text"]="Find the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri, and the Tablet of Sael'hai before returning to Jediga in Azshara."},
 [3518]={["source"]="QuestieDB Forever",["text"]="Bring the Tablet of Beth'Amara to Magatha in Thunder Bluff."},
 [3519]={["source"]="QuestieDB Forever",["text"]="Speak to Dirania Silvershine in Shadowglen."},
 [3520]={["complex"]=true,["extra"]={"Slay Vale Screechers and use Yeh'kinya's Bramble on their corpse."},["source"]="QuestieDB Forever",["text"]="Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.\010Slay Vale Screechers and use Yeh'kinya's Bramble on their corpse."},
 [3521]={["source"]="QuestieDB Forever",["text"]="Collect 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, and 1 Webwood Ichor for Dirania Silveshine in Shadowglen."},
 [3522]={["source"]="QuestieDB Forever",["text"]="Bring Iverron's Antidote to Iverron before the time limit is up. Iverron can be found by the cave to the north."},
 [3523]={["source"]="QuestieDB Forever",["text"]="If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him."},
 [3524]={["source"]="QuestieDB Forever",["text"]="Recover Sea Creature Bones from the beached sea creature just south of Auberdine, and then return with it to Gwennyth Bly'Leggonde in Auberdine."},
 [3525]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.\010Protect Belnistrasz while he performs the ritual to shut down the idol."},
 [3526]={["source"]="QuestieDB Forever",["text"]="If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan."},
 [3527]={["source"]="QuestieDB Forever",["text"]="Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris."},
 [3528]={["source"]="QuestieDB Forever",["text"]="Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris."},
 [3541]={["source"]="QuestieDB Forever",["text"]="Bring the Tablet of Jin'yael to Jes'rimon in Orgrimmar."},
 [3542]={["source"]="QuestieDB Forever",["text"]="Bring the Tablet of Markri to Andron Gant in Undercity."},
 [3561]={["source"]="QuestieDB Forever",["text"]="Bring the Tablet of Sael'hai to Archmage Xylem in Azshara."},
 [3562]={["source"]="QuestieDB Forever",["text"]="Deliver Magatha's Note to Jediga in Azshara."},
 [3563]={["source"]="QuestieDB Forever",["text"]="Deliver Jes'rimon's Note to Jediga in Azshara."},
 [3564]={["source"]="QuestieDB Forever",["text"]="Deliver Andron's Note to Jediga in Azshara."},
 [3565]={["source"]="QuestieDB Forever",["text"]="Deliver Xylem's Note to Jediga in Azshara."},
 [3566]={["source"]="QuestieDB Forever",["text"]="Slay Lathoric the Black and Obsidion, and return to Thorius in Ironforge with the Head of Lathoric the Black and the Heart of Obsidion."},
 [3568]={["source"]="QuestieDB Forever",["text"]="Fill all 4 Empty Vials at the tide pools along the coast of the Ruins of Eldarath in Azshara before returning to Chemist Cuely."},
 [3569]={["source"]="QuestieDB Forever",["text"]="Give Cuely's Elixir to Thersa Windsong in Undercity."},
 [3601]={["source"]="QuestieDB Forever",["text"]="Search the Thalassian Base Camp for Kim'jael's Compass, Scope, Stuffed Chicken and Wizzlegoober, then return them to him in Azshara."},
 [3602]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Recover twenty Crystallized Azsharite from southern Azshara. You may use the Felhound to assist you in 'sniffing' out the location of cleverly hidden deposits.\010Return to Loramus when the task is complete."},
 [3621]={["source"]="QuestieDB Forever",["text"]="Take the Shipment to Galvan the Ancient in Stranglethorn Vale."},
 [3625]={["source"]="QuestieDB Forever",["text"]="Wait for Galvan to finish forging the weaponry."},
 [3626]={["source"]="QuestieDB Forever",["text"]="Return to the Fallen Hero of the Horde."},
 [3627]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Slay Grol the Destroyer, Lady Sevine, and Archmage Allistarj. From their corpses take the Amulet of Grol, the Amulet of Sevine, and the Amulet of Allistarj.\010Remember to USE your Enchanted Azsharite Fel Weaponry to weaken the triad. They cannot be killed otherwise - but use them wisely..."},
 [3628]={["complex"]=true,["extra"]={"Teleport to the top of the mountain.","Use the Ward of the Defiler to summon Razelikh."},["source"]="QuestieDB Forever",["text"]="Destroy Razelikh the Defiler and return the Severed Horn of the Defiler to the Fallen Hero of the Horde. You will also need to return the Ward of the Defiler so that the Fallen Hero can destroy it, preventing it from ever falling into the wrong hands.\010Teleport to the top of the mountain.\010Use the Ward of the Defiler to summon Razelikh."},
 [3629]={["source"]="QuestieDB Forever",["text"]="If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan."},
 [3630]={["source"]="QuestieDB Forever",["text"]="If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge."},
 [3631]={["source"]="QuestieDB Forever",["text"]="Speak to Strahad Farsan in the Barrens."},
 [3632]={["source"]="QuestieDB Forever",["text"]="If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge."},
 [3633]={["source"]="QuestieDB Forever",["text"]="If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan."},
 [3634]={["source"]="QuestieDB Forever",["text"]="If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge."},
 [3635]={["source"]="QuestieDB Forever",["text"]="If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay."},
 [3636]={["source"]="QuestieDB Forever",["text"]="Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs."},
 [3637]={["source"]="QuestieDB Forever",["text"]="If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay."},
 [3638]={["source"]="QuestieDB Forever",["text"]="If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan."},
 [3639]={["source"]="QuestieDB Forever",["text"]="Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to Nixx Sprocketspring in Gadgetzan."},
 [3640]={["source"]="QuestieDB Forever",["text"]="If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark in Ironforge."},
 [3641]={["source"]="QuestieDB Forever",["text"]="Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to Tinkmaster Overspark in Ironforge."},
 [3642]={["source"]="QuestieDB Forever",["text"]="If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Oglethrope Obnoticus in Booty bay."},
 [3643]={["source"]="QuestieDB Forever",["text"]="Bring 6 Mithril Tubes, an Accurate Scope, and a 2 Advanced Target Dummies to Oglethorpe Obnoticus in Booty Bay."},
 [3661]={["source"]="QuestieDB Forever",["text"]="Collect 15 Wildkin Feathers from the Hinterlands for Erelas Ambersky in Rut'theran Village."},
 [3681]={["source"]="QuestieDB Forever",["text"]="Speak with Duthorian Rall in Stormwind."},
 [3701]={["source"]="QuestieDB Forever",["text"]="Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information."},
 [3702]={["source"]="QuestieDB Forever",["text"]="Listen to Royal Historian Archesonus recant the history of Thaurissan."},
 [3741]={["source"]="QuestieDB Forever",["text"]="Find Hilary's Necklace, and return it to Hilary in Lakeshire."},
 [3761]={["source"]="QuestieDB Forever",["text"]="Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff."},
 [3762]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Hamuul Runetotem in Thunder Bluff."},
 [3763]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Fandral Staghelm in Darnassus."},
 [3764]={["source"]="QuestieDB Forever",["text"]="Bring 20 Un'Goro Soil samples to Jenal at the Cenarion Enclave in Darnassus."},
 [3765]={["source"]="QuestieDB Forever",["text"]="Travel to Gershala Nightwhisper in Auberdine."},
 [3781]={["source"]="QuestieDB Forever",["text"]="Take the Arch Druid's Seed Voucher to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus."},
 [3782]={["source"]="QuestieDB Forever",["text"]="Take the Seed Voucher to Bashana Runetotem in Thunder Bluff."},
 [3783]={["source"]="QuestieDB Forever",["text"]="Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook."},
 [3784]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Hamuul Runetotem in Thunder Bluff."},
 [3785]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.\010Bring 10 Morrowgrain to Mathrengyl Bearwalker in Darnassus."},
 [3786]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.\010Bring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff."},
 [3787]={["source"]="QuestieDB Forever",["text"]="Speak with Quintis Jonespyre in Feathermoon Stronghold."},
 [3788]={["source"]="QuestieDB Forever",["text"]="Speak with Quintis Jonespyre in Feathermoon Stronghold."},
 [3789]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Fandral Staghelm in Darnassus."},
 [3790]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Fandral Staghelm in Darnassus."},
 [3791]={["source"]="QuestieDB Forever",["text"]="Bring 10 Morrowgrain to Quintis Jonespyre in Feathermoon Stronghold."},
 [3801]={["source"]="QuestieDB Forever",["text"]="Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major."},
 [3802]={["source"]="QuestieDB Forever",["text"]="Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright."},
 [3821]={["source"]="QuestieDB Forever",["text"]="Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk."},
 [3822]={["source"]="QuestieDB Forever",["text"]="Recover Sha'ni's Nose-Ring from Krom'Grul and return it to Thal'trak in Kargath. Search the various caves and mines in Dreadmaul Rock."},
 [3823]={["source"]="QuestieDB Forever",["text"]="Slay 15 Firegut Ogre-Mages, 7 Firegut Ogres, and 7 Firegut Ogre Brutes, and return to Oralius when you are finished."},
 [3824]={["source"]="QuestieDB Forever",["text"]="Find Gor'tesh, somewhere to the west of Dreadmaul Rock. Kill Gor'tesh and then take Gor'tesh's Lopped Off Head back to Oralius in Burning Steppes."},
 [3825]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Take Gor'tesh's Lopped Off Head and place it at the top of Dreadmaul Rock. Look for a soft dirt mound to plant the pike."},
 [3841]={["source"]="QuestieDB Forever",["text"]="Speak to Quentin in Thousand Needles."},
 [3842]={["source"]="QuestieDB Forever",["text"]="Bring 2 Elixir of Fortitudes to Quentin in Thousand Needles."},
 [3843]={["source"]="QuestieDB Forever",["text"]="Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies."},
 [3844]={["source"]="QuestieDB Forever",["text"]="Look around in the pond for a clue about who this wrecked raft may belong to."},
 [3845]={["source"]="QuestieDB Forever",["text"]="Examine the items inside the pack and bring them to their owner."},
 [3861]={["source"]="QuestieDB Forever",["text"]="Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed."},
 [3881]={["source"]="QuestieDB Forever",["text"]="Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater."},
 [3882]={["source"]="QuestieDB Forever",["text"]="Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater."},
 [3883]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater. Look for the chambers with the hanging larval spawns.\010Bring the Hive Wall Sample to Hol'anyee Marshal in Un'Goro Crater."},
 [3884]={["source"]="QuestieDB Forever",["text"]="Return the journal to Williden Marshal somewhere in Un'Goro Crater."},
 [3901]={["source"]="QuestieDB Forever",["text"]="Kill 12 Rattlecage Skeletons, and then return to Shadow Priest Sarvis in Deathknell when you are done."},
 [3902]={["source"]="QuestieDB Forever",["text"]="Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain."},
 [3903]={["source"]="QuestieDB Forever",["text"]="Speak with Milly Osworth."},
 [3904]={["source"]="QuestieDB Forever",["text"]="Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey."},
 [3905]={["source"]="QuestieDB Forever",["text"]="Bring the Grape Manifest to Brother Neals in Northshire Abbey."},
 [3906]={["source"]="QuestieDB Forever",["text"]="Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment."},
 [3907]={["source"]="QuestieDB Forever",["text"]="Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart."},
 [3908]={["source"]="QuestieDB Forever",["text"]="Take Linken's Sword to Donova Snowden in Winterspring."},
 [3909]={["complex"]=true,["extra"]={"Place the Bait in front of Miblon Snarltooth."},["source"]="QuestieDB Forever",["text"]="Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring.\010Place the Bait in front of Miblon Snarltooth."},
 [3912]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova's instructions to find Gaeriyan."},
 [3913]={["source"]="QuestieDB Forever",["text"]="Resurrect, then look for the gravestone that Gaeriyan told you to find."},
 [3914]={["source"]="QuestieDB Forever",["text"]="Deliver Linken's Superior Sword to Linken in Un'Goro Crater."},
 [3921]={["source"]="QuestieDB Forever",["text"]="Bring the Broken Samophlange to Wenikee Boltbucket."},
 [3922]={["source"]="QuestieDB Forever",["text"]="Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens."},
 [3923]={["source"]="QuestieDB Forever",["text"]="Bring the Broken and Battered Samophlange to Rilli Greasygob in Orgrimmar."},
 [3924]={["source"]="QuestieDB Forever",["text"]="Bring the Samophlange Manual to Rilli Greasygob in Orgrimmar."},
 [3941]={["source"]="QuestieDB Forever",["text"]="Find J.D. Collie in the cave at Marshal's Refuge."},
 [3942]={["source"]="QuestieDB Forever",["text"]="Find Eridan Bluewind in southern Felwood."},
 [3961]={["source"]="QuestieDB Forever",["text"]="Take the Silver Totem of Aquementas to Linken in Marshal's Refuge."},
 [3962]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Travel to Fire Plume Ridge, south of Marshal's Refuge.\010Find Blazerunner and use the totem to remove his protective aura. Once he has been defeated, acquire the Golden Flame from the cave."},
 [3981]={["source"]="QuestieDB Forever",["text"]="Find Commander Gor'shak in Blackrock Depths.\010You recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort."},
 [3982]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Defend Gor'shak."},
 [4001]={["source"]="QuestieDB Forever",["text"]="Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.\010You recall Gor'shak mentioning that Kharan is being held in a cell nearby."},
 [4002]={["source"]="QuestieDB Forever",["text"]="Speak with Thrall if you are prepared to take on the mission he has planned."},
 [4003]={["source"]="QuestieDB Forever",["text"]="Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell."},
 [4004]={["source"]="QuestieDB Forever",["text"]="Return to Thrall!"},
 [4005]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Take the Book of Aquor, the Silvery Claws, and the Irontree Heart to Tanaris.\010Use the Book of Aquor to summon Aquementas.\010After you have the completed totem, take it to J.D. Collie in Marshal's Refuge."},
 [4021]={["complex"]=true,["extra"]={"Hold off Kolkar invaders until Warlord Krom'zar spawns and then loot the banner spawned on his corpse."},["source"]="QuestieDB Forever",["text"]="Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads.\010Hold off Kolkar invaders until Warlord Krom'zar spawns and then loot the banner spawned on his corpse."},
 [4022]={["source"]="QuestieDB Forever",["text"]="Show Cyrus Therepentous the Black Dragonflight Molt you received from Kalaran Windblade."},
 [4023]={["source"]="QuestieDB Forever",["text"]="Show Cyrus Therepentous proof of your worth.\010You have a feeling that Cyrus already knows that you are unworthy."},
 [4024]={["complex"]=true,["extra"]={"Use the Altered Black Dragonflight Molt on Bael'gar's corpse."},["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Depths and slay Bael'Gar.\010You only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.\010Return the Encased Fiery Essence to Cyrus Therepentous.\010Use the Altered Black Dragonflight Molt on Bael'gar's corpse."},
 [4061]={["source"]="QuestieDB Forever",["text"]="Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.\010You recall Theodora mentioning the golems and elementals of that region as being a source for these shards."},
 [4062]={["source"]="QuestieDB Forever",["text"]="Take the Elemental Shard Sample to Lotwil Veriatus.\010You recall Theodora saying that Lotwil was stationed in a camp to the east."},
 [4063]={["source"]="QuestieDB Forever",["text"]="Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic."},
 [4081]={["source"]="QuestieDB Forever",["text"]="Venture to Blackrock Depths and destroy the vile aggressors!\010Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete."},
 [4082]={["source"]="QuestieDB Forever",["text"]="Venture to Blackrock Depths and destroy the vile aggressors!\010Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete."},
 [4083]={["complex"]=true,["source"]="ForeverDungeonJournal authored summary",["text"]="Bring Gloom'rel 2 Star Rubies, 20 Gold Bars and 10 Truesilver Bars, then place them in the Spectral Chalice in the Summoners' Tomb."},
 [4084]={["source"]="QuestieDB Forever",["text"]="Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood."},
 [4101]={["source"]="QuestieDB Forever",["text"]="Bring 15 Blood Amber to Arathandris Silversky in Felwood."},
 [4102]={["source"]="QuestieDB Forever",["text"]="Bring 15 Blood Amber to Maybess Riverbreeze in Felwood."},
 [4120]={["source"]="QuestieDB Forever",["text"]="Talo Thornhoof at Camp Mojache in Feralas wants you to kill 12 Angerclaw Grizzlies and 12 Felpaw Ravagers in Felwood."},
 [4121]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.\010You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.\010You will also be required to hand over your Thorium Shackles to Lexlort."},
 [4122]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.\010When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody."},
 [4123]={["source"]="QuestieDB Forever",["text"]="Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes."},
 [4124]={["source"]="QuestieDB Forever",["text"]="Speak with Ginro Hearthkindle in Feathermoon Stronghold."},
 [4125]={["source"]="QuestieDB Forever",["text"]="Locate the courier's boat somewhere along the coast of Feralas."},
 [4126]={["source"]="QuestieDB Forever",["text"]="Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos."},
 [4127]={["source"]="QuestieDB Forever",["text"]="Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found."},
 [4128]={["source"]="QuestieDB Forever",["text"]="Speak with Ragnar Thunderbrew."},
 [4129]={["source"]="QuestieDB Forever",["text"]="Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold."},
 [4130]={["source"]="QuestieDB Forever",["text"]="Speak with Ginro Hearthkindle in Feathermoon Stronghold."},
 [4131]={["source"]="QuestieDB Forever",["text"]="Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself."},
 [4132]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete."},
 [4133]={["source"]="QuestieDB Forever",["text"]="Speak with Shadowmaster Vivian Lagrave in Kargath."},
 [4134]={["source"]="QuestieDB Forever",["text"]="Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath."},
 [4135]={["source"]="QuestieDB Forever",["text"]="Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep. According to the note, it is located to the south of the Woodpaw gnoll camps."},
 [4136]={["source"]="QuestieDB Forever",["text"]="Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes."},
 [4141]={["source"]="QuestieDB Forever",["text"]="Collect 15 Bloodpetals and return to Muigin."},
 [4142]={["source"]="QuestieDB Forever",["text"]="Take a Bloodpetal to Gregan Brewspewer in Feralas."},
 [4143]={["source"]="QuestieDB Forever",["text"]="Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater."},
 [4145]={["source"]="QuestieDB Forever",["text"]="Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge."},
 [4146]={["source"]="QuestieDB Forever",["text"]="Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge."},
 [4147]={["source"]="QuestieDB Forever",["text"]="Travel to Marvon Rivetseeker's workshop in Ratchet."},
 [4161]={["source"]="QuestieDB Forever",["text"]="Collect 7 Small Spider Legs for Zarrin in Dolanaar."},
 [4181]={["source"]="QuestieDB Forever",["text"]="If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan."},
 [4182]={["source"]="QuestieDB Forever",["text"]="Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete."},
 [4183]={["source"]="QuestieDB Forever",["text"]="Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon."},
 [4184]={["source"]="QuestieDB Forever",["text"]="Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon.\010Bolvar resides in Stormwind Keep."},
 [4185]={["source"]="QuestieDB Forever",["text"]="Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor."},
 [4186]={["source"]="QuestieDB Forever",["text"]="Take Bolvar's Decree to Magistrate Solomon in Lakeshire."},
 [4201]={["source"]="QuestieDB Forever",["text"]="Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths."},
 [4223]={["source"]="QuestieDB Forever",["text"]="Speak with Marshal Maxwell in the Burning Steppes."},
 [4224]={["source"]="QuestieDB Forever",["text"]="Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task.\010You recall Marshal Maxwell telling you to search for him in a cave to the north."},
 [4241]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.\010You recall Ragged John talking about Windsor being dragged off to a prison."},
 [4242]={["source"]="QuestieDB Forever",["text"]="Give Marshal Maxwell the bad news."},
 [4243]={["source"]="QuestieDB Forever",["text"]="Find A-Me 01 in Un'Goro Crater."},
 [4244]={["source"]="QuestieDB Forever",["text"]="Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater."},
 [4245]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater."},
 [4261]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale."},
 [4262]={["source"]="QuestieDB Forever",["text"]="Slay Overmaster Pyron and return to Jalinda Sprig.\010You recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?"},
 [4263]={["source"]="QuestieDB Forever",["text"]="Find Lord Incendius in Blackrock Depths and destroy him!"},
 [4264]={["source"]="QuestieDB Forever",["text"]="You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all."},
 [4265]={["source"]="QuestieDB Forever",["text"]="Free Raschal from the Zukk'ash hive.\010Return to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well."},
 [4266]={["source"]="QuestieDB Forever",["text"]="Speak with Shandris Feathermoon in Feathermoon Stronghold."},
 [4267]={["source"]="QuestieDB Forever",["text"]="Bring Raschal's Report to Gracina Spiritmight in Darnassus."},
 [4281]={["source"]="QuestieDB Forever",["text"]="Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar."},
 [4282]={["source"]="QuestieDB Forever",["text"]="Return Marshal Windsor's Lost Information.\010Marshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge."},
 [4283]={["source"]="QuestieDB Forever",["text"]="Oralius wants 50 Blackrock Medallions. Chances are high that these medallions can be found on the orcs in the Burning Steppes."},
 [4284]={["source"]="QuestieDB Forever",["text"]="Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge."},
 [4285]={["source"]="QuestieDB Forever",["text"]="Discover the location of the Northern Crystal Pylon in Un'Goro Crater."},
 [4286]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions."},
 [4287]={["source"]="QuestieDB Forever",["text"]="Discover the location of the Eastern Crystal Pylon in Un'Goro Crater."},
 [4288]={["source"]="QuestieDB Forever",["text"]="Discover the location of the Western Crystal Pylon."},
 [4289]={["source"]="QuestieDB Forever",["text"]="Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater."},
 [4290]={["source"]="QuestieDB Forever",["text"]="Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater."},
 [4291]={["source"]="QuestieDB Forever",["text"]="Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater."},
 [4292]={["complex"]=true,["extra"]={"Place the meat","Apply the pheromones"},["source"]="QuestieDB Forever",["text"]="Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.\010Place the meat\010Apply the pheromones"},
 [4293]={["source"]="QuestieDB Forever",["text"]="Gather Felwood Slime Samples from any of the slimes in Felwood. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most corrupt. Bring 5 of the Corrupted Felwood Samples you find to Chemist Fuely."},
 [4294]={["source"]="QuestieDB Forever",["text"]="Gather Un'Goro Slime Samples from any of the slimes in Un'Goro Crater. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most pure. Bring 5 of the Pure Un'Goro Samples you find to Chemist Fuely."},
 [4295]={["source"]="ForeverDungeonJournal authored summary",["text"]="Bring Private Rocknot two Dark Iron Ale Mugs."},
 [4296]={["source"]="QuestieDB Forever",["text"]="Bring the Tablet Transcript to Maxwort Uberglint in the Burning Steppes."},
 [4297]={["source"]="QuestieDB Forever",["text"]="Bring 5 Silvermane Stalker Flanks to Agnar Beastamer in Hinterlands."},
 [4298]={["source"]="QuestieDB Forever",["text"]="Speak to Agnar Beastamer in the Hinterlands."},
 [4300]={["source"]="QuestieDB Forever",["text"]="Bring 8 White Ravasaur Claws to Jes'rimon in Orgrimmar."},
 [4301]={["source"]="QuestieDB Forever",["text"]="Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater."},
 [4321]={["source"]="QuestieDB Forever",["text"]="Speak with J.D. Collie in a moment."},
 [4322]={["source"]="QuestieDB Forever",["text"]="Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed."},
 [4324]={["source"]="QuestieDB Forever",["text"]="Speak with Yuka Screwspigot in the Burning Steppes."},
 [4341]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Depths and find Kharan Mighthammer.\010The King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison."},
 [4342]={["source"]="QuestieDB Forever",["text"]="Listen as Kharan Mighthammer tells his story."},
 [4361]={["source"]="QuestieDB Forever",["text"]="Return to Ironforge and deliver the bad news to King Magni Bronzebeard."},
 [4362]={["source"]="QuestieDB Forever",["text"]="Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan."},
 [4363]={["source"]="QuestieDB Forever",["text"]="Return to Ironforge and speak with King Magni Bronzebeard."},
 [4402]={["source"]="QuestieDB Forever",["text"]="Bring Galgar 10 Cactus Apples. You remember him saying that they could be found near cactuses."},
 [4421]={["source"]="QuestieDB Forever",["text"]="Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed."},
 [4441]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial."},
 [4442]={["source"]="QuestieDB Forever",["text"]="Speak to Eridan again in a moment."},
 [4449]={["source"]="QuestieDB Forever",["text"]="Kill 8 Dark Iron Geologists and bring 15 pieces of Silk Cloth to the person locked in the outhouse in Searing Gorge."},
 [4450]={["source"]="QuestieDB Forever",["text"]="Take the copy of Goodsteel's Ledger and then find the items listed in it before seeking Krinkle Goodsteel in Tanaris."},
 [4451]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Search Searing Gorge and find a use for the Grimesilt Outhouse Key you have found."},
 [4485]={["source"]="QuestieDB Forever",["text"]="Speak to Duthorian Rall in Stormwind."},
 [4486]={["source"]="QuestieDB Forever",["text"]="Speak to Duthorian Rall in Stormwind."},
 [4487]={["source"]="QuestieDB Forever",["text"]="Speak to Strahad Farsan in Ratchet."},
 [4488]={["source"]="QuestieDB Forever",["text"]="Speak to Strahad Farsan in Ratchet."},
 [4489]={["source"]="QuestieDB Forever",["text"]="Speak to Strahad Farsan in Ratchet."},
 [4490]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Speak to Strahad Farsan in Ratchet to learn the ability to summon a Felsteed."},
 [4491]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Lead Ringo to Spraggle Frock at Marshal's Refuge.\010If Ringo faints, use Spraggle's Canteen to revive him."},
 [4492]={["source"]="QuestieDB Forever",["text"]="Find Ringo at Fire Plume Ridge."},
 [4493]={["source"]="QuestieDB Forever",["text"]="Speak to Alchemist Pestlezugg in Gadgetzan."},
 [4494]={["source"]="QuestieDB Forever",["text"]="Speak to Alchemist Pestlezugg in Gadgetzan."},
 [4495]={["source"]="QuestieDB Forever",["text"]="Find Iverron by the cave to the north."},
 [4496]={["source"]="QuestieDB Forever",["text"]="Bring a Gorishi Scent Gland and 5 Un'Goro Soil samples to Alchemist Pestlezugg in Gadgetzan."},
 [4501]={["source"]="QuestieDB Forever",["text"]="Kill 10 Pterrordax and 15 Frenzied Pterrordax, then speak to Spraggle Frock at Marshal's Refuge."},
 [4502]={["source"]="QuestieDB Forever",["text"]="Collect 9 samples of Un'Goro Ash from the fire elementals around the volcano in Un'Goro Crater, and return them to Liv Rizzlefix in Ratchet."},
 [4503]={["source"]="QuestieDB Forever",["text"]="Collect 8 Webbed Diemetradon Scales and 8 Webbed Pterrordax Scales for Shizzle in Marshal's Refuge."},
 [4504]={["source"]="QuestieDB Forever",["text"]="Collect 12 samples of Super Sticky Tar for Tran'rek in Gadgetzan."},
 [4505]={["source"]="QuestieDB Forever",["text"]="Collect a sample of corrupted water from the Jadefire Satyrs' moonwell and bring it to Winna Hazzard at Bloodvenom Post."},
 [4506]={["complex"]=true,["extra"]={"Release the kitten near the Jadefire Satyrs' corrupted moonwell."},["source"]="QuestieDB Forever",["text"]="Take Winna's kitten to the corrupted moonwell, release it, then bring it back to Winna.\010Once you have returned to Winna, click on the cat to release it to Winna.\010Release the kitten near the Jadefire Satyrs' corrupted moonwell."},
 [4507]={["complex"]=true,["extra"]={"Use the Gorishi Queen Lure."},["source"]="QuestieDB Forever",["text"]="Defeat the Gorishi Hive Queen once she is summoned.\010Bring the Gorishi Queen's Brain to Alchemist Pestlezugg in Gadgetzan.\010Use the Gorishi Queen Lure."},
 [4508]={["source"]="QuestieDB Forever",["text"]="Bring Pestlezugg's Un'Goro Report to Gracina Spiritmight in Darnassus."},
 [4509]={["source"]="QuestieDB Forever",["text"]="Bring Pestlezugg's Un'Goro Report to Zilzibin Drumlore in Orgrimmar."},
 [4510]={["source"]="QuestieDB Forever",["text"]="Bring the Bank Voucher to Idriana in the bank of Darnassus."},
 [4511]={["source"]="QuestieDB Forever",["text"]="Bring the Bank Voucher to Karus in the bank of Orgrimmar."},
 [4512]={["source"]="QuestieDB Forever",["text"]="Bring 6 Filled Cursed Ooze Jars and 6 Filled Tainted Ooze Jars to Laris Geardawdle in Ironforge."},
 [4513]={["source"]="QuestieDB Forever",["text"]="Bring 10 Filled Pure Sample Jars to Laris Geardawdle in Ironforge.\010If you have trouble finding them, perhaps try to get more clues from Laris."},
 [4521]={["source"]="QuestieDB Forever",["text"]="Trull Failbane in Felwood wants you to kill 15 Raging Owlbeasts and 15 Ragged Owlbeasts."},
 [4542]={["source"]="QuestieDB Forever",["text"]="Bring the Urgent Message to Cliffwatcher Longhorn at Freewind Post."},
 [4581]={["source"]="QuestieDB Forever",["text"]="Take Shindrell's Note to Kayneth Stillwind in Forest Song."},
 [4601]={["source"]="QuestieDB Forever",["text"]="Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine."},
 [4602]={["source"]="QuestieDB Forever",["text"]="Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine."},
 [4621]={["source"]="QuestieDB Forever",["text"]="Slay Fleet Master Seahorn and Baron Revilgaz of Booty Bay, and then return to Fleet Master Firallon aboard the Crimson Veil off the coast of Stranglethorn Vale."},
 [4641]={["source"]="QuestieDB Forever",["text"]="Speak with Gornek. You recall Kaltunk marking your map with his location and mentioning that Gornek resided in the Den, a building to the west."},
 [4642]={["source"]="QuestieDB Forever",["text"]="Bring a Merged Ooze Sample to Chemist Fuely in Undercity."},
 [4681]={["source"]="QuestieDB Forever",["text"]="Recover the Sea Turtle Remains from the Skeletal Sea Turtle in the waters west of Auberdine, and then speak with Gwennyth Bly'Leggonde back in Auberdine."},
 [4701]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg."},
 [4721]={["source"]="QuestieDB Forever",["text"]="Trull Failbane in Felwood wants you to hunt 10 Berserk Owlbeasts in Winterspring."},
 [4722]={["source"]="QuestieDB Forever",["text"]="Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine."},
 [4723]={["source"]="QuestieDB Forever",["text"]="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
 [4724]={["source"]="QuestieDB Forever",["text"]="Slay Halycon, pack mistress of the Bloodaxe worg."},
 [4725]={["source"]="QuestieDB Forever",["text"]="Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine."},
 [4726]={["complex"]=true,["extra"]={"Use the Draco-Incarcinatrix 900 and defeat the dragonkin."},["source"]="QuestieDB Forever",["text"]="Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes.\010Use the Draco-Incarcinatrix 900 and defeat the dragonkin."},
 [4727]={["source"]="QuestieDB Forever",["text"]="Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine."},
 [4728]={["source"]="QuestieDB Forever",["text"]="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
 [4729]={["complex"]=true,["extra"]={"Use the Empty Worg Pup Cage to capture it."},["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler.\010Use the Empty Worg Pup Cage to capture it."},
 [4730]={["source"]="QuestieDB Forever",["text"]="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
 [4731]={["source"]="QuestieDB Forever",["text"]="Take the Strangely Marked Box to Gwennyth Bly'Leggonde in Auberdine."},
 [4732]={["source"]="QuestieDB Forever",["text"]="Take the Sea Turtle Remains to Gwennyth Bly'Leggonde in Auberdine."},
 [4733]={["source"]="QuestieDB Forever",["text"]="Take the Sea Creature Bones to Gwennyth Bly'Leggonde in Auberdine."},
 [4734]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Eggscilloscope Prototype on an egg in the Rookery."},
 [4735]={["source"]="QuestieDB Forever",["text"]="Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes."},
 [4736]={["source"]="QuestieDB Forever",["text"]="Speak to Menara Voidrender in the Barrens."},
 [4737]={["source"]="QuestieDB Forever",["text"]="Speak to Menara Voidrender in the Barrens."},
 [4738]={["source"]="QuestieDB Forever",["text"]="Speak with Menara Voidrender in the Barrens."},
 [4739]={["source"]="QuestieDB Forever",["text"]="Speak to Menara Voidrender in the Barrens."},
 [4740]={["source"]="QuestieDB Forever",["text"]="Find and slay the murloc known as Murkdeep. The creature is thought to be defending the murloc huts south of Auberdine along the water.\010Report the death of Murkdeep to Sentinel Glynda Nal'Shea in Auberdine."},
 [4741]={["source"]="QuestieDB Forever",["text"]="Trull Failbane in Felwood wants you to hunt 13 Moontouched Owlbeasts."},
 [4742]={["source"]="QuestieDB Forever",["text"]="Find the three gemstones of command: The Gemstone of Smolderthorn, Gemstone of Spirestone, and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan.\010The Generals, as told to you by Vaelan, are: War Master Voone of the Smolderthorn; Highlord Omokk of the Spirestone; and Overlord Wyrmthalak of the Bloodaxe."},
 [4743]={["complex"]=true,["extra"]={"Beat Emberstrife till his will is broken, then place the Unforged Seal of Ascension before him and use the Orb of Draconic Energy.","Use the Flames of the Black Flight over it to create the Seal."},["source"]="QuestieDB Forever",["text"]="Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake, Emberstrife and beat him without mercy until his will is broken.\010It is at that moment which you must place the Unforged Seal of Ascension before the great beast. You must then be quick to use the Orb of Draconic Energy on his weakened form and claim dominion over his mental faculties. Control the beast and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension!\010Beat Emberstrife till his will is broken, then place the Unforged Seal of Ascension before him and use the Orb of Draconic Energy.\010Use the Flames of the Black Flight over it to create the Seal."},
 [4761]={["source"]="QuestieDB Forever",["text"]="Speak with Thundris Windweaver in Auberdine."},
 [4762]={["source"]="QuestieDB Forever",["text"]="Travel north of Auberdine to the first waterfall along the Cliffspring River and draw a sample from the pool there.\010Return to Thundris Windweaver in Auberdine with the Cliffspring River Sample."},
 [4763]={["complex"]=true,["extra"]={"Summon Xabraxxis once you have the required items from the Blackwood Stores.","Kill Xabraxxis"},["source"]="QuestieDB Forever",["text"]="Fill the Empty Cleansing Bowl at the Auberdine Moonwell.\010Gather a sample of fruit, nut, and grain from the northern Blackwood furbolg camps.\010Mix the bowl and place it near the bonfire closest to the Cliffspring River at the northern camp, thus summoning the satyr corruptor.\010Take the Talisman of Corruption and bring it to Thundris Windweaver in Auberdine.\010Summon Xabraxxis once you have the required items from the Blackwood Stores.\010Kill Xabraxxis"},
 [4764]={["source"]="QuestieDB Forever",["text"]="Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes."},
 [4765]={["source"]="QuestieDB Forever",["text"]="Bring Ridgewell's Crate to Remington Ridgewell in Stormwind."},
 [4766]={["source"]="QuestieDB Forever",["text"]="Speak with Mayara Brightwing in the Burning Steppes."},
 [4767]={["source"]="QuestieDB Forever",["text"]="Bring 10 Highperch Wyvern Eggs to Elu in Freewind Post."},
 [4768]={["source"]="QuestieDB Forever",["text"]="Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath."},
 [4769]={["source"]="QuestieDB Forever",["text"]="Speak with Shadowmage Vivian Lagrave."},
 [4770]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Pao'ka Swiftmountain from Highperch, and then talk to Motega Firemane in Whitereach Post."},
 [4771]={["source"]="QuestieDB Forever",["text"]="Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink."},
 [4781]={["source"]="QuestieDB Forever",["text"]="Bring a Gold Bar to Xizk Goodstitch in Stranglethorn Vale."},
 [4782]={["source"]="QuestieDB Forever",["text"]="Return to Menara Voidrender in the Barrens."},
 [4783]={["source"]="QuestieDB Forever",["text"]="Bring 10 Vials of Hatefury Blood and 1 Lesser Infernal Stone to Menara Voidrender in the Barrens."},
 [4784]={["source"]="QuestieDB Forever",["text"]="Bring some Fine Gold Thread, 2 Smoldering Coals, and a Soul Shard to Menara Voidrender in the Barrens."},
 [4786]={["source"]="QuestieDB Forever",["text"]="Wait for Menara Voidrender to complete your robe and then speak to her again."},
 [4787]={["source"]="QuestieDB Forever",["text"]="Bring the Ancient Egg to Yeh'kinya in Tanaris."},
 [4788]={["source"]="QuestieDB Forever",["text"]="Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris."},
 [4808]={["source"]="QuestieDB Forever",["text"]="Give Tinkee's Letter to Felnok Steelspring."},
 [4809]={["source"]="QuestieDB Forever",["text"]="Bring 8 Uncracked Chillwind Horns to Felnok Steelspring."},
 [4810]={["source"]="QuestieDB Forever",["text"]="Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes."},
 [4811]={["source"]="QuestieDB Forever",["text"]="Travel east of Auberdine and look for a large, red crystal along Darkshore's eastern mountain range. Report back what you find to Sentinel Glynda Nal'Shea in Auberdine."},
 [4812]={["source"]="QuestieDB Forever",["text"]="Fill the Empty Water Tube at the Auberdine moonwell, and then investigate the red crystal along Darkshore's eastern mountain wall."},
 [4813]={["source"]="QuestieDB Forever",["text"]="Report back what you have found to Sentinel Glynda Nal'Shea in Auberdine."},
 [4821]={["source"]="QuestieDB Forever",["text"]="Return the Alien Egg to Hagar Lightninghoof in Freewind Post."},
 [4822]={["source"]="QuestieDB Forever",["text"]="Get some Strawberry Ice Cream for your ward. The lad seems to prefer Tigule's brand ice cream."},
 [4841]={["source"]="QuestieDB Forever",["text"]="Kill 12 Galak Scouts, 10 Galak Wranglers, and 6 Galak Windchasers, and then return to Cliffwatcher Longhorn in Freewind Post."},
 [4842]={["source"]="QuestieDB Forever",["text"]="Follow Donova Snowden's instructions, then report back."},
 [4861]={["source"]="QuestieDB Forever",["text"]="Locate Jaron Stoneshaper's wrecked camp and supplies in southern Winterspring."},
 [4862]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler.\010By the sound of it, these eggs could be found near spiders."},
 [4863]={["source"]="QuestieDB Forever",["text"]="Find Jaron Stoneshaper's wrecked wagon."},
 [4864]={["source"]="QuestieDB Forever",["text"]="Pick up Jaron's Supplies from the snow, then find the wildkin that stole the amulet Jaron spoke of.\010Bring Jaron's Supplies and the Blue-feathered Amulet to Jaron Stoneshaper at the lodge in Winterspring."},
 [4865]={["source"]="QuestieDB Forever",["text"]="Report your findings to Motega Firemane."},
 [4866]={["source"]="QuestieDB Forever",["text"]="In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you."},
 [4867]={["complex"]=true,["extra"]={"Combine Omokk's Head with the Roughshod Pike.","Use it to instantly kill one nearby ogre."},["source"]="QuestieDB Forever",["text"]="Read Warosh's Scroll. Bring Warosh's Mojo to Warosh.\010Combine Omokk's Head with the Roughshod Pike.\010Use it to instantly kill one nearby ogre."},
 [4881]={["source"]="QuestieDB Forever",["text"]="Warn Kanati Greycloud at Whitereach Post of the plot to kill him."},
 [4882]={["source"]="QuestieDB Forever",["text"]="Take the Blue-feathered Necklace to Trull Failbane at Bloodvenom Post."},
 [4883]={["source"]="QuestieDB Forever",["text"]="Take the Blue-feathered Necklace to Nara Wildmane."},
 [4901]={["complex"]=true,["extra"]={"Use it when Ranshalla tells you to"},["source"]="QuestieDB Forever",["text"]="Protect Ranshalla while she attempts to reactivate the Altar of Elune. Report your findings to Erelas Ambersky in Rut'theran Village.\010Use it when Ranshalla tells you to"},
 [4902]={["source"]="QuestieDB Forever",["text"]="Speak with Arch Druid Fandral Staghelm in Darnassus."},
 [4903]={["source"]="QuestieDB Forever",["text"]="Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished."},
 [4904]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Lakota Windsong from the Darkcloud Pinnacle, and then talk to Thalia Amberhide at Freewind Post."},
 [4906]={["source"]="QuestieDB Forever",["text"]="Eridan Bluewind in Felwood wants you to kill 8 Jadefire Hellcallers, 8 Jadefire Betrayers, 8 Jadefire Tricksters, and Xavaric. Return to Eridan when the task is completed."},
 [4907]={["source"]="QuestieDB Forever",["text"]="Speak with Tinkee Steamboil."},
 [4921]={["source"]="QuestieDB Forever",["text"]="Find Mankrik's wife and then return to him in the Crossroads."},
 [4941]={["source"]="QuestieDB Forever",["text"]="Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall.\010You recall having seen Eitrigg in Thrall's chamber."},
 [4961]={["source"]="QuestieDB Forever",["text"]="Kill the Demon of the Orb, then speak with Tabetha."},
 [4962]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Take the Felhas Ruby and use it on one of the Felhounds found in Desolace. After successful, bring the Felhas Ruby and the Imprisoned Felhound Spirit back to Menara Voidrender in the Barrens."},
 [4963]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Take the Infus Emerald and use it on one of the Infernals found in Desolace. After successful, bring the Infus Emerald and the Imprisoned Infernal Spirit back to Menara Voidrender in the Barrens."},
 [4964]={["source"]="QuestieDB Forever",["text"]="Wait for Menara Voidrender to complete the Orb of Dar'Orahil and then speak to her again."},
 [4965]={["source"]="QuestieDB Forever",["text"]="Speak to Menara Voidrender in the Barrens."},
 [4966]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Protect Kanati Greycloud from the centaur attack."},
 [4967]={["source"]="QuestieDB Forever",["text"]="Speak to Menara Voidrender in the Barrens."},
 [4968]={["source"]="QuestieDB Forever",["text"]="Speak to Menara Voidrender in the Barrens."},
 [4969]={["source"]="QuestieDB Forever",["text"]="Speak to Menara Voidrender in the Barrens."},
 [4970]={["source"]="QuestieDB Forever",["text"]="Collect 5 Shardtooth Meats and 5 Chillwind Meats for Rivern Frostwind in Winterspring."},
 [4971]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Temporal Displacer near one of Andorhal's silos and uncover Temporal Parasites.\010Slay 10 Temporal Parasites, and then return the Temporal Displacer to Chromie in the Andorhal Inn, Western Plaguelands."},
 [4972]={["source"]="QuestieDB Forever",["text"]="Locate 5 Andorhal Watches, found in lockboxes amongst the rubble of the city. Return with them to Chromie in the Andorhal Inn, Western Plaguelands."},
 [4973]={["source"]="QuestieDB Forever",["text"]="Locate 5 Andorhal Watches amongst the rubble of the city, and return with them to Chromie in the Andorhal Inn, Western Plaguelands."},
 [4974]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar."},
 [4975]={["source"]="QuestieDB Forever",["text"]="Wait for Menara Voidrender to complete the Orb of Noh'Orahil and then speak to her again."},
 [4976]={["source"]="QuestieDB Forever",["text"]="Return the Cleansed Infernal Orb to Menara Voidrender in the Barrens."},
 [4981]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Spire and find out what happened to Bijou."},
 [4982]={["source"]="QuestieDB Forever",["text"]="Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city."},
 [4983]={["source"]="QuestieDB Forever",["text"]="Take Bijou's Reconnaissance Report back to Grandmaster Lexlort in Kargath."},
 [4984]={["source"]="QuestieDB Forever",["text"]="Destroy 8 Diseased Wolves, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands."},
 [4985]={["source"]="QuestieDB Forever",["text"]="Destroy 8 Diseased Grizzlies, and then return to Mulgris Deepriver at the Writhing Haunt, Western Plaguelands."},
 [4986]={["source"]="QuestieDB Forever",["text"]="Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Darnassus is the next step the tauren druid sought. Seek one of the druids there for assistance."},
 [4987]={["source"]="QuestieDB Forever",["text"]="Based on the magic enchanted within the Glyphed Oaken Branch, its delivery to the Cenarion Circle in Thunder Bluff is the next step the tauren druid sought. Seek one of the druids there for assistance."},
 [5001]={["source"]="QuestieDB Forever",["text"]="Find Bijou's Belongings and return them to her. Good luck!"},
 [5002]={["source"]="QuestieDB Forever",["text"]="Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell."},
 [5021]={["source"]="QuestieDB Forever",["text"]="The ramblings of the ghostly woman indicated that she needed a package delivered. She claimed that it was where her horse was. As to where the horse is or where the package was to be delivered - the ghost remains incomprehensible."},
 [5022]={["source"]="QuestieDB Forever",["text"]="Check with the Royal Factors of Stormwind to learn the whereabouts of an Emma Felstone. There is usually a census officer located in City Hall."},
 [5023]={["source"]="QuestieDB Forever",["text"]="Check with the Royal Overseers of the Undercity to learn the whereabouts of a Jeremiah Felstone. There is usually a census officer located near guild and tabard registration."},
 [5041]={["source"]="ForeverDungeonJournal learned client text",["text"]="Find and return Crossroads' Supply Crates to Thork in the Barrens."},
 [5047]={["source"]="QuestieDB Forever",["text"]="Talk to Malyfous Darkhammer in Everlook."},
 [5048]={["source"]="QuestieDB Forever",["text"]="Find Ol' Emma in Stormwind and see if she is in fact Emma Felstone. If she is, then perhaps she'd like the package Janice Felstone made for her."},
 [5049]={["source"]="QuestieDB Forever",["text"]="Find Jeremiah Payson in the Undercity and see if he is in fact Jeremiah Felstone. If he is, then perhaps he'd like the package Janice Felstone made for him."},
 [5050]={["source"]="QuestieDB Forever",["text"]="Return to Janice Felstone in Western Plaguelands her Good Luck Half-Charm."},
 [5051]={["source"]="QuestieDB Forever",["text"]="Locate the other half of the Good Luck Charm somewhere on the Felstone Farm in Western Plaguelands and reassemble it.\010Give the Good Luck Charm to Janice Felstone on the Felstone Farm, Western Plaguelands."},
 [5052]={["source"]="QuestieDB Forever",["text"]="Bring a Blood Shard to Mangletooth in Camp Taurajo in the Barrens.\010Collect more Blood Shards if you want him to bless you with Agamaggan's power."},
 [5054]={["source"]="QuestieDB Forever",["text"]="Storm Shadowhoof at Everlook in Winterspring wants you to kill Ursius."},
 [5055]={["source"]="QuestieDB Forever",["text"]="Storm Shadowhoof at Everlook in Winterspring wants you to kill Brumeran."},
 [5056]={["source"]="QuestieDB Forever",["text"]="Storm Shadowhoof at Everlook in Winterspring wants you to defeat Shy-Rotam."},
 [5061]={["source"]="QuestieDB Forever",["text"]="Return to Darnassus and show Mathrengyl Bearwalker the Pendant of the Sea Lion."},
 [5062]={["source"]="QuestieDB Forever",["text"]="Gather 10 bushels of Incendia Agave, and then consult Magatha Grimtotem on Elder Rise in Thunderbluff."},
 [5063]={["source"]="QuestieDB Forever",["text"]="In order to create the Cap of the Scarlet Savant, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 8 Arcane Crystals; 5 Enchanted Scarlet Thread.\010You will also be required to pay 50 gold pieces for the crafting of the item."},
 [5064]={["source"]="QuestieDB Forever",["text"]="Locate and retrieve the three Secret Notes in Darkcloud Pinnacle."},
 [5065]={["source"]="QuestieDB Forever",["text"]="Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris."},
 [5066]={["source"]="QuestieDB Forever",["text"]="Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains."},
 [5067]={["source"]="QuestieDB Forever",["text"]="In order to create the Leggings of Arcana, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 5 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Frostwhisper's Embalming Fluid.\010You will also be required to pay 50 gold pieces for the crafting of the item."},
 [5068]={["source"]="QuestieDB Forever",["text"]="In order to create the Breastplate of Bloodthirst, you will be required to bring the following items back to Malyfous Darkhammer: 1 Pristine Hide of the Beast; 10 Frayed Abomination Stitchings; 5 Arcanite Bars; 5 Skin of Shadow.\010You will also be required to pay 50 gold pieces for the crafting of the item."},
 [5081]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done."},
 [5082]={["source"]="QuestieDB Forever",["text"]="Donova Snowden in Winterspring wants you to kill 8 Winterfall Pathfinders, 8 Winterfall Den Watchers, and 8 Winterfall Totemics."},
 [5083]={["source"]="QuestieDB Forever",["text"]="Bring the Empty Firewater Flask to Donova Snowden in Winterspring."},
 [5084]={["source"]="QuestieDB Forever",["text"]="Search the Deadwood furbolg camp in northern Felwood for a clue."},
 [5085]={["source"]="QuestieDB Forever",["text"]="Report back to Donova Snowden with your findings."},
 [5086]={["source"]="QuestieDB Forever",["text"]="Collect 3 Toxic Horror Droplets for Donova Snowden in Winterspring."},
 [5087]={["source"]="QuestieDB Forever",["text"]="Find the Winterfall Runners and stop them from delivering their shipment to Winterfall Village."},
 [5088]={["source"]="QuestieDB Forever",["text"]="Slay Arikara. Bring her remains and the Incendia powder to Motega Firemane in Whitereach Post as proof of your deed."},
 [5089]={["source"]="QuestieDB Forever",["text"]="Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes."},
 [5090]={["source"]="QuestieDB Forever",["text"]="Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains."},
 [5091]={["source"]="QuestieDB Forever",["text"]="Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains."},
 [5092]={["source"]="QuestieDB Forever",["text"]="Kill 10 Skeletal Flayers and 10 Slavering Ghouls in Sorrow Hill.\010Return to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands."},
 [5093]={["source"]="QuestieDB Forever",["text"]="Seek out High Executor Derrington. His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity."},
 [5094]={["source"]="QuestieDB Forever",["text"]="Seek out High Executor Derrington. His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity."},
 [5095]={["source"]="QuestieDB Forever",["text"]="Seek out High Executor Derrington. His base camp is located at the Bulwark, east of Tirisfal Glades and the Undercity."},
 [5096]={["source"]="QuestieDB Forever",["text"]="Proceed to the Scarlet Crusade's base camp between Felstone Field and Dalson's Tears and destroy their command tent.\010Place the Scourge banner at the camp, and then return to High Executor Derrington at the Bulwark, Western Plaguelands."},
 [5097]={["source"]="QuestieDB Forever",["text"]="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.\010Once all four towers are marked, return the Beacon Torch to Commander Ashlam Valorfist in Chillwind Camp, Western Plaguelands."},
 [5098]={["source"]="QuestieDB Forever",["text"]="Using the Beacon Torch, mark each tower in Andorhal; you will need to stand in the doorway of the tower to successfully mark it.\010Once all four towers are marked, return the Beacon Torch to High Executor Derrington at the Bulwark, Western Plaguelands."},
 [5102]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done."},
 [5103]={["source"]="QuestieDB Forever",["text"]="Someone in this world must know what to do with these gauntlets. Good luck!"},
 [5121]={["source"]="QuestieDB Forever",["text"]="Donova Snowden in Winterspring wants you to defeat High Chief Winterfall."},
 [5122]={["source"]="ForeverDungeonJournal authored summary",["text"]="Retrieve the Medallion of Faith from Malor the Zealous in the Scarlet Bastion and bring it back to Aurius."},
 [5123]={["source"]="QuestieDB Forever",["text"]="Bring the Crudely-written Log to Donova Snowden in Winterspring."},
 [5124]={["source"]="QuestieDB Forever",["text"]="Bring Malyfous Darkhammer 6 Enchanted Thorium Bars, 2 Essence of Fire, and 4 Star Rubies. You will also need to turn in your Unfired Plate Gauntlets."},
 [5125]={["source"]="ForeverDungeonJournal authored summary",["text"]="Give Aurius the Medallion of Faith; he joins the fight against Baron Rivendare. Claim his reward after the battle."},
 [5126]={["source"]="QuestieDB Forever",["text"]="Speak with Lorax. Listen to what he has to say."},
 [5127]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Spire and find Goraluk Anvilcrack. Slay him and then use the Blood Stained Pike upon his corpse. After his soul has been siphoned, the pike will be Soul Stained.\010You must also find the Unforged Rune Covered Breastplate.\010Return both the Soul Stained Pike and the Unforged Rune Covered Breastplate to Lorax in Winterspring."},
 [5128]={["source"]="QuestieDB Forever",["text"]="Take the Crudely-written Log to Kelek Skykeeper in southern Felwood."},
 [5141]={["source"]="QuestieDB Forever",["text"]="Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Peter Galen in Azshara.\010Completing this quest will give you access to the Dragonscale Leatherworking arts.\010The completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so."},
 [5142]={["source"]="QuestieDB Forever",["text"]="Find Pamela Redpath."},
 [5143]={["source"]="QuestieDB Forever",["text"]="Bring a Wild Leather Vest and a Wild Leather Helmet to Caryssia Moonhunter in Feralas.\010Completing this quest will give you access to the Tribal Leatherworking arts.\010The completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so."},
 [5144]={["source"]="QuestieDB Forever",["text"]="Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Sarah Tanner in Searing Gorge.\010Completing this quest will give you access to the Elemental Leatherworking arts.\010The completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so."},
 [5145]={["source"]="QuestieDB Forever",["text"]="Bring 2 Tough Scorpid Breastplates, 2 Tough Scorpid Gloves, and 10 Worn Dragonscales to Thorkaf Dragoneye in the Badlands.\010Completing this quest will give you access to the Dragonscale Leatherworking arts.\010The completion of this quest will prevent you from learning Elemental Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so."},
 [5146]={["source"]="QuestieDB Forever",["text"]="Bring 2 Heart of Fire, 2 Globe of Water, 2 Core of Earth, and 2 Breath of Wind to Brumn Winterhoof in the Arathi Mountains.\010Completing this quest will give you access to the Elemental Leatherworking arts.\010The completion of this quest will prevent you from learning Dragonscale Leatherworking and Tribal Leatherworking; be sure this is the path you wish to follow before doing so."},
 [5147]={["source"]="QuestieDB Forever",["text"]="Slay Arnak Grimtotem and bring proof of your deed to Cliffwatcher Longhorn in Freewind Post."},
 [5148]={["source"]="QuestieDB Forever",["text"]="Bring a Wild Leather Vest and a Wild Leather Helmet to Se'Jib in Stranglethorn Vale.\010Completing this quest will give you access to the Tribal Leatherworking arts.\010The completion of this quest will prevent you from learning Dragonscale Leatherworking and Elemental Leatherworking; be sure this is the path you wish to follow before doing so."},
 [5149]={["source"]="QuestieDB Forever",["text"]="Find Pamela's doll."},
 [5151]={["complex"]=true,["extra"]={"Open the cage"},["source"]="QuestieDB Forever",["text"]="Slay the beast and bring back the Hypercapacitor Gizmo and Panther Cage Key to Wizlo Bearingshiner.\010Open the cage"},
 [5152]={["source"]="QuestieDB Forever",["text"]="Speak with Marlene, south of the Ruins of Andorhal."},
 [5153]={["source"]="QuestieDB Forever",["text"]="Bring Joseph's Wedding Ring to Chromie."},
 [5154]={["source"]="QuestieDB Forever",["text"]="Bring the Annals of Darrowshire to Chromie in Andorhal."},
 [5155]={["source"]="QuestieDB Forever",["text"]="Enter Jaedenar and slay 4 Jaedenar Hounds, 4 Jaedenar Guardsmen, 6 Jaedenar Adepts, and 6 Jaedenar Cultists before returning to Greta Mosshoof in Felwood."},
 [5156]={["source"]="QuestieDB Forever",["text"]="Seek out and destroy 2 Entropic Beasts and 2 Entropic Horrors while exploring Shatter Scar Vale. After checking to see if the craters there are still filled with corrupt fel water, return to Taronn Redfeather in Felwood."},
 [5157]={["source"]="QuestieDB Forever",["text"]="Take the Empty Canteen to the Moon Well in the center of Jaedenar and fill it before returning to Greta Mosshoof in Felwood."},
 [5158]={["source"]="QuestieDB Forever",["text"]="Take the Corrupt Moon Well Water to Islen Waterseer in the Barrens."},
 [5159]={["source"]="QuestieDB Forever",["text"]="Take the Purified Moon Well Water to Greta Mosshoof in Felwood."},
 [5160]={["source"]="QuestieDB Forever",["text"]="Travel to Winterspring and find Haleh. Give her Awbee's scale."},
 [5161]={["source"]="QuestieDB Forever",["text"]="Speak with Haleh if you wish to continue."},
 [5162]={["source"]="QuestieDB Forever",["text"]="Speak with Jeziba in the Plaguelands. He resides in Andorhal."},
 [5163]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Take Umi's Mechanical Yeti and scare her friends with it:\010Legacki in Everlook (Winterspring)\010Sprinkle in Gadgetzan (Tanaris)\010Quixxil in Marshal's Refuge (Un'Goro Crater)\010When you are done, bring the Mechanical Yeti back to Umi."},
 [5164]={["source"]="QuestieDB Forever",["text"]="Read from the Catalogue of the Wayward."},
 [5165]={["source"]="QuestieDB Forever",["text"]="Using the Purified Moon Well Water, douse the flames of the four braziers of protection within Shadow Hold in Felwood, then return to Greta Mosshoof in the Emerald Sanctuary."},
 [5166]={["source"]="QuestieDB Forever",["text"]="To forge the Breastplate of the Chromatic Flight, you will be required to bring the following items to Jeziba the 'Sculptor':\0101 Chromatic Carapace.\01010 Brilliant Chromatic Scales.\01010 Blood of Heroes.\01010 Frayed Abomination Stitchings."},
 [5167]={["source"]="QuestieDB Forever",["text"]="To forge the Legplates of the Chromatic Defier, you will be required to bring the following items to Jeziba the 'Sculptor':\0101 Chromatic Carapace.\01010 Brilliant Chromatic Scales.\01010 Blood of Heroes.\0105 Skin of Shadow."},
 [5168]={["source"]="QuestieDB Forever",["text"]="Bring Davil's Libram and Redpath's Shield to Carlin Redpath."},
 [5181]={["source"]="QuestieDB Forever",["text"]="Bring the Skull of Horgus and the Shattered Sword of Marduk to Carlin Redpath at Light's Hope Chapel."},
 [5201]={["source"]="QuestieDB Forever",["text"]="Rivern Frostwind wants you to slay 5 Winterfall Shaman and 5 Winterfall Ursa."},
 [5202]={["source"]="QuestieDB Forever",["text"]="Search through Jaedenar to discover what the Blood Red Key is used for."},
 [5203]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Arko'narin to where Lightforge and her equipment are being held, and then protect her as you escape Shadow Hold. Afterwards, seek out Jessir Moonbow in Felwood to let her know what's happened to her friends."},
 [5204]={["source"]="QuestieDB Forever",["text"]="Return to Jaedenar and kill the succubus Rakaiah before finding the Remains of Trey Lightforge."},
 [5206]={["source"]="QuestieDB Forever",["text"]="Bring 5 Resonating Skulls and the Mystic Crystal to Carlin Redpath in Eastern Plaguelands."},
 [5210]={["source"]="QuestieDB Forever",["text"]="Bring the Extended Annals of Darrowshire to Carlin Redpath in Eastern Plaguelands."},
 [5211]={["complex"]=true,["extra"]={"Slay ghouls to free Darrowshire spirits"},["source"]="QuestieDB Forever",["text"]="Free 15 Darrowshire Spirits and return to Carlin Redpath.\010Slay ghouls to free Darrowshire spirits"},
 [5212]={["source"]="QuestieDB Forever",["text"]="Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample."},
 [5213]={["source"]="QuestieDB Forever",["text"]="Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink."},
 [5214]={["complex"]=true,["extra"]={"Open the box"},["source"]="QuestieDB Forever",["text"]="Find Ezra Grimm's smoke shop in Stratholme and recover a box of Grimm's Premium Tobacco. Return to Smokey LaRue when the job is done.\010Open the box"},
 [5215]={["source"]="QuestieDB Forever",["text"]="Speak with High Priestess MacDonnell at Chillwind Point, Western Plaguelands."},
 [5216]={["source"]="QuestieDB Forever",["text"]="Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron."},
 [5217]={["source"]="QuestieDB Forever",["text"]="Bring the Filled Felstone Field Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
 [5219]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron."},
 [5220]={["source"]="QuestieDB Forever",["text"]="Bring the Filled Dalson's Tears Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
 [5222]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron."},
 [5223]={["source"]="QuestieDB Forever",["text"]="Bring the Filled Writhing Haunt Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
 [5225]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron."},
 [5226]={["source"]="QuestieDB Forever",["text"]="Bring the Filled Gahrron's Withering Bottle to High Priestess MacDonnell at Chillwind Camp, Western Plaguelands."},
 [5228]={["source"]="QuestieDB Forever",["text"]="Speak with Shadow Priestess Vandis at the Bulwark, Western Plaguelands."},
 [5229]={["source"]="QuestieDB Forever",["text"]="Go to Felstone Field in Western Plaguelands to locate and defeat the Cauldron Lord present there. It may have a key that will allow access to the cauldron. You must have the Empty Felstone Field Bottle with you to secure a sample of the poisons used inside the cauldron."},
 [5230]={["source"]="QuestieDB Forever",["text"]="Bring the Filled Felstone Field Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."},
 [5231]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Go to Dalson's Tears in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Dalson's Tears Bottle with you to secure a sample of the poisons used inside the cauldron."},
 [5232]={["source"]="QuestieDB Forever",["text"]="Bring the Filled Dalson's Tears Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."},
 [5233]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Go to the Writhing Haunt in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Writhing Haunt Bottle with you to secure a sample of the poisons used inside the cauldron."},
 [5234]={["source"]="QuestieDB Forever",["text"]="Bring the Filled Writhing Haunt Bottle to Shadow Priestess Vandis at The Bulwark, Western Plaguelands."},
 [5235]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Go to Gahrron's Withering in Western Plaguelands to locate and defeat the Cauldron Lord present there, and use its key to gain access to the cauldron. You must have the Empty Gahrron's Withering Bottle with you to secure a sample of the poisons used inside the cauldron."},
 [5236]={["source"]="QuestieDB Forever",["text"]="Bring the Filled Gahrron's Withering Bottle to Shadow Priestess Vandis at the Bulwark, Western Plaguelands."},
 [5241]={["source"]="QuestieDB Forever",["text"]="Find Carlin Redpath."},
 [5242]={["source"]="QuestieDB Forever",["text"]="Kill Moora and Salia, and bring Shadow Lord Fel'dan's Head to Greta Mosshoof in Felwood."},
 [5243]={["source"]="QuestieDB Forever",["text"]="Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid."},
 [5244]={["source"]="QuestieDB Forever",["text"]="Speak with Jaron Stoneshaper in Starfall Village."},
 [5245]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands."},
 [5246]={["source"]="QuestieDB Forever",["text"]="Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands."},
 [5247]={["source"]="QuestieDB Forever",["text"]="Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands."},
 [5248]={["source"]="QuestieDB Forever",["text"]="Take the Crystal of Zin-Malor to Lake Kel'Theril in Winterspring and find a highborne spirit that will speak to you."},
 [5249]={["source"]="QuestieDB Forever",["text"]="Find Starfall Village in Winterspring and speak with Wynd Nightchaser."},
 [5250]={["source"]="QuestieDB Forever",["text"]="Find Starfall in Winterspring and speak with Wynd Nightchaser."},
 [5251]={["source"]="QuestieDB Forever",["text"]="Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive."},
 [5252]={["source"]="QuestieDB Forever",["text"]="Speak with Wynd Nightchaser in Starfall Village, and ask about the proper place for the Crystal of Zin-Malor."},
 [5253]={["source"]="QuestieDB Forever",["text"]="Deliver the Crystal of Zin-Malor to Arch Druid Fandral Staghelm in Darnassus."},
 [5261]={["source"]="QuestieDB Forever",["text"]="Speak with Eagan Peltskinner."},
 [5262]={["source"]="QuestieDB Forever",["text"]="Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands."},
 [5263]={["source"]="QuestieDB Forever",["text"]="Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff."},
 [5264]={["source"]="QuestieDB Forever",["text"]="Speak with Lord Maxwell Tyrosus. He is inside the church."},
 [5265]={["source"]="QuestieDB Forever",["text"]="Open the Argent Hold and claim your reward."},
 [5281]={["source"]="QuestieDB Forever",["text"]="Find Egan. You only know that he was last seen around Stratholme."},
 [5282]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs!\010Free 15 Restless Souls and return to Egan."},
 [5283]={["source"]="QuestieDB Forever",["text"]="To become an Armorsmith, you must make the following items and return them to Grumnus: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate."},
 [5284]={["source"]="QuestieDB Forever",["text"]="To become a Weaponsmith, you must make the following items and return them to Ironus: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces."},
 [5301]={["source"]="QuestieDB Forever",["text"]="To become an armorsmith, you must make the following items and return them to Okothos: 4 Ornate Mithril Helms, 2 Ornate Mithril Boots, 1 Ornate Mithril Breastplate."},
 [5302]={["source"]="QuestieDB Forever",["text"]="To become a Weaponsmith, you must make the following items and return them to Borgosh: 4 Moonsteel Broadswords, 4 Massive Iron Axes, 2 Heavy Mithril Axes, and 2 Big Black Maces."},
 [5305]={["source"]="QuestieDB Forever",["text"]="Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith."},
 [5306]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram."},
 [5307]={["source"]="QuestieDB Forever",["text"]="Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane."},
 [5321]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Kerlonian Evershade to Liladris Moonriver at Maestra's Post in Ashenvale."},
 [5341]={["source"]="QuestieDB Forever",["text"]="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task."},
 [5342]={["source"]="QuestieDB Forever",["text"]="Travel to Chillwind Camp - Alliance territory - and assassinate Weldon Barov. Take his head and return to Alexi Barov.\010Be warned, Weldon will probably be well protected by Alliance scum."},
 [5343]={["source"]="QuestieDB Forever",["text"]="Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task."},
 [5344]={["source"]="QuestieDB Forever",["text"]="Travel to the Bulwark - Horde territory - and assassinate Alexi Barov. Take his head and return to Weldon Barov.\010Be warned, Alexi will probably be well protected by Horde filth."},
 [5361]={["source"]="QuestieDB Forever",["text"]="Deliver Cliffwatcher Longhorn Report to Nataka Longhorn at Ghost Walker Post in Desolace."},
 [5381]={["source"]="QuestieDB Forever",["text"]="Retrieve the Demon Box from Thunder Axe Fortress, and return it, along with the Demon Pick to Taiga Wisemane in Shadowprey Village."},
 [5382]={["source"]="QuestieDB Forever",["text"]="Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete."},
 [5384]={["complex"]=true,["extra"]={"Summon Kirtonos"},["source"]="QuestieDB Forever",["text"]="Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul.\010Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff.\010Summon Kirtonos"},
 [5385]={["source"]="QuestieDB Forever",["text"]="Return the Remains of Trey Lightforge to Jessir Moonbow in Felwood."},
 [5386]={["source"]="QuestieDB Forever",["text"]="Talk to Jinar'Zillen at Shadowprey Village, and then bring Nataka Longhorn 2 Bloodbelly fish."},
 [5441]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Foreman's Blackjack on Lazy Peons when they're sleeping. Wake up 5 peons, then return the Foreman's Blackjack to Foreman Thazz'ril in the Valley of Trials."},
 [5461]={["source"]="QuestieDB Forever",["text"]="Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke."},
 [5462]={["source"]="QuestieDB Forever",["text"]="Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered."},
 [5463]={["source"]="QuestieDB Forever",["text"]="Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground."},
 [5464]={["source"]="QuestieDB Forever",["text"]="Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands."},
 [5465]={["source"]="QuestieDB Forever",["text"]="Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake."},
 [5466]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke."},
 [5481]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 3 Gloom Weed and deliver them to Junior Apothecary Holland in the Brill graveyard."},
 [5482]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 10 Doom Weed and deliver them back to Junior Apothecary Holland."},
 [5501]={["source"]="QuestieDB Forever",["text"]="Bring 10 Kodo Bones from the Kodo Graveyard to Bibbly F'utzbuckle at Kormek's Hut."},
 [5502]={["source"]="QuestieDB Forever",["text"]="Return your ward to the Orgrimmar orphanage by handing in the Orcish Orphan Whistle to Orphan Matron Battlewail in the Valley of Honor."},
 [5504]={["source"]="QuestieDB Forever",["text"]="Bring 10 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark, Western Plaguelands."},
 [5507]={["source"]="QuestieDB Forever",["text"]="Bring 10 Argent Dawn Valor Tokens to Quartermaster Lightspark at Chillwind Camp, Western Plaguelands."},
 [5513]={["source"]="QuestieDB Forever",["text"]="Bring 10 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands."},
 [5514]={["source"]="QuestieDB Forever",["text"]="Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan."},
 [5515]={["source"]="QuestieDB Forever",["text"]="Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff."},
 [5517]={["source"]="QuestieDB Forever",["text"]="Bring 25 Argent Dawn Valor Tokens to Quartermaster Breechlock at Light's Hope Chapel, Eastern Plaguelands."},
 [5518]={["source"]="QuestieDB Forever",["text"]="Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul."},
 [5521]={["source"]="QuestieDB Forever",["text"]="Bring 25 Argent Dawn Valor Tokens to Quartermaster Lightspark at Chillwind Camp, Western Plaguelands."},
 [5522]={["source"]="QuestieDB Forever",["text"]="Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands."},
 [5524]={["source"]="QuestieDB Forever",["text"]="Bring 25 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark, Western Plaguelands."},
 [5525]={["complex"]=true,["source"]="ForeverDungeonJournal authored summary",["text"]="Find a Gordok Shackle Key on the ogres of the Gordok wing and use it to free Knot Thimblejack."},
 [5526]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade."},
 [5527]={["source"]="QuestieDB Forever",["text"]="Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade."},
 [5529]={["source"]="QuestieDB Forever",["text"]="Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel."},
 [5531]={["source"]="QuestieDB Forever",["text"]="Bring the Frozen Eggs to Betina Bigglezink."},
 [5533]={["source"]="QuestieDB Forever",["text"]="Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands."},
 [5534]={["source"]="QuestieDB Forever",["text"]="Find Some Rune that the naga have in their possession in the Ruins of Eldarath and return it to Kim'jael in Azshara."},
 [5535]={["source"]="QuestieDB Forever",["text"]="Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara."},
 [5536]={["source"]="QuestieDB Forever",["text"]="Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale."},
 [5537]={["source"]="QuestieDB Forever",["text"]="Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands."},
 [5538]={["source"]="QuestieDB Forever",["text"]="Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan."},
 [5541]={["source"]="QuestieDB Forever",["text"]="Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh."},
 [5542]={["source"]="QuestieDB Forever",["text"]="Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete."},
 [5543]={["source"]="QuestieDB Forever",["text"]="Slay 30 Plaguebats and return to Tirion Fordring."},
 [5544]={["source"]="QuestieDB Forever",["text"]="Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat."},
 [5545]={["source"]="QuestieDB Forever",["text"]="Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp."},
 [5561]={["complex"]=true,["extra"]={"Lure the Kodos to Smeed Scrabblescrew."},["source"]="QuestieDB Forever",["text"]="Bring five Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp.\010Lure the Kodos to Smeed Scrabblescrew."},
 [5581]={["source"]="QuestieDB Forever",["text"]="Banish 6 Portals at Mannoroc Coven and return to Taiga Wisemane at Shadowprey Village."},
 [5582]={["source"]="QuestieDB Forever",["text"]="Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands."},
 [5601]={["source"]="QuestieDB Forever",["text"]="Find Pamela Redpath in Darrowshire."},
 [5621]={["source"]="QuestieDB Forever",["text"]="Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar."},
 [5622]={["source"]="QuestieDB Forever",["text"]="Speak to Laurna Morninglight in Teldrassil."},
 [5623]={["source"]="QuestieDB Forever",["text"]="Speak to Priestess Josetta in Elwynn Forest."},
 [5624]={["source"]="QuestieDB Forever",["text"]="Find Guard Roberts and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Priestess Josetta in Goldshire."},
 [5625]={["source"]="QuestieDB Forever",["text"]="Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos."},
 [5626]={["source"]="QuestieDB Forever",["text"]="Speak to Maxan Anvol in Dun Morogh."},
