 [5648]={["source"]="QuestieDB Forever",["text"]="Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill."},
 [5649]={["source"]="QuestieDB Forever",["text"]="Speak to Tai'jin in Durotar."},
 [5650]={["source"]="QuestieDB Forever",["text"]="Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill."},
