 [5713]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale."},
 [5721]={["complex"]=true,["extra"]={"Place the Relic Bundle in the Town Square."},["source"]="QuestieDB Forever",["text"]="Place the Relic Bundle at the Darrowshire town square.\010Prevent Davil Lightfire's death until the death of Horgus.\010Prevent Captain Redpath's death until Redpath the Corrupted appears.\010Defeat Redpath the Corrupted.\010Speak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.\010Place the Relic Bundle in the Town Square."},
 [5722]={["source"]="ForeverDungeonJournal learned client text",["text"]="Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest."},
 [5723]={["source"]="ForeverDungeonJournal learned client text",["text"]="Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff."},
 [5724]={["source"]="ForeverDungeonJournal learned client text",["text"]="Take the Grimtotem Satchel to Rahauro in Thunder Bluff."},
 [5725]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity."},
 [5726]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring a Lieutenant's Insignia to Thrall in Orgrimmar."},
 [5727]={["source"]="ForeverDungeonJournal learned client text",["text"]="Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar."},
 [5728]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar."},
 [5729]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak to Neeru Fireblade in Orgrimmar."},
 [5730]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak to Thrall in Orgrimmar and tell him what you've learned."},
 [5741]={["source"]="QuestieDB Forever",["text"]="Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor."},
 [5742]={["source"]="QuestieDB Forever",["text"]="Listen to what Tirion Fordring has to say."},
 [5761]={["source"]="ForeverDungeonJournal learned client text",["text"]="Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar."},
 [5762]={["source"]="QuestieDB Forever",["text"]="Take Kravel's Crate to Hemet Nesingwary in Stranglethorn."},
 [5763]={["source"]="QuestieDB Forever",["text"]="Bring Roon's Kodo Horn to Hemet Nesingwary in Stranglethorn."},
 [5781]={["complex"]=true,["extra"]={"Search the false grave for the Taelan's Hammer."},["source"]="QuestieDB Forever",["text"]="Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.\010Search the false grave for the Taelan's Hammer."},
 [5801]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.\010Bring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands."},
 [5802]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.\010Bring the Unfinished Skeleton Key to Apothecary Dithers at the Bulwark, Western Plaguelands."},
 [5803]={["source"]="QuestieDB Forever",["text"]="Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands."},
 [5804]={["source"]="QuestieDB Forever",["text"]="Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands."},
 [5805]={["source"]="QuestieDB Forever",["text"]="Bring the Northshire Gift Voucher to Merissa Stilwell."},
 [5821]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort the Gizelton Caravan past the Kolkar Centaur village. Talk with Smeed at Scrabblescrew's Camp for your reward."},
 [5841]={["source"]="QuestieDB Forever",["text"]="Bring the Coldridge Valley Gift Voucher to Yori Crackhelm."},
 [5842]={["source"]="QuestieDB Forever",["text"]="Bring the Shadowglen Gift Voucher to Orenthil Whisperwind."},
 [5843]={["source"]="QuestieDB Forever",["text"]="Bring the Valley of Trials Gift Voucher to Magga."},
 [5844]={["source"]="QuestieDB Forever",["text"]="Bring the Camp Narache Gift Voucher to Vorn Skyseer."},
 [5845]={["source"]="QuestieDB Forever",["text"]="Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective."},
 [5846]={["source"]="QuestieDB Forever",["text"]="Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."},
 [5847]={["source"]="QuestieDB Forever",["text"]="Bring the Deathknell Gift Voucher to Claire Willower in Deathknell."},
 [5848]={["source"]="QuestieDB Forever",["text"]="Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.\010Return the painting to Tirion Fordring."},
 [5861]={["source"]="QuestieDB Forever",["text"]="Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the Hag Tirion's Gift."},
 [5862]={["complex"]=true,["extra"]={"Ask for the illusion"},["source"]="QuestieDB Forever",["text"]="Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.\010Hearthglen is to the north, Taelan should be inside of Mardenholde Keep.\010Ask for the illusion"},
 [5863]={["source"]="QuestieDB Forever",["text"]="Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager."},
 [5881]={["source"]="QuestieDB Forever",["text"]="Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens."},
 [5892]={["source"]="QuestieDB Forever",["text"]="Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar."},
 [5893]={["source"]="QuestieDB Forever",["text"]="Bring 10 Coldtooth Supplies to the Horde Quatermaster in Frostwolf Keep."},
 [5901]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Mickey Levine at the Bulwark in Tirisfal Glades."},
 [5902]={["source"]="QuestieDB Forever",["text"]="Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites."},
 [5903]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands."},
 [5904]={["complex"]=true,["extra"]={"Place the Termite Barrel"},["source"]="QuestieDB Forever",["text"]="Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.\010Place the Termite Barrel"},
 [5921]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven."},
 [5922]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven."},
 [5923]={["source"]="QuestieDB Forever",["text"]="Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."},
 [5924]={["source"]="QuestieDB Forever",["text"]="Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."},
 [5925]={["source"]="QuestieDB Forever",["text"]="Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."},
 [5926]={["source"]="QuestieDB Forever",["text"]="Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."},
 [5927]={["source"]="QuestieDB Forever",["text"]="Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."},
 [5928]={["source"]="QuestieDB Forever",["text"]="Speak with Turak Runetotem on the Elder Rise of Thunder Bluff."},
 [5929]={["source"]="QuestieDB Forever",["text"]="Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear. When finished, return to Dendrite Starblaze in Nighthaven, Moonglade."},
 [5930]={["source"]="QuestieDB Forever",["text"]="Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear. When finished, return to Dendrite Starblaze in Nighthaven, Moonglade."},
 [5931]={["complex"]=true,["extra"]={"Talk to Silva Fil'naveth to fly back to Darnassus"},["source"]="QuestieDB Forever",["text"]="Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave.\010Talk to Silva Fil'naveth to fly back to Darnassus"},
 [5932]={["complex"]=true,["extra"]={"Talk to Bunthen Plainswind to fly back to Thunder Bluff"},["source"]="QuestieDB Forever",["text"]="Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise.\010Talk to Bunthen Plainswind to fly back to Thunder Bluff"},
 [5941]={["source"]="QuestieDB Forever",["text"]="Take the Bundle of Relics to Chromie in Andorhal."},
 [5942]={["source"]="QuestieDB Forever",["text"]="Bring Joseph's Key to Joseph's Chest."},
 [5943]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort the Gizelton Caravan through Mannoroc Coven. Talk with Smeed at Scrabblescrew's Camp for your reward."},
 [5944]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Taelan Fordring out of Hearthglen."},
 [5961]={["source"]="QuestieDB Forever",["text"]="Speak with Nathanos Blightcaller in the Eastern Plaguelands. He is said to have taken up residence at the Marris Stead."},
 [5981]={["source"]="QuestieDB Forever",["text"]="Rivern Frostwind wants you to kill 4 Frostmaul Giants and 4 Frostmaul Preservers."},
 [6001]={["complex"]=true,["extra"]={"Use the Cenarion Moondust","Defeat Lunaclaw"},["source"]="QuestieDB Forever",["text"]="Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\010Speak with Mathrengyl Bearwalker in Darnassus when you are done.\010Defeat Lunaclaw"},
 [6002]={["complex"]=true,["extra"]={"Use the Cenarion Lunardust","Defeat Lunaclaw"},["source"]="QuestieDB Forever",["text"]="Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\010Speak with Turak Runetotem in Thunder Bluff when you are done.\010Defeat Lunaclaw"},
 [6004]={["source"]="QuestieDB Forever",["text"]="Kill 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi and 2 Scarlet Knights before returning to Kirsta Deepshadow in Western Plaguelands."},
 [6021]={["source"]="QuestieDB Forever",["text"]="Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel."},
 [6022]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot."},
 [6023]={["source"]="QuestieDB Forever",["text"]="Kill Huntsman Radley and Cavalier Durgen before returning to Kirsta Deepshadow in Western Plaguelands."},
 [6024]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Kill Infiltrator Hameya. Use his key on the Mound of Dirt behind the Undercroft."},
 [6025]={["source"]="QuestieDB Forever",["text"]="Enter Hearthglen and find a high vantage point from which you can see the town and gauge the Scarlet Crusade's forces, then return to Kirsta Deepshadow in Western Plaguelands."},
 [6026]={["source"]="QuestieDB Forever",["text"]="Smokey LaRue wants you to get 2 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs, and 8 Unstable Triggers.\010You will have to find a blacksmith and an engineer for these items."},
 [6027]={["complex"]=true,["extra"]={"Summon Lord Kragaru"},["source"]="QuestieDB Forever",["text"]="Get the Book of the Ancients and return it to Azore Aldamort at the tower in Ethel Rethor.\010Summon Lord Kragaru"},
 [6028]={["source"]="QuestieDB Forever",["text"]="Deliver the Everlook Report to Argent Officer Pureheart at Chillwind Camp, Western Plaguelands."},
 [6029]={["source"]="QuestieDB Forever",["text"]="Deliver the Everlook Report to Argent Officer Garush at the Bulwark, Western Plaguelands."},
 [6030]={["source"]="QuestieDB Forever",["text"]="Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands."},
 [6031]={["source"]="QuestieDB Forever",["text"]="Bring 30 Runecloth to Meilosh in Timbermaw Hold."},
 [6032]={["source"]="QuestieDB Forever",["text"]="Bring 2 Mooncloth to Meilosh in Timbermaw Hold."},
 [6041]={["complex"]=true,["extra"]={"Plant the bomb!"},["source"]="QuestieDB Forever",["text"]="Travel to Plaguewood, northwest of Light's Hope. Destroy 8 Scourge Structures by using Smokey's Special Compound at the Mark of Detonation planted inside each building. Smokey has had the Ziggurats and Slaughterhouses marked.\010Once you plant the bomb, leave the building and marvel at your handiwork.\010By the way, Smokey's Special Compound is rather... unstable."},
 [6042]={["source"]="QuestieDB Forever",["text"]="Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished."},
 [6061]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."},
 [6062]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill."},
 [6063]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."},
 [6064]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos."},
 [6065]={["source"]="QuestieDB Forever",["text"]="Speak with Yaw Sharpmane in Bloodhoof Village."},
 [6066]={["source"]="QuestieDB Forever",["text"]="Speak with Yaw Sharpmane in Bloodhoof Village."},
 [6067]={["source"]="QuestieDB Forever",["text"]="Speak with Yaw Sharpmane in Bloodhoof Village."},
 [6068]={["source"]="QuestieDB Forever",["text"]="Speak with Thotar at Razor Hill."},
 [6069]={["source"]="QuestieDB Forever",["text"]="Speak with Thotar at Razor Hill."},
 [6070]={["source"]="QuestieDB Forever",["text"]="Speak with Thotar at Razor Hill."},
 [6071]={["source"]="QuestieDB Forever",["text"]="Speak with Dazalar in Dolanaar."},
 [6072]={["source"]="QuestieDB Forever",["text"]="Speak with Dazalar in Dolanaar."},
 [6073]={["source"]="QuestieDB Forever",["text"]="Speak with Dazalar in Dolanaar."},
 [6074]={["source"]="QuestieDB Forever",["text"]="Speak with Grif Wildheart in Kharanos."},
 [6075]={["source"]="QuestieDB Forever",["text"]="Speak with Grif Wildheart in Kharanos."},
 [6076]={["source"]="QuestieDB Forever",["text"]="Speak with Grif Wildheart in Kharanos."},
 [6081]={["source"]="QuestieDB Forever",["text"]="Speak with Ormak Grimshot in Orgrimmar."},
 [6082]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill."},
 [6083]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill."},
 [6084]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos."},
 [6085]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos."},
 [6086]={["source"]="QuestieDB Forever",["text"]="Speak with Belia Thundergranite in Ironforge."},
 [6087]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."},
 [6088]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village."},
 [6089]={["source"]="QuestieDB Forever",["text"]="Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff."},
 [6101]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."},
 [6102]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar."},
 [6103]={["source"]="QuestieDB Forever",["text"]="Speak to Jocaste in the Cenarion Enclave, in Darnassus."},
 [6121]={["source"]="QuestieDB Forever",["text"]="Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."},
 [6122]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\010Deliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore."},
 [6123]={["source"]="QuestieDB Forever",["text"]="Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve."},
 [6124]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them. Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins."},
 [6125]={["source"]="QuestieDB Forever",["text"]="Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus."},
 [6126]={["source"]="ForeverDungeonJournal learned client text",["text"]="Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven."},
 [6127]={["complex"]=true,["source"]="ForeverDungeonJournal learned client text",["text"]="Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.\010\010Deliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens."},
 [6128]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve."},
 [6129]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them. Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads."},
 [6130]={["source"]="QuestieDB Forever",["text"]="Return to Turak Runetotem on the Elder Rise, Thunder Bluff."},
 [6132]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Melizza Brimbuzzle, then speak with Hornizz Brimbuzzle at the Kodo Graveyard in Desolace."},
 [6133]={["source"]="QuestieDB Forever",["text"]="Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.\010You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen."},
 [6134]={["complex"]=true,["extra"]={"Place the Crate of Ghost Magnets"},["source"]="QuestieDB Forever",["text"]="Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.\010Place the Crate of Ghost Magnets"},
 [6135]={["source"]="QuestieDB Forever",["text"]="Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller.\010It is said that Duskwing roams the countryside to the north of Marris Stead."},
 [6136]={["source"]="QuestieDB Forever",["text"]="Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete."},
 [6141]={["source"]="QuestieDB Forever",["text"]="Speak with Brother Anton in Desolace."},
 [6142]={["source"]="QuestieDB Forever",["text"]="Find 10 pieces of Soft-shelled Clam Meat and bring it back to Mai'Lahii at Shadowprey Village."},
 [6143]={["source"]="QuestieDB Forever",["text"]="Slay 7 Slitherblade Myrmidon, 7 Slitherblade Naga, and 5 Slitherblade Sorceresses, and then talk to Drulzegar at Shadowprey in Desolace."},
 [6144]={["source"]="QuestieDB Forever",["text"]="Travel to the Undercity and speak with Varimathras."},
 [6145]={["source"]="QuestieDB Forever",["text"]="Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.\010Take the command to Nathanos Blightcaller for further instruction."},
 [6146]={["source"]="QuestieDB Forever",["text"]="Travel to Tyr's Hand, southeast of the Marris Stead. Once there, take a bite of the Rotten Apple. While under the guise of the Scarlet Crusade, deliver the Grand Crusader's Command to Crusader Lord Valdelmar."},
 [6147]={["source"]="QuestieDB Forever",["text"]="Return to Nathanos Blightcaller with the new information."},
 [6148]={["source"]="QuestieDB Forever",["text"]="The Scarlet Crusade is on the move. Somewhere along the road from Tyr's Hand to Stratholme you will find the Oracle, Demetria, and her entourage. Hunt her down and slay her. Return to Nathanos Blightcaller should you succeed."},
 [6161]={["source"]="QuestieDB Forever",["text"]="Find Rackmore's Silver Key. Find Rackmore's Golden Key. Find and open Rackmore's Chest."},
 [6162]={["source"]="QuestieDB Forever",["text"]="Kill Overlord Ror and return his claw to Dreka'Sur at Bloodvenom Post in Felwood."},
 [6163]={["source"]="QuestieDB Forever",["text"]="Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos."},
 [6164]={["source"]="QuestieDB Forever",["text"]="Bring Augustus' Receipt Book to Augustus the Touched in Terrordale."},
 [6181]={["source"]="QuestieDB Forever",["text"]="Bring Lewis' Note to Thor the gryphon master."},
 [6182]={["source"]="QuestieDB Forever",["text"]="Speak with Mathias Shaw in Old Town Stormwind. He resides in the Barracks."},
 [6183]={["source"]="QuestieDB Forever",["text"]="Speak with Mathias Shaw again if you wish to accept his task."},
 [6184]={["source"]="QuestieDB Forever",["text"]="Travel to Chillwind Camp in the Western Plaguelands and meet up with your contact, Flint Shadowmore."},
 [6185]={["source"]="QuestieDB Forever",["text"]="Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp."},
 [6186]={["source"]="QuestieDB Forever",["text"]="Return to Stormwind and inform Highlord Bolvar Fordragon of the fate of Nathanos Marris."},
 [6261]={["source"]="QuestieDB Forever",["text"]="Bring Osric's Crate to Dungar Longdrink the gryphon master."},
 [6281]={["source"]="QuestieDB Forever",["text"]="Buy a gryphon ride from the gryphon master Thor, then bring Lewis' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind."},
 [6282]={["source"]="QuestieDB Forever",["text"]="Maggran Earthbinder in Sun Rock Retreat wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers."},
 [6283]={["source"]="QuestieDB Forever",["text"]="Maggran at Sun Rock Retreat wishes you to slay Bloodfury Ripper and bring her remains as proof of your deed."},
 [6284]={["source"]="QuestieDB Forever",["text"]="Kill Besseleth and bring Besseleth's Fang to Maggran at Sun Rock Retreat."},
 [6285]={["source"]="QuestieDB Forever",["text"]="Buy a gryphon ride to Sentinel Hill from the gryphon master Dungar Longdrink, then take Osric's Crate to Lewis at Sentinel Hill."},
 [6301]={["source"]="QuestieDB Forever",["text"]="Tammra Windfield at Sun Rock Retreat wants you to gather 10 Gaea Seeds."},
 [6321]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Podrig's Order to Karos Razok."},
 [6322]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Gordon's Crate to Michael Garrett."},
 [6323]={["source"]="ForeverDungeonJournal learned client text",["text"]="Buy a bat ride to the Undercity from the bat master Karos Razok, then take Podrig's Order to Gordon Wendham in the Undercity."},
 [6324]={["source"]="ForeverDungeonJournal learned client text",["text"]="Buy a bat ride to the Sepulcher from the bat master Michael Garrett, then bring Gordon's Crate to Deathguard Podrig in the Sepulcher."},
 [6341]={["source"]="QuestieDB Forever",["text"]="Bring Nessa's Collection to Vesprystus."},
 [6342]={["source"]="QuestieDB Forever",["text"]="Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa's Collection to Laird."},
 [6343]={["source"]="QuestieDB Forever",["text"]="Bring Laird's Response to Nessa Shadowsong."},
 [6344]={["source"]="QuestieDB Forever",["text"]="Speak with Nessa Shadowsong."},
 [6361]={["source"]="QuestieDB Forever",["text"]="Bring the Bundle of Hides to the wind rider master Devrak in the Crossroads."},
 [6362]={["source"]="QuestieDB Forever",["text"]="Buy a wind rider to Thunder Bluff from the wind rider master Devrak, then bring the Bundle of Hides to Ahanu in Thunder Bluff."},
 [6363]={["source"]="QuestieDB Forever",["text"]="Bring Ahanu's Leather Goods to Tal in Thunder Bluff."},
 [6364]={["source"]="QuestieDB Forever",["text"]="Buy a wind rider to the Crossroads from the wind rider master Tal, then bring Ahanu's Leather Goods to Jahan Hawkwing."},
 [6365]={["source"]="QuestieDB Forever",["text"]="Bring Zargh's Meats to Devrak in the Crossroads."},
 [6381]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Plant 10 Gaea Seeds in Gaea Dirt Mounds, and then return the remaining Enchanted Gaea Seeds to Tammra at Sun Rock Retreat."},
 [6382]={["source"]="QuestieDB Forever",["text"]="Speak with Senani Thunderheart at Splintertree Post, Ashenvale."},
 [6384]={["source"]="QuestieDB Forever",["text"]="Buy a wind rider to Orgrimmar from the wind rider master Devrak, then bring Zargh's Meats to Gryshka in Orgrimmar."},
 [6385]={["source"]="QuestieDB Forever",["text"]="Bring Gryshka's Letter to Doras in Orgrimmar."},
 [6386]={["source"]="QuestieDB Forever",["text"]="Buy a wind rider to the Crossroads from the wind rider master Doras, then bring Gryshka's Letter to Zargh at the Crossroads."},
 [6387]={["source"]="QuestieDB Forever",["text"]="Bring Brock's List to Thorgrum Borrelson in Thelsamar."},
 [6388]={["source"]="QuestieDB Forever",["text"]="Bring the Honorary Picks to Gryth Thurden in Ironforge."},
 [6389]={["source"]="QuestieDB Forever",["text"]="Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Nathaniel Dumah at Chillwind Camp in Western Plaguelands."},
 [6390]={["source"]="QuestieDB Forever",["text"]="Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Mickey Levine at the Bulwark in Tirisfal Glades."},
 [6391]={["source"]="QuestieDB Forever",["text"]="Buy a gryphon to Ironforge from the gryphon master Thorgrum Borrelson, then bring Brock's List to Golnir Bouldertoe in Ironforge."},
 [6392]={["source"]="QuestieDB Forever",["text"]="Buy a gryphon to Thelsamar from the gryphon master Gryth Thurden, then bring the Honorary Picks to Brock Stoneseeker in Thelsamar."},
 [6393]={["source"]="QuestieDB Forever",["text"]="Bring 10 Incendrites to Tsunaman at Sun Rock Retreat."},
 [6394]={["source"]="QuestieDB Forever",["text"]="Bring Thazz'ril's Pick to Foreman Thazz'ril."},
 [6395]={["source"]="QuestieDB Forever",["text"]="Bring Samuel Fipps' Remains to Marla's Grave, then return to Novice Elreth."},
 [6401]={["source"]="QuestieDB Forever",["text"]="Tell Tammra Windfield in Sun Rock Retreat the good news."},
 [6402]={["complex"]=true,["extra"]={"Talk to Squire Rowe"},["source"]="QuestieDB Forever",["text"]="Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived.\010Talk to Squire Rowe"},
 [6403]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Follow Reginald Windsor through Stormwind. Protect him from harm!"},
 [6421]={["source"]="QuestieDB Forever",["text"]="Explore deep into the cave at Boulderslide Ravine and bring back 10 Resonite Crystals for Mor'rogal at Sun Rock Retreat to investigate."},
 [6441]={["source"]="QuestieDB Forever",["text"]="Collect 16 Satyr Horns for Pixel in Splintertree Post."},
 [6442]={["source"]="QuestieDB Forever",["text"]="Bring 20 Wrathtail Heads to Marukai along the Zoram Strand."},
 [6461]={["source"]="QuestieDB Forever",["text"]="Xen'zilla at Malaka'Jin needs you to kill 10 Deepmoss Creepers and 7 Deepmoss Venomspitters."},
 [6462]={["source"]="QuestieDB Forever",["text"]="Bring 8 Troll Charms to Mitsuwa at the Zoram'gar Outpost."},
 [6481]={["source"]="QuestieDB Forever",["text"]="Open the Resonite cask with the Enchanted Resonite Crystal, and then slay Goggeroc. Return to Mor'rogal with the news and Enchanted Resonite Crystal."},
 [6482]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Ruul, then speak with Yama Snowhoof in Splintertree Post."},
 [6501]={["source"]="QuestieDB Forever",["text"]="You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist."},
 [6502]={["source"]="QuestieDB Forever",["text"]="You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire."},
 [6503]={["source"]="QuestieDB Forever",["text"]="Kill 9 Ashenvale Outrunners, then return to Kuray'bin at Splintertree Outpost."},
 [6504]={["source"]="QuestieDB Forever",["text"]="Find the 12 missing pages of the Shredder Operating Manual, and put them together to form Chapters 1, 2, and 3. Return the pages to Gurda Ragescar near Splintertree Post."},
 [6521]={["source"]="QuestieDB Forever",["text"]="Bring Ambassador Malcin's Head to Varimathras in the Undercity."},
 [6522]={["source"]="QuestieDB Forever",["text"]="Take the Small Scroll to Varimathras in the Undercity."},
 [6523]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Kaya Flathoof to Camp Aparaje, and then return to Makaba Flathoof near the southeastern edge of Stonetalon."},
 [6541]={["source"]="QuestieDB Forever",["text"]="Report to Kadrak at the watch tower in northern Barrens."},
 [6542]={["source"]="QuestieDB Forever",["text"]="Report to Kadrak at the watch tower in northern Barrens."},
 [6543]={["source"]="QuestieDB Forever",["text"]="Open the Bundle of Reports. Take the Warsong Reports to the Warsong Scout, Warsong Runner, and Warsong Outrider. Bring back the updates they give you to Kadrak at the northern watch tower in the barrens."},
 [6544]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post."},
 [6548]={["source"]="QuestieDB Forever",["text"]="Kill 8 Grimtotem Ruffians and 6 Grimtotem Mercenaries, and then return to Makaba Flathoof near the southeastern edge of Stonetalon."},
 [6561]={["source"]="QuestieDB Forever",["text"]="Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff."},
 [6562]={["source"]="QuestieDB Forever",["text"]="Speak to Je'neu Sancrea in Ashenvale."},
 [6563]={["source"]="QuestieDB Forever",["text"]="Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale."},
 [6564]={["source"]="QuestieDB Forever",["text"]="Bring the Damp Note to Je'neu Sancrea in Ashenvale."},
 [6565]={["source"]="QuestieDB Forever",["text"]="Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale."},
 [6566]={["source"]="QuestieDB Forever",["text"]="Listen to Thrall."},
 [6567]={["source"]="QuestieDB Forever",["text"]="Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas."},
 [6568]={["source"]="QuestieDB Forever",["text"]="Deliver Rexxar's Letter to Myranda the Hag in the Western Plaguelands."},
 [6569]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete."},
 [6570]={["source"]="QuestieDB Forever",["text"]="Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife."},
 [6571]={["source"]="QuestieDB Forever",["text"]="Collect the Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil, and the Warsong Axe Shipment for Locke Okarr in Splintertree Post."},
 [6582]={["source"]="QuestieDB Forever",["text"]="You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.\010You know that Scryer can be found in Winterspring."},
 [6583]={["source"]="QuestieDB Forever",["text"]="Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife."},
 [6584]={["source"]="QuestieDB Forever",["text"]="Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife."},
 [6585]={["source"]="QuestieDB Forever",["text"]="Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife."},
 [6601]={["source"]="QuestieDB Forever",["text"]="It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next."},
 [6602]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar."},
 [6603]={["source"]="QuestieDB Forever",["text"]="Find Donova Snowden near the hot springs in Winterspring."},
 [6604]={["source"]="QuestieDB Forever",["text"]="Speak with Jaron Stoneshaper at Starfall Village."},
 [6605]={["source"]="QuestieDB Forever",["text"]="Speak with Winna Hazzard in Felwood."},
 [6606]={["source"]="QuestieDB Forever",["text"]="Speak with Witch Doctor Mau'ari in Everlook."},
 [6607]={["source"]="QuestieDB Forever",["text"]="Nat Pagle wants you to catch the following fish:\010Misty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows.\010A Sar'theris Striker from the Sar'theris Strand in Desolace.\010Feralas Ahi from the Verdantis River of Feralas.\010Savage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale.\010Return to Nat Pagle when you have reeled them all in!"},
 [6608]={["source"]="QuestieDB Forever",["text"]="You think Lumak is trying to tell you that he can no longer help you improve your fishing skill. You may want to try to find his friend, Nat Pagle, a human fishing off one of the islands south of Theramore (at least that's what you think Lumak said)."},
 [6609]={["source"]="QuestieDB Forever",["text"]="Travel to Kalimdor, to the coastal city of Theramore. From there you must search for an island, south of the main town. Nat Pagle awaits your arrival!"},
 [6610]={["source"]="QuestieDB Forever",["text"]="Dirge Quikcleave wants you to get the following items:\01012 Giant Eggs. You will find those on the Rocs wandering Tanaris or any other species of large bird.\01010 pieces of Zesty Clam Meat. You can find those in clams, naturally!\01020 pieces of Alterac Swiss. Get thee to a cheesery!\010Gather all of the items and return to Dirge."},
 [6611]={["source"]="QuestieDB Forever",["text"]="Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career."},
 [6612]={["source"]="QuestieDB Forever",["text"]="Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career."},
 [6621]={["source"]="QuestieDB Forever",["text"]="Place Karang's Banner on the Foulweald Totem Mound. Do not let the furbolgs destroy the banner. Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar."},
 [6622]={["source"]="QuestieDB Forever",["text"]="Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.\010Remember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged."},
 [6623]={["source"]="QuestieDB Forever",["text"]="Travel to Hammerfall in the Arathi Highlands and speak with Doctor Gregory Victor about joining the ranks of Horde Trauma."},
 [6624]={["source"]="QuestieDB Forever",["text"]="Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.\010Remember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged."},
 [6625]={["source"]="QuestieDB Forever",["text"]="Travel to Theramore in the Dustwallow Marsh and speak with Doctor Gustaf VanHowzen about joining the ranks of Alliance Trauma."},
 [6626]={["source"]="QuestieDB Forever",["text"]="Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs."},
 [6627]={["source"]="QuestieDB Forever",["text"]="Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready."},
 [6628]={["source"]="QuestieDB Forever",["text"]="Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready."},
 [6629]={["source"]="QuestieDB Forever",["text"]="Kill Grundig Darkcloud and 6 Grimtotem Brutes, and return to Makaba Flathoof near the southeastern edge of Stonetalon."},
 [6641]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Keep Muglash safe as he travels to the brazier. Help him by putting the brazier out, then protect him as you fight against the Naga.\010If you are successful, return to the Zoram'gar Outpost and inform the Warsong Runner of the death of Vorsha the Lasher."},
 [6661]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Capture 5 Deeprun Rats by using the Rat Catcher's Flute. Lead the rats back to Monty. Don't forget to turn in the flute when you're finished."},
 [6662]={["source"]="QuestieDB Forever",["text"]="Take the Carton of Mystery Meat to Nipsy at the Stormwind Deeprun Tram Depot."},
 [6681]={["source"]="QuestieDB Forever",["text"]="Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\010Your cunning will be tested along the way. Be prepared."},
 [6721]={["source"]="QuestieDB Forever",["text"]="Speak with Dazalar in Dolanaar."},
 [6722]={["source"]="QuestieDB Forever",["text"]="Speak with Dazalar in Dolanaar."},
 [6761]={["source"]="QuestieDB Forever",["text"]="Speak with Mathrengyl Bearwalker at the Cenarion Enclave of Darnassus."},
 [6762]={["source"]="QuestieDB Forever",["text"]="Speak with Rabine Saturna in the village of Nighthaven, Moonglade. Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold."},
 [6804]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands. Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara."},
 [6805]={["source"]="QuestieDB Forever",["text"]="Kill 15 Dust Stormers and 15 Desert Rumblers and then return to Duke Hydraxis in Azshara."},
 [6821]={["source"]="QuestieDB Forever",["text"]="Bring the Eye of the Emberseer to Duke Hydraxis in Azshara."},
 [6822]={["source"]="QuestieDB Forever",["text"]="Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara."},
 [6823]={["source"]="QuestieDB Forever",["text"]="Earn an Honored faction with the Hydraxian Waterlords, then talk to Duke Hydraxis in Azshara."},
 [6824]={["source"]="QuestieDB Forever",["text"]="Bring the Hands of Lucifron, Sulfuron, Gehennas and Shazzrah to Duke Hydraxis in Azshara."},
 [6844]={["source"]="QuestieDB Forever",["text"]="Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade."},
 [6845]={["source"]="QuestieDB Forever",["text"]="Speak with Rabine Saturna in the village of Nighthaven, Moonglade."},
 [6847]={["source"]="QuestieDB Forever",["text"]="Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\010Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!"},
 [6848]={["source"]="QuestieDB Forever",["text"]="Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\010Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!"},
 [6921]={["source"]="QuestieDB Forever",["text"]="Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."},
 [6922]={["source"]="QuestieDB Forever",["text"]="Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."},
 [6961]={["source"]="QuestieDB Forever",["text"]="Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar."},
 [6962]={["source"]="QuestieDB Forever",["text"]="Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Orgrimmar."},
 [6963]={["source"]="QuestieDB Forever",["text"]="Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains."},
 [6964]={["source"]="QuestieDB Forever",["text"]="Speak with Sagorne Creststrider in the Valley of Wisdom of Orgrimmar about the Feast of Winter Veil."},
 [6981]={["source"]="QuestieDB Forever",["text"]="Travel to Ratchet to find someone that can tell you more about the glowing shard.\010Then, deliver the shard as you are directed."},
 [6982]={["source"]="QuestieDB Forever",["text"]="Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar."},
 [6983]={["source"]="QuestieDB Forever",["text"]="Locate and return the Stolen Treats to Kaymard Copperpinch in Orgrimmar. It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains."},
 [6984]={["source"]="QuestieDB Forever",["text"]="Speak with Great-father Winter in Orgrimmar."},
 [6985]={["source"]="QuestieDB Forever",["text"]="Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep."},
 [7001]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master. Speak with the Frostwolf Stable Master to earn credit for the capture."},
 [7003]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas."},
 [7021]={["source"]="QuestieDB Forever",["text"]="Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar."},
 [7022]={["source"]="QuestieDB Forever",["text"]="Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge."},
 [7023]={["source"]="QuestieDB Forever",["text"]="Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge."},
 [7024]={["source"]="QuestieDB Forever",["text"]="Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar."},
 [7025]={["source"]="QuestieDB Forever",["text"]="Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Ironforge."},
 [7027]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture."},
 [7028]={["source"]="QuestieDB Forever",["text"]="Collect 15 Theradric Crystal Carvings for Willow in Desolace."},
 [7029]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\010Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\010Heal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village."},
 [7041]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\010Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\010Heal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point."},
 [7042]={["source"]="QuestieDB Forever",["text"]="Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains."},
 [7043]={["source"]="QuestieDB Forever",["text"]="Locate and return the Stolen Treats to Wulmort Jinglepocket in Ironforge. It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains."},
 [7044]={["source"]="QuestieDB Forever",["text"]="Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.\010Find a way to speak with Celebras."},
 [7045]={["source"]="QuestieDB Forever",["text"]="Speak with Greatfather Winter in Ironforge."},
 [7046]={["source"]="QuestieDB Forever",["text"]="Assist Celebras the Redeemed while he creates the Scepter of Celebras.\010Speak with him when the ritual is complete."},
 [7061]={["source"]="QuestieDB Forever",["text"]="Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday. When you are finished with the book, deliver it to Cairne Bloodhoof in Thunder Bluff."},
 [7062]={["source"]="QuestieDB Forever",["text"]="Speak with Historian Karnik at the Explorer's League in Ironforge about the Feast of Winter Veil."},
 [7063]={["source"]="QuestieDB Forever",["text"]="Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday. When you are finished with the book, deliver it to King Magni Bronzebeard in Ironforge."},
 [7064]={["source"]="QuestieDB Forever",["text"]="Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace."},
 [7065]={["source"]="QuestieDB Forever",["text"]="Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace."},
 [7066]={["source"]="QuestieDB Forever",["text"]="Seek out Remulos in Moonglade and give him the Seed of Life."},
 [7067]={["source"]="QuestieDB Forever",["text"]="Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace."},
 [7068]={["source"]="QuestieDB Forever",["text"]="Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar."},
 [7070]={["source"]="QuestieDB Forever",["text"]="Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh."},
 [7081]={["source"]="QuestieDB Forever",["text"]="Assault a graveyard, then return to Sergeant Durgen Stormpike in the Alterac Mountains."},
 [7082]={["source"]="QuestieDB Forever",["text"]="Assault a graveyard, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains."},
 [7101]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Capture an enemy tower, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains."},
 [7102]={["source"]="QuestieDB Forever",["text"]="Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Alterac Mountains."},
 [7121]={["source"]="QuestieDB Forever",["text"]="Speak with the Stormpike Quartermaster."},
 [7122]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains."},
 [7123]={["source"]="QuestieDB Forever",["text"]="Speak with the Frostwolf Quartermaster."},
 [7124]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Capture a mine, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains."},
 [7141]={["source"]="QuestieDB Forever",["text"]="Enter Alterac Valley, defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Alterac Mountains."},
 [7142]={["source"]="QuestieDB Forever",["text"]="Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike. Then, return to Voggah Deathgrip in the Alterac Mountains."},
 [7161]={["source"]="QuestieDB Forever",["text"]="Travel to the Wildpaw cavern located southeast of the main base in Alterac Valley and find the Frostwolf Banner. Return the Frostwolf Banner to Warmaster Laggrond."},
 [7162]={["source"]="QuestieDB Forever",["text"]="Travel to the Icewing Caverns located southwest of Dun Baldar in Alterac Valley and recover the Stormpike Banner. Return the Stormpike Banner to Lieutenant Haggerdin in the Alterac Mountains."},
 [7181]={["source"]="QuestieDB Forever",["text"]="According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\010Should Korrak make himself known, destroy him and return to Warmaster Laggrond."},
 [7201]={["source"]="QuestieDB Forever",["text"]="Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals."},
 [7202]={["source"]="QuestieDB Forever",["text"]="According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\010Should Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Alterac Mountains."},
 [7221]={["source"]="QuestieDB Forever",["text"]="Speak with Prospector Stonehewer in the Dun Baldar garrison."},
 [7222]={["source"]="QuestieDB Forever",["text"]="Speak with Voggah in Frostwolf Keep."},
 [7223]={["source"]="QuestieDB Forever",["text"]="Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar."},
 [7224]={["source"]="QuestieDB Forever",["text"]="Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village."},
 [7241]={["source"]="QuestieDB Forever",["text"]="Venture to Alterac Valley, located in the Alterac Mountains. Find and speak with Warmaster Laggrond - who stands outside the tunnel entrance - to begin your career as a soldier of Frostwolf. You will find Alterac Valley north of Tarren Mill at the base of the Alterac Mountains."},
 [7261]={["source"]="QuestieDB Forever",["text"]="Travel to Alterac Valley in the Hillsbrad Foothills. Outside of the entrance tunnel, find and speak with Lieutenant Haggerdin.\010For the glory of Bronzebeard!"},
 [7281]={["source"]="QuestieDB Forever",["text"]="Travel into Stormpike territory and slay Commander Karl Philips. Return to Commander Louis Philips when the task is complete."},
 [7282]={["source"]="QuestieDB Forever",["text"]="Travel into Frostwolf territory and slay Commander Louis Philips. Return to Commander Karl Philips when the task is complete."},
 [7301]={["source"]="QuestieDB Forever",["text"]="Travel to Frostwolf territory and search for Wing Commander Slidore, Wing Commander Vipore, and Wing Commander Ichman. Return to Commander Duffy should you complete your mission."},
 [7302]={["source"]="QuestieDB Forever",["text"]="Find out what became of Wing Commander Guse, Wing Commander Jeztor, and Wing Commander Mulverick. Return to Commander Mulfort should you complete your mission."},
 [7321]={["source"]="QuestieDB Forever",["text"]="Bring 10 pieces of Turtle Meat and some Soothing Spices to Christoph Jeffcoat in Tarren Mill."},
 [7361]={["source"]="QuestieDB Forever",["text"]="You have been tasked with slaying opposing night elf players in Alterac Valley.\010Kill a night elf and return to Najak Hexxen at Frostwolf Keep with a Severed Night Elf Head."},
 [7362]={["source"]="QuestieDB Forever",["text"]="You have been tasked with slaying opposing gnome players in Alterac Valley.\010Kill a gnome and return to Ravak Grimtotem at Frostwolf Keep with a Tuft of Gnome Hair."},
 [7363]={["source"]="QuestieDB Forever",["text"]="You have been tasked with slaying opposing human players in Alterac Valley.\010Kill a human and return to Commander Louis Philips (who wanders between the front lines and Frostwolf keep) with a Human Bone Chip.\010A cure for the human condition is close at hand!"},
 [7364]={["source"]="QuestieDB Forever",["text"]="You have been tasked with slaying opposing tauren players in Alterac Valley.\010Kill a tauren and return to Dirk Swindle at Dun'Baldar with a Tauren Hoof."},
 [7365]={["source"]="QuestieDB Forever",["text"]="You have been tasked with slaying opposing troll players in Alterac Valley.\010Kill a troll and return to Athramanis at Dun'Baldar with Darkspear Troll Mojo."},
 [7366]={["source"]="QuestieDB Forever",["text"]="You have been tasked with slaying opposing Forsaken players in Alterac Valley.\010Kill a Forsaken and return to Commander Karl Philips (who wanders between the lumber mill and the mine) with a Forsaken Heart."},
 [7367]={["source"]="QuestieDB Forever",["text"]="Find the Frostwolf Explosives Expert and kill him. Return to the Stormpike Explosives Expert when the task is complete."},
 [7368]={["source"]="QuestieDB Forever",["text"]="Find the Stormpike Explosives Expert and kill him. Return to the Frostwolf Explosives Expert when the task is complete."},
 [7381]={["source"]="QuestieDB Forever",["text"]="Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him.\010Return the Skull of Korrak to Warmaster Laggrond in the Hillsbrad Foothills."},
 [7382]={["source"]="QuestieDB Forever",["text"]="Should Korrak the Bloodrager make a return to the Field of Strife, seek him out and destroy him.\010Return the Skull of Korrak to Lieutenant Haggerdin in the Hillsbrad Foothills."},
 [7383]={["source"]="QuestieDB Forever",["text"]="Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar."},
 [7401]={["source"]="QuestieDB Forever",["text"]="You have been tasked with slaying opposing Dwarf players in Alterac Valley.\010Kill a Dwarf and rip out their spine. Take the Dwarf Spine to Sergeant Yazra Bloodsnarl at Frostwolf Keep."},
 [7402]={["source"]="QuestieDB Forever",["text"]="You have been tasked with slaying opposing Orc players in Alterac Valley.\010Kill an Orc and take their Orc Tooth back to Corporal Noreg Stormpike at Dun Baldar."},
 [7441]={["source"]="QuestieDB Forever",["text"]="Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.\010Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations."},
 [7461]={["source"]="QuestieDB Forever",["text"]="You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\010Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\010Return to the Shen'dralar Ancient in the courtyard should you complete this quest."},
 [7462]={["source"]="QuestieDB Forever",["text"]="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!"},
 [7463]={["source"]="QuestieDB Forever",["text"]="Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence."},
 [7481]={["source"]="QuestieDB Forever",["text"]="Search Dire Maul for Telmius Dreamseeker. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find."},
 [7482]={["source"]="QuestieDB Forever",["text"]="Search Dire Maul for Telmius Dreamseeker. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find."},
 [7483]={["source"]="QuestieDB Forever",["text"]="Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity."},
 [7484]={["source"]="QuestieDB Forever",["text"]="Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus."},
 [7485]={["source"]="QuestieDB Forever",["text"]="Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection."},
 [7486]={["source"]="QuestieDB Forever",["text"]="Claim your reward from Hydraxis' Coffer."},
 [7488]={["source"]="QuestieDB Forever",["text"]="Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas."},
 [7489]={["source"]="QuestieDB Forever",["text"]="Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas."},
 [7490]={["source"]="QuestieDB Forever",["text"]="Take the Head of Onyxia to Thrall in Orgrimmar."},
 [7491]={["source"]="QuestieDB Forever",["text"]="Seek out Overlord Runthak in the Valley of Strength."},
 [7492]={["source"]="QuestieDB Forever",["text"]="Speak with Talo Thornhoof at Camp Mojache in Feralas."},
 [7494]={["source"]="QuestieDB Forever",["text"]="Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas."},
 [7495]={["source"]="QuestieDB Forever",["text"]="Take the Head of Onyxia to Highlord Bolvar Fordragon in Stormwind."},
 [7496]={["source"]="QuestieDB Forever",["text"]="Seek out Major Mattingly in the Valley of Heroes."},
 [7498]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7499]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7500]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7501]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7502]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7503]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7504]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7505]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7506]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7507]={["source"]="QuestieDB Forever",["text"]="Return Nostro's Compendium of Dragon Slaying to the Athenaeum."},
 [7508]={["source"]="QuestieDB Forever",["text"]="Give the Dull and Flat Elven Blade to Lorekeeper Lydros."},
 [7509]={["source"]="QuestieDB Forever",["text"]="You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\010The last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\010Do this and Quel'Serrar will be yours."},
 [7562]={["source"]="QuestieDB Forever",["text"]="Speak with Mor'zul Bloodbringer in the Burning Steppes."},
 [7563]={["source"]="QuestieDB Forever",["text"]="Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes."},
 [7564]={["source"]="QuestieDB Forever",["text"]="Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes."},
 [7581]={["source"]="QuestieDB Forever",["text"]="Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done."},
 [7582]={["source"]="QuestieDB Forever",["text"]="Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task."},
 [7583]={["complex"]=true,["extra"]={"Imprison the Doomguard Commander"},["source"]="QuestieDB Forever",["text"]="Venture forth into the Tainted Scar and locate a Doomguard Commander.\010Use the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.\010Should you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar.\010Imprison the Doomguard Commander"},
 [7601]={["source"]="QuestieDB Forever",["text"]="Speak with Impsy in Felwood."},
 [7602]={["source"]="QuestieDB Forever",["text"]="Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.\010The Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.\010Recover the Flawless Fel Essences and return to Impsy in Felwood."},
 [7603]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.\010Return Kroshius' Infernal Core to Niby the Almighty in Felwood."},
 [7604]={["source"]="QuestieDB Forever",["text"]="Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron."},
 [7622]={["source"]="QuestieDB Forever",["text"]="Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\010You may view the Death Post to view how many Peasants have been slain."},
 [7623]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Purchase Shadowy Potions from Gorzeeki in the Burning Steppes.\010Use the potions to travel through Jaedenar, and speak with Lord Banehollow."},
 [7624]={["source"]="QuestieDB Forever",["text"]="Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar."},
 [7625]={["source"]="QuestieDB Forever",["text"]="Purchase Xorothian Stardust from Ur'dan. Bring it to Gorzeeki Wildeyes in the Burning Steppes."},
 [7626]={["source"]="QuestieDB Forever",["text"]="Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes."},
 [7627]={["source"]="QuestieDB Forever",["text"]="Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes."},
 [7628]={["source"]="QuestieDB Forever",["text"]="Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes."},
 [7629]={["source"]="QuestieDB Forever",["text"]="Bring the Imp in a Jar to the alchemy lab in the Scholomance. After the parchment is created, return the jar to Gorzeeki Wildeyes."},
 [7630]={["source"]="QuestieDB Forever",["text"]="Bring 3 Arcanite Bar to Gorzeeki in the Burning Steppes."},
 [7631]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you."},
 [7634]={["source"]="QuestieDB Forever",["text"]="Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood."},
 [7635]={["source"]="QuestieDB Forever",["text"]="Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood."},
 [7636]={["source"]="QuestieDB Forever",["text"]="You must find and destroy these four demonic corrupters:\010Simone the Seductress.\010Klinfran the Crazed.\010Solenor the Slayer.\010Artorius the Doombringer.\010Destroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\010Refer to the Petrified Bark in your inventory for clues as to their whereabouts.\010You MUST complete this task by yourself."},
 [7637]={["source"]="QuestieDB Forever",["text"]="Travel to Ironforge and get High Priest Rohan's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it."},
 [7638]={["source"]="QuestieDB Forever",["text"]="Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."},
 [7639]={["source"]="QuestieDB Forever",["text"]="Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."},
 [7640]={["complex"]=true,["extra"]={"Exorcise the spirits"},["source"]="QuestieDB Forever",["text"]="Use the Exorcism Censer to drive out the spirits that torment Terrordale. When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.\010Exorcise the spirits"},
 [7641]={["source"]="QuestieDB Forever",["text"]="Speak with Grimand Elmore in Stormwind's Dwarven District."},
 [7642]={["source"]="QuestieDB Forever",["text"]="Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind."},
 [7643]={["source"]="QuestieDB Forever",["text"]="Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food.\010Travel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it."},
 [7644]={["source"]="QuestieDB Forever",["text"]="Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."},
 [7645]={["source"]="QuestieDB Forever",["text"]="Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills. The Argent Dawn is known as the sole purveyor of the biscuits.\010You also need to give her 50 gold to soothe her ruffled sensibilities."},
 [7646]={["source"]="QuestieDB Forever",["text"]="Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."},
 [7647]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger.\010Give the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."},
 [7648]={["source"]="QuestieDB Forever",["text"]="Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection."},
 [7649]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7650]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7651]={["source"]="QuestieDB Forever",["text"]="Return the book to its rightful owners."},
 [7667]={["source"]="QuestieDB Forever",["text"]="If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond."},
 [7668]={["source"]="QuestieDB Forever",["text"]="Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar."},
 [7670]={["source"]="QuestieDB Forever",["text"]="Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."},
 [7677]={["source"]="QuestieDB Forever",["text"]="If you bring me your white stallion, I'll trade you for one from the new herd. The new horse will be just as fast as your old one, but have a different look to it. You can look at the swift steeds here to see what it will look like.\010MUST PAY 500 Gold too...."},
 [7701]={["source"]="QuestieDB Forever",["text"]="Deep within the Slag Pit of the Cauldron, in the Searing Gorge, you will find the traitorous Dark Iron dwarf named Overseer Maltorius.\010Slay Overseer Maltorius and take his head. Return the head to Lookout Captain Lolo Longstriker in the Searing Gorge for your reward."},
 [7703]={["source"]="QuestieDB Forever",["text"]="Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\010According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings."},
 [7704]={["source"]="QuestieDB Forever",["text"]="Take Chambermaid Pillaclencher's Pillow to Evonice Sootsmoker in the Searing Gorge."},
 [7721]={["source"]="QuestieDB Forever",["text"]="Collect 10 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there."},
 [7722]={["source"]="QuestieDB Forever",["text"]="Somewhere in the Slag Pit of the Cauldron you will find the Secret Plans: Fiery Flux that Overseer Maltorius stole. Find those plans and return them to Master Smith Burninate in the Searing Gorge."},
 [7723]={["source"]="QuestieDB Forever",["text"]="Hansel Heavyhands wants you to kill 20 Heavy War Golems.\010The Heavy War Golems wander the areas surrounding the Cauldron in the Searing Gorge. When you've killed enough, return to Hansel in Searing Gorge."},
 [7724]={["source"]="QuestieDB Forever",["text"]="Hansel Heavyhands wants you to kill 20 Greater Lava Spiders in the Searing Gorge. You can find Greater Lava Spiders in the plateaus and lava pools of the Searing Gorge.\010Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Greater Lava Spiders."},
 [7725]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 10 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas."},
 [7726]={["source"]="QuestieDB Forever",["text"]="Collect 6 Water Elemental Cores from the Sea Elementals and Sea Sprays along the Forgotten Coast of Feralas, and bring them back to Zorbin Fandazzle who is near the dock there."},
 [7727]={["source"]="QuestieDB Forever",["text"]="Hansel Heavyhands wants you to kill 20 Incendosaurs.\010You will find Incendosaurs occupying the lava pools inside the Slag Pit. The Slag Pit can be found in the Cauldron of the Searing Gorge.\010Return to Hansel Heavyhands in the Searing Gorge when you have killed enough Incendosaurs."},
 [7728]={["source"]="QuestieDB Forever",["text"]="Find and return the Smithing Tuyere and Lookout's Spyglass to Taskmaster Scrange in the Searing Gorge.\010The only information you have about these items is the following: They were definitely stolen by Dark Iron dwarves. The Smithing Tuyere is a blacksmithing tool used by blacksmiths and the Lookout's Spyglass is an invaluable monitoring tool to lookouts."},
 [7729]={["source"]="QuestieDB Forever",["text"]="Slay 15 Dark Iron Taskmasters and 15 Dark Iron Slavers. Return to Taskmaster Scrange in the Searing Gorge once you have accomplished this task."},
 [7730]={["source"]="QuestieDB Forever",["text"]="Bring 20 Zukk'ash Carapaces to Hadoken Swiftstrider at Camp Mojache, Feralas."},
 [7731]={["source"]="QuestieDB Forever",["text"]="Defeat Stinglasher in the Writhing Deep, bringing its glands back to Hadoken Swiftstrider at Camp Mojache, Feralas."},
 [7732]={["source"]="QuestieDB Forever",["text"]="Deliver the Camp Mojache Zukk'ash Report to Zilzibin Drumlore. He resides in the Drag of Orgrimmar."},
 [7733]={["source"]="QuestieDB Forever",["text"]="Bring 10 Rage Scar Yeti Hides to Pratt McGrubben at Feathermoon Stronghold, Feralas."},
 [7734]={["source"]="QuestieDB Forever",["text"]="Bring 10 Rage Scar Yeti Hides to Jangdor Swiftstrider at Camp Mojache, Feralas."},
 [7735]={["source"]="QuestieDB Forever",["text"]="Bring the Pristine Yeti Hide to Pratt McGrubben at the Feathermoon Stronghold, Feralas."},
 [7738]={["source"]="QuestieDB Forever",["text"]="Bring the Perfect Yeti Hide to Jangdor Swiftstrider at Camp Mojache, Feralas."},
 [7761]={["source"]="QuestieDB Forever",["text"]="That is one stupid orc. It would appear as if you need to find this brand and gain the Mark of Drakkisath in order to access the Orb of Command.\010The letter indicates that General Drakkisath guards the brand. Perhaps you should investigate."},
 [7781]={["source"]="QuestieDB Forever",["text"]="Return the Head of Nefarian to Highlord Bolvar Fordragon in Stormwind."},
 [7782]={["source"]="QuestieDB Forever",["text"]="Venture to the Valley of Heroes in Stormwind City and speak with Field Marshal Afrasiabi."},
 [7783]={["source"]="QuestieDB Forever",["text"]="Return the Head of Nefarian to Thrall in Orgrimmar."},
 [7784]={["source"]="QuestieDB Forever",["text"]="Speak with High Overlord Saurfang in Orgrimmar. He stands waiting for you in the Valley of Strength."},
 [7785]={["source"]="QuestieDB Forever",["text"]="Examine the Vessel of Rebirth and return it to Highlord Demitrian."},
 [7786]={["source"]="QuestieDB Forever",["text"]="To free Thunderaan the Windseeker from his prison, you must present the right and left halves of the Bindings of the Windseeker, 10 bars of Elementium, and the Essence of the Firelord to Highlord Demitrian in Silithus."},
 [7787]={["source"]="QuestieDB Forever",["text"]="Present the Dormant Wind Kissed Blade to Highlord Demitrian."},
 [7788]={["source"]="QuestieDB Forever",["text"]="Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove."},
 [7789]={["source"]="QuestieDB Forever",["text"]="Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp."},
 [7810]={["source"]="QuestieDB Forever",["text"]="Speak with Short John Mithril in the Stranglethorn Arena."},
 [7815]={["source"]="QuestieDB Forever",["text"]="Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill 15 Saltwater Snapjaw turtles. Return to him when you have completed this task."},
 [7816]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Katoom the Angler at Revantusk Village in the Hinterlands wants you to kill Gammerita and retrieve Katoom's Best Lure from her corpse.\010Katoom mentioned that Gammerita hangs out on the coast with the other turtles."},
 [7828]={["source"]="QuestieDB Forever",["text"]="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 10 Silvermane Stalkers and 10 Silvermane Howlers. Return to him once the task is complete.\010Markhor mentioned that the wolves hide in the wilds of the Hinterlands."},
 [7829]={["source"]="QuestieDB Forever",["text"]="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill 20 Savage Owlbeasts. Return to him once the task is complete.\010Markhor mentioned that the Savage Owlbeasts occupy the wilds of the Hinterlands."},
 [7830]={["source"]="QuestieDB Forever",["text"]="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to kill a Razorbeak Skylord and retrieve its Skylord Plume. Return to him once the task is complete.\010Markhor mentioned that the Razorbeak Skylord are a rare breed that tend to occupy the wilds of the Hinterlands."},
 [7839]={["source"]="QuestieDB Forever",["text"]="Smith Slagtree at Revantusk Village in the Hinterlands wants you to find Slagtree's Lost Tools. Return to him once this task is complete.\010You recall Smith Slagtree mentioning that the tools might be at one of the Vilebranch temples in the northeastern region of the Hinterlands. You should also check Skulk Rock."},
 [7840]={["source"]="QuestieDB Forever",["text"]="Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.\010Lard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls."},
 [7841]={["source"]="QuestieDB Forever",["text"]="Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.\010You can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands."},
 [7842]={["source"]="QuestieDB Forever",["text"]="Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.\010Gryphons are known to inhabit every region of the Hinterlands."},
 [7843]={["source"]="QuestieDB Forever",["text"]="Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.\010Beware of angry Wildhammer dwarves and unruly members of the Alliance."},
 [7844]={["source"]="QuestieDB Forever",["text"]="Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 30 Vilebranch Scalpers and 15 Vilebranch Soothsayers. Return to her when this task is complete.\010Yayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands."},
 [7845]={["source"]="QuestieDB Forever",["text"]="Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.\010You have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands."},
 [7846]={["source"]="QuestieDB Forever",["text"]="Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torntusk when you have recovered the key."},
 [7847]={["source"]="QuestieDB Forever",["text"]="Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue."},
 [7848]={["source"]="QuestieDB Forever",["text"]="Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment."},
 [7849]={["source"]="QuestieDB Forever",["text"]="Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.\010Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple."},
 [7850]={["source"]="QuestieDB Forever",["text"]="Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete."},
 [7861]={["source"]="QuestieDB Forever",["text"]="You have been ordered to slay Vile Priestess Hexx and 20 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.\010Vile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands."},
 [7862]={["source"]="QuestieDB Forever",["text"]="You have been tasked with the decimation of 20 Vilebranch Berserkers, 20 Vilebranch Shadow Hunters, 20 Vilebranch Blood Drinkers, and 20 Vilebranch Soul Eaters.\010Should you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands."},
 [7871]={["source"]="QuestieDB Forever",["text"]="Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove."},
 [7872]={["source"]="QuestieDB Forever",["text"]="Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove."},
 [7873]={["source"]="QuestieDB Forever",["text"]="Enter Warsong Gulch and defeat the Horde, obtain a Warsong Gulch Mark of Honor, and return to Sentinel Farsong at the Silverwing Grove."},
 [7874]={["source"]="QuestieDB Forever",["text"]="Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp."},
 [7875]={["source"]="QuestieDB Forever",["text"]="Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp."},
 [7876]={["source"]="QuestieDB Forever",["text"]="Enter Warsong Gulch and defeat the Alliance, gain a Warsong Gulch Mark of Honor, and bring it to Captain Shatterskull at the Mor'shan Base Camp."},
 [7877]={["source"]="QuestieDB Forever",["text"]="Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!"},
 [7886]={["source"]="QuestieDB Forever",["text"]="You obtained a Silverwing Talisman of Merit for your last task, talk to me again, and you gain your reward."},
 [7887]={["source"]="QuestieDB Forever",["text"]="You obtained a Silverwing Talisman of Merit for your last task, talk to me again, and you gain your reward."},
 [7888]={["source"]="QuestieDB Forever",["text"]="You obtained a Silverwing Talisman of Merit for your last task, talk to me again, and you gain your reward."},
 [7905]={["source"]="QuestieDB Forever",["text"]="Deliver the Free Ticket Voucher to Gelvas Grimgate, located inside the Darkmoon Faire carnival."},
 [7907]={["source"]="QuestieDB Forever",["text"]="Return the Beast Deck to the Darkmoon Faire when it comes to town."},
 [7921]={["source"]="QuestieDB Forever",["text"]="You obtained a Silverwing Talisman of Merit for your last task, talk to me again, and you gain your reward."},
 [7922]={["source"]="QuestieDB Forever",["text"]="You obtained a Warsong Mark of Honor for your last task, talk to me again, and you gain your reward."},
