 [7926]={["source"]="QuestieDB Forever",["text"]="Deliver the Free Ticket Voucher to Gelvas Grimgate, located inside the Darkmoon Faire carnival."},
 [7927]={["source"]="QuestieDB Forever",["text"]="Return the Portals Deck to the Darkmoon Faire when it comes to town."},
 [7928]={["source"]="QuestieDB Forever",["text"]="Return the Warlords Deck to the Darkmoon Faire when it comes to town."},
 [7929]={["source"]="QuestieDB Forever",["text"]="Return the Elementals Deck to the Darkmoon Faire when it comes to town."},
 [7937]={["source"]="QuestieDB Forever",["text"]="Travel to the Eastvale Logging Camp in Elwynn Forest and seek out your fortune."},
 [7938]={["source"]="QuestieDB Forever",["text"]="Travel to the Deadmines in Westfall and seek out your fortune."},
 [7944]={["source"]="QuestieDB Forever",["text"]="Travel to the Wailing Caverns in the Barrens and seek out your fortune."},
 [7945]={["source"]="QuestieDB Forever",["text"]="Travel to Palemane Rock in Mulgore and seek out your fortune."},
 [8053]={["source"]="QuestieDB Forever",["text"]="Bring Jin'rokh the Breaker Primal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\010Jin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale."},
