 [8105]={["source"]="QuestieDB Forever",["text"]="Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe."},
 [8114]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Enter Arathi Basin, capture and control four bases at the same time, and then return to Field Marshal Oslight at Refuge Pointe."},
 [8115]={["source"]="QuestieDB Forever",["text"]="Control 5 bases in Arathi Basin at the same time, then return to Field Marshal Oslight at Refuge Pointe."},
