 [79242]={["source"]="QuestieDB Forever",["text"]="Find Illari Duskfeather on the coast of Arathi Highlands, and get access to her cache of stolen loot."},
 [79358]={["source"]="QuestieDB Forever",["text"]="Collect 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems, and 5 Twisted Water Totems for Veyric Thunderhame in Arathi Highlands."},
