 [79442]={["source"]="QuestieDB Forever",["text"]="Deliver the Eye of the Tempest to Bath'rah the Windwatcher in Alterac Mountains."},
 [79482]={["source"]="QuestieDB Forever",["text"]="Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains."},
 [79483]={["source"]="QuestieDB Forever",["text"]="Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains."},
 [79492]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Find Metzen the Reindeer. Use the notes provided to you for clues as to where he is being held.\010When you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\010Return the Pouch of Reindeer Dust to Wulmort Jinglepocket in Ironforge once Metzen is freed."},
 [79495]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Find Metzen the Reindeer. Use the notes provided to you for clues as to where he is being held.\010When you find Metzen, have the Pouch of Reindeer Dust in your possession so you can sprinkle some of the dust on him; this should free Metzen from his bonds of captivity.\010Return the Pouch of Reindeer Dust to Kaymard Copperpinch in Orgrimmar once Metzen is freed."},
 [79624]={["source"]="QuestieDB Forever",["text"]="Find an ogre who can read the Illegible Recipe."},
 [79677]={["source"]="QuestieDB Forever",["text"]="Gather the ingredients for Skonk's dish, then bring them to him in Arathi Highlands"},
 [79678]={["source"]="QuestieDB Forever",["text"]="Taste test the recipe with Skonk."},
 [79731]={["source"]="QuestieDB Forever",["text"]="Solve the riddle of the scroll. Once you've done that, Hemet Nesingwary might like to hear the tale."},
 [79939]={["source"]="QuestieDB Forever",["text"]="Recover clues about the recent battle at Mannoroc Coven, and return the Broken Warhammer to Katherine the Pure in Stormwind."},
