 [79946]={["source"]="QuestieDB Forever",["text"]="Speak with Katherine to learn more about Aeonas, and then find him in the Scarlet Monastery."},
 [79963]={["source"]="QuestieDB Forever",["text"]="Heal Aeonas."},
 [79970]={["source"]="QuestieDB Forever",["text"]="Meet Aeonas at the Cathedral of Light in Stormwind."},
 [79974]={["source"]="QuestieDB Forever",["text"]="Dusting off a messenger bag emerging from the soil, you find a parchment nestled among the supplies."},
 [79975]={["source"]="QuestieDB Forever",["text"]="Water spray dampens the air, the view is incredible."},
 [79976]={["source"]="QuestieDB Forever",["text"]="Whoever was here, you just missed them."},
 [79980]={["source"]="QuestieDB Forever",["text"]="Find what awaits you."},
 [80325]={["source"]="QuestieDB Forever",["text"]="Bring Thermaplugg's Engineering Notes to Nogg at the Valley of Honor in Orgrimmar."},
