 [81730]={["source"]="QuestieDB Forever",["text"]="Defeat 10 Nightmare Runners and 10 Nightmare Weavers in the Duskwood Nightmare Incursion in the Rotting Orchard and return to Field Captain Palandar."},
 [81731]={["source"]="QuestieDB Forever",["text"]="Defeat 3 Deranged Ogres and 3 Demented Fire Weavers in the Duskwood Nightmare Incursion at the Vul'gol Ogre Mound and return to Field Captain Palandar."},
 [81732]={["source"]="QuestieDB Forever",["text"]="Defeat 3 Wyrmkin Terrorwalkers and 10 Nightterror Whelps in the Duskwood Nightmare Incursion at the Yorgen Farmstead and return to Field Captain Palandar."},
 [81733]={["source"]="QuestieDB Forever",["text"]="Gather intelligence from Dreamwarden Thalinar in the Duskwood Nightmare Incursion deep inside the Vul'gol Ogre Mound and return to Field Captain Palandar."},
 [81734]={["source"]="QuestieDB Forever",["text"]="Gather intelligence from Dreamwarden Dorilar in the Duskwood Nightmare Incursion in the barn at the Rotting Orchard and return to Field Captain Palandar."},
 [81735]={["source"]="QuestieDB Forever",["text"]="Gather intelligence from Dreamwarden Amalia in the Duskwood Nightmare Incursion in the farmhouse at the Yorgen Farmstead and return to Field Captain Palandar."},
 [81736]={["source"]="QuestieDB Forever",["text"]="Recover the Shadowscythe in the Duskwood Nightmare Incursion upstairs in the farmhouse at the Rotting Orchard and return to Field Captain Palandar."},
 [81737]={["source"]="QuestieDB Forever",["text"]="Recover an Ogre Magi Text in the Duskwood Nightmare Incursion within the Vul'gol Ogre Mound and return to Field Captain Palandar."},
 [81738]={["source"]="QuestieDB Forever",["text"]="Recover an Unhatched Green Dragon Egg in the Duskwood Nightmare Incursion from the Yorgen Farmstead near the large stump in the fields and return to Field Captain Palandar."},
 [81739]={["source"]="QuestieDB Forever",["text"]="Gather 10 Nightmare Moss in the Duskwood Nightmare Incursions and return to Field Captain Palandar."},
 [81740]={["source"]="QuestieDB Forever",["text"]="Gather 10 Cold Iron Ore in the Duskwood Nightmare Incursions and return to Field Captain Palandar."},
 [81741]={["source"]="QuestieDB Forever",["text"]="Gather 10 Dream-Touched Dragonscales in the Duskwood Nightmare Incursions and return to Field Captain Palandar."},
 [81742]={["source"]="QuestieDB Forever",["text"]="Defeat Ylanthrius in the Duskwood Nightmare Incursion at the Yorgen Farmstead field and return to Field Captain Palandar."},
 [81743]={["source"]="QuestieDB Forever",["text"]="Defeat Vvarc'zul in the Duskwood Nightmare Incursion deep in the Vul'gol Ogre Mound and return to Field Captain Palandar."},
 [81744]={["source"]="QuestieDB Forever",["text"]="Defeat Amokarok in the Duskwood Nightmare Incursion at a campsite near the barn in the Rotting Orchard and return to Field Captain Palandar."},
 [81745]={["source"]="QuestieDB Forever",["text"]="Rescue Kroll Mountainshade from the Duskwood Nightmare Incursion in the guest house at the Rotting Orchard and return to Field Captain Palandar."},
 [81746]={["source"]="QuestieDB Forever",["text"]="Rescue Alara Grovemender in the Duskwood Nightmare Incursion in the stable at the Yorgen Farmstead and return to Field Captain Palandar."},
 [81747]={["source"]="QuestieDB Forever",["text"]="Rescue Elenora Marshwalker in the Duskwood Nightmare Incursion in the ruins of a farmhouse near the Vul'gol Ogre Mound and return to Field Captain Palandar."},
 [81762]={["source"]="QuestieDB Forever",["text"]="Speak with Katherine the Pure at the Cathedral of Light in Stormwind."},
 [81764]={["source"]="QuestieDB Forever",["text"]="Travel to Theramore and find the mysterious merchant."},
 [81765]={["source"]="QuestieDB Forever",["text"]="Speak with Elrick to learn more."},
 [81766]={["source"]="QuestieDB Forever",["text"]="Bring the missive to Katherine the Pure at the Cathedral of Light in Stormwind."},
 [81790]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the hints in Gregory's Note to determine where to find the magical components needed for the ritual. You will need help from allies for this."},
 [81900]={["source"]="QuestieDB Forever",["text"]="Find an expert on the beasts of the Blasted Lands."},
