 [84148]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Beaststalker's Bindings to Deliana in Ironforge."},
 [84149]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Magister's Bindings to Deliana in Ironforge."},
 [84150]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Lightforge Bracers to Deliana in Ironforge."},
 [84154]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Bracers of Valor to Deliana in Ironforge."},
 [84155]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Wildheart Bracers to Mokvar in Orgrimmar."},
 [84156]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Beaststalker's Bindings to Mokvar in Orgrimmar."},
 [84157]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Magister's Bindings to Mokvar in Orgrimmar."},
 [84158]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Devout Bracers to Mokvar in Orgrimmar."},
 [84159]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Shadowcraft Bracers to Mokvar in Orgrimmar."},
 [84160]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Bindings of the Elements to Mokvar in Orgrimmar."},
 [84161]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Dreadmist Bracers to Mokvar in Orgrimmar."},
 [84162]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Bracers of Valor to Mokvar in Orgrimmar."},
 [84318]={["source"]="QuestieDB Forever",["text"]="Find Orthas' missing hammer in Corrin's Crossing."},
 [84330]={["source"]="QuestieDB Forever",["text"]="Obtain a Necrotic Runestone from Maleki the Pallid in Stratholme, then find the Rotting Dwarf Corpse near the Undercroft in southwestern Eastern Plaguelands."},
 [86574]={["source"]="QuestieDB Forever",["text"]="Collect 6 Stonetalon Supplies from Pridewing Wyverns and deliver them to Innkeeper Faralia."},
 [86576]={["source"]="QuestieDB Forever",["text"]="Bring 15 Glittering Sunstones to Mor'rogal."},
 [86585]={["source"]="QuestieDB Forever",["text"]="Raise the standard of Ironforge, call out the trogg Headsplitter and kill it, then report to Captain Rugelfuss."},
 [86611]={["source"]="QuestieDB Forever",["text"]="Take the Stag Lord's Bauble to someone in Talonbranch Glade who may know about it."},
 [86612]={["source"]="QuestieDB Forever",["text"]="Take the Stag Lord's Bauble to someone in Bloodvenom Post who may know about it."},
 [86613]={["source"]="QuestieDB Forever",["text"]="Return 6 Excavation Tools to Magmar Fellhew."},
 [86614]={["source"]="QuestieDB Forever",["text"]="Return the Monogrammed Silver Hair clip to its owner."},
 [86615]={["source"]="QuestieDB Forever",["text"]="Find Ambassador Redstone's missing diplomatic satchel in Wildhammer Keep."},
 [86616]={["source"]="QuestieDB Forever",["text"]="Bring 12 Vilebranch Totems back to Maret Firetend."},
 [86667]={["source"]="QuestieDB Forever",["text"]="Deliver a Jar of Snow to Norric Lochthane at his house on the northwest coast of the Loch."},
 [86757]={["source"]="QuestieDB Forever",["text"]="Bring 6 Jagged Orc Swords and 4 Curved Orc Daggers to Shandrina."},
 [86758]={["source"]="QuestieDB Forever",["text"]="Find and defeat the crocolisk Daggerfang and bring back Marek's knife."},
 [86776]={["source"]="QuestieDB Forever",["text"]="Bring 10 Bronze Bars to Morhan Coppertongue."},
 [86784]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 6 Dry Branches and bring them to Eleanor Shackleton."},
 [87288]={["source"]="QuestieDB Forever",["text"]="Bring 6 Soft Nightsaber Pelts to Aldria."},
 [87318]={["source"]="QuestieDB Forever",["text"]="Search for Corma's partner Essene."},
 [87451]={["source"]="QuestieDB Forever",["text"]="Take the Carved Stone Trinket to Dispatch Commander Ruag in Stonard, in the Swamp of Sorrows."},
 [87491]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort the captive fire elemental out of Dun Modr and to its freedom."},
 [87492]={["source"]="QuestieDB Forever",["text"]="Bring 1 Damaged Blue Crystal back to Torwa Pathfinder."},
 [87760]={["source"]="QuestieDB Forever",["text"]="Find a Stormscale Beastmistress, slay her, and bring back her Rod of Deep Dominion."},
 [88756]={["source"]="QuestieDB Forever",["text"]="Retrieve 3 Stolen Explosives from the Dark Iron Dwarf camps."},
 [88757]={["source"]="QuestieDB Forever",["text"]="Bring back Essene's Necklace, Essene's Spellbook, and Essene's Waterskin."},
 [88758]={["source"]="QuestieDB Forever",["text"]="Bring Essene's note back to Corma Villard."},
 [88807]={["source"]="QuestieDB Forever",["text"]="Kill 8 Spitelash Warriors and 8 Spitelash Screamers for Commander Truesong in Azshara."},
 [88809]={["source"]="QuestieDB Forever",["text"]="Collect 12 Eldarath Relics from Spitelash Serpent Guards, Spitelash Sirens, and Spitelash Myrmidons, and Lord Sarthiss' Head for Commander Truesong in Azshara."},
 [88812]={["source"]="QuestieDB Forever",["text"]="Kill 5 Spitelash Battlemasters, 5 Spitelash Enchantresses, and nullify the 3 Naga Power Stones near Ravencrest Monument for Commander Truesong in Azshara."},
 [88813]={["source"]="QuestieDB Forever",["text"]="Bring Warlord Krellian's head to Commander Truesong in Azshara."},
 [88821]={["source"]="QuestieDB Forever",["text"]="Find the Kaldorei woman last seen on the Shattered Strand."},
 [88857]={["source"]="QuestieDB Forever",["text"]="Help Keldara Sunblade escape the Haldarr Encampment, then speak to Commander Truesong at Talrendis Point."},
 [88884]={["source"]="QuestieDB Forever",["text"]="Find the three highborne tablets among the ruins of Southridge Beach, then bring them to Saria Fairmoon in Azshara."},
 [88917]={["source"]="QuestieDB Forever",["text"]="Find the Staff of Archmage Selwyn among the Ruins of Eldarath, and bring it to Saria Fairmoon in Azshara."},
 [89001]={["source"]="QuestieDB Forever",["text"]="Bring 5 Mosshoof Hides to Berdun Cliffbrew at Talrendis Point in Azshara."},
 [89013]={["source"]="QuestieDB Forever",["text"]="Gather 5 Wild Honey from Wasp Nests using Berdun's Pellet Gun."},
 [89015]={["source"]="QuestieDB Forever",["text"]="Bring a Mammoth Shark Steak to Berdun Cliffbrew at Talrendis Point in Azshara."},
 [89037]={["source"]="QuestieDB Forever",["text"]="Take the Memory Crystal from Razorgill near the Tower of Eldara, and bring it to Saria Fairmoon in Azshara."},
 [89038]={["source"]="QuestieDB Forever",["text"]="Search for the Mark of the Queen among the ruins of the Ravencrest Monument, and bring it to Saria Fairmoon in Azshara."},
 [89053]={["source"]="QuestieDB Forever",["text"]="See what Saria has to show you."},
 [89228]={["source"]="QuestieDB Forever",["text"]="Fish up 10 Winter Squid for Berdun Cliffbrew at Talrendis Point, in Azshara."},
 [89470]={["source"]="QuestieDB Forever",["text"]="Bring Saria's Knapsack back to Commander Truesong at Talrendis Point."},
 [90702]={["source"]="QuestieDB Forever",["text"]="Search the area for the grave's missing contents."},
 [90813]={["source"]="QuestieDB Forever",["text"]="Find someone to appraise the Humongous Crystal."},
 [90902]={["source"]="QuestieDB Forever",["text"]="Heal 5 Injured Deathguard with your Holy Light ability."},
 [91208]={["source"]="QuestieDB Forever",["text"]="Find the Frightened Paladin in Deathknell."},
 [91209]={["source"]="ForeverDungeonJournal learned client text",["text"]="Follow the road east out of Deathknell to find the town of Brill. Report to Shari Stilwell to continue your training."},
 [91282]={["source"]="QuestieDB Forever",["text"]="Find the fortress of Bandarion Keep and report to Breton Samuels there."},
 [91285]={["source"]="QuestieDB Forever",["text"]="Slay 8 Vile Fin Attackers and 8 Vile Fin Seers and report back to Breton Samuels when it is done."},
 [91294]={["source"]="QuestieDB Forever",["text"]="Speak to the residents of Bandarion Keep."},
 [91316]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 12 pieces of Sturdy Lumber from Shadowvale in Tirisfal Glades."},
 [91317]={["source"]="QuestieDB Forever",["text"]="Slay 8 Tarnished Drudges, 6 Tarnished Zealots, and collect the head of Commander Rudolph Gelhardt in Tirisfal Glades."},
 [91488]={["source"]="QuestieDB Forever",["text"]="Bring 5 Mosshoof Hides to Kurll at Valormok in Azshara."},
 [91497]={["source"]="QuestieDB Forever",["text"]="Bring the Seal of the Warden, Seal of the Warrior, and Seal of the Ranger to the Sin'dorei Tome of Summoning."},
 [91500]={["source"]="QuestieDB Forever",["text"]="Break the Seals of the Sin'dorei, then bring Magus Rimtori's head to Ag'tor Bloodfist in Valormok."},
 [91531]={["source"]="QuestieDB Forever",["text"]="Bring the Head of Magus Rimtori to Belgrom Rockmaul in Orgrimmar."},
 [91538]={["source"]="QuestieDB Forever",["text"]="Bring the Sin'dorei Tome of Summoning back to Jediga in Valormok."},
 [91547]={["source"]="QuestieDB Forever",["text"]="Bring the Sin'dorei Tome of Summoning to Zevrost in Orgrimmar."},
 [91548]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Sin'dorei Tome of Summoning to summon Vek'zol at the Altar of Storms in the Blasted Lands. Bring the Heart of Vek'zol to Zevrost in Orgrimmar."},
 [91568]={["source"]="QuestieDB Forever",["text"]="Dig up 10 Highborne Treasure Fragments with the Treasure Trowel 3000 for Izvi Glidfizz in Valormok."},
 [91569]={["source"]="QuestieDB Forever",["text"]="Bring a Mana-Siphoning Wand to Izvi Gildfizz at Valormok."},
 [91607]={["source"]="QuestieDB Forever",["text"]="Find someone to appraise the Humongous Crystal."},
 [91608]={["source"]="QuestieDB Forever",["text"]="Gather 5 Wild Honey from Wasp Nests using Kurll's Pellet Gun."},
 [91610]={["source"]="QuestieDB Forever",["text"]="Fish up 10 Winter Squid for Kurll at Valormok."},
 [91611]={["source"]="QuestieDB Forever",["text"]="Bring a Mammoth Shark Steak to Kurll at Valormok."},
 [91685]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Mana-Siphoning Wand on the Leyline Rift in Lake Mennar and bring the Tear of Mennar to Izvi Gildfizz."},
 [91688]={["source"]="QuestieDB Forever",["text"]="Travel to the Summit of Eternity and speak with the druids about the survivor village."},
 [91723]={["source"]="QuestieDB Forever",["text"]="Kill 8 Kobold Geomancers in Jasperlode Mine, then return to Hamish Bergwort in the Tower of Azora."},
 [91724]={["source"]="QuestieDB Forever",["text"]="Kill 8 Defias Rogue Wizards at Stone Cairn Lake, then return to Hamish Bergwort in the Tower of Azora."},
 [91725]={["source"]="QuestieDB Forever",["text"]="Collect 5 Stolen Enchanting Supplies from gnoll camps around Stone Cairn Lake, then return to Blixie Fitzwink near the Tower of Azora."},
 [91732]={["source"]="QuestieDB Forever",["text"]="Collect 4 Mining Tools from Jasperlode Mine, then return to Hagar Lowe in Eastvale Logging Camp."},
 [91733]={["source"]="QuestieDB Forever",["text"]="Collect the Waterlogged Axe, Waterlogged Saw, and Waterlogged Toolbox that have washed downstream from Eastvale Logging Camp, then return to Ormin Pelford."},
 [91734]={["source"]="QuestieDB Forever",["text"]="Speak to Jediga in Azshara."},
 [91735]={["source"]="QuestieDB Forever",["text"]="Speak to Jediga in Azshara."},
 [91737]={["source"]="QuestieDB Forever",["text"]="Speak to Jediga in Azshara."},
 [91740]={["source"]="QuestieDB Forever",["text"]="Deliver Croaky's Head to Merell Ross at Ridgepoint Tower."},
 [91741]={["source"]="QuestieDB Forever",["text"]="Return the book to Brother Paxton."},
 [91743]={["source"]="QuestieDB Forever",["text"]="Retrieve 8 Stolen Books from kobolds in Northshire Valley and return them to Brother Paxton."},
 [91745]={["source"]="QuestieDB Forever",["text"]="Talk to Kelsey Fargo outside the Echo Ridge Mine in Northshire Valley."},
 [91746]={["source"]="QuestieDB Forever",["text"]="Deliver Elmpaw's Head to Helene Peltskinner near Goldshire."},
 [91751]={["source"]="QuestieDB Forever",["text"]="Skin wolves around Elwynn Forest to obtain 7 Rough Wolf Pelts, then deliver them to Helene Peltskinner near Goldshire."},
 [91752]={["source"]="QuestieDB Forever",["text"]="Retrieve a Sack of \"Picture\" Books from Shinyfinder Narf. Bring the sack to Marshal McBride just inside Northshire's Abbey."},
 [91753]={["source"]="QuestieDB Forever",["text"]="Kitta Firewind in the Tower of Azora wants you to collect 3 Luminous Residue.\010Luminous Residue can be obtained by disenchanting Crude Wax Effigies dropped by Kobold Geomancers."},
 [91758]={["source"]="QuestieDB Forever",["text"]="Speak to Tordrin Sternblade near the stable behind Northshire's Abbey."},
 [91772]={["source"]="QuestieDB Forever",["text"]="Follow the kobold tracks and report to Marshal Dughan in Goldshire with your findings and the Kobold Tracking Kit."},
 [91775]={["source"]="QuestieDB Forever",["text"]="Find 6 Lost Books and \"Fun with Elementals\" and return them to Marshal Dughan."},
 [91777]={["source"]="QuestieDB Forever",["text"]="Recover \"Geomancy for Curious Young Wizards\" and \"Arcane Explainer: Magical Stuff in Simple Words\" and return them to Brother Paxton inside Northshire's Abbey."},
 [91794]={["source"]="QuestieDB Forever",["text"]="Collect 1 Horde Flag and 3 Scraps of Horde Heraldry for Kal'tinzan at Elderwild."},
 [91858]={["source"]="ForeverDungeonJournal learned client text",["text"]="Travel to The Sepulcher in Silverpine Forest and speak with Trevan Rol about the missing Earthen Ring travelers."},
 [91859]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Deathguard Baldren about the mysterious Earthen Ring travelers who recently passed through The Sepulcher."},
 [91860]={["source"]="ForeverDungeonJournal learned client text",["text"]="Investigate Fenris Isle to the east and learn the fate of the Earthen Ring traveling party."},
 [91861]={["source"]="QuestieDB Forever",["text"]="Investigate Fenris Keep to the north and attempt to locate the missing member of the Earthen Ring party."},
 [91862]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Retrieve the Fenris Isle Key from the Rot Hide Gnolls and use it to free Lumina Windsinger."},
 [91881]={["source"]="QuestieDB Forever",["text"]="Meet Sefira Everbright at the outpost."},
 [91920]={["source"]="ForeverDungeonJournal learned client text",["text"]="Gather 3 murloc eyes and bring them to Apothecary Renferrel at the Sepulcher."},
 [91921]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher."},
 [92014]={["source"]="QuestieDB Forever",["text"]="Return 9 Rustleaf Fox Tails to Johun \"Punchy\" Dillas in Hyjal."},
 [92015]={["source"]="QuestieDB Forever",["text"]="Make skunks leave the area around Johun's equipment without killing them."},
 [92064]={["source"]="QuestieDB Forever",["text"]="Break the tree branch to free Fenwick Togglespring."},
 [92065]={["source"]="ForeverDungeonJournal authored summary",["text"]="Bring Varrox Bleakhoof's Head to Gatekeeper Rageroar at Ursolan."},
 [92066]={["source"]="ForeverDungeonJournal authored summary",["text"]="Find the Totem of Ursoc and the Totem of Ursol inside Blackmaw Hold. Then, return them to Lorekeeper Nok at Ursolan."},
 [92067]={["source"]="ForeverDungeonJournal authored summary",["text"]="Bring Fel-Tainted Flesh."},
 [92069]={["source"]="ForeverDungeonJournal authored summary",["text"]="Bring the Claws of the Great Bear and the Tusks of the Unbroken to Ogtinc in Azshara."},
 [92070]={["source"]="ForeverDungeonJournal authored summary",["text"]="Find the owner of the Feathered Charm Necklace."},
 [92101]={["source"]="QuestieDB Forever",["text"]="Find the Veteran of the Third War's markings of significance on the Great Lift."},
 [92109]={["source"]="QuestieDB Forever",["text"]="Bring 5 Empty Vials, 5 Silverleaf, and 5 Peacebloom to the young, aspiring alchemist inside the barn of Moonbrook in Westfall."},
 [92110]={["source"]="QuestieDB Forever",["text"]="Gather 3 Murloc Eyes for the young, aspiring alchemist inside the barn of Moonbrook in Westfall."},
 [92124]={["source"]="QuestieDB Forever",["text"]="Speak to Daniel, Brother Paxton's assistant in the library."},
 [92343]={["source"]="QuestieDB Forever",["text"]="Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Nara Wildmane in Thunder Bluff."},
 [92344]={["source"]="QuestieDB Forever",["text"]="Gather 10 Nordrassil Root Caps inside Blackmaw Hold for Mathrengyl Bearwalker in Darnassus."},
 [92345]={["source"]="QuestieDB Forever",["text"]="Speak to Mathrengyl Bearwalker at the Cenarion Enclave in Darnassus."},
 [92346]={["source"]="QuestieDB Forever",["text"]="Speak to Nara Wildmane at Elder Rise in Thunder Bluff."},
 [92401]={["source"]="ForeverDungeonJournal learned client text",["text"]="Investigate the disappearance of Edward Heartweaver in the Ruins of Lordaeron."},
 [92415]={["source"]="QuestieDB Forever",["text"]="Bring the Blood-Stained Letter to Orphan Matron Nightingale in Stormwind City."},
 [92421]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 25 Intact Limbs within The Ruins of Lordaeron for Morbin Lightbane in the Undercity."},
 [92422]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kill Rath'mael in the Ruins of Lordaeron for Deathguard Kristof in Brill."},
 [92432]={["source"]="QuestieDB Forever",["text"]="Report to the Image of Archmage Modera near the City of Dalaran."},
 [92434]={["source"]="QuestieDB Forever",["text"]="Find a way into Dalaran along the Lordamere Lake."},
 [92446]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Take the rabbit carcass into the woods to the south, lure out Head Scratcher, defeat him, and bring his claws back to Zet'gan."},
 [92449]={["source"]="QuestieDB Forever",["text"]="Eliminate 3 Forgotten Soldiers and 12 Fleshflay Raveners."},
 [92456]={["source"]="QuestieDB Forever",["text"]="Collect a Fel Infused Blossom from the City of Dalaran for Shylamiir in Stormwind City."},
 [92457]={["source"]="QuestieDB Forever",["text"]="Defeat 8 Seeking Remnants, 8 Saturated Remnants, and 8 Mana Echoes inside the City of Dalaran for Archmage Modera outside of Dalaran."},
 [92458]={["source"]="QuestieDB Forever",["text"]="Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran."},
 [92459]={["source"]="QuestieDB Forever",["text"]="Speak to Archmage Celindra in the City of Dalaran."},
 [92460]={["source"]="QuestieDB Forever",["text"]="Speak with Rorian the Dayseeker in Thendal Grove."},
 [92461]={["source"]="QuestieDB Forever",["text"]="Slay 8 Vuldren Juveniles in Thendal Grove."},
 [92462]={["source"]="QuestieDB Forever",["text"]="Slay 8 Pesky Cirrusflies in Thendal Grove."},
 [92463]={["source"]="QuestieDB Forever",["text"]="Destroy the Cirrusfly Queen in Thendal Grove."},
 [92464]={["source"]="QuestieDB Forever",["text"]="Speak to Yala Windwatcher in Thendal Grove."},
 [92465]={["source"]="QuestieDB Forever",["text"]="Slay 6 Roiling Winds and 7 Al'Aketh Converts in Thendal Grove."},
 [92466]={["source"]="QuestieDB Forever",["text"]="Bring a Signet of Akir to Windshaper Boro."},
 [92467]={["source"]="QuestieDB Forever",["text"]="Find the Rise of Spirits and drink the Earth Sapta."},
 [92468]={["source"]="QuestieDB Forever",["text"]="Bring the Rough Quartz to Windshaper Boros in Thendal Grove."},
 [92469]={["source"]="QuestieDB Forever",["text"]="Bring word of the Al'Aketh to Rorian the Dayseeker in Thendal Grove."},
 [92470]={["source"]="QuestieDB Forever",["text"]="Slay 8 Ursera Scavengers and collect the head of the den mother, Urs'anah in Thendal Grove."},
 [92471]={["source"]="QuestieDB Forever",["text"]="Speak with Aetheen of the Gales in Thendal Grove."},
 [92472]={["source"]="QuestieDB Forever",["text"]="Report to Constable Aonda in Shen'dar Village."},
 [92473]={["source"]="QuestieDB Forever",["text"]="Collect 6 Scrawny Ursera Claws from Scrawny Ursera in Thendal Grove."},
 [92474]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Jump from the top of the watchtower in Thendal Grove and use your Walk on Air ability to slow your fall."},
 [92479]={["source"]="QuestieDB Forever",["text"]="Read the Scribbled Letter and speak to Tordrin Stemblade in Northshire Abbey."},
 [92481]={["source"]="QuestieDB Forever",["text"]="Examine the Glowing Recall Crystal, then speak with Dorii Brightwhisper in Thendal Grove."},
 [92482]={["source"]="QuestieDB Forever",["text"]="Read the Scribbled Note and then speak with Tai'ree Farsight in Thendal Grove."},
 [92483]={["source"]="QuestieDB Forever",["text"]="Read the Simple Note then speak with Akeri Duskblade within the watchtower in Thendal Grove."},
 [92484]={["source"]="QuestieDB Forever",["text"]="Examine the Humming Recall Crystal then speak with Windshaper Boro in Thendal Grove."},
 [92485]={["source"]="QuestieDB Forever",["text"]="Read the Folded Parchment then speak with Xyton Silverwind in Thendal Grove."},
 [92489]={["source"]="QuestieDB Forever",["text"]="Slay the Mana Elemental in the City of Dalaran for High Sorcerer Andromath in Stormwind City."},
 [92514]={["source"]="QuestieDB Forever",["text"]="Speak with Illaya Amberwind and Coriella Calmbreeze in Shen'dar Village."},
 [92515]={["source"]="QuestieDB Forever",["text"]="Collect 10 Prideclaw Pelts from the Prideclaws in Shen'dar Highlands."},
 [92516]={["source"]="ForeverDungeonJournal learned client text",["text"]="Slay 8 Hippogryph Youths, 6 Hippogryph Protectors and a Hippogryph Matriarch in the Shen'dar Highlands."},
 [92517]={["source"]="QuestieDB Forever",["text"]="Kill 10 Highlands Bandits and their leader, \"Badwind\" Bennic in the Shen'dar Highlands."},
 [92519]={["source"]="QuestieDB Forever",["text"]="Pick up a case of Packaged Tonics at Jorell's lab in Go'shek Farm and return to Doctor Gregory Victor in Hammerfall."},
 [92528]={["source"]="QuestieDB Forever",["text"]="Look around Falaath Village to learn about the cult's intentions in the Shen'dar Highlands."},
 [92529]={["source"]="QuestieDB Forever",["text"]="Report to Missionary Jasaan near the entrance to Falaath Village.\010If you lose your Mark of Akir, speak with Sania Silverstream in Shen'dar Village to regain the effect."},
 [92532]={["source"]="QuestieDB Forever",["text"]="Read the Crumpled Note you've been given, then seek out Blademaster Ren inside the Thendal Village watchtower."},
 [92544]={["source"]="QuestieDB Forever",["text"]="Slay 6 Al'Aketh Brutes, 4 Al'Aketh Neophytes, and Malduko Cloudcrush in Thendal Grove."},
 [92550]={["source"]="ForeverDungeonJournal learned client text",["text"]="Travel to the ruins of Falaath Village and slay 6 Al'Aketh Stormcallers, 4 Living Lightning and take the head of Commander Cyclas."},
 [92551]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 10 packs of Stolen Shen'dar Supplies from Falaath Village in the Shen'dar Highlands."},
 [92553]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 3 Small Eggs and 8 Strider Meat from creatures found throughout the Shen'dar Highlands."},
 [92579]={["source"]="ForeverDungeonJournal learned client text",["text"]="Deliver Aonda's Written Report to Valennia Stormfist in Valanaar."},
 [92591]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Survivor's Torch on the Bone Pile, then collect the Reanimator's Amulet."},
 [92592]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Survivor's Torch on the Bone Pile, then collect the Reanimator's Amulet."},
 [92593]={["source"]="QuestieDB Forever",["text"]="Enter Dae'gun and locate a high vantage point, then report details to Johun."},
 [92595]={["source"]="QuestieDB Forever",["text"]="Listen to what Illaya Amberwind has to say."},
 [92596]={["source"]="QuestieDB Forever",["text"]="Have a seat and speak with Rathiril Sunlance."},
 [92597]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use your Read Leyline racial ability at the leyline in Thendal Grove."},
 [92598]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use your Skysight racial ability at the Elemental Convergence in Thendal Grove."},
 [92609]={["source"]="QuestieDB Forever",["text"]="Gather 9 Hyjal Owl Feathers for Zet'gan."},
 [92640]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Valennia Stormfist in Valanaar and follow her instructions."},
 [92642]={["source"]="ForeverDungeonJournal learned client text",["text"]="Slay 4 Al'Aketh Healers and 8 Al'Aketh Brawlers in the Gustberry Lowlands."},
 [92643]={["source"]="ForeverDungeonJournal learned client text",["text"]="Find the cultist turncoat at the house just inside the highlands northwest of Valanaar."},
 [92644]={["source"]="ForeverDungeonJournal learned client text",["text"]="Deliver the glowing crystal to Talanaanis Shadowsong in Valanaar."},
 [92645]={["source"]="ForeverDungeonJournal learned client text",["text"]="Slay Commander Belguilos in the Gustberry Lowlands."},
 [92646]={["complex"]=true,["extra"]={"Take the portal","Start the fight"},["source"]="ForeverDungeonJournal learned client text and QuestieDB Forever",["text"]="Take the portal to the Rohashi Spires overhead and join Elaadrin Evengale and Ayessa Dawnsinger in their confrontation with the High Priestess Lorthuna.\010Start the fight"},
 [92679]={["source"]="ForeverDungeonJournal learned client text",["text"]="Listen to what Alvarion Windfield has to say and find Aamelia Windfield at the Windfield Orchard."},
 [92682]={["source"]="ForeverDungeonJournal learned client text",["text"]="Gather 10 Ripe Stormapples and slay 5 Hungry Bandits at the Windfield Orchard."},
 [92683]={["complex"]=true,["extra"]={"Use the Flutterfly Swatter"},["source"]="ForeverDungeonJournal learned client text and QuestieDB Forever",["text"]="Gather 5 Flutterfly Dust from the Flutterflies around the Gustberry Lowlands.\010Use the Flutterfly Swatter"},
 [92684]={["source"]="ForeverDungeonJournal learned client text",["text"]="Gather 7 Lowlands Galestrider Tenderloins from the Ornery Galestriders found throughout the Gustberry Lowlands."},
 [92685]={["source"]="ForeverDungeonJournal learned client text",["text"]="Loot 7 Blood-Stained Bandit Masks from Highwayman Bandits in the Gustberry Lowlands."},
 [92693]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Aamelia Windfield when you are ready to confront the bandit leader."},
 [92698]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Aamelia Windfield about the Malfunctioning Cyclone Construct."},
 [92699]={["source"]="QuestieDB Forever",["text"]="Find Elaadrin Evengale in Valanaar."},
 [92700]={["source"]="ForeverDungeonJournal learned client text",["text"]="Find Ayessa Dawnsinger in Valanaar."},
 [92701]={["source"]="QuestieDB Forever",["text"]="Deliver Aonda's Written Report to Valennia Stormfist in Valanaar."},
 [92702]={["source"]="QuestieDB Forever",["text"]="Locate a sturdy branch capable of reaching Fenwick Togglespring."},
 [92703]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Alvarion Windfield in Valanaar."},
 [92706]={["source"]="QuestieDB Forever",["text"]="Bring Bruuz's Dorsal Fin to Gazlowe in Ratchet."},
 [92707]={["source"]="QuestieDB Forever",["text"]="Bring the Goliath's Wristguards to Drum Fel in Hammerfall."},
 [92708]={["source"]="ForeverDungeonJournal learned client text",["text"]="Listen to what Ayessa Dawnsinger has to say."},
 [92709]={["source"]="QuestieDB Forever",["text"]="Listen to what Elaadrin Evengale in Valanaar has to say."},
 [92727]={["source"]="QuestieDB Forever",["text"]="Discover what became of Fillion Flamebreeze."},
 [92741]={["source"]="QuestieDB Forever",["text"]="Travel to Shadowgale Forest and collect 8 Shriekling Talons for Iaadaria Bitterwind in Valanaar."},
 [92742]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Well Water Sample Kit to collect samples from the wells at the Jansen Stead and the Molsen Farm."},
 [92743]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram, and return a Conqueror's Crown from the Badlands to Warug in Magram Village."},
 [92744]={["source"]="QuestieDB Forever",["text"]="Alba Fairmoon wants you to collect 7 Longshore Murloc Gills along the shoreline of Westfall."},
 [92745]={["source"]="QuestieDB Forever",["text"]="Slay 4 Kobold Diggers in the Jangolode Mine and 6 Riverpaw Miners in the Gold Coast Quarry."},
 [92747]={["source"]="QuestieDB Forever",["text"]="Collect 8 Suspicious Industrial Supplies from Moonbrook."},
 [92748]={["source"]="QuestieDB Forever",["text"]="Travel to the Dwarven District in Stormwind and find an engineer who can help."},
 [92749]={["source"]="QuestieDB Forever",["text"]="Obtain 10 Coarse Dynamite from crafting, trading, or the auction house, then return to Sprite Jumpsprocket in the Dwarven District of Stormwind."},
 [92750]={["source"]="QuestieDB Forever",["text"]="Talk to someone in Stormwind Intelligence about acquiring a remote detonator."},
 [92751]={["source"]="QuestieDB Forever",["text"]="Bring the Remote Detonator Kit to Sprite Jumpsprocket in the Dwarven District of Stormwind."},
 [92752]={["source"]="QuestieDB Forever",["text"]="Return to Alba Fairmoon in Westfall."},
 [92753]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Find the forge hidden in the Deadmines, and plant the Extra-Destructive Explosives nearby. Then, meet up with Alba Fairmoon at the Deadmines exit."},
 [92754]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram, and bring 3 Greater Shadow Protection Potions to Mirda in the Magram Village in Desolace."},
 [92755]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis, and bring 3 Greater Mystic Essences to Halea in the Gelkis Village in Desolace."},
 [92814]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis, and bring a White Bandit Mask to Molkar in the Gelkis Village in Desolace."},
 [92817]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis, and bring a Barbaric Harness to Talra in the Gelkis Village in Desolace."},
 [92818]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram, and bring 2 Massive Iron Axes to Grolkar in the Magram Village in Desolace."},
 [92819]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the detonator."},
 [92834]={["source"]="QuestieDB Forever",["text"]="Collect 10 Al'Aketh Windstone Charms from Al'Aketh cultists found north of Valanaar at the Gustberry Fields or Shrine of Akir."},
 [92840]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Take the Index Esoteria to the Overlook Standing Stones in Shen'dar Highlands and use it on the Windstone Formations in the area to gather data."},
 [92841]={["source"]="QuestieDB Forever",["text"]="Improve your reputation with the Magram, and locate Orgrul near the Valley of Bones south of Magram Village."},
 [92844]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram, and bring 426 Gently Cursed Bones to Orgrul south of the Magram Village in Desolace."},
 [92846]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram, and slay Outcast Necromancers within the Valley of Bones."},
 [92847]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram, and bring 3 Petrified Bark and 3 Imbued Tears back to Orgrul."},
 [92849]={["source"]="QuestieDB Forever",["text"]="Keep searching for Fillion Flamebreeze."},
 [92850]={["source"]="QuestieDB Forever",["text"]="Slay the Shriekling Matriarch in the Shriekling Den then return its head to Fillion Flamebreeze in Valanaar."},
 [92858]={["source"]="QuestieDB Forever",["text"]="Bring the Staff of Ohk'zi to Latronicus Moonspear at Feathermoon Stronghold."},
 [92860]={["source"]="QuestieDB Forever",["text"]="Report to Valennia Stormfist and let her know that the High Order is with them in their fight against the Al'Aketh."},
 [92867]={["source"]="QuestieDB Forever",["text"]="Defeat the Boulderfist, Syndicate, and Witherbark intruders in Stromgarde Keep and return to Groundskeeper Lomar."},
 [92871]={["source"]="ForeverDungeonJournal learned client text",["text"]="Report to Valennia Stormfist and let her know that the Windshapers are with them in their fight against the Al'Aketh."},
 [92872]={["source"]="QuestieDB Forever",["text"]="Throw the Pouch of Tomb Dust into The Great Sea and return to Caretaker Alaric in the Stromgarde Keep crypt."},
 [92873]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram Clan, then bring 426 Well Cursed Bones from a successful ritual back to Orgrul."},
 [92878]={["source"]="QuestieDB Forever",["text"]="Bring proof of Namida Grimtotem's demise to Blaise Montgomery at Camp Mojache."},
 [92880]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Yorna's Report to Valennia Stormfist in Valanaar."},
 [92881]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Talaanis Shadowsong in Valanaar."},
 [92893]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram Clan, and slay 5 Gelkis Captives scattered around the Valley of Bones. Return to Orgrul after the task is complete."},
 [92894]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram Clan, and use the Enhanced Necromancy Staff to fully raise undead that are struggling to emerge throughout the Valley of Bones. Return to Orgrul once the Magram army has grown."},
 [92909]={["source"]="QuestieDB Forever",["text"]="Ozwin Ironsprocket at Saldean's Farm wants you to bring him 14 Golem Isosprings and 5 Harvester Gyrostabilizers."},
 [92910]={["source"]="QuestieDB Forever",["text"]="Bring the Precessive Autocognition Assembly to Ozwin Ironsprocket at Saldean's Farm."},
 [92911]={["source"]="QuestieDB Forever",["text"]="Ozwin Ironsprocket at Saldean's Farm wants you to bring him 8 Golem Isosprings, 4 Copper Modulators, and a Crude Scope."},
 [92914]={["source"]="ForeverDungeonJournal authored summary",["text"]="Explore Shen'dralas in an effort to find other pylons like the one you found."},
 [92947]={["source"]="ForeverDungeonJournal learned client text",["text"]="Slay 7 Al'Aketh Guardians, 7 Al'Aketh Spiritcallers, and 7 Al'Aketh Blademasters, then report to Hyusaa Quickbreeze at the Shrine of Akir."},
 [93016]={["source"]="ForeverDungeonJournal authored summary",["text"]="Speak with Mordent Evenshade in Shen'dralas for information about the crystals you repaired."},
 [93030]={["source"]="QuestieDB Forever",["text"]="Speak with the Knight of Mourning to learn more about his unfinished quest."},
 [93034]={["source"]="QuestieDB Forever",["text"]="Improve your reputation with the Gelkis, and locate Nerlokh near the Valley of Bones far east of Gelkis Village."},
 [93035]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis Clan and slay 6 Undead Ravagers, then return to Nerlokh at the southern entrance to Valley of Bones."},
 [93036]={["source"]="QuestieDB Forever",["text"]="Speak with Sania Silverstream in Shen'dar Village."},
 [93037]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis Clan, and bring 1 Necromantic Garb to Nerlokh at the entrance of the Valley of Bones."},
 [93041]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis Clan, and bring an Accursed Skull and Gelkis Necromantic Garb to Uthek the Wise in Gelkis Village."},
 [93044]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis, and bring Tears of Theradras back to Uthek the Wise in Gelkis Village."},
 [93045]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis, and dispel the necromantic curse present on the Accursed Skull. Once successful, report back to Nerlokh near the Valley of Bones."},
 [93058]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis clan, and rescue 5 Gelkis Captives within the Valley of Bones. Return to Nerlokh near the entrance when you are done."},
 [93062]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis Clan, and dispel the curses from 8 failed summons throughout the Valley of Bones."},
 [93065]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Valennia Stormfist in the Gustberry Lowlands."},
 [93066]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram, and slay quilboar at Bristleback Retreat. Then report to Hagiak at the Magram Front on the other side of Valley of Bones in Desolace."},
 [93072]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram clan and slay 2 Outcast Scouts, 6 Outcast Marauders, and 8 Outcast Necromancers then return to Hagiak at the Magram Front."},
 [93089]={["source"]="QuestieDB Forever",["text"]="Speak with Elaadrin Evengale when you are prepared to leave Zephras Isle."},
 [93090]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Ayessa Dawnsinger when you are prepared to leave Zephras Isle."},
 [93122]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis, and investigate centaur points of interest within Shen'dralas. Then return to Nerlokh at the entrance of Valley of Bones with your findings."},
 [93125]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis, and escort Rokren out of the Outcast Hideaway. Then inform Nerlokh near the Valley of Bones about what happened."},
 [93128]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Gelkis, and slay Khan Jhen at Magram Village. Once you have succeeded, report to Uthek the Wise in Gelkis Village in Desolace."},
 [93129]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram, and bring 6 Stolen Supplies back to Hagiak at the Magram Front."},
 [93159]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with the Strange Hermit in the Shadowgale Forest and learn more about him."},
 [93160]={["source"]="ForeverDungeonJournal learned client text",["text"]="Gather 8 Shadowgale Acorns in Shadowgale Forest."},
 [93165]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 5 Al'Aketh Cultist's Ears from the Al'Aketh cultists in Shadowgale Forest, the Shrine of Akir, or Gustberry Lowlands."},
 [93172]={["source"]="ForeverDungeonJournal learned client text",["text"]="Destroy 10 Wind Hollows in Shadowgale Forest."},
 [93176]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the items contained in the Entomology Starter Kit to find and catch an Arbor Tarantula, Hay Weevil Specimen, and a Flesh Picker."},
 [93188]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram, and report back to Orgrul near the northern entrance to Valley of Bones."},
 [93196]={["source"]="QuestieDB Forever",["text"]="Maintain your reputation with the Magram and perform a necromancy ritual to resurrect Khan Jehn. The ritual site can be found in a tent at the central lake of Magram Village."},
 [93224]={["source"]="QuestieDB Forever",["text"]="Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Captain Pentigast at Nijel's Point."},
 [93225]={["source"]="QuestieDB Forever",["text"]="Acquire 5 Carved Centaur Totems by slaying centaur of any clan throughout Desolace, then return them to Gurda Wildmane at Ghost Walker Post."},
 [93226]={["source"]="QuestieDB Forever",["text"]="Bring the Totem Tote to the Magram Quartermaster at Magram Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Magram Clan Centaur."},
 [93227]={["source"]="QuestieDB Forever",["text"]="Bring the Totem Tote to the Gelkis Quartermaster at Gelkis Village in the Desolace to significantly increase your reputation with that clan. You must be of at least Neutral standing with the Gelkis Clan Centaur."},
 [93317]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 6 pieces of Windsong Crawler Meat."},
 [93318]={["source"]="QuestieDB Forever",["text"]="Kill Vulgara the Insatiable in the Shen'dar Highlands and bring her head to Danarii Bellowveil."},
 [93319]={["source"]="QuestieDB Forever",["text"]="Collect 10 Pilfered Windstones from the Highlands Bandits in the Shen'dar Highlands."},
 [93320]={["source"]="ForeverDungeonJournal learned client text",["text"]="Report to Yorana Windyreed at the eastern watchtower in the Gustberry Lowlands."},
 [93341]={["source"]="ForeverDungeonJournal authored summary",["text"]="Investigate the Forlorn Gardens near Shen'dralas and then return to Mithera at the nearby temple."},
 [93383]={["source"]="QuestieDB Forever",["text"]="Wait until you can safely open the Personal Survival Pack."},
 [93394]={["source"]="ForeverDungeonJournal authored summary",["text"]="Locate Magister Kirandis inside the temple of Shen'dralas."},
 [93404]={["complex"]=true,["source"]="ForeverDungeonJournal authored summary",["text"]="Venture to Maraudon and recover a Vial of Earth Song Water, then use it to put out Woodwyrd's flame at the Forlorn Gardens."},
 [93429]={["source"]="QuestieDB Forever",["text"]="Slay 10 Lost Ones in the Fallow Sanctuary."},
 [93430]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Find the Lost One Fisherman who stole Pelluk's lure, and take it back."},
 [93443]={["source"]="QuestieDB Forever",["text"]="Deliver the Lost Shipping Crate to Friz Frazzlespark at Powderfuse Port in the Riverglades."},
 [93461]={["source"]="QuestieDB Forever",["text"]="Speak with Rathiril Sunlance and Coriella Calmbreeze in Shen'dar Village."},
 [93464]={["source"]="QuestieDB Forever",["text"]="Find the mage in Desolace who knows about the power of draenethyst."},
 [93465]={["source"]="QuestieDB Forever",["text"]="Take Gimashi's notes on Draenethyst, and bring them back to Azore Aldamort."},
 [93510]={["source"]="QuestieDB Forever",["text"]="Find the anchor on Lake Everstill the War Veteran remembers from childhood."},
 [93552]={["source"]="QuestieDB Forever",["text"]="Collect 15 Windstone Clusters from Raw Windstones in Thendal Grove."},
 [93585]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Father Tuttle to The Harborage."},
 [93594]={["source"]="ForeverDungeonJournal authored summary",["text"]="Find Woodwyrd in the Forlorn Gardens at Shen'dralas."},
 [93601]={["source"]="ForeverDungeonJournal authored summary",["text"]="Seek out a quilboar of significance at the Bristleback Retreat."},
 [93604]={["source"]="ForeverDungeonJournal authored summary",["text"]="Venture to Razorfen Downs and acquire Virulent Blood of Agamaggan, then return it to Kog'thug the Brave at Bristleback Retreat."},
 [93663]={["source"]="QuestieDB Forever",["text"]="Find the missing courier, and ensure Dar's shipment is delivered to the Harborage."},
 [93678]={["source"]="QuestieDB Forever",["text"]="Take Azore's transcribed notes back to Magtoor at the Harborage in Swamp of Sorrows."},
 [93680]={["source"]="QuestieDB Forever",["text"]="Acquire the Dalaran Sewer Key for Magus Wordeen Voidglare in Tarren Mill."},
 [93735]={["source"]="ForeverDungeonJournal learned client text",["text"]="Find Riaani Nightwind on the west side of Valanaar."},
 [93736]={["source"]="ForeverDungeonJournal learned client text",["text"]="Gather 10 Wind Hollow Essences from Wind Hollows in the Shadowgale Forest."},
 [93737]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Riaani Nightwind and listen to what he has to say."},
 [93738]={["source"]="ForeverDungeonJournal learned client text",["text"]="Report back to Ayessa Dawnsinger in Valanaar."},
 [93739]={["complex"]=true,["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Nazgrel in Grommash Hold to receive further instructions. Use the instructions received to locate and speak with Vol'jin, Cairne Bloodhoof, and Lady Sylvanas Windrunner."},
 [93740]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 10 Al'Aketh Windstone Charms from the corpses of Al'Aketh cultists in the Gustberry Lowlands."},
 [93746]={["source"]="ForeverDungeonJournal learned client text",["text"]="Confront Belathaan Brightwish along the road to the Shrine of Akir."},
 [93786]={["source"]="QuestieDB Forever",["text"]="Slay 12 Meadowsbrook Farmhands, then return to Krom'rosh with news of your success."},
 [93787]={["source"]="QuestieDB Forever",["text"]="Steal 6 Feed Satchels from the Alliance farm in Meadowsbrook then return to Krom'rosh."},
 [93788]={["source"]="QuestieDB Forever",["text"]="Retrieve 10 Woodworker's Axe from the lumberjacks at Turner's Logging Camp for Kreza Darkthorn in Rog'mar."},
 [93791]={["source"]="QuestieDB Forever",["text"]="Speak with Belann Windwood in Valanaar."},
 [93797]={["source"]="QuestieDB Forever",["text"]="Bring a Wind-Infused Bough to Belann Windwood in Valanaar."},
 [93835]={["complex"]=true,["extra"]={"Take the portal","Start the fight"},["source"]="QuestieDB Forever",["text"]="Take the portal to the Rohashi Spires overhead and join Elaadrin Evengale and Ayessa Dawnsinger in their confrontation with High Priestess Lorthuna.\010Start the fight"},
 [93836]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Talaanis Shadowsong in Valanaar."},
 [93926]={["source"]="ForeverDungeonJournal learned client text",["text"]="Find Peacekeeper Vaaniel at the western watchtower."},
 [93927]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect the note you found near the dead peacekeeper and read it to determine your next steps."},
 [93928]={["source"]="QuestieDB Forever",["text"]="Get the mouse a cookie."},
 [93948]={["source"]="ForeverDungeonJournal learned client text",["text"]="Deliver the Shadowsong Family Signet to Talaanis Shadowsong in Valanaar."},
 [93949]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kill Skyhoppers in Valanaar until you've eliminated 8 Enchanted Skyhoppers."},
 [93951]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 8 Hippogryph Down feathers in the Shen'dar Highlands."},
 [93958]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Valennia Stormfist inside the inner sanctum at the Shrine of Akir."},
 [93963]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Speak with Randal Emerson in Stormwind Keep to receive further instructions. Use the instructions received to locate and speak with King Magni Bronzebeard, High Tinker Mekkatorque, and Tyrande Whisperwind."},
 [93971]={["source"]="QuestieDB Forever",["text"]="Bring the report to Krom'rosh at Rog'mar."},
 [93976]={["source"]="QuestieDB Forever",["text"]="Deliver the blade to Kreza Darkthorn's acquaintance at the docks east of Rog'mar."},
 [94003]={["source"]="QuestieDB Forever",["text"]="Reclaim the Skybreaker Bulwark from Zaal Stormshield at the Shrine of Akir."},
 [94004]={["source"]="QuestieDB Forever",["text"]="Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction."},
 [94006]={["source"]="QuestieDB Forever",["text"]="Speak with Urs'endris near the falls northeast of Valanaar."},
 [94007]={["source"]="QuestieDB Forever",["text"]="Report to Quel'ana Quickgale in Valanaar."},
 [94013]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame a Vuldren Alpha in the Gustberry Lowlands. Practice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar."},
 [94050]={["source"]="QuestieDB Forever",["text"]="Speak to Quel'dora Quickgale in Valanaar."},
 [94212]={["source"]="QuestieDB Forever",["text"]="Acquire the items requested by the customer and deliver them to the location marked on your map. This writ must be in your possession to complete the transaction."},
