 [94369]={["source"]="QuestieDB Forever",["text"]="Speak with Talaanis Shadowsong in Valanaar."},
 [94373]={["source"]="QuestieDB Forever",["text"]="Bring 2 Frostmane Bear Pendants to Teo Hammerstorm in Anvilmar."},
 [94374]={["source"]="QuestieDB Forever",["text"]="Find the Spirit Stone and drink the Earth Sapta."},
 [94375]={["source"]="QuestieDB Forever",["text"]="Bring the Rough Quartz to Teo Hammerstorm in Anvilmar."},
 [94399]={["source"]="QuestieDB Forever",["text"]="Collect 5 Diemetradon Meats and 5 Pterrodax Meats for Mor'vek in Un'Goro Crater."},
 [94411]={["source"]="QuestieDB Forever",["text"]="Slay 6 High Order Apprentices in Shen'dar Highlands."},
 [94413]={["source"]="QuestieDB Forever",["text"]="Slay 6 Windshaper Novice Seers in Shen'dar Highlands."},
 [94414]={["source"]="QuestieDB Forever",["text"]="Speak with Halaan Hawk-Eye and borrow his gift to view the anchor pylon in the distance."},
 [94427]={["source"]="QuestieDB Forever",["text"]="Speak to Tanis Alderwood in the Undercity."},
 [94434]={["source"]="QuestieDB Forever",["text"]="Bring 10 Linen Cloth to Tanis Alderwood in the Undercity."},
 [94435]={["source"]="QuestieDB Forever",["text"]="Return to Danitha Morr at Bandarion Keep."},
 [94436]={["source"]="QuestieDB Forever",["text"]="Speak with Deathguard Billmuth at Bandarion Keep.\010Should you misplace your Symbol of Life, return to Danitha Morr for a replacement."},
 [94438]={["complex"]=true,["source"]="ForeverDungeonJournal learned client text",["text"]="Take the Symbol of Life and use it to resurrect Deathguard Falgan at Venomweb Vale.\010\010Should you misplace your Symbol of Life, return to Danitha Morr for a replacement."},
 [94440]={["source"]="ForeverDungeonJournal learned client text",["text"]="Retrieve the Scarlet Crusade Attack Plans from the Scarlet Crusaders at Venomweb Vale, and return to Deathguard Billmuth at Bandarion Keep."},
 [94441]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with Danitha Morr in the keep at Bandarion Keep."},
 [94449]={["source"]="QuestieDB Forever",["text"]="Find Bruegs Kindleborn in Dun Morogh."},
 [94465]={["source"]="QuestieDB Forever",["text"]="Bring the Torch of the Dormant Flame to Braldir Ashmantle in Loch Modan."},
 [94466]={["source"]="QuestieDB Forever",["text"]="Bring 1 Fire Tar and 1 Reagent Pouch to Braldir Ashmantle in Loch Modan."},
