 [94975]={["source"]="QuestieDB Forever",["text"]="Collect 15 Cultist Ears from the Twilight's Hammer in Krol'dok Stronghold."},
 [94978]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Taming Rod to tame a Windsong Crawler found near bodies of water.\010Practice your skills, then return the Taming Rod to Quel'ana Quickgale in Valanaar."},
