 [94980]={["source"]="QuestieDB Forever",["text"]="Find someone in Farholde Keep who may know about the mould."},
 [94981]={["source"]="QuestieDB Forever",["text"]="Bring 4 Thick Leather and 12 Iron Bars to Alphonse Dumas."},
 [94982]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Infiltrate Krol'dok Stronghold and return to Commander Brant with proof of their leader's demise."},
