 [95181]={["source"]="QuestieDB Forever",["text"]="Deliver Azka's message to Krom'rosh at Rog'mar."},
 [95183]={["source"]="QuestieDB Forever",["text"]="Gather 10 Good Rocks for Hamur in Bolder'ok."},
 [95184]={["source"]="QuestieDB Forever",["text"]="Bring 8 Solid Sharpening Stones to Ember Bladewhisper at the Farholde training grounds."},
 [95189]={["source"]="QuestieDB Forever",["text"]="Return the Crest of Lordaeron to Lady Dena Kennedy in Stormwind City."},
 [95194]={["source"]="QuestieDB Forever",["text"]="Seek out the SI:7 agent stationed on Theramore Isle."},
 [95195]={["source"]="QuestieDB Forever",["text"]="Collect 10 Bloodied Insignias and take them to General Marcus Jonathan in Stormwind City."},
 [95196]={["source"]="QuestieDB Forever",["text"]="Meet Sully McCleary in Dustwallow Marsh and learn more about your mission."},
 [95198]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the SI:7 Disguise Kit to eavesdrop on Jaina and her inner circle at the Theramore Mage Tower."},
 [95204]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring the Crest of Lordaeron to Oran Snakewrithe in Undercity."},
 [95212]={["source"]="QuestieDB Forever",["text"]="Collect 6 Pristine Leopard Pelts and deliver them to Amberstill Ranch."},
 [95213]={["source"]="QuestieDB Forever",["text"]="Bring the Empty Powder Keg to Quarrymaster Thesten at Gol'Bolar Quarry."},
