 [95216]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect the Highly Toxic Strain from Witherfang in Ruins of Lordaeron for Theodore Griffs in Undercity."},
 [95217]={["source"]="QuestieDB Forever",["text"]="Collect 12 Copper Bars and 4 Toughened Boar Hides and deliver them to Frast Dokner."},
