 [95248]={["source"]="QuestieDB Forever",["text"]="Travel to the Summit of Eternity and speak with the druids about the survivor village."},
 [95250]={["source"]="QuestieDB Forever",["text"]="Collect the Head of the Baron in the Ruins of Lordaeron and bring it back to Captain Truman."},
 [95254]={["source"]="QuestieDB Forever",["text"]="Bring Trapclaw's Pincer to Fimbo Greasemitz."},
 [95262]={["source"]="QuestieDB Forever",["text"]="Enter Alcaz Prison and learn what became of the King of Stormwind."},
 [95263]={["source"]="QuestieDB Forever",["text"]="Return to Sully McCleary in Dustwallow Marsh."},
 [95264]={["source"]="QuestieDB Forever",["text"]="Bring the news to Matthias Shaw in Stormwind."},
 [95267]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Big Ball o' Bait to lure out the sea monster. Then, bring its head to Argo Brinewhistle."},
 [95278]={["source"]="QuestieDB Forever",["text"]="Deliver the missive to Krom'rosh at Rog'mar."},
 [95283]={["source"]="QuestieDB Forever",["text"]="Speak with Nazeer Bloodspike in Brackenwall Village."},
 [95284]={["source"]="QuestieDB Forever",["text"]="Find the missing Kor'kron Elites."},
 [95285]={["source"]="QuestieDB Forever",["text"]="Speak with Sergeant Ulka to learn more about the situation on Alcaz Isle."},
 [95293]={["source"]="QuestieDB Forever",["text"]="Deliver The Friz Special to Captain Bentcoin in Eastwind Shore."},
 [95295]={["source"]="QuestieDB Forever",["text"]="Speak to Friz's contact in Booty Bay."},
 [95309]={["source"]="QuestieDB Forever",["text"]="Enter the Alcaz Prison and find Commander Folkar."},
 [95314]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 8 Bottles of Whispering Elixir from Shadowvale, then return to Carolai Anise in Brill."},
 [95315]={["source"]="QuestieDB Forever",["text"]="Deliver Captain Nials' Correspondence to Demar Brant at Farholde Keep along the southeastern coast in the Riverglades."},
 [95328]={["source"]="QuestieDB Forever",["text"]="Deliver Whispering Horror Residue to Father Lankester in the War Quarter of Undercity."},
 [95329]={["source"]="QuestieDB Forever",["text"]="Go to Terral's Watch to get a status report from Watcher Cornelius."},
 [95330]={["source"]="QuestieDB Forever",["text"]="Deliver Cassandra's surplus farm goods to Halligan Turner at Turner's Logging Camp."},
 [95349]={["source"]="ForeverDungeonJournal learned client text",["text"]="Take the skycutter ship from Zephras Isle to Mulgore and speak with Alaana Stormwalker when you arrive."},
 [95350]={["source"]="ForeverDungeonJournal learned client text",["text"]="Travel to Orgrimmar and speak with Thrall in the Valley of Wisdom."},
 [95384]={["source"]="QuestieDB Forever",["text"]="Bring the partial scroll to Dudd Fizzlescroll in Booty Bay."},
 [95417]={["source"]="QuestieDB Forever",["text"]="Find missing ogres in the caves beneath Sunnyglade for Clubtoe."},
 [95418]={["source"]="QuestieDB Forever",["text"]="Deliver the head of Chogg to Tran'gul in Rog'mar."},
 [95420]={["source"]="QuestieDB Forever",["text"]="Deliver Chogg's head to the ogre city to the north."},
 [95424]={["source"]="QuestieDB Forever",["text"]="Kill 7 Twilight Maulers and 7 Twilight Firecallers for Clugfist in Bolder'ok."},
 [95425]={["source"]="QuestieDB Forever",["text"]="Collect Skullthumper from Klunk for Clugfist in Bolder'ok."},
 [95426]={["source"]="QuestieDB Forever",["text"]="Retrieve 8 Horde Supply Shipment from the training camps north of Rog'mar."},
 [95427]={["source"]="QuestieDB Forever",["text"]="Kill Chogg'Zac in the Sunnyglade cave and collect their heads for Clubtoe."},
 [95428]={["source"]="QuestieDB Forever",["text"]="Report to Krom'rosh in Rog'mar."},
 [95431]={["source"]="QuestieDB Forever",["text"]="Look for the Bolder'ok ogre in the nearby cave."},
 [95432]={["source"]="QuestieDB Forever",["text"]="Recruit 5 Ogre Miners."},
 [95433]={["source"]="QuestieDB Forever",["text"]="Collect the Executioner's Mace from Executioner Morg in the Twilight Shroud for Clugfist in Bolder'ok."},
 [95454]={["source"]="QuestieDB Forever",["text"]="Look for King Varian Wrynn in Alcaz Prison."},
 [95483]={["source"]="QuestieDB Forever",["text"]="Bring word of Varian Wrynn's fate to Thrall in Orgrimmar."},
 [95494]={["source"]="QuestieDB Forever",["text"]="Collect 6 Savannah Lion Hides from the Savannah Matriarchs and Savannah Patriarchs in the Barrens."},
 [95495]={["source"]="QuestieDB Forever",["text"]="Bring the Bundle of Hides to the hermit on the ridge overlooking the Dry Hills in the Barrens."},
 [95507]={["source"]="QuestieDB Forever",["text"]="Collect 8 Trapped Game from traps found in Sprung Traps in the Barrens."},
 [95508]={["source"]="QuestieDB Forever",["text"]="Help Walton survive the encounter with Terry Longdrink and the Kul Tiras marines."},
 [95511]={["source"]="QuestieDB Forever",["text"]="Inspect the riding sabers to choose your first mount."},
 [95534]={["source"]="QuestieDB Forever",["text"]="Solve the mystery of Strahnbrad and report your findings in town in Hillsbrad."},
 [95561]={["source"]="QuestieDB Forever",["text"]="Collect 6 Fresh Apples for Tessa Dawnbright in Farholde Keep."},
 [95562]={["source"]="QuestieDB Forever",["text"]="Kill Chogg'Zac in the caves beneath Sunnyglade and retrieve their heads for Apprentice Claire."},
 [95601]={["source"]="QuestieDB Forever",["text"]="Kill 5 Empowered Brutes and 10 Twilight Ritualists then return to Clubtoe in Sunnyglade."},
 [95602]={["source"]="QuestieDB Forever",["text"]="Destroy 5 Twilight Ritual Circles found throughout the caves underneath Sunnyglade."},
 [95603]={["source"]="QuestieDB Forever",["text"]="Kill 5 Roosting Duskbats in the Farholde Cathedral for Sister Rowland."},
 [95613]={["source"]="QuestieDB Forever",["text"]="Bring 5 Holy Candles to Sister Rowland in Farholde Keep."},
 [95615]={["source"]="QuestieDB Forever",["text"]="Place 3 Memorial Candles on graves in the chapel graveyard for Sister Rowland at Farholde Keep."},
 [95621]={["source"]="QuestieDB Forever",["text"]="Travel to the wrecked caravan and learn more about why the Kul Tirans are here."},
 [95642]={["source"]="QuestieDB Forever",["text"]="Absorb 25 samples into the Crystal Catalyst from Twilight's Hammer cultists and Twilight Ritual Circles in the cave underneath Sunnyglade for Apprentice Claire."},
 [95643]={["source"]="QuestieDB Forever",["text"]="Kill 5 Twilight Ritualists and 5 Empowered Brutes within the caves underneath Sunnyglade."},
 [95646]={["source"]="QuestieDB Forever",["text"]="Kill a Highland Horror within Excavation Sites and bring its root core to Rethiel the Greenwarden in the Wetlands."},
 [95647]={["source"]="QuestieDB Forever",["text"]="Find Ardin Grassman in the Excavation Sites."},
 [95663]={["source"]="QuestieDB Forever",["text"]="Travel to the Wetlands and meet the Deathstalker Agent in the hills above the Dragonmaw camp."},
 [95664]={["source"]="QuestieDB Forever",["text"]="Take the Titan Relic to the Elder Rise in Thunder Bluff and look for someone who can tell you more about it."},
 [95682]={["source"]="QuestieDB Forever",["text"]="Slay the Dragonmaw forces within the Excavation Site and return to the Deathstalker Agent outside with anything you recover."},
 [95697]={["source"]="QuestieDB Forever",["text"]="Enter the Excavation Sites in the Wetlands and bring back Thicket Raptor Meat."},
 [95737]={["source"]="QuestieDB Forever",["text"]="Speak with Caitlin Grassman in Menethil Harbor."},
 [95748]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the hide and charcoal to create a rubbing of the Third Troll Legend tablet."},
 [95770]={["source"]="QuestieDB Forever",["text"]="Explore the Vile Reef and find the cavern entrance."},
 [95772]={["source"]="QuestieDB Forever",["text"]="Look for Dorin Songblade's brother, Daewyn, in Whelgar's Excavation Site."},
 [95773]={["source"]="QuestieDB Forever",["text"]="Gather 10 Brinescale Tridents from Brinescale Skirmishers."},
 [95774]={["source"]="QuestieDB Forever",["text"]="Slay quilboars and collect 4 of Olgra's Adornments for Mankrik's memorial."},
 [95775]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the hide and charcoal to create rubbings of the tablets found in the Drowned City."},
 [95776]={["source"]="QuestieDB Forever",["text"]="Slay Var'Taka in the Drowned City."},
 [95786]={["source"]="QuestieDB Forever",["text"]="Find Loremaster Dibbs in Southshore and bring him the Savage Coast Report Bundle."},
 [95787]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the hide and charcoal to create rubbings of the tablets found in the Drowned City."},
 [95788]={["source"]="QuestieDB Forever",["text"]="Collect 5 I'lalai Fetishes from trolls in the Drowned City."},
 [95789]={["source"]="QuestieDB Forever",["text"]="Collect 10 Voodoo Infused Artifacts from Saltseer pirates in the Drowned City."},
 [95790]={["source"]="QuestieDB Forever",["text"]="Collect 15 Partially Digested Journal Pages from the Shaper's Terrace."},
 [95791]={["source"]="QuestieDB Forever",["text"]="Slay 3 Saltseer Coroners and Captain Dreadrise in the Drowned City."},
 [95795]={["source"]="QuestieDB Forever",["text"]="Return to Dorin Songblade."},
 [95798]={["source"]="QuestieDB Forever",["text"]="Bring the I'lalai Fetish to Abra Cadabra in Dalaran."},
 [95799]={["source"]="QuestieDB Forever",["text"]="Bring Loremaster Dibbs' I'lalai Translations to Historian Karnik in Ironforge."},
 [95803]={["source"]="QuestieDB Forever",["text"]="Bring the head of Rudolph Gelhardt to Sylvanas Windrunner in the Undercity."},
 [95805]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Carry the Smoldering Incense to the shrine of An'she and Mu'sha in the southeastern hills before the incense burns to ash in ten minutes!"},
 [95809]={["source"]="QuestieDB Forever",["text"]="Return to Caitlin Grassman in Menethil Harbor."},
 [95810]={["source"]="QuestieDB Forever",["text"]="Bring the Titan Relic to Prospector Whelgar in the Wetlands excavation site."},
 [95816]={["source"]="QuestieDB Forever",["text"]="Bring the completed form to Elaine Compton in Redridge Mountains."},
 [95817]={["source"]="QuestieDB Forever",["text"]="Meet Rotgath Stonebeard near the Great Forge in Ironforge."},
 [95819]={["source"]="QuestieDB Forever",["text"]="Bring the completed form to Jornah in The Barrens."},
 [95882]={["source"]="QuestieDB Forever",["text"]="Bring the Scoutmaster's Eye to Neza Bloodsnout in Rog'mar."},
 [95883]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect a Tortured Soul from the nearby undead in Beren's Peril in Silverpine Forest."},
 [95884]={["source"]="ForeverDungeonJournal learned client text",["text"]="Find the Offering Stone in Beren's Peril in Silverpine Forest."},
 [95885]={["complex"]=true,["source"]="ForeverDungeonJournal learned client text",["text"]="Use the Tortured Soul to give an offering of blood at the Offering Stone in Beren's Peril."},
 [95912]={["source"]="QuestieDB Forever",["text"]="Bring the Blademaster's Banner to Ember Bladewhisper in Farholde Keep."},
 [95913]={["source"]="QuestieDB Forever",["text"]="Collect 3 Coyote Pelts for Tessa Dawnbright in Farholde Keep."},
 [95924]={["source"]="QuestieDB Forever",["text"]="Slay 6 Ravasaur Matriarchs, 9 Ironhide Ravasaurs and Venomridge in Shaper's Terrace."},
 [95925]={["source"]="QuestieDB Forever",["text"]="Find Interesting Landmarks in Shaper's Terrace and fill out the explorer's map at each."},
 [95926]={["source"]="QuestieDB Forever",["text"]="Gather a colorless Drained Crystal Fragment near the Achromatic Crystal in the Shaper's Terrace."},
 [95928]={["source"]="QuestieDB Forever",["text"]="Bring Mayena Earthseeker a Moist Crystal, a Charged Crystal, a Noxious Crystal and a Fiery Crystal from Shaper's Terrace."},
 [95935]={["source"]="QuestieDB Forever",["text"]="Take the Head of Scaldaron to Cedric Dalton at the Southern Watch."},
 [95936]={["source"]="QuestieDB Forever",["text"]="Take the Head of Scaldaron to Krom'rosh at Rog'mar."},
 [95943]={["source"]="QuestieDB Forever",["text"]="Locate the Foreman's Crate and return it to Bertrand Ironbrow in Farholde Keep."},
 [95951]={["source"]="QuestieDB Forever",["text"]="Collect Wood Bundles from Peasant Woodpiles in Turner's Logging Camp then fletch them into 20 Makeshift Stickin' Spears."},
 [95955]={["source"]="QuestieDB Forever",["text"]="Impale 10 Freshwater Crocolisks then return to Tran'jani in Rog'mar."},
 [95957]={["source"]="QuestieDB Forever",["text"]="Deliver Zizplink's Frothing Mug to Gray Dawnbright in Powderfuse Port."},
 [95961]={["source"]="QuestieDB Forever",["text"]="Find Gray Dawnbright in Powderfuse Port."},
 [95975]={["source"]="QuestieDB Forever",["text"]="Gather 20 Wildflowers and deliver them to Tessa Dawnbright in Farholde Keep."},
 [95981]={["source"]="ForeverDungeonJournal learned client text",["text"]="Slay 8 Dalaran Wizards and 8 Dalaran Watchers for Shadow Priest Allister in the Sepulcher."},
 [95982]={["source"]="QuestieDB Forever",["text"]="Bring 10 Briny Seafood Stew to Jasper Geartoggle in Powderfuse Port."},
 [95983]={["source"]="QuestieDB Forever",["text"]="Bring the Gnawed Skull to Watcher Cornelius at Terral's Watch."},
 [95984]={["source"]="QuestieDB Forever",["text"]="Bring an Intact Tallstrider Beak to Watcher Cornelius at Terral's Watch."},
 [95986]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Tallstrider Call to call forth the leader of the lion pride. Slay the beast and retrieve its hide for Watcher Cornelius at Terral's Watch."},
 [95988]={["source"]="QuestieDB Forever",["text"]="Gather 3 Crawler Spittle, Fresh Chum, Goblin Degreaser, and Expired Poison for Innkeeper Zizplink in Powderfuse Port."},
 [95991]={["source"]="QuestieDB Forever",["text"]="Bring Ghostmaw's Fang to Wheatley in Farholde Keep."},
 [95992]={["source"]="QuestieDB Forever",["text"]="Bring Ghostmaw's Fang to Tan'jani in Rog'mar."},
 [95998]={["source"]="QuestieDB Forever",["text"]="Sit near Sam's Basic Campfire and wait until you receive the Boosted Rest buff."},
 [95999]={["source"]="QuestieDB Forever",["text"]="Deliver the Broken Staff of Incinerator Gar'im to Magistrate Solomon in Lakeshire."},
 [96009]={["source"]="QuestieDB Forever",["text"]="Collect 10 Wood Bundles from Turner's Logging Camp for Bertrand Ironbrow in Farholde Keep."},
 [96010]={["source"]="ForeverDungeonJournal authored summary",["text"]="Recover shards and fragments of the pylons, found guarded at the Magram and Gelkis villages. Return them to Mordent Evenshade."},
 [96015]={["source"]="QuestieDB Forever",["text"]="Defeat 5 Ogre Miners and 5 Twilight Subjugators in the cave near the Twilight's Shroud for Sergeant Riftan."},
 [96016]={["source"]="QuestieDB Forever",["text"]="Deliver the Eye of the Tempest to Bath'rah the Windwatcher in Alterac Mountains."},
 [96018]={["complex"]=true,["source"]="ForeverDungeonJournal authored summary",["text"]="Acquire the Mana Sieve from within the temple in Shen'dralas and use it to collect Ancient Mana Crystals, then empower the pylons and return to Mordent Evenshade."},
 [96026]={["source"]="QuestieDB Forever",["text"]="Deliver 10 Heavy Weightstones to Hamur in Bolder'ok."},
 [96031]={["source"]="QuestieDB Forever",["text"]="Speak with Gretta Finespindle in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96044]={["source"]="QuestieDB Forever",["text"]="Speak with Tognus Flintfire in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96045]={["source"]="QuestieDB Forever",["text"]="Speak with Vosur Brakthel in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96046]={["source"]="QuestieDB Forever",["text"]="Speak with Yarr Hammerstone in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96047]={["source"]="QuestieDB Forever",["text"]="Speak with Thamner Pol in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96050]={["source"]="QuestieDB Forever",["text"]="Speak with Paxton Ganter near Iceflow Lake in Dun Morogh to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96055]={["source"]="QuestieDB Forever",["text"]="Speak with Reyna Stonebranch in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96056]={["source"]="QuestieDB Forever",["text"]="Speak with Balthus Stoneflayer in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96057]={["source"]="QuestieDB Forever",["text"]="Speak with Uthrar Threx in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96058]={["source"]="QuestieDB Forever",["text"]="Speak with Bronk Guzzlegear in Kharanos to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96059]={["source"]="QuestieDB Forever",["text"]="Speak with Thonys Pillarstone in Ironforge to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96077]={["source"]="QuestieDB Forever",["text"]="Deliver the ring to Michelle Belle at the Lion's Pride Inn in Elwynn Forest."},
 [96078]={["source"]="QuestieDB Forever",["text"]="Take the tablet etchings to Master Gadrin in Sen'jin Village in Durotar."},
 [96081]={["source"]="QuestieDB Forever",["text"]="Gather 20 Mageweave Cloth for Brother Lowley at Farholde Keep."},
 [96082]={["source"]="QuestieDB Forever",["text"]="Bandage up 3 Wounded Soldiers for Brother Lowley."},
 [96083]={["source"]="QuestieDB Forever",["text"]="Speak to Sister Rowland at the chapel in Farholde Keep."},
 [96084]={["source"]="QuestieDB Forever",["text"]="Collect a sample of drinking water from the plains for Sister Rowland at the chapel in Farholde Keep."},
 [96085]={["source"]="QuestieDB Forever",["text"]="Find whatever creature is causing the drinking water contamination and eliminate it. Then, return to Sister Rowland at the chapel in Farholde Keep."},
 [96101]={["source"]="QuestieDB Forever",["text"]="Sit near Raan's Basic Campfire and wait until you receive the Boosted Rest buff."},
 [96102]={["source"]="QuestieDB Forever",["text"]="Speak with Snang in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [96103]={["source"]="QuestieDB Forever",["text"]="Bring the Gnawed Skull to Neza Bloodsnout at Rog'mar."},
 [96104]={["source"]="QuestieDB Forever",["text"]="Bring an Intact Tallstrider Beak to Neza Bloodsnout at Rog'mar."},
 [96105]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Tallstrider Call to call forth the leader of the lion pride. Slay the beast and retrieve its hide for Neza Bloodsnout at Rog'mar."},
 [96107]={["source"]="QuestieDB Forever",["text"]="Bring 6 Plains Buzzard Feathers to Neza Bloodsnout at Rog'mar."},
 [96108]={["source"]="QuestieDB Forever",["text"]="Bring 4 samples of Glade Viper Venom to Neza Bloodsnout at Rog'mar."},
 [96109]={["source"]="QuestieDB Forever",["text"]="Gather 6 Prized Lion Hides for Neza Bloodsnout at Rog'mar."},
 [96125]={["source"]="QuestieDB Forever",["text"]="Find Dunston Willis somewhere among the ogres in Bolder'ok."},
 [96126]={["source"]="QuestieDB Forever",["text"]="Find Gronok the Butcher, kill him, and bring Dunston the key to his shackles."},
 [96130]={["source"]="QuestieDB Forever",["text"]="Defeat Chakuyak and bring back her pelt."},
 [96135]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Twisted Totems to put an end to the quilboar ritual."},
 [96136]={["source"]="QuestieDB Forever",["text"]="Find Prate Cloudseer in Thousand Needles."},
 [96137]={["source"]="QuestieDB Forever",["text"]="Defeat 10 Young Black Ravagers and 7 Black Ravagers then return to Sirra Von'Indi in Darkshire for more information."},
 [96138]={["source"]="QuestieDB Forever",["text"]="Defeat 8 Splint Fist Warriors and 4 Splint Fist Taskmasters then return to Sirra Von'Indi in Darkshire for more information."},
 [96139]={["source"]="QuestieDB Forever",["text"]="Search Raven Hill for anything of interest and return to Sirra Von'Indi in Darkshire."},
 [96204]={["source"]="QuestieDB Forever",["text"]="Accompany Lumina Windsinger and help her escape Fenris Keep."},
 [96222]={["source"]="QuestieDB Forever",["text"]="Bring the Maraudine Key Fragment to Umarak in the Desolace."},
 [96241]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Toxin Extractor to gather 5 Gloomrise Toxin Samples from the Gnawed Corpses at Gloomrise."},
 [96243]={["source"]="QuestieDB Forever",["text"]="Find Teo Hammerstorm in Dun Morogh."},
 [96246]={["source"]="ForeverDungeonJournal authored summary",["text"]="Enter Blackmaw Hold and recover 5 Blackmaw Pouches for Ekkal at the Ruins of Eldarath in Azshara."},
 [96259]={["source"]="QuestieDB Forever",["text"]="Kill 10 Gloomrise Hatchlings and 5 Gloomrise Soldiers."},
 [96260]={["source"]="QuestieDB Forever",["text"]="Gather 3 strands of Crystalline Silk from Gloomrise Spinners."},
 [96261]={["source"]="QuestieDB Forever",["text"]="Kill Broodmother Valraxx at Gloomrise."},
 [96264]={["source"]="QuestieDB Forever",["text"]="Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans."},
 [96294]={["source"]="QuestieDB Forever",["text"]="Bring the letter you recovered from Broodmother Valraxx to Muln Earthfury at Skywatcher Plateau."},
 [96332]={["source"]="QuestieDB Forever",["text"]="Enter the Alcaz Prison and slay 15 Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sergeant Ulka."},
 [96334]={["source"]="QuestieDB Forever",["text"]="Enter Alcaz Prison and collect 8 Blood Red Bandanas from the human guards there."},
 [96335]={["source"]="ForeverDungeonJournal authored summary",["text"]="Recover the Alcaz Shackle Key from The Questioner in Alcaz Prison."},
 [96337]={["complex"]=true,["source"]="ForeverDungeonJournal authored summary",["text"]="Use the note provided by Mason Connery to find his hidden treasure."},
 [96369]={["source"]="QuestieDB Forever",["text"]="Report back to Commander Folkar."},
 [96381]={["source"]="QuestieDB Forever",["text"]="Enter the Alcaz Prison and slay 15 Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sully McCleary."},
 [96390]={["source"]="QuestieDB Forever",["text"]="Slay 10 Dark Iron Spies in Dun Morogh."},
 [96391]={["source"]="QuestieDB Forever",["text"]="Deliver the Dark Iron Map to Earthseer Farsen in Dun Morogh."},
 [96392]={["source"]="QuestieDB Forever",["text"]="Speak with Earthseer Farsen and ask him to lend you his far sight to observe the Dark Iron threat."},
 [96393]={["source"]="QuestieDB Forever",["text"]="Enter the Hall of Thanes beneath Old Ironforge and claim the Head of Durgen Dirgehammer."},
 [96394]={["source"]="QuestieDB Forever",["text"]="Kill 15 Enraged Apparitions, 10 Tormented Souls and put the spirit of Anvilmar to rest."},
 [96395]={["source"]="QuestieDB Forever",["text"]="Put the spirit of Faldrim Anvilmar to rest and then return to the Ghostly Attendant in the Hall of Thanes."},
 [96403]={["source"]="QuestieDB Forever",["text"]="Collect 8 Dwarven Heirlooms from the Hall of Thanes."},
 [96408]={["source"]="QuestieDB Forever",["text"]="Investigate the campsite overlooking the Gol'Bolar Quarry."},
 [96438]={["source"]="QuestieDB Forever",["text"]="Investigate the battle at the Mannoroc Coven in Desolace."},
 [96449]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Old Dingy at Menethil Harbor to search for Aeonas."},
 [96476]={["source"]="QuestieDB Forever",["text"]="Search for signs of Aeonas the Vindicated at the Emerald Sanctuary in Felwood."},
 [96494]={["source"]="QuestieDB Forever",["text"]="Find the Blackthorne reinforcement point at the entrance to Hyjal Summit."},
 [96529]={["source"]="QuestieDB Forever",["text"]="Bring the Blackthorne Information to Master Mathias Shaw in Stormwind."},
 [96559]={["source"]="QuestieDB Forever",["text"]="Locate Fenwick Togglespring's Pilot Survival Kit."},
 [96603]={["source"]="QuestieDB Forever",["text"]="Bring 10 Motes of Unstable Magic to Archmage Celindra in Dalaran."},
 [96604]={["source"]="QuestieDB Forever",["text"]="Sit near Brakk's Basic Campfire and wait until you receive the Boosted Rest buff."},
 [96605]={["source"]="QuestieDB Forever",["text"]="Sit near Kaga's Basic Campfire and wait until you receive the Boosted Rest buff."},
 [96606]={["source"]="QuestieDB Forever",["text"]="Sit near Lyreena's Basic Campfire and wait until you receive the Boosted Rest buff."},
 [96607]={["source"]="QuestieDB Forever",["text"]="Sit near Eleanor's Basic Campfire and wait until you receive the Boosted Rest buff."},
 [96608]={["source"]="QuestieDB Forever",["text"]="Sit near Eric's Basic Campfire and wait until you receive the Boosted Rest buff."},
 [96609]={["source"]="QuestieDB Forever",["text"]="Bring 10 bottles of Silvermoon Shimmerwine to Arille Azuregaze in Dalaran city."},
 [96616]={["source"]="QuestieDB Forever",["text"]="Collect 12 Hyjal Silphium."},
 [96622]={["source"]="QuestieDB Forever",["text"]="Deliver the Hyjal Silphium Poultice to Enho and Maruke."},
 [96626]={["source"]="QuestieDB Forever",["text"]="Speak with Tomas in Goldshire to learn to become a cook."},
 [96627]={["source"]="QuestieDB Forever",["text"]="Speak to Sam Sarsparilla near Goldshire."},
 [96628]={["source"]="QuestieDB Forever",["text"]="Deliver the Supply Bundle to Eric Brighthammer near Kharanos."},
 [96629]={["source"]="QuestieDB Forever",["text"]="Speak with Gremlock Pilsnor in Kharanos to learn to become a cook."},
 [96630]={["source"]="QuestieDB Forever",["text"]="Bring the journal to Lyreena Duskblade near Dolanaar."},
 [96634]={["source"]="QuestieDB Forever",["text"]="Speak with Zarrin in Dolanaar to learn to become a cook."},
 [96638]={["source"]="QuestieDB Forever",["text"]="Speak to Raan Wildwind near Shen'dar Village."},
 [96646]={["source"]="QuestieDB Forever",["text"]="Speak with Zerril Softbreeze in Shen'dar Village to learn to become a cook."},
 [96652]={["source"]="QuestieDB Forever",["text"]="Bring the journal to Brakk near Razor Hill."},
 [96655]={["source"]="QuestieDB Forever",["text"]="Speak with Cook Torka in Razor Hill to learn to become a cook."},
 [96656]={["source"]="QuestieDB Forever",["text"]="Speak to Eleanor Shackleton near Brill."},
 [96658]={["source"]="ForeverDungeonJournal learned client text",["text"]="Speak with William Pickman in Brill to learn to become a cook."},
 [96659]={["source"]="QuestieDB Forever",["text"]="Deliver the Supply Bundle to Kaga Wildhoof near Bloodhoof Village."},
 [96661]={["source"]="QuestieDB Forever",["text"]="Speak with Pyall Silentstride in Bloodhoof Village to learn to become a cook."},
 [96674]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Capture and return 6 Escaped Sheep."},
 [96676]={["source"]="QuestieDB Forever",["text"]="Bring the Alliance Equipment to Johun \"Punchy\" Dillas in Hyjal."},
 [96770]={["source"]="QuestieDB Forever",["text"]="Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Archmage Lan'dalock in Dalaran."},
 [96771]={["source"]="QuestieDB Forever",["text"]="Travel to Krol'dok Stronghold and slay Zalfan Moonshadow."},
 [96772]={["source"]="QuestieDB Forever",["text"]="Recover Zarla's Journal from the depths of Alcaz Prison."},
 [96773]={["source"]="QuestieDB Forever",["text"]="Recover The Coldbringer's Eye from Razorfen Downs."},
 [96774]={["source"]="QuestieDB Forever",["text"]="Recover an Ancient Gurubashi Idol from the Drowned City."},
 [96775]={["source"]="QuestieDB Forever",["text"]="Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Mazu'kon in Mulgore."},
 [96776]={["source"]="QuestieDB Forever",["text"]="Recover the crystal known as An'she's Radiance from Maraudon."},
 [96779]={["source"]="QuestieDB Forever",["text"]="Find Lord Tomas inside Durnholde Keep, in Hillsbrad Foothills, and kill him. Then, return to Myrokos Silentform."},
 [96781]={["source"]="QuestieDB Forever",["text"]="Steal Barton's Scouting Report by pickpocketing it from him. Then, bring the report to Myrokos Silentform at Ravenholdt Manor."},
 [96782]={["source"]="QuestieDB Forever",["text"]="Find the Blade of House Perenolde and the Royal Aegis of Perenolde among the ruins of Alterac. Then, bring them to Myrokos Silentform."},
 [96783]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Steal a Syndicate uniform from Northfold Manor to infiltrate Stromgarde Keep."},
 [96784]={["source"]="QuestieDB Forever",["text"]="While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal."},
 [96785]={["source"]="QuestieDB Forever",["text"]="Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal."},
 [96786]={["source"]="QuestieDB Forever",["text"]="Break up the secret deal, and take the object being traded to the Syndicate. Then, return to Myrokos Silentform at Ravenholdt Manor."},
 [96797]={["source"]="QuestieDB Forever",["text"]="Travel to Nethergarde Keep in the Blasted Lands and locate Sergeant Danneth."},
 [96798]={["source"]="QuestieDB Forever",["text"]="Find Sergeant Danneth somewhere in the Serpent's Coil caverns southeast of Nethergarde Keep."},
 [96799]={["source"]="QuestieDB Forever",["text"]="Speak with Sergeant Danneth at Nethergarde Keep."},
 [96800]={["source"]="QuestieDB Forever",["text"]="Retrieve the book The Lost Magic of the Runemasters from the Scarlet Monastery."},
 [96811]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Sergeant Danneth out of the Serpent's Coil caves and back to Nethergarde Keep."},
 [96812]={["source"]="QuestieDB Forever",["text"]="Return to Orphan Matron Aria in Dalaran and inform her of Sergeant Danneth's intentions to take in Randal."},
 [96821]={["source"]="QuestieDB Forever",["text"]="Kill 6 Ridgeshade Creepers and 6 Ridgeshade Lurkers in southern Durotar, then report to Gar'thok in Razor Hill."},
 [96822]={["source"]="QuestieDB Forever",["text"]="Collect the Raider's Battleaxe, Raider's Bow, and Raider's Shield from the Tiragarde Keep outskirts, then return them to Turroc in Razor Hill."},
 [96825]={["source"]="QuestieDB Forever",["text"]="Cook Torka in Razor Hill wants you to collect 8 Prickly Pear Fruit from the Razormane Grounds west of town."},
 [96873]={["source"]="QuestieDB Forever",["text"]="Pa'zula in Sen'jin Village wants you to collect 3 Luminous Residue. Luminous Residue can be obtained by disenchanting Hexed Pendants dropped by trolls in the Echo Isles."},
 [96874]={["source"]="QuestieDB Forever",["text"]="Ug'thok in Orgrimmar wants you to collect 5 Weathered Spines from beasts in Thunder Ridge, along with 5 Rough Grinding Stones."},
 [96875]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kamari in Orgrimmar wants you to collect 5 Rough Lizard Hide from beasts in Thunder Ridge, along with 2 Cured Light Hides."},
 [96876]={["source"]="QuestieDB Forever",["text"]="Return the pack to Ukor in southern Durotar."},
 [96877]={["source"]="QuestieDB Forever",["text"]="Deliver Halikor's Hoof to Orgrimmar."},
 [96895]={["source"]="QuestieDB Forever",["text"]="Find the Argent Dawn member near the entrance to the Undercity."},
 [96896]={["source"]="QuestieDB Forever",["text"]="Observe the conversation between Danitha Morr and Leonid Barthalomew the Revered."},
 [96897]={["source"]="QuestieDB Forever",["text"]="Kill 8 Dark Neophytes and 8 Dark Enforcers in Tirisfal Glades."},
 [96898]={["source"]="QuestieDB Forever",["text"]="Gather 12 Necrotic Crystal Fragments in Tirisfal Glades."},
 [96899]={["source"]="QuestieDB Forever",["text"]="Meet Leonid Barthalomew at Bandarion Keep in Tirisfal Glades."},
 [96982]={["source"]="QuestieDB Forever",["text"]="Inspect the riding kodos to choose your first mount."},
 [96984]={["source"]="QuestieDB Forever",["text"]="Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill."},
 [96986]={["source"]="QuestieDB Forever",["text"]="Defeat Atrexis the Grave Knight in the City of Dalaran for Melisara in Tarren Mill."},
 [96987]={["source"]="QuestieDB Forever",["text"]="Collect the Founding of Dalaran from the City of Dalaran for Rexxie Copperclutch near the sewer entrance."},
 [96988]={["source"]="QuestieDB Forever",["text"]="Collect 6 Cracked Sentry Cores in the City of Dalaran for Doctor Martin Felben in Undercity."},
 [96989]={["source"]="QuestieDB Forever",["text"]="Inspect the riding raptors to choose your first mount."},
 [96992]={["source"]="QuestieDB Forever",["text"]="Look through the burned buildings in the Cradle of Tranquility for 6 Metal Brackets and 30 Nails and return to Johun \"Punchy\" Dillas in Hyjal."},
 [96994]={["source"]="QuestieDB Forever",["text"]="Inspect the riding wolves to choose your first mount."},
 [96996]={["source"]="QuestieDB Forever",["text"]="Inspect the riding striders to choose your first mount."},
 [96997]={["source"]="QuestieDB Forever",["text"]="Inspect the undead riding horses to choose your first mount."},
 [96998]={["source"]="QuestieDB Forever",["text"]="Take the War Paint Wrap to someone who may recognize it."},
 [96999]={["source"]="QuestieDB Forever",["text"]="Take the War Paint Wrap to someone in Sen'jin Village."},
 [97000]={["source"]="QuestieDB Forever",["text"]="Search Hyjal's destroyed Alliance camps for signs of Abigail Sawyer's father, Lawrence."},
 [97001]={["source"]="QuestieDB Forever",["text"]="Take the Sawyer Family Ledger to Abigail Sawyer in Undercity's War Quarter."},
 [97003]={["source"]="QuestieDB Forever",["text"]="Bring the head of Chol'aruk to Gur'ak in the Barrens."},
 [97005]={["source"]="QuestieDB Forever",["text"]="Bring Chol'aruk's Head to Bainham in the Barrens."},
 [97006]={["source"]="QuestieDB Forever",["text"]="Take the Sawyer Family Ledger to Royal Overseer Bauhaus in Undercity's Trade Quarter."},
 [97007]={["source"]="QuestieDB Forever",["text"]="Return the notarized Sawyer Family Ledger to Abigail Sawyer in the War Quarter."},
 [97017]={["source"]="QuestieDB Forever",["text"]="Inspect the riding rams to choose your first mount."},
 [97018]={["source"]="QuestieDB Forever",["text"]="Learn the Apprentice Riding skill from Ultham Ironhorn."},
 [97022]={["source"]="QuestieDB Forever",["text"]="Speak with Danitha Morr at Bandarion Keep."},
 [97045]={["source"]="QuestieDB Forever",["text"]="Inspect the riding horses to choose your first mount."},
 [97046]={["source"]="QuestieDB Forever",["text"]="Inspect the riding mechanostriders to choose your first mount."},
 [97047]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Find a key to Wendel's cage, and a disguise for him to sneak out, within the Kurzen compound."},
 [97048]={["source"]="QuestieDB Forever",["text"]="Speak to Captain Aransas in Booty Bay."},
 [97049]={["source"]="QuestieDB Forever",["text"]="Gather 8 Seeping Slime Essence in the Shaper's Terrace."},
 [97074]={["source"]="QuestieDB Forever",["text"]="Learn the Apprentice Riding skill from Jartsam."},
 [97119]={["source"]="QuestieDB Forever",["text"]="Bring 6 Savory Stag Sliders to Ortak Lomgok in Elderwild."},
 [97130]={["source"]="QuestieDB Forever",["text"]="Recover an Ancient Gurubashi Idol from the Drowned City."},
 [97168]={["source"]="QuestieDB Forever",["text"]="If you are interested in helping Eldrun Stormbreaker in Ironforge, bring him an Azerothian Diamond and a Pristine Black Diamond."},
 [97170]={["source"]="QuestieDB Forever",["text"]="Learn the Apprentice Riding skill from Randal Hunter."},
 [97171]={["source"]="QuestieDB Forever",["text"]="Inspect the riding horses to choose your first mount."},
 [97173]={["source"]="QuestieDB Forever",["text"]="Recover a Blackmaw Ritual Totem from Blackmaw Hold."},
 [97174]={["source"]="QuestieDB Forever",["text"]="Speak with Danitha Morr at Bandarion Keep in Tirisfal Glades."},
 [97175]={["source"]="QuestieDB Forever",["text"]="Travel to Orgrimmar and get High Priest Zayus's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it."},
 [97177]={["source"]="QuestieDB Forever",["text"]="Return the Exorcism Censer to Danitha Morr at Bandarion Keep in Tirisfal Glades."},
 [97179]={["source"]="QuestieDB Forever",["text"]="Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Ott in Hillsbrad Foothills."},
 [97188]={["source"]="QuestieDB Forever",["text"]="Learn the Apprentice Riding skill from Binjy Featherwhistle."},
 [97194]={["source"]="QuestieDB Forever",["text"]="Learn the Apprentice Riding skill from Kildar."},
 [97196]={["source"]="QuestieDB Forever",["text"]="Recover The Coldbringer's Eye from Razorfen Downs."},
 [97197]={["source"]="QuestieDB Forever",["text"]="Recover a Fragment of the Firelands from Blackrock Depths for Alaana Stormwalker in Mulgore."},
 [97198]={["source"]="QuestieDB Forever",["text"]="Recover a Blackmaw Ritual Totem from Blackmaw Hold."},
 [97200]={["source"]="QuestieDB Forever",["text"]="Learn the Apprentice Riding skill from Xar'ti."},
 [97203]={["source"]="QuestieDB Forever",["text"]="Learn the Apprentice Riding skill from Velma Warnam."},
 [97204]={["source"]="QuestieDB Forever",["text"]="Learn the Apprentice Riding skill from Kar Stormsinger."},
 [97205]={["source"]="QuestieDB Forever",["text"]="Learn the Apprentice Riding skill from Genn Fairweather."},
 [97220]={["source"]="QuestieDB Forever",["text"]="Bring the Gatehouse Shipment to the stockroom entrance located in Trias' Cheese shop in the Trade District."},
 [97222]={["source"]="QuestieDB Forever",["text"]="Carry the Gatehouse Shipment up the stairs in Trias' shop and leave it outside the door."},
 [97223]={["source"]="QuestieDB Forever",["text"]="Bring Eggs of the Bloodtalon Matriarch to Xar'Ti in Sen'jin Village."},
 [97225]={["source"]="QuestieDB Forever",["text"]="Collect 8 Forgotten Loa Idols from the Echo Isles. Bring them to Master Gadrin in Sen'jin Village."},
 [97234]={["source"]="QuestieDB Forever",["text"]="Bring the wrapped reading material to the Stormwind library."},
 [97236]={["source"]="QuestieDB Forever",["text"]="Deliver the Fang of Githyiss to someone interested in the study of spiders in Aldrassil."},
 [97237]={["source"]="QuestieDB Forever",["text"]="Find each of the reading materials located somewhere in the library and then return to Roy Lewells in Stormwind's Park."},
 [97242]={["source"]="ForeverDungeonJournal learned client text",["text"]="Take some cuttings from the Cattails and Speargrass growing around the water flows in the Valley of Honor and return to Kor'geld in Yelmak's Alchemy and Potions."},
 [97243]={["source"]="QuestieDB Forever",["text"]="Bring the Torch of Dormant Flame to Olariaan Swiftburn at the Shrine of Flames in the Gustberry Lowlands."},
 [97244]={["source"]="QuestieDB Forever",["text"]="Slay Skypriest Faladiel in the Gustberry Lowlands and collect Faladiel's Heart."},
 [97245]={["complex"]=true,["extra"]={"Knock on Kuramaa's Stump"},["source"]="QuestieDB Forever",["text"]="Find the home of Kuramaa in the Shen'dar Highlands, and defeat the spirit in combat. Bring Kuramaa's Mask to Olariaan Swiftburn in the Gustberry Lowlands when you are victorious.\010Knock on Kuramaa's Stump"},
 [97246]={["source"]="ForeverDungeonJournal learned client text",["text"]="Visit Borstan's Firepit and tell him Thatog wants you to deliver Migi's lunch to him personally."},
 [97249]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Migi's Lunch to him behind Grommash Hold."},
 [97250]={["source"]="QuestieDB Forever",["text"]="Slay Alliance soldiers encroaching into the Barrens at the border to Dustwallow Marsh, then return to Grunt Logmar at Camp Taurajo."},
 [97253]={["source"]="QuestieDB Forever",["text"]="Collect 5 Handfuls of Complicated Parts from the upper pirate camp south of Ratchet, then return to Wrenix the Wretched in Ratchet."},
 [97257]={["source"]="QuestieDB Forever",["text"]="Wait for Olariaan to begin the ritual at the Brazier of Offering and follow his instructions.\010You must deliver the Eternal Flame to Valanaar before the timer runs out."},
 [97263]={["source"]="QuestieDB Forever",["text"]="Deliver Eldrun's misplaced package."},
 [97264]={["source"]="QuestieDB Forever",["text"]="Remove 12 Elder Shardtooth from nearby areas, then return to Sarna Brownhorn."},
 [97265]={["source"]="QuestieDB Forever",["text"]="Defeat a variety of Hatefury satyr at Sargeron in Desolace and then return to Aka'rai in Shadowprey Village."},
 [97275]={["source"]="ForeverDungeonJournal learned client text",["text"]="Give Yelmak's Potion to Whuut."},
 [97277]={["source"]="QuestieDB Forever",["text"]="Find Grund and Gozwin's camp in the hills to the northwest. Recover Gozwin's Mechanic's Log and kill the Snow Leopard Prowler."},
 [97279]={["source"]="QuestieDB Forever",["text"]="Collect 6 Abandoned Training Weapons, then return to Kzan Thornslash in the Den."},
 [97281]={["source"]="QuestieDB Forever",["text"]="Bring the Dull Stormy Orb to Rezlak near Drygulch Ravine."},
 [97282]={["source"]="QuestieDB Forever",["text"]="Bring 5 Charged Thunder Lizard Organs to Rezlak near Drygulch Ravine."},
 [97284]={["source"]="QuestieDB Forever",["text"]="Slay Burning Blade orcs at Thunder Axe Fortress in the Desolace, then return to Vahlarriel Demonslayer at Nijel's Point."},
 [97287]={["source"]="QuestieDB Forever",["text"]="Speak with Archmage Celindra in the City of Dalaran."},
 [97288]={["source"]="ForeverDungeonJournal learned client text",["text"]="Deliver the Abominable Head to Master Apothecary Faranell within the Undercity."},
 [97289]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring the Head of the Baron to the body of Othmar in the Undercity."},
 [97290]={["source"]="ForeverDungeonJournal learned client text",["text"]="Report your findings to Master Apothecary Faranell in Undercity."},
 [97291]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the Herbalism Trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter for Master Apothecary Faranell in Undercity."},
 [97292]={["source"]="ForeverDungeonJournal learned client text",["text"]="Inject the Hissing Serum into the system above Othmar's body for Master Apothecary Faranell."},
 [97319]={["source"]="QuestieDB Forever",["text"]="Find the missing cousin somewhere on Mount Hyjal."},
 [97326]={["source"]="ForeverDungeonJournal learned client text",["text"]="Return 8 Smooth Boulders to Thra behind Grommash Hold."},
 [97328]={["source"]="QuestieDB Forever",["text"]="Recover 8 Stolen Shipments from the Ruins of Zul'Kunda in Stranglethorn Vale and return your haul to someone in Booty Bay."},
 [97329]={["source"]="QuestieDB Forever",["text"]="Bring the Primitive Key obtained from the trolls at the Ruins of Zul'kunda in Stranglethorn Vale to Zimmix Sputterspark."},
 [97331]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Escort Zimmix Sputterspark away from the Ruins of Zul'Kunda then tell Wharfmaster Lozgil in Booty Bay of your successful rescue."},
 [97332]={["source"]="QuestieDB Forever",["text"]="Deliver the Twice Reordered Package to Wharfmaster Whizzbuzz at Powderfuse Port in the Riverglades."},
 [97386]={["source"]="QuestieDB Forever",["text"]="Commander Aggro'gosh of the Grom'gol base camp wants you to kill ogres at the Mosh'Ogg Ogre Mount."},
 [97403]={["source"]="QuestieDB Forever",["text"]="Kill 15 Chillwind Ravagers and return to Rilan Howard in northern Winterspring."},
 [97404]={["source"]="QuestieDB Forever",["text"]="Kill the old shardtooth matriarchs, Kuroma and Kamuro, and return their heads to Sarna Brownhorn."},
 [97405]={["source"]="QuestieDB Forever",["text"]="Knaz Blunderflame wants you to kill 3 Mosh'Ogg Spellcrafters, 3 Mosh'Ogg Warmongers, 3 Mosh'Ogg Maulers, and 3 Mosh'Ogg Shaman at the Mosh'Ogg Ogre Mount."},
 [97411]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Lightforge Bracers to Mokvar in Orgrimmar."},
 [97420]={["source"]="QuestieDB Forever",["text"]="Acquire 5 Drums of Crude Oil from the Venture Co. operations at Lake Nazferiti, then return to Knaz Blunderflame in Stranglethorn Vale."},
 [97446]={["source"]="QuestieDB Forever",["text"]="Inspect the riding kodos to choose your first mount."},
 [97447]={["source"]="QuestieDB Forever",["text"]="Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Bindings of the Elements to Deliana in Ironforge."},
 [97453]={["source"]="QuestieDB Forever",["text"]="Slay 6 Carnivorous Weeds south of Grom'gol and then inform Gemmil's mother."},
 [97485]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Purchase a Bundle of Herbs from Nida the herbalist, a Bundle of Cedar Twigs from Nata the enchanting supplier, and Sinew Thread from Mahu the leatherworking supplier and Ceremonial Flint and Tinder from Naal the cooking supplier.\010Combine the items and sprinkle the incense off of Hunter's Rise."},
 [97530]={["source"]="QuestieDB Forever",["text"]="Security Chief Bilgewhizzle of Steamwheedle Port in Tanaris wants you to recover a particularly shiny bangle bracelet lost near the Dunemaul ogre compound."},
 [97534]={["source"]="QuestieDB Forever",["text"]="Quinn wants you to recover 7 pieces of Desert Debris and return to her in Gadgetzan."},
 [97536]={["source"]="QuestieDB Forever",["text"]="Jhordy Lapforge wants you to return to him after you have dumped the Crate of Radioactive Refuse in the desert of Tanaris a safe distance away from Gadgetzan and other trash."},
 [97538]={["source"]="QuestieDB Forever",["text"]="Tah Winterhoof in Thunder Bluff wants 30 Mirkweed Pods from Mirkfallon Lake."},
 [97539]={["source"]="QuestieDB Forever",["text"]="Return 12 Surgical Spidersilk to Doctor Gregory Victor in Hammerfall, Arathi Highlands."},
 [97558]={["source"]="QuestieDB Forever",["text"]="Bring Shelene Rhobart 8 Duskbat Wing Membranes, 6 Darkhound Hides and 3 Vile Fin Murloc Skin."},
 [97583]={["source"]="ForeverDungeonJournal learned client text",["text"]="Purchase Nutritious Slime Sludge and return to your befriended excitable slime. If it seems tired, try dancing with it again to catch its attention."},
 [97617]={["source"]="QuestieDB Forever",["text"]="Recover 8 Unstudied Artifacts, an Explorers' League Mining Helmet, and a Pristine Mattock and bring them to Dorgaron at the border of Loch Modan and the Badlands."},
 [97884]={["source"]="QuestieDB Forever",["text"]="Travel to Sunnyglade in the Riverglades and recover the tome of Tremayne Family Blacksmithing Techniques."},
 [97891]={["source"]="QuestieDB Forever",["text"]="Bring the Unstable Potion to Doctor Martin Felben in the Apothecarium within the time limit."},
 [97894]={["source"]="QuestieDB Forever",["text"]="Check on Gorbold Steelhand in Auberdine in Darkshore.\010Borgus mentioned a boat on the southern-most dock in Stormwind Harbor that can take you there."},
 [97899]={["source"]="QuestieDB Forever",["text"]="Speak with Whuut in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97900]={["source"]="QuestieDB Forever",["text"]="Speak with Dwukk in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97901]={["source"]="QuestieDB Forever",["text"]="Speak with Jhag in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97902]={["source"]="QuestieDB Forever",["text"]="Speak with Mukdrak in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97903]={["source"]="QuestieDB Forever",["text"]="Speak with Rawrk in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97904]={["source"]="QuestieDB Forever",["text"]="Speak with Lau'Tiki near Sen'jin Village to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97905]={["source"]="QuestieDB Forever",["text"]="Speak with Jandi in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97906]={["source"]="QuestieDB Forever",["text"]="Speak with Karolek in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97907]={["source"]="QuestieDB Forever",["text"]="Speak with Krunn in Razor Hill to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97908]={["source"]="QuestieDB Forever",["text"]="Speak with Thuwd in Orgrimmar to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97914]={["source"]="QuestieDB Forever",["text"]="Bring Thundris' Letter to Baros Alexston in Stormwind.\010Thundris mentioned a boat in Auberdine that can take you there."},
 [97915]={["source"]="QuestieDB Forever",["text"]="Speak with Alchemist Mallory in Elwynn Forest near Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97916]={["source"]="QuestieDB Forever",["text"]="Speak with Smith Argus in Goldshire to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97917]={["source"]="QuestieDB Forever",["text"]="Speak with Betty Quin in Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97918]={["source"]="QuestieDB Forever",["text"]="Speak with Sprite Jumpsprocket in Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97919]={["source"]="QuestieDB Forever",["text"]="Speak with Michelle Belle in Goldshire to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97920]={["source"]="QuestieDB Forever",["text"]="Speak with Lee Brown near Goldshire to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [97921]={["source"]="QuestieDB Forever",["text"]="Speak with Herbalist Pomeroy in Elwynn Forest to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
