 [97977]={["source"]="QuestieDB Forever",["text"]="Collect 4 Gnarlpine Totems and bring them to Tarindrella."},
 [97979]={["source"]="QuestieDB Forever",["text"]="Cast Elune's Light and Shadowmeld."},
 [97985]={["source"]="QuestieDB Forever",["text"]="Slay Stormheart in Thousand Needles and acquire its heart."},
 [97987]={["source"]="QuestieDB Forever",["text"]="Speak with Saera Wirraway in Stormwind in The Park."},
 [97988]={["source"]="QuestieDB Forever",["text"]="Speak with Corswyn Aseril in Orgrimmar's Valley of Wisdom."},
 [98013]={["source"]="QuestieDB Forever",["text"]="Eliminate 12 Stormscale Myrmidons, 8 Stormscale Sorceresses, and 6 Stormscale Warriors for Arbal at the Grove of the Ancients."},
 [98021]={["source"]="QuestieDB Forever",["text"]="Report To Gryan Stoutmantle at Sentinel Hill in Westfall."},
 [98024]={["source"]="ForeverDungeonJournal learned client text",["text"]="Report To Thork at The Crossroads in The Barrens."},
 [98025]={["source"]="QuestieDB Forever",["text"]="Find and slay the owl known as Jai'vhanel and take one of her feathers. The black owl was last seen north of the Ameth'Aran ruins near the mountain base. Report the death of Jai'vhanel to Sentinel Glynda Nal'Shea in Auberdine."},
 [98027]={["source"]="QuestieDB Forever",["text"]="Deliver the Crescent Necklace to Maliynn in Astranaar."},
 [98028]={["source"]="QuestieDB Forever",["text"]="Bring the Clouded Water Globe to Onu at the Grove of the Ancients in Darkshore."},
 [98042]={["source"]="QuestieDB Forever",["text"]="Obtain a Peerless Eye from a Twilight Disciple or Thug at the Master's Glaive in Darkshore and find someone in Auberdine who is willing to take it."},
 [98046]={["source"]="QuestieDB Forever",["text"]="Bring the Drained Vessel to Lariia in the Temple of the Moon in Darnassus."},
 [98059]={["source"]="QuestieDB Forever",["text"]="Place the Sealed Company Request you were given on the bookkeeping table within Hillsbrad's town hall."},
 [98065]={["source"]="QuestieDB Forever",["text"]="Bring the Moonwell Remnants to Tyrande Whisperwind in the Temple of the Moon in Darnassus."},
 [98067]={["source"]="QuestieDB Forever",["text"]="Place Sentinel Owls at the entrance to the Cenarion Hold depths, the Darnassus Bank, the Craftsman's Terrace Inn, and the City Gate for Sentinel Dalia Sunblade in the Temple of the Moon in Darnassus."},
 [98069]={["source"]="QuestieDB Forever",["text"]="Bring 8 Stolen Freewind Supplies to Jandia in Freewind Post."},
 [98070]={["source"]="QuestieDB Forever",["text"]="Slay 5 Screeching Harpies, 5 Screeching Roguefeather Harpies and 5 Screeching Windcaller Harpies."},
 [98071]={["source"]="QuestieDB Forever",["text"]="Deliver the bottles of Fallrook Varietal to Dun Garok in southeast Hillsbrad Foothills, and bring back a sack of their Homebrew Hops."},
 [98072]={["source"]="QuestieDB Forever",["text"]="Collect 8 Pristine Crimson Scales and bring them to James Halloran in Menethil Harbor."},
 [98093]={["source"]="QuestieDB Forever",["text"]="Sulhasa in southern Barrens wants you to clear out 7 Stormhide lizards and 7 Hecklefang Stalkers in the area so she can leave the tree safely."},
 [98094]={["source"]="QuestieDB Forever",["text"]="High Executor Darthalia wants you to deliver updated orders to Deathstalker Masoj, south of Tarren Mill, outside of Dun Garok."},
 [98095]={["source"]="QuestieDB Forever",["text"]="Deathstalker Masoj needs you to place the three Apothecary Vials on peaks around Hillsbrad Foothills and return to him."},
 [98155]={["source"]="QuestieDB Forever",["text"]="Bring 5 Pristine Pesterhide Pelts to Kristy Grant."},
 [98156]={["source"]="QuestieDB Forever",["text"]="Bring the Package of Pristine Pelts to Kimberly Grant."},
 [98166]={["source"]="QuestieDB Forever",["text"]="Inspect the riding horses to choose your first mount."},
 [98189]={["source"]="QuestieDB Forever",["text"]="Bring the Menethil Statuette to Captain Stoutfist in Menethil Keep."},
 [98190]={["source"]="QuestieDB Forever",["text"]="Bring the Menethil Statuette to Highlord Bolvar Fordragon in Stormwind Keep."},
 [98191]={["source"]="QuestieDB Forever",["text"]="Bring the Menethil Statuette to Lord Grayson Shadowbreaker in the Cathedral of Light."},
 [98192]={["source"]="QuestieDB Forever",["text"]="Bring 8 Intact Raptor Hides to Krak in Brackenwall Village."},
 [98197]={["source"]="QuestieDB Forever",["text"]="Recover 6 Khaz Modan Timber and 30 Khaz Modan Iron from Menethil Harbor for Valstag Ironjaw."},
 [98203]={["source"]="QuestieDB Forever",["text"]="Kill the Witherbark witch doctor known as Ti'ik in a cave west of Hiri'watha and return with his head."},
 [98208]={["source"]="QuestieDB Forever",["text"]="Recover Nord'el for Sylessa Duskwhisper in Menethil Harbor."},
 [98209]={["source"]="QuestieDB Forever",["text"]="Bring Nord'el to Thundris Windweaver in Auberdine in Darkshore.\010You recall Sylessa mentioning a boat in Menethil Harbor can take you there."},
 [98216]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Goaz Stone near the Goaz Warder and bring its Titanic Keystone back to Prospector Whelgar."},
 [98219]={["source"]="QuestieDB Forever",["text"]="Speak to Lieutenant Farren Orinelle in Southshore in Hillsbrad Foothills."},
 [98221]={["source"]="QuestieDB Forever",["text"]="Captain Stoutfist in Menethil Keep wants you to destroy the 4 sets of Attack Plans in the Angerfang Encampment."},
 [98223]={["source"]="QuestieDB Forever",["text"]="Bring the Tattered Spellbook to Captain Stoutfist in Menethil Harbor."},
 [98230]={["source"]="QuestieDB Forever",["text"]="Find Howin Kindfeather east of Menethil Harbor, along the road."},
 [98233]={["source"]="QuestieDB Forever",["text"]="Recover Jameson's Training Sword and bring it to Guard Jameson."},
 [98240]={["source"]="QuestieDB Forever",["text"]="Bring the Crimson Crate to Howin Kindfeather off the road to the east of Menethil Harbor."},
 [98245]={["source"]="QuestieDB Forever",["text"]="Collect 10 Razormaw Incisors for Howin Kindfeather."},
 [98246]={["source"]="QuestieDB Forever",["text"]="Gather 12 Perfect Razormaw Eggs for Howin Kindfeather."},
 [98247]={["source"]="QuestieDB Forever",["text"]="Deliver the Shipping Label to someone at the Azeroth Commerce Authority trade hub in Redridge Mountains."},
 [98248]={["source"]="ForeverDungeonJournal learned client text",["text"]="Deliver the Shipping Label to someone at the Durotar Supply and Logistics trade hub near the Crossroads in the Barrens."},
 [98251]={["source"]="QuestieDB Forever",["text"]="Kill 6 Shadowhorn Stag and 6 Ashenvale Bear and return to Va'xug Firefure northwest of Fallen Sky Lake."},
 [98252]={["source"]="QuestieDB Forever",["text"]="Show Va'xug's Eye of Kilrogg the way back to the main Ashenvale road."},
 [98282]={["source"]="QuestieDB Forever",["text"]="Collect an Unruptured Stalker Gland from Thelgen Rock for Caitlin Grassman in Menethil Harbor."},
 [98283]={["source"]="QuestieDB Forever",["text"]="Bring Carnage's Head to Rethiel the Greenwarden in The Green Belt."},
 [98284]={["source"]="QuestieDB Forever",["text"]="Speak with Nasalanna Windsinger in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [98285]={["source"]="QuestieDB Forever",["text"]="Speak with the Strange Hermit in Shadowgale Forest to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [98286]={["source"]="QuestieDB Forever",["text"]="Speak with Nasalanna Windsinger in Shen'dar Village to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [98287]={["source"]="QuestieDB Forever",["text"]="Speak with Sprite Jumpsprocket in Stormwind to learn to craft a camping item for your profession once you have shown proficiency in your skill."},
 [98291]={["source"]="QuestieDB Forever",["text"]="Kill 8 Dragonmaw Reclaimers, 5 Dragonmaw Soulbinders, and 3 Dragonmaw Infiltrators in Dragonmaw Retreat for Howin Kindfeather."},
 [98293]={["source"]="QuestieDB Forever",["text"]="Collect 30 Dragonmaw Armaments in Dragonmaw Retreat, then bring them to Captain Stoutfist in Menethil Keep."},
 [98297]={["source"]="QuestieDB Forever",["text"]="Kill the Subdued Dragonspawn at the Dragonmaw Gates for Howin Kindfeather."},
 [98298]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring 6 Worgen Bits to Dalar Dawnweaver in The Sepulcher."},
 [98299]={["source"]="ForeverDungeonJournal learned client text",["text"]="Slay 5 Sickly Refugees and 5 Haggard Refugees for Dalar Dawnweaver in The Sepulcher."},
 [98300]={["source"]="QuestieDB Forever",["text"]="Deliver Howin's Missive to King Magni Bronzebeard in Ironforge."},
 [98310]={["complex"]=true,["source"]="QuestieDB Forever",["text"]="Use the Goaz Stone near Ados, Modr, Golm, and Neru and bring their hearts back to Prospector Whelgar."},
 [98313]={["source"]="QuestieDB Forever",["text"]="Bring the Whelgar Relic Package to Historian Karnik in Ironforge."},
 [98319]={["source"]="QuestieDB Forever",["text"]="Find Mountaineer Cornelius in the Grizzled Den for Mountaineer Gretchen."},
 [98321]={["source"]="QuestieDB Forever",["text"]="Collect 8 Flintfire Shipments from the Grizzled Den for Tongus Flintfire in Kharanos."},
 [98322]={["source"]="QuestieDB Forever",["text"]="Check in on Mountaineer Gretchen west of Kharanos."},
 [98323]={["source"]="QuestieDB Forever",["text"]="Deliver Mountaineer Gretchen's Report back to Senir Whitebeard in Kharanos."},
 [98325]={["source"]="QuestieDB Forever",["text"]="Speak to Warlord Goretooth to serve the Kargath Expeditionary Force."},
 [98326]={["source"]="QuestieDB Forever",["text"]="Slay Frosthowl and collect the Sack of Fish for Gretta Ganter in Brewnall Village."},
 [98340]={["source"]="QuestieDB Forever",["text"]="Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."},
 [98341]={["source"]="QuestieDB Forever",["text"]="Seek out the Avatar of Saeyleenan in the southern part Moonglade and learn what it has to share with you about the nature of the windborne cat."},
 [98342]={["source"]="QuestieDB Forever",["text"]="Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Great Cat Spirit."},
 [98362]={["source"]="QuestieDB Forever",["text"]="Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise."},
 [98386]={["source"]="QuestieDB Forever",["text"]="Slay 12 Greater Tarantulas and destroy 6 Tarantula Eggs in Alther's Mill for Foreman Oslow in Redridge."},
 [98387]={["source"]="QuestieDB Forever",["text"]="Bring 8 Stolen Weapons and 10 Blackrock Supplies to Marshal Marris in Lakeshire."},
 [98389]={["source"]="QuestieDB Forever",["text"]="Free 6 Webbed Victims in Night's Web Hollow for Aramis Hammerhand in Deathknell."},
 [98391]={["source"]="QuestieDB Forever",["text"]="Speak to Sister Aquinne in Darnassus."},
 [98392]={["source"]="QuestieDB Forever",["text"]="Collect Hatescreech's Amulet, Windmistress Gaedress' Amulet, and Witchmother Arysa's Amulet for Sentinel Arynia Cloudsbreak in the Oracle Glade."},
 [98393]={["source"]="QuestieDB Forever",["text"]="Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade."},
 [98394]={["source"]="QuestieDB Forever",["text"]="Seek out the Great Cat Spirit in southern part Moonglade and learn what it has to share with you about the nature of the cat."},
 [98396]={["source"]="QuestieDB Forever",["text"]="Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Great Cat Spirit."},
 [98397]={["source"]="QuestieDB Forever",["text"]="Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave."},
 [98398]={["source"]="QuestieDB Forever",["text"]="Find the Oracle Tree Bark nearby to receive its message."},
 [98403]={["source"]="QuestieDB Forever",["text"]="Kill 8 Befouled Webwoods and bring Xethorr the Wicked's Mature Fel Moss to Tallonkai Swiftroot in Dolanaar."},
 [98404]={["source"]="QuestieDB Forever",["text"]="Recover the Relic of the Fang, Relic of the Claw, and Relic of the Silent Shadow from the Stormrage Barrow Den, and return them to the Avatar of Saeyleenan."},
 [98405]={["source"]="QuestieDB Forever",["text"]="Seek out the Great Cat Spirit in southern part Moonglade and learn what it has to share with you about the nature of the cat."},
 [98407]={["source"]="QuestieDB Forever",["text"]="Collect 5 Spiked Collars from Redridge Thrashers for Deputy Feldon near Lakeshire."},
 [98417]={["source"]="QuestieDB Forever",["text"]="Maseara Autumnmoon wants you to search west of Forest Song, amongst the Satyrnaar demons. Report any signs of her husband Kurothel upon your return."},
 [98418]={["source"]="QuestieDB Forever",["text"]="Kill 5 Xavian Rogues, 5 Felsworn, 5 Betrayers, and 5 Hellcallers.\010Return to Maseara Autumnmoon in Forest Song afterwards."},
 [98423]={["source"]="QuestieDB Forever",["text"]="Deliver the Treaty of Understanding to Magni Bronzebeard in Ironforge."},
 [98424]={["source"]="QuestieDB Forever",["text"]="Collect the rest of Supervisor Fizsprocket's pages inside The Venture Co. Mine and bring them to Morin Cloudstalker near Bloodhoof Village."},
 [98427]={["source"]="QuestieDB Forever",["text"]="Bring the Clearcutter Key to Morin Cloudstalker outside Bloodhoof Village."},
 [98430]={["source"]="QuestieDB Forever",["text"]="Help Perith Stormhoof escape Palemane Rock, and report his safety to Cairne Bloodhoof in Thunder Bluff."},
 [98435]={["source"]="QuestieDB Forever",["text"]="Bring Thunderhorn's Report to Arch Druid Hamuul Runetotem in Thunder Bluff."},
 [98459]={["source"]="QuestieDB Forever",["text"]="Deliver Tom's Gift to Bart Tidewater in Menethil Harbor in the Wetlands."},
 [98461]={["source"]="QuestieDB Forever",["text"]="Deliver Hollee's Note to Tarrel Rockweaver near Menethil Harbor in the Wetlands."},
 [98463]={["source"]="QuestieDB Forever",["text"]="Visit Nixxrax Fillamug in the Salty Sailor Tavern in Booty Bay in Stranglethorn."},
 [98471]={["source"]="QuestieDB Forever",["text"]="Meet Elaadrin Evengale at the cliffs overlooking The Uplands in Alterac Mountains."},
 [98477]={["source"]="QuestieDB Forever",["text"]="Bring 10 Motes of Unstable Magic to Nuara Tremorhoof."},
 [98512]={["source"]="ForeverDungeonJournal learned client text",["text"]="Kill 10 Al'Aketh Assassins in the Shen'dar Highlands."},
 [98517]={["source"]="QuestieDB Forever",["text"]="Report to Sessaria Skystride or Aarnor Galestrike on Zephras Isle to continue your training as a Shaman. You can return to Zephras via the skycutter transport that docks in Mulgore at Skywatcher Plateau, northwest of Thunder Bluff."},
 [98545]={["source"]="ForeverDungeonJournal learned client text",["text"]="Deliver the Sealed Letter to Glix Xizzix in the Undercity."},
 [98574]={["source"]="QuestieDB Forever",["text"]="Read the Hallowed Memorandum and speak to Branstock Khalder in Anvilmar."},
 [98575]={["source"]="QuestieDB Forever",["text"]="Read the Tainted Tablet and speak to Nartok inside the Den in the Valley of Trials."},
 [98576]={["source"]="QuestieDB Forever",["text"]="Read the Glyphic Parchment and speak with Mai'ah near the entrance to the Den in the Valley of Trials."},
 [98581]={["source"]="QuestieDB Forever",["text"]="Read the Archaic Rune and speak to Teo Hammerstorm in Anvilmar."},
 [98601]={["source"]="QuestieDB Forever",["text"]="Read the Consecrated Scroll and speak to Aramis Hammerhand in the church in Deathknell."},
 [98731]={["source"]="QuestieDB Forever",["text"]="Speak to Dendrite."},
 [98738]={["source"]="QuestieDB Forever",["text"]="Speak to Dendrite."},
 [98739]={["source"]="QuestieDB Forever",["text"]="Speak to Dendrite."},
 [98815]={["source"]="QuestieDB Forever",["text"]="Return 4 Thicket Raptor Hides to James Halloran, the tanner, in Menethil Harbor."},
 [98823]={["source"]="QuestieDB Forever",["text"]="Bring the Titan Relic to Muln Earthfury at the Skywatcher Plateau in northwest Mulgore."},
 [98824]={["source"]="QuestieDB Forever",["text"]="Bring the Titan Relic to High Explorer Magellas in Ironforge's Hall of Explorers."},
 [98887]={["source"]="QuestieDB Forever",["text"]="Bring 3 Darkspear Islands Marks of Honor to a Horde Warbringer outside the battlegrounds."},
 [98889]={["source"]="QuestieDB Forever",["text"]="Bring 3 Darkspear Islands Marks of Honor to a Horde Warbringer outside the battlegrounds."},
 [98891]={["source"]="QuestieDB Forever",["text"]="Bring 3 Darkspear Islands Marks of Honor to a Horde Warbringer outside the battlegrounds."},
 [98893]={["source"]="QuestieDB Forever",["text"]="Bring 3 Darkspear Islands Marks of Honor to a Horde Warbringer outside the battlegrounds."},
