 [99046]={["source"]="QuestieDB Forever",["text"]="Search for Sentinel Eralya Leafshadow on the road leading to the Oracle Glade."},
 [99047]={["source"]="QuestieDB Forever",["text"]="Seek aid from Byancie in Dolanaar for Sentinel Eralya Leafshadow."},
 [99048]={["source"]="QuestieDB Forever",["text"]="Find Heglan Shadeeye north of Tiragarde Keep."},
 [99049]={["source"]="QuestieDB Forever",["text"]="Find signs of what attacked Heglan Shadeeye."},
 [99050]={["source"]="QuestieDB Forever",["text"]="Collect 6 Dewy Lasher Fronds, an Empty Vial, and a Refreshing Spring Water for Byancie in Dolanaar."},
 [99051]={["source"]="QuestieDB Forever",["text"]="Collect 9 Naga Spinefins."},
 [99052]={["source"]="QuestieDB Forever",["text"]="Kill the sea giant along Durotar's north coast and bring back proof of your accomplishment."},
 [99053]={["source"]="QuestieDB Forever",["text"]="Help Sentinel Lynessa Duskblossom escape Ban'ethil Barrow Den, and report her safety to Sentinel Kyra Starsong in Dolanaar."},
 [99073]={["source"]="QuestieDB Forever",["text"]="Take the Lashwater Salve to Sentinel Eralya Leafshadow on the road to the Oracle Tree."},
 [99079]={["source"]="QuestieDB Forever",["text"]="Find Longwalker Malah Longwind east of Bloodhoof Village, near the edge of Mulgore."},
 [99080]={["source"]="QuestieDB Forever",["text"]="Kill 6 Galak Centaurs, 4 Galak Outrunners, and bring the head of Herak the Pillager to Baine Bloodhoof."},
 [99081]={["source"]="QuestieDB Forever",["text"]="Bring Longwalker Malah's Report to Brave Wildrunner in Bloodhoof Village."},
 [99082]={["source"]="QuestieDB Forever",["text"]="Seek audience with High Chieftain Cairne Bloodhoof in Thunder Bluff."},
 [99101]={["source"]="QuestieDB Forever",["text"]="Bring Longwalker Malah's Report to Baine Bloodhoof."},
 [99108]={["source"]="QuestieDB Forever",["text"]="Defeat 3 other players in duels or Novice Warriors for Tang Stonehoof."},
 [99123]={["source"]="QuestieDB Forever",["text"]="Help Pal'juh escape Kolkar Crag and bring news of your success to Master Vornal in Sen'jin Village."},
 [99127]={["source"]="QuestieDB Forever",["text"]="Check the fishing traps in Crystal Lake."},
 [99128]={["source"]="QuestieDB Forever",["text"]="Kill 7 Murlocs and 4 Murloc Streamrunner at Crystal Lake, then return to Jason Mathers."},
 [99129]={["source"]="QuestieDB Forever",["text"]="Speak with Remy \"Two Times\" about Jason's murloc problems."},
 [99130]={["source"]="QuestieDB Forever",["text"]="Collect 6 Vials of Animal Blood and 18 Duskweed Petals for murloc bait, then return to Remy \"Two Times\" in Goldshire."},
 [99131]={["source"]="QuestieDB Forever",["text"]="Return to Jason Mathers."},
 [99134]={["source"]="ForeverDungeonJournal learned client text",["text"]="Punish 5 Deathguards for Executor Zygand."},
 [99141]={["source"]="ForeverDungeonJournal learned client text",["text"]="Obtain reports from Deathguard Dillinger, Deathguard Kristof, and Gordo for Executor Zygand."},
 [99142]={["source"]="QuestieDB Forever",["text"]="Collect 5 Tomb Weed and deliver them back to Junior Apothecary Holland."},
 [99143]={["source"]="QuestieDB Forever",["text"]="Collect 6 pieces of shiny junk from the nearby Murloc camp."},
 [99144]={["source"]="QuestieDB Forever",["text"]="Help Bareth Dawnstone escape Crusader's Outpost, and report his safety to Shari Stilwell in Brill."},
 [99152]={["source"]="ForeverDungeonJournal learned client text",["text"]="Collect 6 Faintly Glowing Bones for Hilda the Breaker."},
 [99153]={["source"]="ForeverDungeonJournal learned client text",["text"]="Find the Hidden Crystal Fragment beneath Shadowvale for Ephram Barbaro."},
 [99156]={["source"]="ForeverDungeonJournal learned client text",["text"]="Bring Riptear's Heart to Deathguard Linnea."},
 [99158]={["source"]="QuestieDB Forever",["text"]="Bring the crate of candles to Father Gavin at Misty Pine Refuge."},
 [99159]={["source"]="QuestieDB Forever",["text"]="Collect 14 pieces of firewood."},
 [99160]={["source"]="QuestieDB Forever",["text"]="Destroy 10 minor ice elementals."},
 [99161]={["source"]="QuestieDB Forever",["text"]="Kill Avala and retrieve its core."},
 [99162]={["source"]="QuestieDB Forever",["text"]="Collect the rifles of fallen mountaineers."},
 [99187]={["source"]="QuestieDB Forever",["text"]="Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr."},
 [99205]={["source"]="QuestieDB Forever",["text"]="Learn the Journeyman Riding skill from Jartsam."},
 [99207]={["source"]="QuestieDB Forever",["text"]="Learn the Journeyman Riding skill from Binjy Featherwhistle."},
 [99208]={["source"]="QuestieDB Forever",["text"]="Learn the Journeyman Riding skill from Velma Warnam."},
 [99209]={["source"]="QuestieDB Forever",["text"]="Learn the Journeyman Riding skill from Ultham Ironhorn."},
 [99260]={["source"]="QuestieDB Forever",["text"]="Speak with Elaadrin Evengale in Valanaar."},
 [99326]={["source"]="QuestieDB Forever",["text"]="Inspect the riding horses to choose your first mount."},
 [99411]={["source"]="QuestieDB Forever",["text"]="Ahab Wheathoof at Bloodhoof Village in Mulgore wants you to feed his prized puppy, Kyle the Frenzied.\010Feed Kyle Tender Strider Meat and return to Ahab Wheathoof."},
